-- The full free ExerciseDB catalogue (oss.exercisedb.dev, 1500 exercises), so the library goes
-- well past the original 64. Each comes with its animated GIF (static.exercisedb.dev/media/<gif_id>.gif)
-- and step-by-step instructions. Names follow the library's style ("Bench Press (Barbell)"), muscles
-- are mapped to the app's groups, and exercises already in the library (same GIF or name) are skipped,
-- so running it again changes nothing.

insert into public.exercises (name, primary_muscle, secondary_muscles, equipment, kind, gif_id, instructions)
select v.name, v.primary_muscle, v.secondary_muscles, v.equipment, v.kind, v.gif_id, v.instructions
from (values
('Upward Facing Dog', 'back', array['shoulders', 'chest']::text[], 'bodyweight', 'bodyweight_reps', '01qpYSe', array['Position yourself face down on the floor with your legs extended behind you.', 'Set your hands on the floor next to your lower ribs, fingers pointing forward.', 'Settle into the starting position and take an easy breath before moving deeper.', 'Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.', 'Stay in a mild stretch rather than pulling farther with momentum.', 'Hold the position with steady breathing, then release gently; repeat on the other side if needed.']::text[]),
('Hanging Knee Raise (Assisted)', 'core', '{}'::text[], 'bodyweight', 'bodyweight_reps', '03lzqwk', array['Suspend yourself from a pull-up bar with your arms straight and your palms turned away from you.', 'Brace your trunk muscles and lift your knees toward your chest, bending at the hips and knees.', 'Brace the abdomen and keep the shoulders anchored to the support.', 'Lift your legs by bracing your trunk and moving at the hips rather than swinging.', 'Slow the legs before they pull the lower back out of position.', 'Lower the legs slowly without swinging or losing your trunk position.']::text[]),
('Impossible Dips', 'triceps', array['chest', 'shoulders']::text[], 'bodyweight', 'bodyweight_reps', '05Cf2v8', array['Set yourself between two parallel bars with your arms straight and your body suspended in the air.', 'Before moving, bend your knees and cross your ankles.', 'Set the shoulders down and keep the elbows pointed mostly behind you.', 'Bend the elbows to lower between the supports; stop at a comfortable shoulder depth.', 'Choose a depth that lets the shoulders stay comfortable.', 'Press through the hands to rise, then reset the shoulders before another rep.']::text[]),
('Push-Up Inside Leg Kick', 'glutes', array['quads', 'hamstrings', 'calves', 'core']::text[], 'bodyweight', 'bodyweight_reps', '0br45wL', array['Begin in a push-up position with your hands just beyond shoulder width and your feet together.', 'Lower your body toward the ground by bending your elbows, with your spine steady and your core engaged.', 'Brace the abdomen and glutes so the shoulders, hips and ankles move together.', 'Bend your elbows to lower your chest while keeping your body in one line.', 'Keep the head in line with the spine as the elbows bend.', 'Press back to straight arms, keeping the body line intact.']::text[]),
('Seated Bradford Rocky Press (Barbell)', 'shoulders', array['triceps', 'back']::text[], 'barbell', 'weight_reps', '0dCyly0', array['Take a seat on a bench with your back straight and feet planted.', 'Take hold of the barbell with palms facing down, just beyond shoulder width.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Keep the wrists stacked and use a shoulder path that feels natural.', 'Lower the weight to its starting height under control before pressing again.']::text[]),
('Underhand Pulldown (Band)', 'back', array['biceps', 'forearms']::text[], 'band', 'weight_reps', '0I5fUyn', array['Connect the band to a high anchor point, such as a pull-up bar or sturdy beam.', 'Face the anchor point from a stable stance with feet about shoulder width.', 'Sit tall and set the shoulders before drawing the handle down.', 'Pull the handle down by driving your elbows toward your ribs; keep your torso steady.', 'Control the band on the way back instead of letting it snap you into position.', 'Let the handle rise steadily until the arms are long, then reset the shoulders.']::text[]),
('Standing Reverse Curl (Dumbbell)', 'biceps', array['forearms']::text[], 'dumbbell', 'weight_reps', '0IgNjSM', array['Stand tall with your feet about shoulder width and hold a dumbbell in each hand, palms facing your body.', 'With your upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.', 'Set the shoulders and upper arms before bending the elbows.', 'Curl the weight with your palms facing down, keeping the elbows close and torso still.', 'Keep the torso quiet and let the elbow bend lift the weight.', 'Lower until the elbows are nearly straight, keeping the upper arms still.']::text[]),
('Single-Leg Floor Calf Raise', 'calves', '{}'::text[], 'bodyweight', 'bodyweight_reps', '0jp9Rlz', array['Stand and set your feet about hip width and place your hands on a wall or sturdy object for balance.', 'Before moving, lift one foot off the ground and balance on the other foot.', 'Let the ankles move freely while the rest of the body stays quiet.', 'Rise through the balls of your feet, lifting the heels as high as you can without rocking.', 'Keep the pelvis level as the supporting leg does the work.', 'Lower the heels at a measured pace before rising again; switch sides when the set calls for it.']::text[]),
('Burpee (Dumbbell)', 'cardio', array['quads', 'hamstrings', 'calves', 'shoulders', 'triceps', 'core']::text[], 'dumbbell', 'duration', '0JtKWum', array['Begin in a standing position with your feet about shoulder width and a dumbbell in each hand.', 'Before moving, lower your body into a squat position, placing the dumbbells on the ground in front of you.', 'Start at a pace that lets the feet and arms move in sync.', 'Move at a repeatable pace, keeping the motion smooth and your breathing steady.', 'Keep the pattern repeatable as speed increases.', 'Keep the rhythm for the planned interval, slowing if your form starts to slip.']::text[]),
('Roller Hip Lat Stretch', 'glutes', array['hamstrings', 'quads']::text[], 'other', 'duration', '0L2KwtI', array['Begin by kneeling on the ground with the roller positioned under your hips.', 'Set your hands on the roller for support.', 'Settle into the starting position and take an easy breath before moving deeper.', 'Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.', 'Stay in a mild stretch rather than pulling farther with momentum.', 'Hold the position with steady breathing, then release gently; repeat on the other side if needed.']::text[]),
('Sissy Squat (Weighted)', 'quads', array['glutes', 'hamstrings', 'calves']::text[], 'bodyweight', 'bodyweight_reps', '0lQnxMZ', array['Stand and set your feet about shoulder width and your toes pointing slightly outward.', 'Take a weight ahead of your chest with both hands, or place a barbell across your upper back.', 'Brace the abdomen and spread pressure across the whole foot.', 'Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.', 'Drive upward with the chest and hips rising together; keep the knees from collapsing inward.', 'Stand fully, reset your footing and breathing, then begin the next descent.']::text[]),
('Runners Stretch', 'hamstrings', array['calves', 'quads']::text[], 'bodyweight', 'duration', '0mB6wHO', array['Stand and set your feet about hip width.', 'Step forward with your right foot, keeping your left foot planted.', 'Settle into the starting position and take an easy breath before moving deeper.', 'Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.', 'Stay in a mild stretch rather than pulling farther with momentum.', 'Hold the position with steady breathing, then release gently; repeat on the other side if needed.']::text[]),
('Pulldown (Pro Lat Bar) (Cable)', 'back', array['biceps', 'forearms']::text[], 'cable', 'weight_reps', '0MlxeMn', array['Set the seat height so that your thighs are parallel to the ground and your feet are flat on the floor.', 'Hold the lat bar with palms facing down, just beyond shoulder width.', 'Sit tall and set the shoulders before drawing the handle down.', 'Pull the handle down by driving your elbows toward your ribs; keep your torso steady.', 'Pull with the elbows rather than leaning far back to move the handle.', 'Let the handle rise steadily until the arms are long, then reset the shoulders.']::text[]),
('Inverse Leg Curl (On Pull-Up Cable Machine)', 'hamstrings', array['glutes', 'calves']::text[], 'bodyweight', 'weight_reps', '0rHfvy9', array['Set the cable machine so that the ankle straps are at the lowest setting.', 'Position yourself face down on the bench with your legs extended and the ankle straps attached to your feet.', 'Line the knees up with the machine or bench edge before starting the curl.', 'Bend your knees to draw the pad toward you without lifting your hips from the support.', 'Keep the hips still while the knees bend.', 'Ease back to the start before repeating.']::text[]),
('Seated Single-Leg Calf Raise (Smith Machine)', 'calves', array['hamstrings']::text[], 'machine', 'weight_reps', '0S75mYG', array['Take a seat on the machine with your back against the pad and your feet on the footrest.', 'Set one leg on the footrest and keep the other leg off the footrest.', 'Let the ankles move freely while the rest of the body stays quiet.', 'Rise through the balls of your feet, lifting the heels as high as you can without rocking.', 'Keep the pelvis level as the supporting leg does the work.', 'Lower the heels at a measured pace before rising again; switch sides when the set calls for it.']::text[]),
('Pull-Up (Neutral Grip)', 'back', array['biceps', 'forearms']::text[], 'bodyweight', 'bodyweight_reps', '0V2YQjW', array['Suspend yourself from a pull-up bar with a neutral grip (palms facing each other) and your arms straight.', 'Brace your trunk and draw your shoulder blades toward each other.', 'Begin from a controlled hang with the shoulders active rather than slack.', 'Pull your elbows down and bring your upper chest toward the bar without kicking your legs.', 'Avoid swinging the legs to clear the bar.', 'Lower to long arms without dropping suddenly from the top.']::text[]),
('Seated Hip Abduction (Band)', 'glutes', array['hamstrings']::text[], 'band', 'weight_reps', '0xDpB4L', array['Take a seat on a chair or bench with your back straight and feet planted.', 'Loop the resistance band around your thighs, just above your knees.', 'Square the pelvis before moving the working leg.', 'Open the knees or legs against resistance without shifting your torso.', 'Control the band on the way back instead of letting it snap you into position.', 'Return along the same path at a controlled pace.']::text[]),
('Bear Crawl', 'cardio', array['core', 'shoulders', 'triceps']::text[], 'bodyweight', 'duration', '0Yz8WdV', array['Get onto hands and knees with your hands directly under your shoulders and your knees directly under your hips.', 'Before moving, lift your knees slightly off the ground, keeping your back flat and your core engaged.', 'Start at a pace that lets the feet and arms move in sync.', 'Move at a repeatable pace, keeping the motion smooth and your breathing steady.', 'Keep the pattern repeatable as speed increases.', 'Keep the rhythm for the planned interval, slowing if your form starts to slip.']::text[]),
('Isometric Wipers', 'chest', array['shoulders', 'triceps', 'core']::text[], 'bodyweight', 'duration', '11wrviz', array['Begin by lying flat on your back on a mat or bench.', 'Reach your arms straight out to the sides, perpendicular to your body.', 'Set the pelvis and make the turn through the rib cage.', 'Keep the trunk braced as the legs move together from side to side.', 'Keep the turn smooth instead of throwing the arms across the body.', 'Return through center before turning to the other side.']::text[]),
('Raise Single Arm Push-Up', 'chest', array['triceps', 'shoulders', 'core']::text[], 'bodyweight', 'bodyweight_reps', '13TpY4H', array['Begin in a push-up position with your hands just beyond shoulder width and your feet together.', 'Reach one arm straight out to the side, parallel to the ground.', 'Brace the abdomen and glutes so the shoulders, hips and ankles move together.', 'Bend your elbows to lower your chest while keeping your body in one line.', 'Keep the head in line with the spine as the elbows bend.', 'Press back to straight arms, keeping the body line intact.']::text[]),
('Stretch Lunge (Weighted)', 'glutes', array['quads', 'hamstrings', 'calves']::text[], 'bodyweight', 'duration', '13VW2VO', array['Stand and set your feet about shoulder width.', 'Step forward with your right foot, with your spine steady.', 'Settle into the starting position and take an easy breath before moving deeper.', 'Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.', 'Stay in a mild stretch rather than pulling farther with momentum.', 'Hold the position with steady breathing, then release gently; repeat on the other side if needed.']::text[]),
('Seated Calf Stretch', 'calves', array['hamstrings']::text[], 'bodyweight', 'duration', '17bqEXD', array['Take a seat on the edge of a chair or bench with your feet planted.', 'Reach one leg straight out in front of you, keeping your heel on the ground.', 'Settle into the starting position and take an easy breath before moving deeper.', 'Ease the heel down and shift until the calf stretches; keep the foot pointed ahead.', 'Stay in a mild stretch rather than pulling farther with momentum.', 'Hold the position with steady breathing, then release gently; repeat on the other side if needed.']::text[]),
('Hip Raise (Bent Knee)', 'core', array['glutes', 'hamstrings']::text[], 'bodyweight', 'bodyweight_reps', '196HJGw', array['Settle onto your back with your knees bent and feet planted.', 'Set your hands by your sides, palms facing down.', 'Plant the feet and keep the ribs from flaring as the hips prepare to rise.', 'Press through the feet and lift your hips until your torso and thighs line up.', 'Stop when the hips line up with the torso; do not arch higher through the lower back.', 'Lower the hips steadily and keep the feet planted for the next lift.']::text[]),
('Bent Knee Good Morning (Smith Machine)', 'glutes', array['hamstrings', 'back']::text[], 'machine', 'weight_reps', '1bQkKZK', array['Begin by standing with your feet about shoulder width, toes pointing forward.', 'Set the barbell across your upper back, resting it on your traps.', 'Unlock the knees and brace the abdomen before moving the hips back.', 'Push the hips back while keeping the load close and the spine steady.', 'Keep the weight close to the legs and stop when the back would begin to round.', 'Drive the hips forward to stand tall without leaning back at the top.']::text[]),
('Standing French Press (EZ Bar)', 'triceps', array['shoulders']::text[], 'barbell', 'weight_reps', '1cTf2Ux', array['Stand and set your feet about shoulder width and hold the ez barbell with palms facing down.', 'Raise the barbell above your head, straighten your arms.', 'Set the upper arms in place before extending the elbows.', 'Bend the elbows to lower the bar behind your head while the upper arms stay mostly still.', 'Keep the upper arms steady while the forearms travel.', 'Straighten the elbows to bring the bar overhead, then begin the next controlled rep.']::text[]),
('Upright Row (Smith Machine)', 'shoulders', array['traps', 'biceps']::text[], 'machine', 'weight_reps', '1DN3iz4', array['Stand and set your feet about shoulder width, facing the smith machine.', 'Hold the barbell with palms facing down, hands just beyond shoulder width.', 'Set the torso and allow the arms to reach forward without rounding excessively.', 'Draw your elbows back and bring the handle or weight toward your torso.', 'Bring the elbows back without jerking the torso.', 'Reach the arms forward again without letting the torso lurch.']::text[]),
('Jack Jump', 'cardio', array['quads', 'calves']::text[], 'bodyweight', 'duration', '1g5bPpA', array['Stand and set your feet together and your arms by your sides.', 'Before moving, jump up, spreading your feet apart and raising your arms above your head.', 'Bend the hips and knees slightly to load the jump.', 'Load the legs with a small bend, then drive through the floor and land softly.', 'Land with bent hips and knees and let the feet absorb the impact.', 'Absorb the landing through the hips and knees before repeating.']::text[]),
('Jump Squat (Barbell)', 'glutes', array['quads', 'hamstrings', 'calves']::text[], 'barbell', 'weight_reps', '1gFNTZV', array['Begin by standing with your feet about shoulder width, holding a barbell across your upper back.', 'Before moving, lower your body into a squat position by bending your knees and pushing your hips back.', 'Brace the abdomen and spread pressure across the whole foot.', 'Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.', 'Drive upward with the chest and hips rising together; keep the knees from collapsing inward.', 'Stand fully, reset your footing and breathing, then begin the next descent.']::text[]),
('Janda Sit-Up', 'core', array['back']::text[], 'bodyweight', 'bodyweight_reps', '1GPHRyK', array['Settle onto your back with your knees bent and feet planted.', 'Set your hands behind your head with your elbows pointing outwards.', 'Set the pelvis and keep the neck relaxed before curling upward.', 'Curl your rib cage toward your pelvis, letting the abdominals move the torso.', 'Leave a little space between the chin and chest; keep the movement in the torso.', 'Lower the shoulders or torso with control before the next curl.']::text[]),
('Push-Up on Lower Arms', 'triceps', array['chest', 'shoulders']::text[], 'bodyweight', 'bodyweight_reps', '1IFV9h3', array['Begin in a plank position with your forearms on the ground and elbows directly below your shoulders.', 'Brace your trunk and keep your body in a straight line from head to toe.', 'Brace the abdomen and glutes so the shoulders, hips and ankles move together.', 'Bend your elbows to lower your chest while keeping your body in one line.', 'Keep the head in line with the spine as the elbows bend.', 'Press back to straight arms, keeping the body line intact.']::text[]),
('Prone Twist on Stability Ball', 'core', array['back']::text[], 'bodyweight', 'bodyweight_reps', '1IG6gVF', array['Begin by lying face down on a stability ball with your feet about shoulder width and your toes touching the ground.', 'Set your hands behind your head or cross them over your chest.', 'Set the pelvis and make the turn through the rib cage.', 'Turn through the torso while the hips and lower body stay as steady as the setup allows.', 'Keep the ball steady and use the feet to manage your balance.', 'Return through center before turning to the other side.']::text[]),
('Standing Lateral Stretch', 'back', array['shoulders', 'core']::text[], 'bodyweight', 'duration', '1jXLYEw', array['Stand and set your feet about shoulder width and your knees soft.', 'Reach your arms straight out to the sides, parallel to the ground.', 'Settle into the starting position and take an easy breath before moving deeper.', 'Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.', 'Stay in a mild stretch rather than pulling farther with momentum.', 'Hold the position with steady breathing, then release gently; repeat on the other side if needed.']::text[]),
('Single Leg Calf Raise (Dumbbell)', 'calves', '{}'::text[], 'dumbbell', 'weight_reps', '1kB3Wmk', array['Step onto the edge of a step or platform with your heels hanging off and your toes on the step.', 'Take a dumbbell in one hand and place your other hand on a wall or railing for support.', 'Let the ankles move freely while the rest of the body stays quiet.', 'Rise through the balls of your feet, lifting the heels as high as you can without rocking.', 'Pause at the top without rolling the ankles outward.', 'Lower the heels at a measured pace before rising again.']::text[]),
('Calf Stretch with Rope', 'calves', array['hamstrings']::text[], 'cable', 'duration', '1LVFcEn', array['Face a wall or sturdy object with your feet about hip width.', 'Take hold of the ends of the rope in each hand and place the middle of the rope around the ball of your right foot.', 'Settle into the starting position and take an easy breath before moving deeper.', 'Ease the heel down and shift until the calf stretches; keep the foot pointed ahead.', 'Stay in a mild stretch rather than pulling farther with momentum.', 'Hold the position with steady breathing, then release gently; repeat on the other side if needed.']::text[]),
('Upright Row (Barbell)', 'shoulders', array['traps', 'biceps']::text[], 'barbell', 'weight_reps', '1oE78pm', array['Stand and set your feet about shoulder width and hold a barbell with palms facing down, hands just beyond shoulder width.', 'Keep the barbell hanging ahead of your thighs, arms straight.', 'Set the torso and allow the arms to reach forward without rounding excessively.', 'Draw your elbows back and bring the handle or weight toward your torso.', 'Bring the elbows back without jerking the torso.', 'Reach the arms forward again without letting the torso lurch.']::text[]),
('Incline Pushdown (Cable)', 'back', array['triceps', 'shoulders']::text[], 'cable', 'weight_reps', '1PK5Uo3', array['Connect a straight bar to a high pulley cable machine.', 'Face the away from the machine from a stable stance with feet about shoulder width.', 'Stand far enough from the stack for the cable to stay taut.', 'Keep your elbows near your ribs and straighten your arms against the cable.', 'Keep the elbows close to the body instead of letting the shoulders swing.', 'Return along the same path at a controlled pace.']::text[]),
('Incline Twisted Flyes (Dumbbell)', 'chest', array['shoulders', 'triceps']::text[], 'dumbbell', 'weight_reps', '1PLE8e9', array['Angle an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing each other.', 'Recline on the bench and press the dumbbells up to the starting position, directly above your chest, with your arms extended.', 'Keep a soft elbow bend and set the shoulders before moving the arms.', 'With a soft bend in the elbows, sweep your arms together in a wide arc.', 'Keep the elbow angle nearly unchanged through the arc.', 'Open the arms back along the same arc without dropping the load.']::text[]),
('Decline Hammer Press (Dumbbell)', 'chest', array['triceps', 'shoulders']::text[], 'dumbbell', 'weight_reps', '1qrWgZ2', array['Secure the feet on a decline bench, keeping the head below the hips.', 'Take a dumbbell in each hand with your palms facing each other and your arms extended above your chest.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Keep the palms facing each other and the wrists straight.', 'Lower the weight to its starting height under control before pressing again.']::text[]),
('Iron Cross (Dumbbell)', 'shoulders', array['triceps', 'chest']::text[], 'dumbbell', 'weight_reps', '1RIkUHT', array['Stand and set your feet about shoulder width, holding a dumbbell in each hand at your sides.', 'Before moving, raise your arms out to the sides until they are parallel to the ground, forming a T shape with your body.', 'Start with a manageable load and a small bend in the elbows.', 'Open the arms out to the sides to form a T, then bring them back under control.', 'Stop near shoulder height rather than shrugging to lift higher.', 'Lower the arms slowly to your sides without swinging the weight.']::text[]),
('Single-Arm Shoulder Press (Dumbbell)', 'shoulders', array['triceps', 'back']::text[], 'dumbbell', 'weight_reps', '1TkiAFK', array['Stand and set your feet about shoulder width and hold a dumbbell in one hand at shoulder level, palm facing forward.', 'Brace your trunk and press the dumbbell straight up overhead, fully extending your arm.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Keep both shoulders level and resist turning toward the working arm.', 'Lower the weight to its starting height under control before pressing again; switch sides when the set calls for it.']::text[]),
('Lying Triceps Extension (Barbell)', 'triceps', array['shoulders']::text[], 'barbell', 'weight_reps', '1TVoin7', array['Settle onto a bench with your feet planted and your head at the end of the bench.', 'Take hold of the barbell with palms facing down, hands about shoulder width, and extend your arms straight up over your chest.', 'Set the upper arms in place before extending the elbows.', 'Keep the upper arms steady and extend through the elbows to move the weight.', 'Keep the upper arms steady while the forearms travel.', 'Bend the elbows slowly to return to the start of the next rep.']::text[]),
('Narrow Grip Seated Row (Machine)', 'back', array['biceps', 'forearms']::text[], 'machine', 'weight_reps', '1u36hhy', array['Set the seat height and footrests to ensure proper form.', 'Take a seat on the machine with your feet flat on the footrests and your knees soft.', 'Set the torso and allow the arms to reach forward without rounding excessively.', 'Draw your elbows back and bring the handle or weight toward your torso.', 'Bring the elbows back without jerking the torso.', 'Reach the arms forward again without letting the torso lurch.']::text[]),
('Seated Close-Grip Concentration Curl (Barbell)', 'biceps', array['forearms']::text[], 'barbell', 'weight_reps', '1V1gj1u', array['Plant both feet while seated on a bench; hold a barbell with palms facing up, hands about shoulder width.', 'Set your upper arms against your inner thighs, just above your knees, and let the barbell hang down in front of you.', 'Set the shoulders and upper arms before bending the elbows.', 'Bend your elbows to bring the weight toward your shoulders without swinging your torso.', 'Keep the torso quiet and let the elbow bend lift the weight.', 'Lower until the elbows are nearly straight, keeping the upper arms still.']::text[]),
('Biceps Curl Lunge with Bowling Motion (Dumbbell)', 'biceps', array['forearms', 'shoulders']::text[], 'dumbbell', 'weight_reps', '1VpF8db', array['Stand and set your feet about shoulder width, holding a dumbbell in each hand with your palms facing forward.', 'Step forward with your right foot, bending your right knee and lowering your body into a lunge position.', 'Set your stance wide enough to balance before bending either knee.', 'Step into the movement and bend both knees, keeping your front foot planted.', 'Keep the front foot planted and avoid collapsing inward at the knee.', 'Push through the lead foot to return to the start, then change legs as planned.']::text[]),
('High Pulley Overhead Triceps Extension (Cable)', 'triceps', array['shoulders']::text[], 'cable', 'weight_reps', '1xHyxys', array['Connect a rope to a high pulley and stand turned away from the machine.', 'Hold the rope with both hands and extend your arms overhead.', 'Set the upper arms in place before extending the elbows.', 'Keep the upper arms pointed upward and extend at the elbows without flaring the ribs.', 'Keep the upper arms steady while the forearms travel.', 'Bend the elbows slowly to return to the start of the next rep.']::text[]),
('Incline Close-Grip Push-Up', 'triceps', array['chest', 'shoulders']::text[], 'bodyweight', 'bodyweight_reps', '1YB40kg', array['Set your hands close together on a stable raised surface, then walk the feet back into a plank.', 'Reach your legs behind you, resting on the balls of your feet, with your body forming a straight line from head to heels.', 'Brace the abdomen and glutes so the shoulders, hips and ankles move together.', 'Bend your elbows to lower your chest while keeping your body in one line.', 'Keep the head in line with the spine as the elbows bend.', 'Press back to straight arms, keeping the body line intact.']::text[]),
('Inverted Row', 'back', array['biceps', 'forearms']::text[], 'bodyweight', 'bodyweight_reps', '1YUWDNZ', array['Prepare a bar at waist height or use a suspension trainer.', 'Face the bar or suspension trainer, from a stable stance with feet about shoulder width.', 'Set the torso and allow the arms to reach forward without rounding excessively.', 'Draw your elbows back and bring the handle or weight toward your torso.', 'Bring the elbows back without jerking the torso.', 'Reach the arms forward again without letting the torso lurch.']::text[]),
('Bicycle Crunch', 'core', '{}'::text[], 'bodyweight', 'bodyweight_reps', '1ZFqTDN', array['Settle onto your back with your hands placed behind your head.', 'Before moving, lift your legs off the ground and bend your knees at a 90-degree angle.', 'Set the pelvis and keep the neck relaxed before curling upward.', 'Bring one elbow toward the opposite knee as the other leg extends; switch sides in a steady rhythm.', 'Leave a little space between the chin and chest; keep the movement in the torso.', 'Lower the shoulders or torso with control before the next curl.']::text[]),
('Kneeling Twisting Crunch (Band)', 'core', '{}'::text[], 'band', 'weight_reps', '225x2Vd', array['Connect the band to a sturdy anchor point at waist height.', 'Kneel turned away from the anchor point and hold the band with both hands, keeping your elbows bent and close to your sides.', 'Set the pelvis and keep the neck relaxed before curling upward.', 'Curl your rib cage toward your pelvis, letting the abdominals move the torso.', 'Control the band on the way back instead of letting it snap you into position.', 'Lower the shoulders or torso with control before the next curl.']::text[]),
('Incline Fly (On Stability Ball) (Cable)', 'chest', array['shoulders', 'triceps']::text[], 'cable', 'weight_reps', '27NNGFr', array['Prepare a stability ball at an incline angle.', 'Connect the cable handles to the high pulleys of a cable machine.', 'Keep a soft elbow bend and set the shoulders before moving the arms.', 'With a soft bend in the elbows, sweep your arms together in a wide arc.', 'Keep the ball steady and use the feet to manage your balance.', 'Open the arms back along the same arc without dropping the load.']::text[]),
('Rocking Frog Stretch', 'glutes', array['hamstrings', 'quads']::text[], 'bodyweight', 'duration', '2Dk4xQV', array['Begin by kneeling on the ground with your knees about hip width.', 'Set your hands on the ground in front of you for support.', 'Settle into the starting position and take an easy breath before moving deeper.', 'Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.', 'Stay in a mild stretch rather than pulling farther with momentum.', 'Hold the position with steady breathing, then release gently; repeat on the other side if needed.']::text[]),
('Single-Arm Side Deadlift (Barbell)', 'glutes', array['hamstrings', 'quads', 'back']::text[], 'barbell', 'weight_reps', '2DxtqHL', array['Stand and set your feet about shoulder width, holding a barbell in one hand with palms facing down.', 'Keep your spine in a comfortable neutral position and your core engaged.', 'Unlock the knees and brace the abdomen before moving the hips back.', 'Push the hips back while keeping the load close and the spine steady.', 'Keep both shoulders level and resist turning toward the working arm.', 'Drive the hips forward to stand tall without leaning back at the top; switch sides when the set calls for it.']::text[]),
('3/4 Sit-Up', 'core', array['back']::text[], 'bodyweight', 'bodyweight_reps', '2gPfomN', array['Settle onto your back with your knees bent and feet planted.', 'Set your hands behind your head with your elbows pointing outwards.', 'Set the pelvis and keep the neck relaxed before curling upward.', 'Curl your rib cage toward your pelvis, letting the abdominals move the torso.', 'Leave a little space between the chin and chest; keep the movement in the torso.', 'Lower the shoulders or torso with control before the next curl.']::text[]),
('Floor Calf Raise (Barbell)', 'calves', array['hamstrings']::text[], 'barbell', 'weight_reps', '2IHEa2T', array['Set a barbell on the floor in front of you.', 'Stand and set the balls of your feet on the edge of the barbell, with your heels hanging off.', 'Let the ankles move freely while the rest of the body stays quiet.', 'Rise through the balls of your feet, lifting the heels as high as you can without rocking.', 'Pause at the top without rolling the ankles outward.', 'Lower the heels at a measured pace before rising again.']::text[]),
('Overhead Triceps Extension (Rope Attachment) (Cable)', 'triceps', array['shoulders']::text[], 'cable', 'weight_reps', '2IxROQ1', array['Connect a rope to a cable machine at a high position.', 'Face the away from the machine from a stable stance with feet about shoulder width.', 'Set the upper arms in place before extending the elbows.', 'Keep the upper arms pointed upward and extend at the elbows without flaring the ribs.', 'Keep the upper arms steady while the forearms travel.', 'Bend the elbows slowly to return to the start of the next rep.']::text[]),
('Kneeling Biceps Curl Exercise Ball (Dumbbell)', 'biceps', array['forearms']::text[], 'dumbbell', 'weight_reps', '2JCuFTU', array['Get down on the floor with an exercise ball in front of you.', 'Set your elbows on top of the exercise ball, holding a dumbbell in each hand with your palms facing up.', 'Set the shoulders and upper arms before bending the elbows.', 'Bend your elbows to bring the weight toward your shoulders without swinging your torso.', 'Keep the ball steady and use the feet to manage your balance.', 'Lower until the elbows are nearly straight, keeping the upper arms still.']::text[]),
('Spine Twist', 'core', array['back']::text[], 'bodyweight', 'bodyweight_reps', '2jl9K55', array['Take a seat on the ground with your legs extended in front of you.', 'Bend your knees and place your feet planted, about hip width.', 'Set the pelvis and make the turn through the rib cage.', 'Turn through the torso while the hips and lower body stay as steady as the setup allows.', 'Keep the turn smooth instead of throwing the arms across the body.', 'Return through center before turning to the other side.']::text[]),
('Spider Curl (EZ Bar)', 'biceps', array['forearms']::text[], 'barbell', 'weight_reps', '2kattbR', array['Stand and set your feet about shoulder width and hold the ez barbell with palms facing up.', 'Set your upper arms on a preacher bench or stability ball, letting your elbows to hang down.', 'Set the shoulders and upper arms before bending the elbows.', 'Bend your elbows to bring the weight toward your shoulders without swinging your torso.', 'Keep the torso quiet and let the elbow bend lift the weight.', 'Lower until the elbows are nearly straight, keeping the upper arms still.']::text[]),
('Single-Arm Shoulder Press (Machine)', 'shoulders', array['triceps', 'back']::text[], 'machine', 'weight_reps', '2KGnL6M', array['Fit the seat to your body, then settle into the machine.', 'Hold the lever handle with one hand and position your elbow at a 90-degree angle.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Keep both shoulders level and resist turning toward the working arm.', 'Lower the weight to its starting height under control before pressing again; switch sides when the set calls for it.']::text[]),
('Push-Up (Bosu Ball)', 'chest', array['triceps', 'shoulders', 'core']::text[], 'bodyweight', 'bodyweight_reps', '2kr2lWy', array['Set the bosu ball on the ground with the flat side facing up.', 'Set yourself in a push-up position with your hands on the outer edges of the bosu ball.', 'Brace the abdomen and glutes so the shoulders, hips and ankles move together.', 'Bend your elbows to lower your chest while keeping your body in one line.', 'Keep the head in line with the spine as the elbows bend.', 'Press back to straight arms, keeping the body line intact.']::text[]),
('Exercise Ball Hip Flexor Stretch', 'glutes', array['quads', 'hamstrings']::text[], 'bodyweight', 'duration', '2LQkNPW', array['Set the stability ball on the ground and kneel in front of it.', 'Set your right foot on top of the stability ball, with your knee bent at a 90-degree angle.', 'Settle into the starting position and take an easy breath before moving deeper.', 'Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.', 'Keep the ball steady and use the feet to manage your balance.', 'Hold the position with steady breathing, then release gently; repeat on the other side if needed.']::text[]),
('Biceps Curl on Exercise Ball with Leg Raised (Dumbbell)', 'biceps', array['forearms', 'shoulders']::text[], 'dumbbell', 'weight_reps', '2NImIAG', array['Take a seat on an exercise ball with your feet planted and your back straight.', 'Take a dumbbell in each hand with your palms facing forward and your arms straight.', 'Set the shoulders and upper arms before bending the elbows.', 'Bend your elbows to bring the weight toward your shoulders without swinging your torso.', 'Keep the ball steady and use the feet to manage your balance.', 'Lower until the elbows are nearly straight, keeping the upper arms still.']::text[]),
('Hack Calf Raise', 'calves', array['hamstrings', 'glutes']::text[], 'machine', 'weight_reps', '2ORFMoR', array['Set the sled machine to a comfortable weight.', 'Step onto the sled machine with your toes on the platform and your heels hanging off.', 'Let the ankles move freely while the rest of the body stays quiet.', 'Rise through the balls of your feet, lifting the heels as high as you can without rocking.', 'Pause at the top without rolling the ankles outward.', 'Lower the heels at a measured pace before rising again.']::text[]),
('Decline Press (Cable)', 'chest', array['triceps', 'shoulders']::text[], 'cable', 'weight_reps', '2Pya1cP', array['Set the cable machine to a decline position.', 'Take a seat on the decline bench facing the cable machine.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Keep the wrists stacked and use a shoulder path that feels natural.', 'Lower the weight to its starting height under control before pressing again.']::text[]),
('45° Leg Press (Machine)', 'glutes', array['quads', 'hamstrings', 'calves']::text[], 'machine', 'weight_reps', '2Qh2J1e', array['Set the seat of the sled machine so that your knees are at a 90-degree angle when your feet are on the footplate.', 'Take a seat on the sled machine with your back flat against the backrest and your feet about shoulder width on the footplate.', 'Set your feet firmly on the plate and keep the hips against the seat.', 'Bend the knees to bring the platform toward you, then press it away through the feet.', 'Stop the descent before the hips lift from the seat.', 'Bring the weight or body back to its starting position without rushing.']::text[]),
('Standing Back Wrist Curl (Barbell)', 'forearms', array['biceps', 'shoulders']::text[], 'barbell', 'weight_reps', '2qTvJAZ', array['Stand tall with your feet about shoulder width and hold a barbell with palms facing down.', 'Rest the barbell on the back of your hands with your palms facing down and your fingers pointing toward your body.', 'Keep the elbows relaxed so the small muscles of the hand or forearm take the load.', 'Move through the wrists or fingers while the forearms stay supported and still.', 'Use a small, smooth range without swinging the elbows.', 'Ease back to the start without letting the load fall from your hands.']::text[]),
('Prone Rectus Femoris Stretch (Assisted)', 'core', array['quads']::text[], 'bodyweight', 'duration', '2Ryn564', array['Position yourself face down on the ground with your legs straight.', 'Before moving, bend your right knee and reach back with your right hand to grab your right foot or ankle.', 'Settle into the starting position and take an easy breath before moving deeper.', 'Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.', 'Stay in a mild stretch rather than pulling farther with momentum.', 'Hold the position with steady breathing, then release gently; repeat on the other side if needed.']::text[]),
('Single-Arm Standing Hammer Curl (Dumbbell)', 'biceps', array['forearms']::text[], 'dumbbell', 'weight_reps', '2sQGZ5b', array['Stand tall with a dumbbell in each hand, palms facing your torso.', 'Hold your elbows near your torso and your upper arms stationary.', 'Set the shoulders and upper arms before bending the elbows.', 'Curl with palms facing each other and elbows near your sides; avoid rocking back.', 'Keep both shoulders level and resist turning toward the working arm.', 'Lower until the elbows are nearly straight, keeping the upper arms still; switch sides when the set calls for it.']::text[]),
('Stiff Leg Deadlift (Dumbbell)', 'glutes', array['hamstrings', 'back']::text[], 'dumbbell', 'weight_reps', '2Ty4idJ', array['Stand and set your feet about shoulder width, holding a dumbbell in each hand with palms facing down.', 'With your back straight and your core engaged, hinge at the hips and lower the dumbbells toward the ground, letting a slight bend in your knees.', 'Unlock the knees and brace the abdomen before moving the hips back.', 'Push the hips back while keeping the load close and the spine steady.', 'Keep the weight close to the legs and stop when the back would begin to round.', 'Drive the hips forward to stand tall without leaning back at the top.']::text[]),
('Wrist Circles', 'forearms', '{}'::text[], 'bodyweight', 'bodyweight_reps', '2zNKRUB', array['Reach your arms straight out in front of you.', 'Close both hands into fists.', 'Relax the limb above the joint you are circling.', 'Circle the joint slowly in one direction, then reverse the circle without forcing the range.', 'Keep the rest of the limb still while the joint traces each circle.', 'Switch to the other side after completing both directions.']::text[]),
('Front Raise and Pullover (Barbell)', 'chest', array['shoulders', 'triceps']::text[], 'barbell', 'weight_reps', '33AzZeV', array['Stand and set your feet about shoulder width and hold a barbell with palms facing down.', 'Maintain straight arms and raise the barbell in front of you until it reaches shoulder height.', 'Set the ribs down and keep a small elbow bend before lowering the weight.', 'Lower the weight in an arc behind your head until you feel a comfortable shoulder stretch.', 'Keep the ribs down as the arms travel overhead.', 'Pull the weight back over the chest along the same arc, without lifting the ribs.']::text[]),
('Bench Seated Press (Dumbbell)', 'shoulders', array['triceps', 'chest']::text[], 'dumbbell', 'weight_reps', '3d7wHyd', array['Take a seat on a bench with a dumbbell in each hand, resting on your thighs.', 'Recline and position the dumbbells to the sides of your chest, palms facing forward.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Keep the wrists stacked and use a shoulder path that feels natural.', 'Lower the weight to its starting height under control before pressing again.']::text[]),
('Front Raise (Dumbbell)', 'shoulders', array['biceps', 'traps']::text[], 'dumbbell', 'weight_reps', '3eGE2JC', array['Stand and set your feet about shoulder width, holding a dumbbell in each hand with your palms facing your thighs.', 'With your arms straight, exhale and lift the dumbbells in front of you until they are at shoulder level.', 'Start with a manageable load and a small bend in the elbows.', 'Lift the arms forward to about shoulder height, keeping the ribs down and torso still.', 'Stop near shoulder height rather than shrugging to lift higher.', 'Lower the arms slowly to your sides without swinging the weight.']::text[]),
('Twisting Pull (Cable)', 'back', array['shoulders', 'biceps']::text[], 'cable', 'weight_reps', '3nvEbbF', array['Connect a cable handle to a low pulley and stand facing the machine.', 'Hold the handle with your left hand and step away from the machine, extending your arm fully.', 'Set the pelvis and make the turn through the rib cage.', 'Turn through the torso while the hips and lower body stay as steady as the setup allows.', 'Keep the turn smooth instead of throwing the arms across the body.', 'Return through center before turning to the other side.']::text[]),
('Alternating Biceps Curl (Band)', 'biceps', array['forearms']::text[], 'band', 'weight_reps', '3omWx6P', array['Stand and set your feet about shoulder width and hold the band with palms facing up.', 'Hold your elbows near your sides and With control curl one arm up toward your shoulder, squeezing your biceps at the top.', 'Set the shoulders and upper arms before bending the elbows.', 'Bend your elbows to bring the weight toward your shoulders without swinging your torso.', 'Finish one side''s motion before the other side takes over.', 'Lower until the elbows are nearly straight, keeping the upper arms still; switch sides when the set calls for it.']::text[]),
('Alternating V-Up (Band)', 'core', '{}'::text[], 'band', 'weight_reps', '3pqGMQj', array['Settle onto your back with your legs straight and your arms extended overhead, holding the band.', 'Tighten your midsection and lift your legs and upper body off the ground simultaneously, reaching your hands toward your toes.', 'Set the pelvis and keep the neck relaxed before curling upward.', 'Raise your straight legs and torso together, reaching toward the feet before lowering under control.', 'Finish one side''s motion before the other side takes over.', 'Lower the shoulders or torso with control before the next curl; switch sides when the set calls for it.']::text[]),
('Wide Reverse-Grip Bench Press (Barbell)', 'chest', array['triceps', 'shoulders']::text[], 'barbell', 'weight_reps', '3QgteDK', array['Settle onto a bench with your feet planted and your back pressed against the bench.', 'Hold the barbell with a wide reverse grip, just beyond shoulder width.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Keep the palms in the chosen grip without bending the wrists back.', 'Lower the weight to its starting height under control before pressing again.']::text[]),
('Standing Bent Over Two-Arm Triceps Extension (Dumbbell)', 'triceps', array['shoulders', 'back']::text[], 'dumbbell', 'weight_reps', '3T12T87', array['Stand and set your feet about shoulder width and hold a dumbbell in each hand.', 'Bend forward at the waist, with your spine steady and your knees soft.', 'Set the upper arms in place before extending the elbows.', 'Keep the upper arms steady and extend through the elbows to move the weight.', 'Keep the upper arms steady while the forearms travel.', 'Bend the elbows slowly to return to the start of the next rep.']::text[]),
('Over Bench Reverse Wrist Curl (Dumbbell)', 'forearms', array['biceps']::text[], 'dumbbell', 'weight_reps', '3tAXPQ6', array['Plant both feet while seated on a bench; hold a dumbbell in each hand, palms facing down.', 'Support the forearms on the bench while leaving the wrists free beyond its edge.', 'Keep the elbows relaxed so the small muscles of the hand or forearm take the load.', 'Move through the wrists or fingers while the forearms stay supported and still.', 'Use a small, smooth range without swinging the elbows.', 'Ease back to the start without letting the load fall from your hands.']::text[]),
('Dynamic Chest Stretch', 'chest', array['shoulders', 'triceps']::text[], 'bodyweight', 'duration', '3uj0Ozg', array['Stand tall and set your feet about shoulder width.', 'Reach your arms straight out to the sides, parallel to the ground.', 'Settle into the starting position and take an easy breath before moving deeper.', 'Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.', 'Stay in a mild stretch rather than pulling farther with momentum.', 'Hold the position with steady breathing, then release gently; repeat on the other side if needed.']::text[]),
('Squatting Curl (Cable)', 'biceps', array['forearms']::text[], 'cable', 'weight_reps', '3XFdb1Z', array['Connect a cable handle to the lowest setting on a cable machine.', 'Face the machine from a stable stance with feet about shoulder width.', 'Brace the abdomen and spread pressure across the whole foot.', 'Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.', 'Drive upward with the chest and hips rising together; keep the knees from collapsing inward.', 'Stand fully, reset your footing and breathing, then begin the next descent.']::text[]),
('Bodyweight Squatting Row', 'back', array['biceps', 'shoulders']::text[], 'bodyweight', 'bodyweight_reps', '3xK09Sk', array['Stand and set your feet about shoulder width, holding onto a sturdy object or suspension trainer with your arms extended.', 'Lower your body into a squat position, with your spine steady and your knees behind your toes.', 'Brace the abdomen and spread pressure across the whole foot.', 'Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.', 'Drive upward with the chest and hips rising together; keep the knees from collapsing inward.', 'Stand fully, reset your footing and breathing, then begin the next descent.']::text[]),
('Pushdown (Cable)', 'triceps', array['forearms']::text[], 'cable', 'weight_reps', '3ZflifB', array['Connect a straight bar to a high pulley cable machine.', 'Face the machine with your feet about shoulder width and a slight bend in your knees.', 'Stand far enough from the stack for the cable to stay taut.', 'Keep your elbows near your ribs and straighten your arms against the cable.', 'Keep the elbows close to the body instead of letting the shoulders swing.', 'Ease back to the start before repeating.']::text[]),
('Lateral Pulldown with V-Bar (Cable)', 'back', array['biceps', 'forearms']::text[], 'cable', 'weight_reps', '4c9BhzB', array['Sit down on the cable pulldown machine and grab the v-bar attachment with palms facing down.', 'Set the knee pad so that your thighs are secured under it.', 'Sit tall and set the shoulders before drawing the handle down.', 'Pull the handle down by driving your elbows toward your ribs; keep your torso steady.', 'Pull with the elbows rather than leaning far back to move the handle.', 'Let the handle rise steadily until the arms are long, then reset the shoulders.']::text[]),
('Seated Close-Grip Behind Neck Triceps Extension (Barbell)', 'triceps', array['shoulders']::text[], 'barbell', 'weight_reps', '4CBIBOM', array['Take a seat on a bench with your back straight and feet planted.', 'Take hold of the barbell with a close grip behind your neck, palms facing forward.', 'Set the upper arms in place before extending the elbows.', 'Keep the upper arms steady and extend through the elbows to move the weight.', 'Keep the upper arms steady while the forearms travel.', 'Bend the elbows slowly to return to the start of the next rep.']::text[]),
('Narrow Push-Up on Exercise Ball', 'triceps', array['chest', 'shoulders']::text[], 'bodyweight', 'bodyweight_reps', '4cWjYEN', array['Set the stability ball on the ground and position yourself in a push-up position with your hands on the ball, slightly narrower than about shoulder width.', 'Brace your trunk and keep your body in a straight line from head to toe.', 'Brace the abdomen and glutes so the shoulders, hips and ankles move together.', 'Bend your elbows to lower your chest while keeping your body in one line.', 'Keep the ball steady and use the feet to manage your balance.', 'Press back to straight arms, keeping the body line intact.']::text[]),
('Single-Arm Hammer Preacher Curl (Dumbbell)', 'biceps', array['forearms']::text[], 'dumbbell', 'weight_reps', '4dF3maG', array['Take a seat on a preacher bench with a dumbbell in one hand and your upper arm resting on the pad.', 'Take hold of the dumbbell with a neutral grip (palms facing your body).', 'Set the working upper arm against the preacher pad and leave the elbow free to bend.', 'Curl the weight while your upper arms stay in contact with the pad.', 'Keep both shoulders level and resist turning toward the working arm.', 'Lower until the elbows are nearly straight, keeping the upper arms still; switch sides when the set calls for it.']::text[]),
('Standing Close-Grip Curl (Barbell)', 'biceps', array['forearms']::text[], 'barbell', 'weight_reps', '4dUn2iv', array['Stand tall with your feet about shoulder width and hold a barbell with palms facing up, hands close together.', 'Hold your elbows near your torso and your upper arms stationary throughout the movement.', 'Set the shoulders and upper arms before bending the elbows.', 'Bend your elbows to bring the weight toward your shoulders without swinging your torso.', 'Keep the torso quiet and let the elbow bend lift the weight.', 'Lower until the elbows are nearly straight, keeping the upper arms still.']::text[]),
('Standing Row (V-Bar) (Cable)', 'back', array['biceps', 'shoulders']::text[], 'cable', 'weight_reps', '4f8RXP8', array['Face the cable machine from a stable stance with feet about shoulder width.', 'Hold the v-bar attachment with palms facing down.', 'Set the torso and allow the arms to reach forward without rounding excessively.', 'Draw your elbows back and bring the handle or weight toward your torso.', 'Bring the elbows back without jerking the torso.', 'Reach the arms forward again without letting the torso lurch.']::text[]),
('Superman Push-Up', 'chest', array['core', 'shoulders']::text[], 'bodyweight', 'bodyweight_reps', '4GqRrAk', array['Begin in a high plank position with your hands just beyond shoulder width and your feet together.', 'Brace your trunk and lower your body toward the ground, keeping your elbows close to your sides.', 'Brace the abdomen and glutes so the shoulders, hips and ankles move together.', 'Bend your elbows to lower your chest while keeping your body in one line.', 'Keep the head in line with the spine as the elbows bend.', 'Press back to straight arms, keeping the body line intact.']::text[]),
('45 Degrees Single-Leg Press (Machine)', 'glutes', array['quads', 'hamstrings', 'calves']::text[], 'machine', 'weight_reps', '4H86mXM', array['Set the sled machine to a 45-degree angle.', 'Take a seat on the sled machine with your back against the pad and your feet on the footplate.', 'Set your feet firmly on the plate and keep the hips against the seat.', 'Bend the knees to bring the platform toward you, then press it away through the feet.', 'Keep the pelvis level as the supporting leg does the work.', 'Ease back to the start before repeating; switch sides when the set calls for it.']::text[]),
('Single-Arm Cable Rope Preacher Curl', 'biceps', array['forearms']::text[], 'cable', 'weight_reps', '4hATdoB', array['Connect a rope handle to a low pulley cable machine.', 'Face the machine from a stable stance with feet about shoulder width.', 'Set the working upper arm against the preacher pad and leave the elbow free to bend.', 'Curl the weight while your upper arms stay in contact with the pad.', 'Keep both shoulders level and resist turning toward the working arm.', 'Lower until the elbows are nearly straight, keeping the upper arms still; switch sides when the set calls for it.']::text[]),
('Seated Bent Over Triceps Extension (Dumbbell)', 'triceps', array['shoulders', 'back']::text[], 'dumbbell', 'weight_reps', '4ievMJ9', array['Plant both feet while seated on a bench; hold a dumbbell in each hand.', 'Bend forward at the waist, with your spine steady and your head up.', 'Set the upper arms in place before extending the elbows.', 'Keep the upper arms steady and extend through the elbows to move the weight.', 'Keep the upper arms steady while the forearms travel.', 'Bend the elbows slowly to return to the start of the next rep.']::text[]),
('Alternate Lateral Pulldown', 'back', array['biceps']::text[], 'cable', 'weight_reps', '4IKbhHV', array['Take a seat on the cable machine with your back straight and feet planted.', 'Hold the handles with palms facing down, just beyond shoulder width.', 'Sit tall and set the shoulders before drawing the handle down.', 'Pull the handle down by driving your elbows toward your ribs; keep your torso steady.', 'Finish one side''s motion before the other side takes over.', 'Let the handle rise steadily until the arms are long, then reset the shoulders; switch sides when the set calls for it.']::text[]),
('Over Bench Single-Arm Reverse Wrist Curl (Dumbbell)', 'forearms', array['biceps']::text[], 'dumbbell', 'weight_reps', '4Jc36XM', array['Plant both feet while seated on a bench; hold a dumbbell in one hand, palm facing down.', 'Set your forearm on the bench with your wrist hanging off the edge.', 'Keep the elbows relaxed so the small muscles of the hand or forearm take the load.', 'Move through the wrists or fingers while the forearms stay supported and still.', 'Keep both shoulders level and resist turning toward the working arm.', 'Ease back to the start without letting the load fall from your hands; switch sides when the set calls for it.']::text[]),
('Bottoms Up Clean From the Hang Position (Kettlebell)', 'biceps', array['forearms', 'shoulders']::text[], 'kettlebell', 'duration', '4KJEpzb', array['Stand and set your feet about shoulder width, holding a kettlebell in one hand with palms facing down.', 'Bend your knees slightly and hinge forward at the hips, with your spine steady and chest up.', 'Brace before the pull and keep the load close to the body.', 'Drive through the legs and hips, then guide the weight to its receiving position.', 'Receive the load with the torso braced and feet stable.', 'Stand tall to finish, then lower the weight under control before the next rep.']::text[]),
('Skier (Barbell)', 'shoulders', array['triceps', 'core']::text[], 'barbell', 'weight_reps', '4Leypho', array['Stand and set your feet about shoulder width and hold a barbell ahead of your thighs with palms facing down.', 'Bend your knees slightly and hinge forward at the hips, with your spine steady and chest up.', 'Brace before the pull and keep the load close to the body.', 'Drive through the legs and hips, then guide the weight to its receiving position.', 'Receive the load with the torso braced and feet stable.', 'Stand tall to finish, then lower the weight under control before the next rep.']::text[]),
('Reverse Preacher Curl (Barbell)', 'biceps', array['forearms']::text[], 'barbell', 'weight_reps', '4LIG9xr', array['Take a seat on a preacher bench with your chest against the pad and your arms extended straight down, holding a barbell with palms facing down.', 'With your upper arms stationary, exhale and curl the barbell upward while contracting your biceps.', 'Set the working upper arm against the preacher pad and leave the elbow free to bend.', 'Curl the weight while your upper arms stay in contact with the pad.', 'Keep the torso quiet and let the elbow bend lift the weight.', 'Lower until the elbows are nearly straight, keeping the upper arms still.']::text[]),
('Fixed Back Close-Grip Pulldown (Band)', 'back', array['biceps', 'forearms']::text[], 'band', 'weight_reps', '4LoWllp', array['Connect the band to a fixed point above you, such as a pull-up bar or sturdy beam.', 'Sit down on a bench or chair facing the band, with your feet planted and your knees bent.', 'Sit tall and set the shoulders before drawing the handle down.', 'Pull the handle down by driving your elbows toward your ribs; keep your torso steady.', 'Control the band on the way back instead of letting it snap you into position.', 'Let the handle rise steadily until the arms are long, then reset the shoulders.']::text[]),
('Hanging Straight-Leg Raise', 'core', '{}'::text[], 'bodyweight', 'bodyweight_reps', '4Ml7QFO', array['Suspend yourself from a pull-up bar with your arms straight and your palms turned away from you.', 'Brace your trunk and lift your legs up in front of you, keeping them straight.', 'Brace the abdomen and keep the shoulders anchored to the support.', 'Lift your legs by bracing your trunk and moving at the hips rather than swinging.', 'Slow the legs before they pull the lower back out of position.', 'Lower the legs slowly without swinging or losing your trunk position.']::text[]),
('Suspended Row', 'back', array['biceps', 'shoulders']::text[], 'bodyweight', 'bodyweight_reps', '4OaumBr', array['Prepare a suspension trainer at an appropriate height.', 'Face the anchor point from a stable stance with feet about shoulder width.', 'Set the torso and allow the arms to reach forward without rounding excessively.', 'Draw your elbows back and bring the handle or weight toward your torso.', 'Bring the elbows back without jerking the torso.', 'Reach the arms forward again without letting the torso lurch.']::text[]),
('Pullover (Machine)', 'back', array['triceps', 'shoulders']::text[], 'machine', 'weight_reps', '4U7iLb5', array['Set the seat and handles of the leverage machine to a comfortable position.', 'Take a seat on the machine with your back against the pad and Hold the handles with palms facing down.', 'Set the ribs down and keep a small elbow bend before lowering the weight.', 'Lower the weight in an arc behind your head until you feel a comfortable shoulder stretch.', 'Keep the ribs down as the arms travel overhead.', 'Pull the weight back over the chest along the same arc, without lifting the ribs.']::text[]),
('Seated Chest Press (Band)', 'chest', array['shoulders', 'triceps']::text[], 'band', 'weight_reps', '4x5Okof', array['Take a seat on a chair or bench with your back straight and feet planted.', 'Take hold of the resistance band handles in each hand, with your palms facing down and elbows bent at a 90-degree angle.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Control the band on the way back instead of letting it snap you into position.', 'Lower the weight to its starting height under control before pressing again.']::text[]),
('Biceps Narrow Pull-Ups', 'biceps', array['forearms', 'shoulders']::text[], 'bodyweight', 'bodyweight_reps', '50BETrz', array['Suspend yourself from a pull-up bar with your palms facing toward you and your hands about shoulder width.', 'Brace your trunk and pull yourself up toward the bar, focusing on using your biceps to lift your body.', 'Begin from a controlled hang with the shoulders active rather than slack.', 'Pull your elbows down and bring your upper chest toward the bar without kicking your legs.', 'Avoid swinging the legs to clear the bar.', 'Lower to long arms without dropping suddenly from the top.']::text[]),
('Lying Rear Lateral Raise (Dumbbell)', 'shoulders', array['traps', 'back']::text[], 'dumbbell', 'weight_reps', '53Ttlck', array['Position yourself face down on a flat bench with a dumbbell in each hand, palms facing each other.', 'Extend your arms straight down toward the floor, keeping a slight bend in your elbows.', 'Start with a manageable load and a small bend in the elbows.', 'Raise the arms out to the sides to about shoulder height without leaning or shrugging.', 'Stop near shoulder height rather than shrugging to lift higher.', 'Lower the arms slowly to your sides without swinging the weight.']::text[]),
('Jack Knife Sit-Up (Band)', 'core', '{}'::text[], 'band', 'weight_reps', '58rdhvL', array['Settle onto your back with your legs straight and your arms extended overhead, holding the band.', 'Tighten your midsection and lift your legs and upper body simultaneously, bringing your hands toward your feet.', 'Set the pelvis and keep the neck relaxed before curling upward.', 'Curl your rib cage toward your pelvis, letting the abdominals move the torso.', 'Control the band on the way back instead of letting it snap you into position.', 'Lower the shoulders or torso with control before the next curl.']::text[]),
('Pistol Squat (Kettlebell)', 'glutes', array['quads', 'hamstrings', 'calves']::text[], 'kettlebell', 'weight_reps', '5bpPTHv', array['Stand and set your feet about shoulder width, holding a kettlebell ahead of your chest with both hands.', 'Before moving, lift your left foot off the ground and extend it forward, keeping it parallel to the ground.', 'Brace the abdomen and spread pressure across the whole foot.', 'Extend the free leg ahead of you as you squat on the standing leg, keeping its heel grounded.', 'Drive upward with the chest and hips rising together; keep the knees from collapsing inward.', 'Stand fully, reset your footing and breathing, then begin the next descent.']::text[]),
('Squat to Overhead Reach with Twist', 'quads', array['glutes', 'hamstrings', 'core']::text[], 'bodyweight', 'bodyweight_reps', '5BZHW9s', array['Stand and set your feet about shoulder width and toes slightly turned out.', 'Before moving, lower your body into a squat position by bending your knees and pushing your hips back.', 'Brace the abdomen and spread pressure across the whole foot.', 'Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.', 'Drive upward with the chest and hips rising together; keep the knees from collapsing inward.', 'Stand fully, reset your footing and breathing, then begin the next descent.']::text[]),
('Seated Reverse-Grip Single-Arm Overhead Triceps Extension (Dumbbell)', 'triceps', array['shoulders']::text[], 'dumbbell', 'weight_reps', '5fKX7wi', array['Take a seat on a bench with your back straight and feet planted.', 'Take a dumbbell with palms facing up and extend your arm straight up overhead.', 'Set the upper arms in place before extending the elbows.', 'Keep the upper arms pointed upward and extend at the elbows without flaring the ribs.', 'Keep both shoulders level and resist turning toward the working arm.', 'Bend the elbows slowly to return to the start of the next rep; switch sides when the set calls for it.']::text[]),
('Pull-Up (Assisted)', 'back', array['biceps', 'forearms']::text[], 'machine', 'weight_reps', '5ipN0iE', array['Set the machine to your desired weight and height settings.', 'Hold the handles with palms facing down, just beyond shoulder width.', 'Begin from a controlled hang with the shoulders active rather than slack.', 'Pull your elbows down and bring your upper chest toward the bar without kicking your legs.', 'Avoid swinging the legs to clear the bar.', 'Lower to long arms without dropping suddenly from the top.']::text[]),
('Alternating Press (Kettlebell)', 'shoulders', array['triceps', 'core']::text[], 'kettlebell', 'weight_reps', '5KLbZWx', array['Stand and set your feet about shoulder width, holding a kettlebell in each hand at shoulder height.', 'Before moving, press one kettlebell overhead, fully extending your arm.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Finish one side''s motion before the other side takes over.', 'Lower the weight to its starting height under control before pressing again; switch sides when the set calls for it.']::text[]),
('Bent Over Row (Smith Machine)', 'back', array['biceps', 'forearms']::text[], 'machine', 'weight_reps', '5lE7XRz', array['Prepare the smith machine with the bar at hip height.', 'Face the bar from a stable stance with feet about shoulder width.', 'Set the torso and allow the arms to reach forward without rounding excessively.', 'Draw your elbows back and bring the handle or weight toward your torso.', 'Bring the elbows back without jerking the torso.', 'Reach the arms forward again without letting the torso lurch.']::text[]),
('Ski Step', 'cardio', array['quads', 'hamstrings', 'glutes', 'calves']::text[], 'bodyweight', 'duration', '5MRH8H2', array['Stand and set your feet about shoulder width.', 'Bend your knees slightly and Keep your spine in a comfortable neutral position.', 'Start at a pace that lets the feet and arms move in sync.', 'Bound from side to side, landing on one foot as the other leg sweeps behind it.', 'Keep the pattern repeatable as speed increases.', 'Keep the rhythm for the planned interval, slowing if your form starts to slip.']::text[]),
('Seated Overhead Triceps Extension (Barbell)', 'triceps', array['shoulders']::text[], 'barbell', 'weight_reps', '5uFK1xr', array['Take a seat on a bench with your back straight and feet planted.', 'Take a barbell with palms facing down, hands about shoulder width, and raise it overhead.', 'Set the upper arms in place before extending the elbows.', 'Keep the upper arms pointed upward and extend at the elbows without flaring the ribs.', 'Keep the upper arms steady while the forearms travel.', 'Bend the elbows slowly to return to the start of the next rep.']::text[]),
('Incline Bench Press (Smith Machine)', 'chest', array['shoulders', 'triceps']::text[], 'machine', 'weight_reps', '5v7KYld', array['Set the bench to a 30-45 degree incline.', 'Take a seat on the bench with your back flat against the pad and feet firmly on the ground.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Keep the wrists stacked and use a shoulder path that feels natural.', 'Lower the weight to its starting height under control before pressing again.']::text[]),
('Hack Squat (Barbell)', 'glutes', array['quads', 'hamstrings', 'calves']::text[], 'barbell', 'weight_reps', '5VCj6iH', array['Begin by standing with your feet about shoulder width and your toes slightly turned out.', 'Take hold of the barbell behind your legs, resting it on your upper thighs.', 'Brace the abdomen and spread pressure across the whole foot.', 'Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.', 'Drive upward with the chest and hips rising together; keep the knees from collapsing inward.', 'Stand fully, reset your footing and breathing, then begin the next descent.']::text[]),
('Scott Press (Dumbbell)', 'shoulders', array['triceps', 'chest']::text[], 'dumbbell', 'weight_reps', '5vfAI0I', array['Take a seat on a bench with a dumbbell in each hand, palms facing forward.', 'Before moving, raise the dumbbells to shoulder height, with your elbows bent and palms facing forward.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Keep the wrists stacked and use a shoulder path that feels natural.', 'Lower the weight to its starting height under control before pressing again.']::text[]),
('Bodyweight Incline Side Plank', 'core', array['shoulders']::text[], 'bodyweight', 'duration', '5VXmnV5', array['Begin by lying on your side with your legs extended and stacked on top of each other.', 'Set your forearm on the ground directly below your shoulder, with your elbow bent at a 90-degree angle.', 'Brace the abdomen and find a position you can maintain without holding your breath.', 'Brace your midsection and hold the position while breathing normally.', 'Keep breathing steadily as you maintain the same body line.', 'Keep the shape for the planned time, then come out of it with control.']::text[]),
('Lunge with Swing (Weighted)', 'glutes', array['quads', 'hamstrings', 'calves']::text[], 'bodyweight', 'bodyweight_reps', '5WiFcYk', array['Stand and set your feet about shoulder width, holding a weight in each hand.', 'Step forward with your right foot, lowering your body into a lunge position.', 'Set the shoulders and let the weight move back between the legs as the hips hinge.', 'Hinge back, then drive the hips forward to send the weight up; let the arms guide it.', 'Let the hips, not the shoulders, provide the power.', 'Let the weight fall naturally and hinge again for the next swing.']::text[]),
('Lying Close-Grip Curl (Cable)', 'biceps', array['forearms']::text[], 'cable', 'weight_reps', '61GrD55', array['Connect a straight bar to a low pulley cable machine.', 'Lie face up on a flat bench with your feet planted.', 'Set the shoulders and upper arms before bending the elbows.', 'Bend your elbows to bring the weight toward your shoulders without swinging your torso.', 'Keep the torso quiet and let the elbow bend lift the weight.', 'Lower until the elbows are nearly straight, keeping the upper arms still.']::text[]),
('Rear Lunge (Barbell)', 'glutes', array['quads', 'hamstrings', 'calves']::text[], 'barbell', 'weight_reps', '62Nw60O', array['Stand and set your feet about shoulder width and hold a barbell across your upper back.', 'Step backward with your right foot, landing on the ball of your foot.', 'Set your stance wide enough to balance before bending either knee.', 'Step into the movement and bend both knees, keeping your front foot planted.', 'Keep the front foot planted and avoid collapsing inward at the knee.', 'Push through the lead foot to return to the start, then change legs as planned.']::text[]),
('Incline Reverse-Grip Press (Barbell)', 'triceps', array['chest', 'shoulders']::text[], 'barbell', 'weight_reps', '641mIfk', array['Angle the bench to roughly 45 degrees.', 'Recline on the bench and Hold the barbell with a reverse grip, hands just beyond shoulder width.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Keep the palms in the chosen grip without bending the wrists back.', 'Lower the weight to its starting height under control before pressing again.']::text[]),
('Shoulder Press (Machine)', 'shoulders', array['triceps', 'chest']::text[], 'machine', 'weight_reps', '67n3r98', array['Fit the seat to your body, then settle into the machine.', 'Hold the handles with palms facing down and position your hands at shoulder level.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Keep the wrists stacked and use a shoulder path that feels natural.', 'Lower the weight to its starting height under control before pressing again.']::text[]),
('Side Bend (On Stability Ball) (Weighted)', 'core', array['back']::text[], 'bodyweight', 'weight_reps', '6bOA1Oi', array['Take a seat on a stability ball with your feet about shoulder width and flat on the ground.', 'Take a weight in one hand and place your other hand on your hip.', 'Stand or sit tall with the pelvis facing forward.', 'Bend sideways through the waist without twisting or letting the hips shift.', 'Keep the ball steady and use the feet to manage your balance.', 'Bring the weight or body back to its starting position without rushing.']::text[]),
('Single-Arm Upright Row (Dumbbell)', 'shoulders', array['traps', 'biceps']::text[], 'dumbbell', 'weight_reps', '6cKQC5E', array['Stand and set your feet about shoulder width, holding a dumbbell in one hand with palms facing down.', 'Let the dumbbell hang at arm''s length ahead of your thighs, with your palm facing your body.', 'Set the torso and allow the arms to reach forward without rounding excessively.', 'Draw your elbows back and bring the handle or weight toward your torso.', 'Keep both shoulders level and resist turning toward the working arm.', 'Reach the arms forward again without letting the torso lurch; switch sides when the set calls for it.']::text[]),
('Lying Close-Grip Triceps Extension Behind Head (EZ Bar)', 'triceps', array['shoulders']::text[], 'barbell', 'weight_reps', '6CKUx7o', array['Settle onto a bench with your feet planted and your head at the end of the bench.', 'Take hold of the ez barbell with a close grip, palms facing up, and extend your arms straight up over your chest.', 'Set the upper arms in place before extending the elbows.', 'Keep the upper arms steady and extend through the elbows to move the weight.', 'Keep the upper arms steady while the forearms travel.', 'Bend the elbows slowly to return to the start of the next rep.']::text[]),
('Incline Shoulder Raise (Dumbbell)', 'chest', array['shoulders', 'traps']::text[], 'dumbbell', 'weight_reps', '6e2DcYX', array['Angle an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing down.', 'Set the dumbbells on your thighs and lean back onto the bench.', 'Start with a manageable load and a small bend in the elbows.', 'Lift the weights away from your torso to about shoulder height, keeping the elbows softly bent.', 'Stop near shoulder height rather than shrugging to lift higher.', 'Lower the arms slowly to your sides without swinging the weight.']::text[]),
('Alternate Seated Hammer Curl (Dumbbell)', 'biceps', array['forearms']::text[], 'dumbbell', 'weight_reps', '6em2Dxj', array['Take a seat on a bench with a dumbbell in each hand, palms facing your torso and arms extended down.', 'Keep your spine in a comfortable neutral position and your elbows close to your torso.', 'Set the shoulders and upper arms before bending the elbows.', 'Curl with palms facing each other and elbows near your sides; avoid rocking back.', 'Finish one side''s motion before the other side takes over.', 'Lower until the elbows are nearly straight, keeping the upper arms still; switch sides when the set calls for it.']::text[]),
('Semi Squat Jump', 'cardio', array['quads', 'hamstrings', 'calves']::text[], 'bodyweight', 'duration', '6FMU51h', array['Stand and set your feet about shoulder width.', 'Before moving, bend your knees and lower your body into a squat position.', 'Brace the abdomen and spread pressure across the whole foot.', 'Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.', 'Drive upward with the chest and hips rising together; keep the knees from collapsing inward.', 'Stand fully, reset your footing and breathing, then begin the next descent.']::text[]),
('Standing Rocking Leg Calf Raise (Barbell)', 'calves', array['hamstrings', 'quads']::text[], 'barbell', 'weight_reps', '6HiHHe0', array['Stand and set your feet about shoulder width and hold a barbell across your upper back.', 'Before moving, raise your heels off the ground as high as possible, balancing on the balls of your feet.', 'Let the ankles move freely while the rest of the body stays quiet.', 'Rise through the balls of your feet, lifting the heels as high as you can without rocking.', 'Pause at the top without rolling the ankles outward.', 'Lower the heels at a measured pace before rising again.']::text[]),
('Standing Calf Raise (On a Staircase)', 'calves', '{}'::text[], 'bodyweight', 'bodyweight_reps', '6HmFgmx', array['Step onto the edge of a step or a sturdy platform with your heels hanging off and your toes on the step.', 'Use a railing or wall for balance if needed.', 'Let the ankles move freely while the rest of the body stays quiet.', 'Rise through the balls of your feet, lifting the heels as high as you can without rocking.', 'Pause at the top without rolling the ankles outward.', 'Lower the heels at a measured pace before rising again.']::text[]),
('Wrist Curl (Barbell)', 'forearms', array['biceps']::text[], 'barbell', 'weight_reps', '6kSxYnw', array['Plant both feet while seated on a bench; your knees bent.', 'Take a barbell with palms facing up, and your hands about shoulder width.', 'Keep the elbows relaxed so the small muscles of the hand or forearm take the load.', 'Move through the wrists or fingers while the forearms stay supported and still.', 'Use a small, smooth range without swinging the elbows.', 'Ease back to the start without letting the load fall from your hands.']::text[]),
('Standing Leg Calf Raise (Smith Machine)', 'calves', array['hamstrings', 'glutes']::text[], 'machine', 'weight_reps', '6MaEjVA', array['Set the smith machine bar to a height that allows you to stand with your feet planted and your shoulders under the bar.', 'Set yourself under the bar with your feet about shoulder width and your toes pointing forward.', 'Let the ankles move freely while the rest of the body stays quiet.', 'Rise through the balls of your feet, lifting the heels as high as you can without rocking.', 'Pause at the top without rolling the ankles outward.', 'Lower the heels at a measured pace before rising again.']::text[]),
('Lying Single Extension (Dumbbell)', 'triceps', array['shoulders']::text[], 'dumbbell', 'weight_reps', '6MfS53i', array['Settle onto a bench with a dumbbell in one hand and your arm straight above your chest.', 'Lower the dumbbell in a controlled manner toward your forehead, keeping your upper arm stationary.', 'Set the upper arms in place before extending the elbows.', 'Keep the upper arms steady and extend through the elbows to move the weight.', 'Keep the upper arms steady while the forearms travel.', 'Bend the elbows slowly to return to the start of the next rep.']::text[]),
('Single-Arm Snatch (Dumbbell)', 'glutes', array['hamstrings', 'quads', 'core']::text[], 'dumbbell', 'weight_reps', '6pTkI99', array['Stand and set your feet about shoulder width, holding a dumbbell in one hand with palms facing down.', 'Bend your knees slightly and hinge forward at the hips, with your spine steady and chest up.', 'Brace before the pull and keep the load close to the body.', 'Drive through the legs and hips, then guide the weight to its receiving position.', 'Keep both shoulders level and resist turning toward the working arm.', 'Stand tall to finish, then lower the weight under control before the next rep; switch sides when the set calls for it.']::text[]),
('Reverse Spider Curl (Dumbbell)', 'biceps', array['forearms']::text[], 'dumbbell', 'weight_reps', '6sMAmNv', array['Stand tall with a dumbbell in each hand, palms facing your body and arms straight.', 'With your upper arms stationary, exhale and curl the weights while contracting your biceps.', 'Set the shoulders and upper arms before bending the elbows.', 'Curl the weight with your palms facing down, keeping the elbows close and torso still.', 'Keep the torso quiet and let the elbow bend lift the weight.', 'Lower until the elbows are nearly straight, keeping the upper arms still.']::text[]),
('Bent Knee Lying Twist', 'glutes', array['core']::text[], 'bodyweight', 'bodyweight_reps', '6sYyrRX', array['Settle onto your back with your knees bent and feet planted.', 'Reach your arms out to the sides, perpendicular to your body.', 'Set the pelvis and make the turn through the rib cage.', 'Turn through the torso while the hips and lower body stay as steady as the setup allows.', 'Keep the turn smooth instead of throwing the arms across the body.', 'Return through center before turning to the other side.']::text[]),
('Single-Arm Incline Press on Exercise Ball (Cable)', 'chest', array['shoulders', 'triceps']::text[], 'cable', 'weight_reps', '6t00BsF', array['Take a seat on an exercise ball with your feet planted and your back resting against an incline bench.', 'Take a cable handle in one hand and position your arm at a 90-degree angle with your elbow bent.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Keep both shoulders level and resist turning toward the working arm.', 'Lower the weight to its starting height under control before pressing again; switch sides when the set calls for it.']::text[]),
('Curl (EZ Bar)', 'biceps', array['forearms']::text[], 'barbell', 'weight_reps', '6TG6x2w', array['Stand tall with your feet about shoulder width and hold the ez barbell with palms facing up.', 'Hold your elbows near your torso and your upper arms stationary throughout the movement.', 'Set the shoulders and upper arms before bending the elbows.', 'Bend your elbows to bring the weight toward your shoulders without swinging your torso.', 'Keep the torso quiet and let the elbow bend lift the weight.', 'Lower until the elbows are nearly straight, keeping the upper arms still.']::text[]),
('Twisted Leg Raise', 'core', '{}'::text[], 'bodyweight', 'bodyweight_reps', '6Wr0F3W', array['Settle onto your back with your legs extended and your arms by your sides.', 'Bend your knees and lift your legs off the ground, bringing them toward your chest.', 'Brace the abdomen and keep the shoulders anchored to the support.', 'Lift your legs by bracing your trunk and moving at the hips rather than swinging.', 'Slow the legs before they pull the lower back out of position.', 'Lower the legs slowly without swinging or losing your trunk position.']::text[]),
('Quads (Bodyweight Squat)', 'quads', array['hamstrings', 'glutes']::text[], 'bodyweight', 'bodyweight_reps', '6YUfHPL', array['Stand and set your feet about shoulder width.', 'Before moving, lower your body by bending your knees and pushing your hips back as if sitting on a chair.', 'Brace the abdomen and spread pressure across the whole foot.', 'Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.', 'Drive upward with the chest and hips rising together; keep the knees from collapsing inward.', 'Stand fully, reset your footing and breathing, then begin the next descent.']::text[]),
('Sit-Up with Arms on Chest', 'core', '{}'::text[], 'bodyweight', 'bodyweight_reps', '6ZCiYWQ', array['Settle onto your back with your knees bent and feet planted.', 'Fold your arms over your chest.', 'Set the pelvis and keep the neck relaxed before curling upward.', 'Curl your rib cage toward your pelvis, letting the abdominals move the torso.', 'Leave a little space between the chin and chest; keep the movement in the torso.', 'Lower the shoulders or torso with control before the next curl.']::text[]),
('Archer Pull-Up', 'back', array['biceps', 'forearms']::text[], 'bodyweight', 'bodyweight_reps', '72BC5Za', array['Begin by hanging from a pull-up bar with palms facing down, just beyond shoulder width.', 'Brace your trunk and pull your shoulder blades down and back.', 'Begin from a controlled hang with the shoulders active rather than slack.', 'Pull your elbows down and bring your upper chest toward the bar without kicking your legs.', 'Avoid swinging the legs to clear the bar.', 'Lower to long arms without dropping suddenly from the top.']::text[]),
('Potty Squat', 'core', array['quads', 'glutes']::text[], 'bodyweight', 'bodyweight_reps', '75Bgtjy', array['Stand and set your feet about shoulder width, toes pointing slightly outward.', 'Before moving, lower your body down by bending your knees and pushing your hips back as if you were sitting on a chair.', 'Brace the abdomen and spread pressure across the whole foot.', 'Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.', 'Drive upward with the chest and hips rising together; keep the knees from collapsing inward.', 'Stand fully, reset your footing and breathing, then begin the next descent.']::text[]),
('Step Up Single Leg Balance with Biceps Curl (Dumbbell)', 'biceps', array['quads', 'glutes', 'hamstrings']::text[], 'dumbbell', 'weight_reps', '76vfTdU', array['Take your place in front of a step or platform with a dumbbell in each hand, palms facing your body.', 'Set your right foot on the step, ensuring your entire foot is in contact with the surface.', 'Set the shoulders and upper arms before bending the elbows.', 'Bend your elbows to bring the weight toward your shoulders without swinging your torso.', 'Keep the torso quiet and let the elbow bend lift the weight.', 'Lower until the elbows are nearly straight, keeping the upper arms still.']::text[]),
('Step-Up Lunge (Dumbbell)', 'quads', array['glutes', 'hamstrings', 'calves']::text[], 'dumbbell', 'weight_reps', '7858za8', array['Take your place in front of a step or platform with a dumbbell in each hand, palms facing your sides.', 'Set your right foot on the step, ensuring your entire foot is on the surface.', 'Put the lead foot fully on the platform before shifting your weight onto it.', 'Step onto the platform and drive through the lead foot to stand tall on it.', 'Keep the front foot planted and avoid collapsing inward at the knee.', 'Push through the lead foot to return to the start, then change legs as planned.']::text[]),
('Incline Reverse-Grip Press (Smith Machine)', 'chest', array['triceps', 'shoulders']::text[], 'machine', 'weight_reps', '78VqWQK', array['Set the seat of the smith machine to a comfortable incline angle.', 'Take a seat on the machine with your back against the pad and your feet planted.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Keep the palms in the chosen grip without bending the wrists back.', 'Lower the weight to its starting height under control before pressing again.']::text[]),
('Over Bench Single-Arm Wrist Curl (Dumbbell)', 'forearms', array['biceps', 'shoulders']::text[], 'dumbbell', 'weight_reps', '7AnZtSv', array['Plant both feet while seated on a bench; hold a dumbbell in one hand, palm facing down.', 'Set your forearm on the bench with your wrist hanging off the edge.', 'Keep the elbows relaxed so the small muscles of the hand or forearm take the load.', 'Move through the wrists or fingers while the forearms stay supported and still.', 'Keep both shoulders level and resist turning toward the working arm.', 'Ease back to the start without letting the load fall from your hands; switch sides when the set calls for it.']::text[]),
('Medicine Ball Chest Push Multiple Response', 'chest', array['triceps', 'shoulders']::text[], 'other', 'weight_reps', '7aolH9D', array['Stand and set your feet about shoulder width, holding a medicine ball at chest level.', 'Reach your arms forward, pushing the medicine ball away from your chest.', 'Set a firm stance and leave enough clear space for the ball to travel.', 'Drive the ball away forcefully, using the arms and trunk together; catch or retrieve it before resetting.', 'Follow through with the whole body while keeping control of the landing or catch.', 'Bring the weight or body back to its starting position without rushing.']::text[]),
('Triceps Dips Floor', 'triceps', array['chest', 'shoulders']::text[], 'bodyweight', 'bodyweight_reps', '7aVz15j', array['Take a seat on the edge of a chair or bench with your hands next to your hips, fingers pointing forward.', 'Move your butt off the front of the chair with your legs extended in front of you.', 'Set the shoulders down and keep the elbows pointed mostly behind you.', 'Bend the elbows to lower between the supports; stop at a comfortable shoulder depth.', 'Choose a depth that lets the shoulders stay comfortable.', 'Press through the hands to rise, then reset the shoulders before another rep.']::text[]),
('Calf Press (Machine)', 'calves', array['hamstrings']::text[], 'machine', 'weight_reps', '7B4F5nZ', array['Set the seat of the leverage machine so that your shoulders are aligned with the lever pad.', 'Set your toes on the lever pad, with your heels hanging off the edge.', 'Let the ankles move freely while the rest of the body stays quiet.', 'Rise through the balls of your feet, lifting the heels as high as you can without rocking.', 'Pause at the top without rolling the ankles outward.', 'Lower the heels at a measured pace before rising again.']::text[]),
('Two-Arm Clean (Kettlebell)', 'shoulders', array['traps', 'forearms']::text[], 'kettlebell', 'weight_reps', '7Ba7bQ2', array['Stand and set your feet about shoulder width, holding a kettlebell ahead of your thighs with both hands, palms facing toward you.', 'Bend your knees slightly and hinge at the hips, lowering the kettlebell toward the ground.', 'Brace before the pull and keep the load close to the body.', 'Drive through the legs and hips, then guide the weight to its receiving position.', 'Receive the load with the torso braced and feet stable.', 'Stand tall to finish, then lower the weight under control before the next rep.']::text[]),
('Seated Preacher Curl (Dumbbell)', 'biceps', array['forearms']::text[], 'dumbbell', 'weight_reps', '7D5bgLT', array['Take a seat on a preacher curl bench with your feet planted.', 'Take a dumbbell in one hand with palms facing up, resting your upper arm against the preacher pad.', 'Set the working upper arm against the preacher pad and leave the elbow free to bend.', 'Curl the weight while your upper arms stay in contact with the pad.', 'Keep the torso quiet and let the elbow bend lift the weight.', 'Lower until the elbows are nearly straight, keeping the upper arms still.']::text[]),
('Chest Tap Push-Up', 'chest', array['triceps', 'shoulders']::text[], 'bodyweight', 'bodyweight_reps', '7E06s6d', array['Begin in a high plank position with your hands just beyond shoulder width and your body in a straight line.', 'Lower your body toward the ground by bending your elbows, keeping them close to your sides.', 'Brace the abdomen and glutes so the shoulders, hips and ankles move together.', 'Bend your elbows to lower your chest while keeping your body in one line.', 'Keep the head in line with the spine as the elbows bend.', 'Press back to straight arms, keeping the body line intact.']::text[]),
('Exercise Ball Seated Triceps Stretch', 'triceps', array['shoulders']::text[], 'bodyweight', 'duration', '7ePTw4B', array['Take a seat on a stability ball with your feet planted and your back straight.', 'Take a dumbbell in one hand and extend your arm straight up above your head.', 'Settle into the starting position and take an easy breath before moving deeper.', 'Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.', 'Keep the ball steady and use the feet to manage your balance.', 'Hold the position with steady breathing, then release gently; repeat on the other side if needed.']::text[]),
('Front Pulldown (Machine)', 'back', array['biceps', 'shoulders']::text[], 'machine', 'weight_reps', '7F1DVzn', array['Fit the seat to your body, then settle into the machine.', 'Hold the handles with palms facing down, just beyond shoulder width.', 'Sit tall and set the shoulders before drawing the handle down.', 'Pull the handle down by driving your elbows toward your ribs; keep your torso steady.', 'Pull with the elbows rather than leaning far back to move the handle.', 'Let the handle rise steadily until the arms are long, then reset the shoulders.']::text[]),
('Seated Single-Arm Rotate (Dumbbell)', 'forearms', array['shoulders', 'biceps']::text[], 'dumbbell', 'weight_reps', '7f2jsqP', array['Take a seat on a bench with your back straight and hold a dumbbell in one hand, resting it on your thigh.', 'Before moving, raise the dumbbell up to shoulder height, keeping your elbow close to your body.', 'Keep the elbows relaxed so the small muscles of the hand or forearm take the load.', 'Move through the wrists or fingers while the forearms stay supported and still.', 'Keep both shoulders level and resist turning toward the working arm.', 'Ease back to the start without letting the load fall from your hands; switch sides when the set calls for it.']::text[]),
('Lying Hammer Press (Dumbbell)', 'chest', array['triceps', 'shoulders']::text[], 'dumbbell', 'weight_reps', '7gdLIXa', array['Settle onto a bench with a dumbbell in each hand, palms facing each other and arms extended straight up.', 'Before moving, lower the dumbbells to the sides of your chest, keeping your elbows at a 90-degree angle.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Keep the palms facing each other and the wrists straight.', 'Lower the weight to its starting height under control before pressing again.']::text[]),
('Standing Triceps Extension (With Towel) (Assisted)', 'triceps', array['shoulders']::text[], 'bodyweight', 'bodyweight_reps', '7HcfMBP', array['Stand and set your feet about shoulder width and hold a towel with both hands behind your head.', 'Hold your elbows near your ears and your upper arms stationary.', 'Set the upper arms in place before extending the elbows.', 'Keep the upper arms steady and extend through the elbows to move the weight.', 'Keep the upper arms steady while the forearms travel.', 'Bend the elbows slowly to return to the start of the next rep.']::text[]),
('Clean (Dumbbell)', 'glutes', array['hamstrings', 'quads', 'calves']::text[], 'dumbbell', 'weight_reps', '7Hg55JG', array['Stand and set your feet about shoulder width, holding a dumbbell in each hand with palms facing down.', 'Bend your knees and lower your hips into a squat position, with your spine steady and chest up.', 'Brace before the pull and keep the load close to the body.', 'Drive through the legs and hips, then guide the weight to its receiving position.', 'Receive the load with the torso braced and feet stable.', 'Stand tall to finish, then lower the weight under control before the next rep.']::text[]),
('Cocoons', 'core', array['back']::text[], 'bodyweight', 'bodyweight_reps', '7i4msxz', array['Settle onto your back with your knees bent and feet planted.', 'Set your hands behind your head with your elbows pointing outwards.', 'Set the pelvis and keep the neck relaxed before curling upward.', 'Curl your rib cage toward your pelvis, letting the abdominals move the torso.', 'Leave a little space between the chin and chest; keep the movement in the torso.', 'Lower the shoulders or torso with control before the next curl.']::text[]),
('Seated Row (Machine)', 'back', array['biceps', 'forearms']::text[], 'machine', 'weight_reps', '7I6LNUG', array['Set the seat height and footrests to a comfortable position.', 'Take a seat on the machine with your chest against the pad and your feet on the footrests.', 'Set the torso and allow the arms to reach forward without rounding excessively.', 'Draw your elbows back and bring the handle or weight toward your torso.', 'Bring the elbows back without jerking the torso.', 'Reach the arms forward again without letting the torso lurch.']::text[]),
('Standing Concentration Curl (Dumbbell)', 'biceps', array['forearms']::text[], 'dumbbell', 'weight_reps', '7inpWch', array['Stand and set your feet about shoulder width and hold a dumbbell in one hand, with your arm straight and palm facing inwards.', 'Set your opposite hand on your thigh for support.', 'Set the shoulders and upper arms before bending the elbows.', 'Bend your elbows to bring the weight toward your shoulders without swinging your torso.', 'Keep the torso quiet and let the elbow bend lift the weight.', 'Lower until the elbows are nearly straight, keeping the upper arms still.']::text[]),
('Close-Grip Press (Dumbbell)', 'triceps', array['chest', 'shoulders']::text[], 'dumbbell', 'weight_reps', '7jGOBF3', array['Take a seat on a flat bench with a dumbbell in each hand, resting on your thighs.', 'Use your thighs to help raise the dumbbells, lift the dumbbells one at a time so that you can hold them in front of you at shoulder width.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Keep the wrists stacked and use a shoulder path that feels natural.', 'Lower the weight to its starting height under control before pressing again.']::text[]),
('Rollout (Barbell)', 'core', array['back']::text[], 'barbell', 'weight_reps', '7M66AVi', array['Get down on the floor and hold a barbell with both hands, about shoulder width.', 'Guide the barbell forward, extending your arms and keeping your core engaged.', 'Tighten the abdomen and keep the pelvis tucked before the arms reach away.', 'Reach the arms away while keeping your ribs and pelvis aligned; stop before the lower back sags.', 'Stop reaching when the lower back starts to sag.', 'Pull back to the start through your shoulders and abdominals, keeping the same body line.']::text[]),
('Standing Chin-Up (Assisted)', 'back', array['biceps', 'forearms']::text[], 'machine', 'weight_reps', '7OeHptV', array['Set the machine to your desired assistance level.', 'Step onto the foot platform and grip the handles with palms facing down, just beyond shoulder width.', 'Begin from a controlled hang with the shoulders active rather than slack.', 'Pull your elbows down and bring your upper chest toward the bar without kicking your legs.', 'Avoid swinging the legs to clear the bar.', 'Lower to long arms without dropping suddenly from the top.']::text[]),
('Lying Pronation on Floor (Dumbbell)', 'forearms', array['biceps', 'triceps']::text[], 'dumbbell', 'weight_reps', '7RWNjiB', array['Settle onto the floor with your face down and your arms extended straight out in front of you, holding a dumbbell in each hand.', 'Rotate your palms so they are facing down toward the floor.', 'Keep the elbows relaxed so the small muscles of the hand or forearm take the load.', 'Move through the wrists or fingers while the forearms stay supported and still.', 'Use a small, smooth range without swinging the elbows.', 'Ease back to the start without letting the load fall from your hands.']::text[]),
('Decline Fly (Cable)', 'chest', array['shoulders', 'triceps']::text[], 'cable', 'weight_reps', '7saC5zz', array['Set the cable machine to a decline position.', 'Face the away from the machine from a stable stance with feet about shoulder width.', 'Keep a soft elbow bend and set the shoulders before moving the arms.', 'With a soft bend in the elbows, sweep your arms together in a wide arc.', 'Keep the elbow angle nearly unchanged through the arc.', 'Open the arms back along the same arc without dropping the load.']::text[]),
('Kneeling Step with Swing (Weighted)', 'shoulders', array['triceps', 'core']::text[], 'bodyweight', 'bodyweight_reps', '7uFJuXp', array['Begin in a kneeling position with your knees about hip width and your back straight.', 'Take a weight in each hand, with your arms extended straight down in front of you.', 'Set the shoulders and let the weight move back between the legs as the hips hinge.', 'Hinge back, then drive the hips forward to send the weight up; let the arms guide it.', 'Let the hips, not the shoulders, provide the power.', 'Let the weight fall naturally and hinge again for the next swing.']::text[]),
('Incline Row (Dumbbell)', 'back', array['biceps', 'shoulders']::text[], 'dumbbell', 'weight_reps', '7vG5o25', array['Angle the bench to roughly 45 degrees.', 'Take hold of a dumbbell in each hand and Take a seat on the bench with your chest against the incline.', 'Set the torso and allow the arms to reach forward without rounding excessively.', 'Draw your elbows back and bring the handle or weight toward your torso.', 'Bring the elbows back without jerking the torso.', 'Reach the arms forward again without letting the torso lurch.']::text[]),
('Alternating Press on Floor (Kettlebell)', 'chest', array['shoulders', 'triceps']::text[], 'kettlebell', 'weight_reps', '7w6i0vE', array['Begin by lying on your back on the floor with your knees bent and feet planted.', 'Take a kettlebell in each hand, with your palms facing toward your feet and your arms extended straight up toward the ceiling.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Finish one side''s motion before the other side takes over.', 'Lower the weight to its starting height under control before pressing again; switch sides when the set calls for it.']::text[]),
('Side Hip Abduction', 'glutes', array['quads']::text[], 'bodyweight', 'bodyweight_reps', '7WaDzyL', array['Stand and set your feet about shoulder width and your hands on your hips.', 'Transfer your weight to one leg and lift the opposite leg out to the side, keeping it straight.', 'Brace the abdomen and keep the shoulders anchored to the support.', 'Open the knees or legs against resistance without shifting your torso.', 'Slow the legs before they pull the lower back out of position.', 'Lower the legs slowly without swinging or losing your trunk position.']::text[]),
('Machine Incline Triceps Extension (Smith Machine)', 'triceps', array['shoulders']::text[], 'machine', 'weight_reps', '7WcQgkm', array['Set the seat of the smith machine so that the bar is at shoulder height.', 'Take a seat on the bench with your back against the pad and your feet planted.', 'Set the upper arms in place before extending the elbows.', 'Keep the upper arms steady and extend through the elbows to move the weight.', 'Keep the upper arms steady while the forearms travel.', 'Bend the elbows slowly to return to the start of the next rep.']::text[]),
('Scapula Dips', 'traps', array['back', 'shoulders']::text[], 'bodyweight', 'bodyweight_reps', '7xeukSt', array['Begin by standing with your feet about shoulder width and your arms extended in front of you.', 'Bend your knees slightly and hinge forward at the hips, with your spine steady.', 'Set the shoulders down and keep the elbows pointed mostly behind you.', 'Bend the elbows to lower between the supports; stop at a comfortable shoulder depth.', 'Choose a depth that lets the shoulders stay comfortable.', 'Press through the hands to rise, then reset the shoulders before another rep.']::text[]),
('Bench Press (Cable)', 'chest', array['triceps', 'shoulders']::text[], 'cable', 'weight_reps', '7xI5MXA', array['Set the cable machine to chest height and attach the handles.', 'Face the away from the machine from a stable stance with feet about shoulder width.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Keep the wrists stacked and use a shoulder path that feels natural.', 'Lower the weight to its starting height under control before pressing again.']::text[]),
('Reverse-Grip Preacher Curl (Machine)', 'biceps', array['forearms']::text[], 'machine', 'weight_reps', '7y9JIMj', array['Fit the seat to your body, then settle into the machine.', 'Hold the handles with palms facing up.', 'Set the working upper arm against the preacher pad and leave the elbow free to bend.', 'Curl the weight while your upper arms stay in contact with the pad.', 'Keep the palms in the chosen grip without bending the wrists back.', 'Lower until the elbows are nearly straight, keeping the upper arms still.']::text[]),
('Leg Press (Smith Machine)', 'glutes', array['quads', 'hamstrings', 'calves']::text[], 'machine', 'weight_reps', '7zdxRTl', array['Set the seat and footplate of the smith machine to a comfortable position.', 'Take a seat on the machine with your back against the backrest and your feet about shoulder width on the footplate.', 'Set your feet firmly on the plate and keep the hips against the seat.', 'Bend the knees to bring the platform toward you, then press it away through the feet.', 'Stop the descent before the hips lift from the seat.', 'Return along the same path at a controlled pace.']::text[]),
('Seated Single-Arm Biceps Curl on Exercise Ball with Leg Raised (Dumbbell)', 'biceps', array['forearms', 'shoulders']::text[], 'dumbbell', 'weight_reps', '84sESNy', array['Take a seat on an exercise ball with your feet planted and your back straight.', 'Take a dumbbell in one hand with your palm facing up and your arm straight.', 'Set the shoulders and upper arms before bending the elbows.', 'Bend your elbows to bring the weight toward your shoulders without swinging your torso.', 'Keep both shoulders level and resist turning toward the working arm.', 'Lower until the elbows are nearly straight, keeping the upper arms still; switch sides when the set calls for it.']::text[]),
('Seated Press (Kettlebell)', 'shoulders', array['triceps', 'core']::text[], 'kettlebell', 'weight_reps', '89HVjEp', array['Take a seat on a bench with your back straight and feet planted.', 'Take a kettlebell in each hand at shoulder height, palms facing forward.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Keep the wrists stacked and use a shoulder path that feels natural.', 'Lower the weight to its starting height under control before pressing again.']::text[]),
('Sumo High Pull (Kettlebell)', 'traps', array['shoulders', 'glutes', 'hamstrings']::text[], 'kettlebell', 'weight_reps', '8ARQ9Hw', array['Stand and set your feet wider than about shoulder width, toes pointing outwards.', 'Take a kettlebell with both hands ahead of your body, arms extended downwards.', 'Brace before the pull and keep the load close to the body.', 'Drive up from the wide stance and pull the kettlebell toward the upper chest, leading with the elbows.', 'Receive the load with the torso braced and feet stable.', 'Stand tall to finish, then lower the weight under control before the next rep.']::text[]),
('Seated Roller Shoulder Flexion and Retraction', 'chest', array['shoulders', 'triceps']::text[], 'other', 'bodyweight_reps', '8coXSYU', array['Take a seat on a flat surface with your legs extended in front of you.', 'Take hold of the roller with both hands, palms facing down, and place it on your thighs.', 'Tighten the abdomen and keep the pelvis tucked before the arms reach away.', 'Roll the roller away along your legs as the arms reach forward, then draw it back toward your thighs.', 'Stop reaching when the lower back starts to sag.', 'Pull back to the start through your shoulders and abdominals, keeping the same body line.']::text[]),
('Reverse-Grip Incline Bench Row (Barbell)', 'back', array['biceps', 'forearms']::text[], 'barbell', 'weight_reps', '8d8qJQI', array['Angle the bench to roughly 45 degrees.', 'Take a seat on the bench facing the backrest with your chest against it.', 'Set the torso and allow the arms to reach forward without rounding excessively.', 'Draw your elbows back and bring the handle or weight toward your torso.', 'Keep the palms in the chosen grip without bending the wrists back.', 'Reach the arms forward again without letting the torso lurch.']::text[]),
('Palms in Incline Bench Press (Dumbbell)', 'triceps', array['chest', 'shoulders']::text[], 'dumbbell', 'weight_reps', '8eqjhOl', array['Angle the bench to roughly 45 degrees.', 'Take a seat on the bench with your back against the backrest and feet planted.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Keep the wrists stacked and use a shoulder path that feels natural.', 'Lower the weight to its starting height under control before pressing again.']::text[]),
('Standing Single-Arm Concentration Curl (Dumbbell)', 'biceps', array['forearms']::text[], 'dumbbell', 'weight_reps', '8fgqP5a', array['Stand tall with your feet about shoulder width and hold a dumbbell in one hand, palm facing up.', 'Set your free hand on your thigh for support.', 'Set the shoulders and upper arms before bending the elbows.', 'Bend your elbows to bring the weight toward your shoulders without swinging your torso.', 'Keep both shoulders level and resist turning toward the working arm.', 'Lower until the elbows are nearly straight, keeping the upper arms still; switch sides when the set calls for it.']::text[]),
('Standing Crunch (With Rope Attachment) (Cable)', 'core', '{}'::text[], 'cable', 'weight_reps', '8gQo5Ss', array['Connect a rope to a cable machine at chest height.', 'Face the away from the machine from a stable stance with feet about shoulder width.', 'Set the pelvis and keep the neck relaxed before curling upward.', 'Curl your rib cage toward your pelvis, letting the abdominals move the torso.', 'Leave a little space between the chin and chest; keep the movement in the torso.', 'Lower the shoulders or torso with control before the next curl.']::text[]),
('Hip Lift (Band)', 'glutes', array['hamstrings', 'quads']::text[], 'band', 'weight_reps', '8IbNZwc', array['Settle onto your back with your knees bent and feet planted.', 'Set a resistance band just above your knees.', 'Plant the feet and keep the ribs from flaring as the hips prepare to rise.', 'Press through the feet and lift your hips until your torso and thighs line up.', 'Control the band on the way back instead of letting it snap you into position.', 'Lower the hips steadily and keep the feet planted for the next lift.']::text[]),
('Hanging Knee Raise with Throw Down (Assisted)', 'core', array['back']::text[], 'bodyweight', 'bodyweight_reps', '8K0w2yA', array['Suspend yourself from a pull-up bar with your arms straight and your palms turned away from you.', 'Brace your trunk and lift your knees toward your chest, keeping your legs together.', 'Brace the abdomen and keep the shoulders anchored to the support.', 'Lift your legs by bracing your trunk and moving at the hips rather than swinging.', 'Slow the legs before they pull the lower back out of position.', 'Lower the legs slowly without swinging or losing your trunk position.']::text[]),
('Medicine Ball Close-Grip Push Up', 'triceps', array['chest', 'shoulders']::text[], 'other', 'weight_reps', '8K7m2SS', array['Begin in a high plank position with your hands on the medicine ball, about shoulder width.', 'Lower your body toward the ground by bending your elbows, keeping them close to your sides.', 'Brace the abdomen and glutes so the shoulders, hips and ankles move together.', 'Bend your elbows to lower your chest while keeping your body in one line.', 'Keep the head in line with the spine as the elbows bend.', 'Press back to straight arms, keeping the body line intact.']::text[]),
('Seated Curl (Cable)', 'biceps', array['forearms']::text[], 'cable', 'weight_reps', '8oYqOt9', array['Take a seat on a cable machine with your feet planted and your back straight.', 'Hold the cable attachment with palms facing up, and your arms straight.', 'Set the shoulders and upper arms before bending the elbows.', 'Bend your elbows to bring the weight toward your shoulders without swinging your torso.', 'Keep the torso quiet and let the elbow bend lift the weight.', 'Lower until the elbows are nearly straight, keeping the upper arms still.']::text[]),
('Standing Calf Raise (Barbell)', 'calves', array['hamstrings', 'glutes']::text[], 'barbell', 'weight_reps', '8ozhUIZ', array['Stand and set your feet about shoulder width and place a barbell across your upper back.', 'Before moving, raise your heels off the ground as high as possible, using only your toes.', 'Let the ankles move freely while the rest of the body stays quiet.', 'Rise through the balls of your feet, lifting the heels as high as you can without rocking.', 'Pause at the top without rolling the ankles outward.', 'Lower the heels at a measured pace before rising again.']::text[]),
('Hyperextension (On Stability Ball) (Weighted)', 'back', array['glutes', 'hamstrings']::text[], 'bodyweight', 'weight_reps', '8urJS9b', array['Set yourself face down on a stability ball with your hips resting on the ball and your feet against a wall for stability.', 'Set your hands behind your head or cross them over your chest.', 'Secure the hips and feet on the support before lifting.', 'Raise your torso or legs until they line up with your body, without arching sharply at the lower back.', 'Keep the ball steady and use the feet to manage your balance.', 'Return along the same path at a controlled pace.']::text[]),
('Concentration Curl (Cable)', 'biceps', array['forearms']::text[], 'cable', 'weight_reps', '8yBgwBS', array['Take a seat on a bench or chair with your feet planted and your knees soft.', 'Take hold of the cable handle with palms facing up and rest your elbow against the inside of your thigh.', 'Set the shoulders and upper arms before bending the elbows.', 'Bend your elbows to bring the weight toward your shoulders without swinging your torso.', 'Keep the torso quiet and let the elbow bend lift the weight.', 'Lower until the elbows are nearly straight, keeping the upper arms still.']::text[]),
('Shoulder Press (Smith Machine)', 'shoulders', array['triceps', 'back']::text[], 'machine', 'weight_reps', '903mzG8', array['Fit the seat to your body, then settle into the machine.', 'Hold the bar with palms facing down, just beyond shoulder width.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Keep the wrists stacked and use a shoulder path that feels natural.', 'Lower the weight to its starting height under control before pressing again.']::text[]),
('Hamstring Stretch', 'hamstrings', array['glutes']::text[], 'bodyweight', 'duration', '99rWm7w', array['Stand and set your feet about shoulder width.', 'Move forward with your right foot and shift your weight onto your right leg.', 'Settle into the starting position and take an easy breath before moving deeper.', 'Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.', 'Stay in a mild stretch rather than pulling farther with momentum.', 'Hold the position with steady breathing, then release gently; repeat on the other side if needed.']::text[]),
('Decline Crunch', 'core', '{}'::text[], 'bodyweight', 'bodyweight_reps', '9Ap7miY', array['Settle onto a decline bench with your feet secured and your knees bent at a 90-degree angle.', 'Set your hands behind your head or across your chest.', 'Set the pelvis and keep the neck relaxed before curling upward.', 'Curl your rib cage toward your pelvis, letting the abdominals move the torso.', 'Leave a little space between the chin and chest; keep the movement in the torso.', 'Lower the shoulders or torso with control before the next curl.']::text[]),
('Bridge - Mountain Climber (Cross Body)', 'core', array['glutes', 'quads', 'hamstrings', 'shoulders', 'triceps']::text[], 'bodyweight', 'bodyweight_reps', '9c6T1YX', array['Begin in a high plank position with your hands directly under your shoulders and your body in a straight line.', 'Brace your trunk and lift your right foot off the ground, bringing your right knee toward your left elbow.', 'Brace the trunk lightly before moving a limb.', 'Move the working arm or leg while keeping the trunk steady and the breathing even.', 'Keep the pelvis from rocking as the arm or leg moves.', 'Reset your posture before changing sides or beginning the next rep.']::text[]),
('Split Squats', 'quads', array['glutes', 'hamstrings', 'calves']::text[], 'bodyweight', 'bodyweight_reps', '9E25EOx', array['Stand and set your feet about shoulder width.', 'Step forward with one foot and place it about two feet in front of the other foot.', 'Brace the abdomen and spread pressure across the whole foot.', 'Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.', 'Drive upward with the chest and hips rising together; keep the knees from collapsing inward.', 'Stand fully, reset your footing and breathing, then begin the next descent.']::text[]),
('Palm Rotational Row (Cable)', 'back', array['biceps', 'forearms']::text[], 'cable', 'weight_reps', '9fCHfSc', array['Connect a handle to a cable machine at waist height.', 'Face the machine from a stable stance with feet about shoulder width.', 'Set the torso and allow the arms to reach forward without rounding excessively.', 'Draw your elbows back and bring the handle or weight toward your torso.', 'Bring the elbows back without jerking the torso.', 'Reach the arms forward again without letting the torso lurch.']::text[]),
('Seated Hip Internal Rotation (Band)', 'glutes', array['hamstrings', 'quads']::text[], 'band', 'weight_reps', '9gbyYKk', array['Take a seat on a chair or bench with your back straight and feet planted.', 'Set a resistance band around your thighs, just above your knees.', 'Set the pelvis and make the turn through the rib cage.', 'Turn through the torso while the hips and lower body stay as steady as the setup allows.', 'Control the band on the way back instead of letting it snap you into position.', 'Return through center before turning to the other side.']::text[]),
('Single-Leg Floor Calf Raise (Smith Machine)', 'calves', array['hamstrings', 'glutes']::text[], 'machine', 'weight_reps', '9GXrTE6', array['Set yourself on the floor under the smith machine bar, turned away from the machine.', 'Set the balls of your feet on a raised surface, such as a weight plate or block.', 'Let the ankles move freely while the rest of the body stays quiet.', 'Rise through the balls of your feet, lifting the heels as high as you can without rocking.', 'Keep the pelvis level as the supporting leg does the work.', 'Lower the heels at a measured pace before rising again; switch sides when the set calls for it.']::text[]),
('Lying Leg-Hip Raise', 'core', '{}'::text[], 'bodyweight', 'bodyweight_reps', '9IxJdtC', array['Settle onto your back with your legs extended and your arms by your sides.', 'Set your hands under your glutes for support.', 'Plant the feet and keep the ribs from flaring as the hips prepare to rise.', 'Press through the feet and lift your hips until your torso and thighs line up.', 'Stop when the hips line up with the torso; do not arch higher through the lower back.', 'Lower the hips steadily and keep the feet planted for the next lift.']::text[]),
('Single Leg Calf Raise (Band)', 'calves', '{}'::text[], 'band', 'weight_reps', '9JprnPh', array['Stand and set your feet about hip width and place the band around the ball of your left foot.', 'Use a stable object for balance if needed.', 'Let the ankles move freely while the rest of the body stays quiet.', 'Rise through the balls of your feet, lifting the heels as high as you can without rocking.', 'Control the band on the way back instead of letting it snap you into position.', 'Lower the heels at a measured pace before rising again.']::text[]),
('Horizontal Single-Leg Press (Machine)', 'glutes', array['quads', 'hamstrings', 'calves']::text[], 'machine', 'weight_reps', '9KU9TYF', array['Set the seat of the machine so that your knees are at a 90-degree angle when your feet are on the footplate.', 'Take a seat on the machine with your back against the backrest and your feet about shoulder width on the footplate.', 'Set your feet firmly on the plate and keep the hips against the seat.', 'Bend the knees to bring the platform toward you, then press it away through the feet.', 'Keep the pelvis level as the supporting leg does the work.', 'Return along the same path at a controlled pace; switch sides when the set calls for it.']::text[]),
('Lying Squat (Machine)', 'glutes', array['quads', 'hamstrings', 'calves']::text[], 'machine', 'weight_reps', '9n2149Z', array['Set the sled machine to a comfortable weight.', 'Settle onto your back on the sled machine with your feet on the footplate.', 'Brace the abdomen and spread pressure across the whole foot.', 'Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.', 'Drive upward with the chest and hips rising together; keep the knees from collapsing inward.', 'Stand fully, reset your footing and breathing, then begin the next descent.']::text[]),
('Horizontal Pallof Press (Band)', 'core', array['glutes']::text[], 'band', 'weight_reps', '9pa4H5m', array['Connect the band to a sturdy anchor point at waist height.', 'Stand perpendicular to the anchor point with your feet about shoulder width.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Control the band on the way back instead of letting it snap you into position.', 'Lower the weight to its starting height under control before pressing again.']::text[]),
('Reverse-Grip Incline Bench Two-Arm Row (Dumbbell)', 'back', array['biceps', 'forearms']::text[], 'dumbbell', 'weight_reps', '9pQSkH8', array['Angle the bench to roughly 45 degrees.', 'Take a seat on the bench with your chest against the backrest and your feet planted.', 'Set the torso and allow the arms to reach forward without rounding excessively.', 'Draw your elbows back and bring the handle or weight toward your torso.', 'Keep the palms in the chosen grip without bending the wrists back.', 'Reach the arms forward again without letting the torso lurch.']::text[]),
('Bench Dip on Floor', 'triceps', array['chest', 'shoulders']::text[], 'bodyweight', 'bodyweight_reps', '9RT8oQW', array['Take a seat on the edge of a bench or chair with your hands gripping the edge, fingers pointing forward.', 'Move your butt off the bench, supporting your weight with your hands.', 'Set the shoulders down and keep the elbows pointed mostly behind you.', 'Bend the elbows to lower between the supports; stop at a comfortable shoulder depth.', 'Choose a depth that lets the shoulders stay comfortable.', 'Press through the hands to rise, then reset the shoulders before another rep.']::text[]),
('Decline Pullover (Barbell)', 'chest', array['triceps', 'shoulders']::text[], 'barbell', 'weight_reps', '9sgNE2O', array['Get onto a decline bench with your head lower than your hips and your feet secured.', 'Take hold of the barbell with a pronated grip (palms turned away from you) and your hands just beyond shoulder width.', 'Set the ribs down and keep a small elbow bend before lowering the weight.', 'Lower the weight in an arc behind your head until you feel a comfortable shoulder stretch.', 'Keep the ribs down as the arms travel overhead.', 'Pull the weight back over the chest along the same arc, without lifting the ribs.']::text[]),
('Windmill (Kettlebell)', 'core', array['shoulders']::text[], 'kettlebell', 'weight_reps', '9Tkqa9O', array['Stand and set your feet about shoulder width, holding a kettlebell in your right hand overhead.', 'Before moving, rotate your left foot outwards about 45 degrees and keep your right foot pointing forward.', 'Set the pelvis and make the turn through the rib cage.', 'Turn through the torso while the hips and lower body stay as steady as the setup allows.', 'Keep the turn smooth instead of throwing the arms across the body.', 'Return through center before turning to the other side.']::text[]),
('Triceps Pushdown (V-Bar) (Cable)', 'triceps', array['forearms']::text[], 'cable', 'weight_reps', '9tvVVM9', array['Connect a v-bar attachment to the cable machine at the highest setting.', 'Face the cable machine from a stable stance with feet about shoulder width.', 'Stand far enough from the stack for the cable to stay taut.', 'Keep your elbows near your ribs and straighten your arms against the cable.', 'Keep the elbows close to the body instead of letting the shoulders swing.', 'Return along the same path at a controlled pace.']::text[]),
('Pullover (Dumbbell)', 'chest', array['back', 'triceps']::text[], 'dumbbell', 'weight_reps', '9XjtHvS', array['Settle onto a bench with your head at one end and your feet on the floor.', 'Take a dumbbell with both hands and extend your arms straight above your chest.', 'Set the ribs down and keep a small elbow bend before lowering the weight.', 'Lower the weight in an arc behind your head until you feel a comfortable shoulder stretch.', 'Keep the ribs down as the arms travel overhead.', 'Pull the weight back over the chest along the same arc, without lifting the ribs.']::text[]),
('Triceps Dip (Between Benches)', 'triceps', array['chest', 'shoulders']::text[], 'bodyweight', 'bodyweight_reps', '9ZGnq1w', array['Take a seat on a bench with your hands gripping the edge of the bench, fingers pointing forward.', 'Move your butt off the bench, supporting your weight with your hands.', 'Set the shoulders down and keep the elbows pointed mostly behind you.', 'Bend the elbows to lower between the supports; stop at a comfortable shoulder depth.', 'Choose a depth that lets the shoulders stay comfortable.', 'Press through the hands to rise, then reset the shoulders before another rep.']::text[]),
('Incline Twisting Sit-Up', 'core', '{}'::text[], 'bodyweight', 'bodyweight_reps', '9ZGZuOD', array['Angle the bench to roughly 45 degrees.', 'Get onto the bench with your feet secured under the foot pads.', 'Set the pelvis and keep the neck relaxed before curling upward.', 'Curl your rib cage toward your pelvis, letting the abdominals move the torso.', 'Leave a little space between the chin and chest; keep the movement in the torso.', 'Lower the shoulders or torso with control before the next curl.']::text[]),
('Single-Leg Donkey Calf Raise', 'calves', array['hamstrings', 'glutes']::text[], 'bodyweight', 'bodyweight_reps', 'A2upspL', array['Stand and set your feet about shoulder width, toes pointing forward.', 'Set your hands on a stable surface for support, such as a wall or a bar.', 'Let the ankles move freely while the rest of the body stays quiet.', 'Rise through the balls of your feet, lifting the heels as high as you can without rocking.', 'Keep the pelvis level as the supporting leg does the work.', 'Lower the heels at a measured pace before rising again; switch sides when the set calls for it.']::text[]),
('Seated Row (Cable)', 'back', array['biceps', 'forearms']::text[], 'cable', 'weight_reps', 'A3P4O0R', array['Take a seat on the cable row machine with your feet flat on the footrests and your knees soft.', 'Hold the handles with palms facing down, with your spine steady and your shoulders relaxed.', 'Set the torso and allow the arms to reach forward without rounding excessively.', 'Draw your elbows back and bring the handle or weight toward your torso.', 'Bring the elbows back without jerking the torso.', 'Reach the arms forward again without letting the torso lurch.']::text[]),
('Double Alternating Hang Clean (Kettlebell)', 'biceps', array['forearms', 'shoulders']::text[], 'kettlebell', 'duration', 'a4F9Oyc', array['Stand and set your feet about shoulder width, holding a kettlebell in each hand with palms facing down.', 'Bend your knees slightly and hinge forward at the hips, with your spine steady and chest up.', 'Brace before the pull and keep the load close to the body.', 'Drive through the legs and hips, then guide the weight to its receiving position.', 'Finish one side''s motion before the other side takes over.', 'Stand tall to finish, then lower the weight under control before the next rep; switch sides when the set calls for it.']::text[]),
('Standing Overhead Press (Dumbbell)', 'shoulders', array['triceps', 'back']::text[], 'dumbbell', 'weight_reps', 'A6wtbuL', array['Stand and set your feet about shoulder width, holding a dumbbell in each hand at shoulder level with your palms facing forward.', 'Press the dumbbells upward until your arms are straight overhead.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Keep the wrists stacked and use a shoulder path that feels natural.', 'Lower the weight to its starting height under control before pressing again.']::text[]),
('Stationary Bike Walk', 'cardio', array['quads', 'hamstrings', 'calves']::text[], 'machine', 'duration', 'a8VDgLw', array['Set the seat height and position on the stationary bike to ensure proper alignment.', 'Set your feet on the pedals and secure them with the straps if available.', 'Start at a pace that lets the feet and arms move in sync.', 'Move at a repeatable pace, keeping the motion smooth and your breathing steady.', 'Keep the pattern repeatable as speed increases.', 'Keep the rhythm for the planned interval, slowing if your form starts to slip.']::text[]),
('Archer Push Up', 'chest', array['triceps', 'shoulders', 'core']::text[], 'bodyweight', 'bodyweight_reps', 'A9qxk2F', array['Begin in a push-up position with your hands just beyond shoulder width.', 'Reach one arm straight out to the side, parallel to the ground.', 'Brace the abdomen and glutes so the shoulders, hips and ankles move together.', 'Shift toward one hand and bend that elbow while the other arm straightens to the side.', 'Keep the head in line with the spine as the elbows bend.', 'Press back to straight arms, keeping the body line intact.']::text[]),
('Reverse-Grip Bent Over Row (Smith Machine)', 'back', array['biceps', 'forearms']::text[], 'machine', 'weight_reps', 'aaxA3cm', array['Prepare the smith machine with the bar at hip height.', 'Face the bar from a stable stance with feet about shoulder width.', 'Set the torso and allow the arms to reach forward without rounding excessively.', 'Draw your elbows back and bring the handle or weight toward your torso.', 'Keep the palms in the chosen grip without bending the wrists back.', 'Reach the arms forward again without letting the torso lurch.']::text[]),
('Medicine Ball Chest Pass', 'chest', array['shoulders', 'triceps']::text[], 'other', 'weight_reps', 'aDoFKrE', array['Stand and set your feet about shoulder width, holding the medicine ball at chest level.', 'Reach your arms forward, pushing the medicine ball away from your chest with force.', 'Set a firm stance and leave enough clear space for the ball to travel.', 'Drive the ball away forcefully, using the arms and trunk together; catch or retrieve it before resetting.', 'Follow through with the whole body while keeping control of the landing or catch.', 'Ease back to the start before repeating.']::text[]),
('Standing Reverse-Grip Curl (Barbell)', 'biceps', array['forearms']::text[], 'barbell', 'weight_reps', 'AdxxqfF', array['Stand tall with your feet about shoulder width and hold a barbell with palms facing up.', 'Hold your elbows near your torso and your upper arms stationary.', 'Set the shoulders and upper arms before bending the elbows.', 'Curl the weight with your palms facing down, keeping the elbows close and torso still.', 'Keep the palms in the chosen grip without bending the wrists back.', 'Lower until the elbows are nearly straight, keeping the upper arms still.']::text[]),
('Incline Curl (Dumbbell)', 'biceps', array['forearms']::text[], 'dumbbell', 'weight_reps', 'ae9UoXQ', array['Angle an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing forward.', 'Set your upper arms on the incline bench and let your elbows hang down, straighten your arms.', 'Set the shoulders and upper arms before bending the elbows.', 'Bend your elbows to bring the weight toward your shoulders without swinging your torso.', 'Keep the torso quiet and let the elbow bend lift the weight.', 'Lower until the elbows are nearly straight, keeping the upper arms still.']::text[]),
('Biceps Curl (With Arm Blaster) (Barbell)', 'biceps', array['forearms']::text[], 'barbell', 'weight_reps', 'aee2Fcj', array['Stand tall with your feet about shoulder width and hold a barbell with palms facing up.', 'Set your upper arms against the arm blaster, keeping your elbows close to your torso.', 'Set the shoulders and upper arms before bending the elbows.', 'Bend your elbows to bring the weight toward your shoulders without swinging your torso.', 'Keep the torso quiet and let the elbow bend lift the weight.', 'Lower until the elbows are nearly straight, keeping the upper arms still.']::text[]),
('Muscle-Up (On Vertical Bar)', 'back', array['biceps', 'triceps', 'forearms']::text[], 'bodyweight', 'bodyweight_reps', 'Af0EW2I', array['Begin by hanging from a vertical bar with your palms turned away from you and your arms straight.', 'Brace your trunk and pull your body up toward the bar, leading with your chest.', 'Begin from a controlled hang with the shoulders active rather than slack.', 'Pull your elbows down and bring your upper chest toward the bar without kicking your legs.', 'Avoid swinging the legs to clear the bar.', 'Lower to long arms without dropping suddenly from the top.']::text[]),
('Y-Raise (Band)', 'shoulders', array['traps', 'back']::text[], 'band', 'weight_reps', 'aHDy5O5', array['Stand and set your feet about shoulder width and hold the band ahead of your thighs with your palms facing inwards.', 'Maintain straight arms and lift them up and out to the sides, forming a ''Y'' shape with your body.', 'Start with a manageable load and a small bend in the elbows.', 'Raise the arms diagonally into a Y shape while keeping the shoulders away from your ears.', 'Control the band on the way back instead of letting it snap you into position.', 'Lower the arms slowly to your sides without swinging the weight.']::text[]),
('Upright Row (Dumbbell)', 'shoulders', array['traps', 'biceps']::text[], 'dumbbell', 'weight_reps', 'ainizkb', array['Stand and set your feet about shoulder width, holding a dumbbell in each hand with palms facing down.', 'Let the dumbbells hang ahead of your thighs, with your arms straight.', 'Set the torso and allow the arms to reach forward without rounding excessively.', 'Draw your elbows back and bring the handle or weight toward your torso.', 'Bring the elbows back without jerking the torso.', 'Reach the arms forward again without letting the torso lurch.']::text[]),
('Seated Pectoralis Major Stretch with Stability Ball (Assisted)', 'chest', array['shoulders', 'triceps']::text[], 'bodyweight', 'duration', 'Aj9vWh7', array['Take a seat on a stability ball with your feet planted and your back straight.', 'Take a stability ball with both hands and extend your arms straight out in front of you.', 'Settle into the starting position and take an easy breath before moving deeper.', 'Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.', 'Keep the ball steady and use the feet to manage your balance.', 'Hold the position with steady breathing, then release gently; repeat on the other side if needed.']::text[]),
('Medicine Ball Supine Chest Throw', 'triceps', array['chest', 'shoulders']::text[], 'other', 'weight_reps', 'Al3tP0D', array['Settle onto your back on a bench with your knees bent and feet planted.', 'Take hold of the medicine ball with both hands, extending your arms straight up above your chest.', 'Brace and settle into a stable starting position.', 'Move through the intended path under control, keeping the joints aligned with the resistance.', 'Keep the movement controlled throughout the range.', 'Bring the weight or body back to its starting position without rushing.']::text[]),
('Single-Arm Fly on Exercise Ball (Dumbbell)', 'chest', array['shoulders', 'triceps']::text[], 'dumbbell', 'weight_reps', 'Am02iPd', array['Take a seat on an exercise ball with a dumbbell in one hand and your feet planted.', 'Step your feet forward and roll your body down until your upper back is resting on the exercise ball.', 'Keep a soft elbow bend and set the shoulders before moving the arms.', 'With a soft bend in the elbows, sweep your arms together in a wide arc.', 'Keep both shoulders level and resist turning toward the working arm.', 'Open the arms back along the same arc without dropping the load; switch sides when the set calls for it.']::text[]),
('Lower Back Curl', 'back', array['glutes', 'hamstrings']::text[], 'bodyweight', 'bodyweight_reps', 'ANbbry2', array['Settle onto your stomach with your legs extended and your arms by your sides.', 'Engage your glutes and hamstrings, and With control lift your upper body off the ground, curling your back upwards.', 'Set the shoulders and upper arms before bending the elbows.', 'Bend your elbows to bring the weight toward your shoulders without swinging your torso.', 'Keep the torso quiet and let the elbow bend lift the weight.', 'Lower until the elbows are nearly straight, keeping the upper arms still.']::text[]),
('Full Can Lateral Raise (Dumbbell)', 'shoulders', array['traps']::text[], 'dumbbell', 'weight_reps', 'AQ0mC4Y', array['Stand and set your feet about shoulder width, holding a dumbbell in each hand with your palms facing your body.', 'Keep your spine in a comfortable neutral position and Brace your trunk.', 'Start with a manageable load and a small bend in the elbows.', 'Raise the arms out to the sides to about shoulder height without leaning or shrugging.', 'Stop near shoulder height rather than shrugging to lift higher.', 'Lower the arms slowly to your sides without swinging the weight.']::text[]),
('Lying Elbow to Knee', 'core', array['back']::text[], 'bodyweight', 'bodyweight_reps', 'AQIhRjM', array['Settle onto your back with your knees bent and feet planted.', 'Set your hands behind your head with your elbows pointing outwards.', 'Set the pelvis and keep the neck relaxed before curling upward.', 'Curl your rib cage toward your pelvis, letting the abdominals move the torso.', 'Leave a little space between the chin and chest; keep the movement in the torso.', 'Lower the shoulders or torso with control before the next curl.']::text[]),
('Crossover Reverse Fly (Cable)', 'shoulders', array['back', 'traps']::text[], 'cable', 'weight_reps', 'aqvSOQE', array['Connect a D-handle to each low pulley cable and stand in the middle of the cable crossover machine.', 'Hold the handles with a pronated grip (palms facing down) and take a step forward, positioning your feet about shoulder width.', 'Keep a soft elbow bend and set the shoulders before moving the arms.', 'Bring the handles across the front of your chest in a broad arc, keeping a slight elbow bend.', 'Keep the elbow angle nearly unchanged through the arc.', 'Open the arms back along the same arc without dropping the load.']::text[]),
('Flexion Leg Sit Up (Bent Knee)', 'core', '{}'::text[], 'bodyweight', 'bodyweight_reps', 'AR0ig3o', array['Settle onto your back with your knees bent and feet planted.', 'Set your hands behind your head with your elbows pointing outwards.', 'Set the pelvis and keep the neck relaxed before curling upward.', 'Curl your rib cage toward your pelvis, letting the abdominals move the torso.', 'Leave a little space between the chin and chest; keep the movement in the torso.', 'Lower the shoulders or torso with control before the next curl.']::text[]),
('Single-Arm Single Leg Split Squat (Band)', 'quads', array['glutes', 'hamstrings']::text[], 'band', 'weight_reps', 'arsYEd3', array['Stand and set your feet about hip width and place a resistance band around your ankles.', 'Reach one leg forward and rest the top of your foot on a bench or step behind you.', 'Brace the abdomen and spread pressure across the whole foot.', 'Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.', 'Keep both shoulders level and resist turning toward the working arm.', 'Stand fully, reset your footing and breathing, then begin the next descent; switch sides when the set calls for it.']::text[]),
('Modified Push Up to Lower Arms', 'forearms', array['triceps', 'chest', 'shoulders']::text[], 'bodyweight', 'bodyweight_reps', 'arvaszz', array['Begin in a push-up position with your hands directly under your shoulders and your body in a straight line.', 'Lower your body down toward the ground by bending your elbows, keeping them close to your sides.', 'Brace the abdomen and glutes so the shoulders, hips and ankles move together.', 'Bend your elbows to lower your chest while keeping your body in one line.', 'Keep the head in line with the spine as the elbows bend.', 'Press back to straight arms, keeping the body line intact.']::text[]),
('Incline Single-Arm Lateral Raise (Dumbbell)', 'shoulders', array['traps', 'triceps']::text[], 'dumbbell', 'weight_reps', 'aTNKZiC', array['Take a seat on an incline bench with a dumbbell in one hand, resting it on your thigh.', 'Tip forward and position your upper arm against the inside of your thigh.', 'Start with a manageable load and a small bend in the elbows.', 'Raise the arms out to the sides to about shoulder height without leaning or shrugging.', 'Keep both shoulders level and resist turning toward the working arm.', 'Lower the arms slowly to your sides without swinging the weight; switch sides when the set calls for it.']::text[]),
('Sit-Up (Assisted)', 'core', '{}'::text[], 'bodyweight', 'bodyweight_reps', 'aumB2IV', array['Sit at the bench edge, or ask a partner to secure your feet.', 'Settle onto your back with your knees bent and feet planted.', 'Set the pelvis and keep the neck relaxed before curling upward.', 'Curl your rib cage toward your pelvis, letting the abdominals move the torso.', 'Leave a little space between the chin and chest; keep the movement in the torso.', 'Lower the shoulders or torso with control before the next curl.']::text[]),
('Twist (Cable)', 'core', '{}'::text[], 'cable', 'weight_reps', 'aVs3BR3', array['Stand and set your feet about shoulder width, facing the cable machine.', 'Take hold of the cable handle with both hands ahead of your chest, keeping your arms soft.', 'Set the pelvis and make the turn through the rib cage.', 'Turn through the torso while the hips and lower body stay as steady as the setup allows.', 'Keep the turn smooth instead of throwing the arms across the body.', 'Return through center before turning to the other side.']::text[]),
('Reverse-Grip Machine Lat Pulldown', 'back', array['biceps', 'forearms']::text[], 'machine', 'weight_reps', 'AwAIlSo', array['Fit the seat to your body, then settle into the machine.', 'Hold the handles with palms facing up, just beyond shoulder width.', 'Sit tall and set the shoulders before drawing the handle down.', 'Pull the handle down by driving your elbows toward your ribs; keep your torso steady.', 'Keep the palms in the chosen grip without bending the wrists back.', 'Let the handle rise steadily until the arms are long, then reset the shoulders.']::text[]),
('Glute Bridge Two-Leg on Bench', 'glutes', array['hamstrings', 'core']::text[], 'bodyweight', 'bodyweight_reps', 'aWedzZX', array['Take a seat on the edge of a bench with your back against it and your feet planted.', 'Set your hands on the bench beside your hips for support.', 'Plant the feet and keep the ribs from flaring as the hips prepare to rise.', 'Press through the feet and lift your hips until your torso and thighs line up.', 'Stop when the hips line up with the torso; do not arch higher through the lower back.', 'Lower the hips steadily and keep the feet planted for the next lift.']::text[]),
('Finger Curls', 'forearms', '{}'::text[], 'barbell', 'weight_reps', 'awG04cF', array['Plant both feet while seated on a bench; hold a barbell with palms facing up.', 'Set your forearms on your thighs, letting your wrists hang off the edge.', 'Keep the elbows relaxed so the small muscles of the hand or forearm take the load.', 'Let the bar roll toward your fingertips, then close your fingers firmly around it.', 'Use a small, smooth range without swinging the elbows.', 'Ease back to the start without letting the load fall from your hands.']::text[]),
('Twist Hip Lift', 'glutes', array['core', 'hamstrings']::text[], 'bodyweight', 'bodyweight_reps', 'AX1kB0o', array['Settle onto your back with your knees bent and feet planted.', 'Set your hands by your sides for support.', 'Plant the feet and keep the ribs from flaring as the hips prepare to rise.', 'Press through the feet and lift your hips until your torso and thighs line up.', 'Stop when the hips line up with the torso; do not arch higher through the lower back.', 'Lower the hips steadily and keep the feet planted for the next lift.']::text[]),
('Single-Arm Snatch (Kettlebell)', 'shoulders', array['traps', 'forearms', 'core']::text[], 'kettlebell', 'weight_reps', 'aXcUyKb', array['Stand and set your feet about shoulder width, holding a kettlebell in one hand between your legs.', 'Bend your knees slightly and hinge at the hips, lowering the kettlebell toward the ground.', 'Brace before the pull and keep the load close to the body.', 'Drive through the legs and hips, then guide the weight to its receiving position.', 'Keep both shoulders level and resist turning toward the working arm.', 'Stand tall to finish, then lower the weight under control before the next rep; switch sides when the set calls for it.']::text[]),
('Hack Single-Leg Calf Raise', 'calves', array['hamstrings', 'glutes']::text[], 'machine', 'weight_reps', 'AxFoqAD', array['Set the sled machine to an appropriate weight.', 'Step onto the sled machine with one foot, keeping the other foot off the ground.', 'Let the ankles move freely while the rest of the body stays quiet.', 'Rise through the balls of your feet, lifting the heels as high as you can without rocking.', 'Keep the pelvis level as the supporting leg does the work.', 'Lower the heels at a measured pace before rising again; switch sides when the set calls for it.']::text[]),
('Step-Up (Dumbbell)', 'glutes', array['quads', 'hamstrings', 'calves']::text[], 'dumbbell', 'weight_reps', 'aXtJhlg', array['Take your place in front of a bench or step with a dumbbell in each hand, palms facing your body.', 'Set your right foot on the bench or step, ensuring your entire foot is in contact with the surface.', 'Put the lead foot fully on the platform before shifting your weight onto it.', 'Step onto the platform and drive through the lead foot to stand tall on it.', 'Keep the front foot planted and avoid collapsing inward at the knee.', 'Push through the lead foot to return to the start, then change legs as planned.']::text[]),
('Incline Shoulder Raises (Smith Machine)', 'chest', array['shoulders', 'traps']::text[], 'machine', 'weight_reps', 'ayAHcEm', array['Set the smith machine to an incline position.', 'Face the machine from a stable stance with feet about shoulder width.', 'Start with a manageable load and a small bend in the elbows.', 'Lift the weights away from your torso to about shoulder height, keeping the elbows softly bent.', 'Stop near shoulder height rather than shrugging to lift higher.', 'Lower the arms slowly to your sides without swinging the weight.']::text[]),
('Incline Push-Up', 'chest', array['triceps', 'shoulders']::text[], 'bodyweight', 'bodyweight_reps', 'B1EVP9F', array['Set your hands on an elevated surface, such as a bench or step, just beyond shoulder width.', 'Reach your legs behind you, resting on the balls of your feet, creating a straight line from your head to your heels.', 'Brace the abdomen and glutes so the shoulders, hips and ankles move together.', 'Bend your elbows to lower your chest while keeping your body in one line.', 'Keep the head in line with the spine as the elbows bend.', 'Press back to straight arms, keeping the body line intact.']::text[]),
('Front Raise (Barbell)', 'shoulders', array['biceps', 'triceps']::text[], 'barbell', 'weight_reps', 'b2Uoz54', array['Stand and set your feet about shoulder width and hold a barbell ahead of your thighs with palms facing down.', 'Maintain straight arms and lift the barbell forward and upward until it reaches shoulder level.', 'Start with a manageable load and a small bend in the elbows.', 'Lift the arms forward to about shoulder height, keeping the ribs down and torso still.', 'Stop near shoulder height rather than shrugging to lift higher.', 'Lower the arms slowly to your sides without swinging the weight.']::text[]),
('Seated Biceps Curl (On Stability Ball) (Weighted)', 'biceps', array['forearms']::text[], 'other', 'weight_reps', 'b4b6afT', array['Take a seat on a stability ball with your feet planted and your back straight.', 'Take a medicine ball with palms facing up, and let your arms hang down by your sides.', 'Set the shoulders and upper arms before bending the elbows.', 'Bend your elbows to bring the weight toward your shoulders without swinging your torso.', 'Keep the ball steady and use the feet to manage your balance.', 'Lower until the elbows are nearly straight, keeping the upper arms still.']::text[]),
('Exercise Ball Alternating Arm Ups', 'back', array['shoulders', 'core']::text[], 'bodyweight', 'bodyweight_reps', 'b5uBMv2', array['Take a seat on the stability ball with your feet planted and your back straight.', 'Take a dumbbell in each hand with your palms facing inwards and your arms extended down by your sides.', 'Start with a manageable load and a small bend in the elbows.', 'Lift the weights away from your torso to about shoulder height, keeping the elbows softly bent.', 'Finish one side''s motion before the other side takes over.', 'Lower the arms slowly to your sides without swinging the weight; switch sides when the set calls for it.']::text[]),
('Hands Clasped Circular Toe Touch', 'glutes', array['hamstrings', 'quads', 'calves']::text[], 'bodyweight', 'bodyweight_reps', 'B5xca8s', array['Stand and set your feet about shoulder width and your hands clasped together ahead of your chest.', 'Bend your knees slightly and hinge forward at the hips, with your spine steady.', 'Soften the knees and let the hips start the fold.', 'Fold forward from the hips and let your hands travel toward your feet without forcing the reach.', 'Keep the movement controlled throughout the range.', 'Hold briefly at a comfortable depth, then rise by extending the hips.']::text[]),
('Potty Squat with Support', 'glutes', array['quads', 'hamstrings', 'calves']::text[], 'bodyweight', 'bodyweight_reps', 'b63ZzGe', array['Stand and set your feet about shoulder width, toes pointing slightly outward.', 'Use a stable support, such as a chair or wall, for balance.', 'Brace the abdomen and spread pressure across the whole foot.', 'Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.', 'Drive upward with the chest and hips rising together; keep the knees from collapsing inward.', 'Stand fully, reset your footing and breathing, then begin the next descent.']::text[]),
('Seated Wrist Curl (Smith Machine)', 'forearms', array['biceps']::text[], 'machine', 'weight_reps', 'B6dAO1t', array['Take a seat on a bench in front of a Smith machine with your feet planted.', 'Hold the barbell with palms facing up, hands about shoulder width.', 'Keep the elbows relaxed so the small muscles of the hand or forearm take the load.', 'Move through the wrists or fingers while the forearms stay supported and still.', 'Use a small, smooth range without swinging the elbows.', 'Ease back to the start without letting the load fall from your hands.']::text[]),
('Preacher Curl (Machine)', 'biceps', array['forearms']::text[], 'machine', 'weight_reps', 'b6hQYMb', array['Fit the seat to your body, then settle into the machine.', 'Set your upper arms on the pad and grip the handles with palms facing up.', 'Set the working upper arm against the preacher pad and leave the elbow free to bend.', 'Curl the weight while your upper arms stay in contact with the pad.', 'Keep the torso quiet and let the elbow bend lift the weight.', 'Lower until the elbows are nearly straight, keeping the upper arms still.']::text[]),
('Alternating Renegade Row (Kettlebell)', 'back', array['core', 'shoulders']::text[], 'kettlebell', 'weight_reps', 'b9kqlBy', array['Begin in a high plank position with your hands gripping the kettlebells and your feet about hip width.', 'Brace your trunk and keep your body in a straight line from head to heels.', 'Set the torso and allow the arms to reach forward without rounding excessively.', 'Draw your elbows back and bring the handle or weight toward your torso.', 'Finish one side''s motion before the other side takes over.', 'Reach the arms forward again without letting the torso lurch; switch sides when the set calls for it.']::text[]),
('Hanging Oblique Knee Raise', 'core', '{}'::text[], 'bodyweight', 'bodyweight_reps', 'BaE7O6U', array['Suspend yourself from a pull-up bar with your arms straight and your palms turned away from you.', 'Brace your trunk and lift your knees toward your chest, twisting your torso to the side as you do so.', 'Brace the abdomen and keep the shoulders anchored to the support.', 'Lift your legs by bracing your trunk and moving at the hips rather than swinging.', 'Slow the legs before they pull the lower back out of position.', 'Lower the legs slowly without swinging or losing your trunk position.']::text[]),
('Standing Toe Touch', 'glutes', array['hamstrings', 'calves']::text[], 'bodyweight', 'bodyweight_reps', 'BbfB8Gb', array['Stand and set your feet about shoulder width and your arms by your sides.', 'Bend forward at the waist, with your spine steady and your knees soft.', 'Settle into the starting position and take an easy breath before moving deeper.', 'Fold forward from the hips and let your hands travel toward your feet without forcing the reach.', 'Stay in a mild stretch rather than pulling farther with momentum.', 'Hold briefly at a comfortable depth, then rise by extending the hips.']::text[]),
('Standing Alternate Overhead Press (Dumbbell)', 'shoulders', array['triceps', 'core']::text[], 'dumbbell', 'weight_reps', 'bBi35y3', array['Stand and set your feet about shoulder width, holding a dumbbell in each hand at shoulder level with your palms facing forward.', 'Before moving, press one dumbbell overhead, fully extending your arm.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Finish one side''s motion before the other side takes over.', 'Lower the weight to its starting height under control before pressing again; switch sides when the set calls for it.']::text[]),
('Lying Straight-Leg Raise (Band)', 'core', '{}'::text[], 'band', 'weight_reps', 'bbLR7fB', array['Settle onto your back with your legs straight and your feet together.', 'Set the band around the arches of your feet and hold the ends of the band with your hands.', 'Brace the abdomen and keep the shoulders anchored to the support.', 'Lift your legs by bracing your trunk and moving at the hips rather than swinging.', 'Control the band on the way back instead of letting it snap you into position.', 'Lower the legs slowly without swinging or losing your trunk position.']::text[]),
('Close-Grip Curl (Cable)', 'biceps', array['forearms']::text[], 'cable', 'weight_reps', 'BCGQ6J5', array['Connect a straight bar to a low pulley cable machine.', 'Face the machine with your feet about shoulder width and your knees soft.', 'Set the shoulders and upper arms before bending the elbows.', 'Bend your elbows to bring the weight toward your shoulders without swinging your torso.', 'Keep the torso quiet and let the elbow bend lift the weight.', 'Lower until the elbows are nearly straight, keeping the upper arms still.']::text[]),
('Seated Alternate Leg Raise (Barbell)', 'core', array['quads']::text[], 'barbell', 'weight_reps', 'BCs0G2F', array['Take a seat on a bench with your back straight and hold a barbell across your thighs.', 'Set your hands on the sides of the bench for support.', 'Brace the abdomen and keep the shoulders anchored to the support.', 'Lift your legs by bracing your trunk and moving at the hips rather than swinging.', 'Finish one side''s motion before the other side takes over.', 'Lower the legs slowly without swinging or losing your trunk position; switch sides when the set calls for it.']::text[]),
('Standing Single-Arm Extension (Dumbbell)', 'triceps', array['shoulders']::text[], 'dumbbell', 'weight_reps', 'BCUR88E', array['Stand and set your feet about shoulder width, holding a dumbbell in one hand.', 'Before moving, raise the dumbbell overhead, fully extending your arm.', 'Set the upper arms in place before extending the elbows.', 'Keep the upper arms steady and extend through the elbows to move the weight.', 'Keep both shoulders level and resist turning toward the working arm.', 'Bend the elbows slowly to return to the start of the next rep; switch sides when the set calls for it.']::text[]),
('Wrist Rollerer', 'forearms', array['biceps', 'triceps']::text[], 'bodyweight', 'bodyweight_reps', 'bd5b860', array['Connect a weight to one end of a rope or bar.', 'Take hold of the other end of the rope or bar with both hands, palms facing down.', 'Keep the elbows relaxed so the small muscles of the hand or forearm take the load.', 'Move through the wrists or fingers while the forearms stay supported and still.', 'Use a small, smooth range without swinging the elbows.', 'Ease back to the start without letting the load fall from your hands.']::text[]),
('Frankenstein Squat', 'glutes', array['quads', 'hamstrings', 'calves']::text[], 'barbell', 'weight_reps', 'bdWcbaU', array['Stand and set your feet about shoulder width and hold the barbell ahead of your body with straight arms.', 'With your back straight, lower your body by bending at the knees and hips, as if sitting back into a chair.', 'Brace the abdomen and spread pressure across the whole foot.', 'Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.', 'Drive upward with the chest and hips rising together; keep the knees from collapsing inward.', 'Stand fully, reset your footing and breathing, then begin the next descent.']::text[]),
('Side-To-Side Chin', 'back', array['biceps', 'forearms']::text[], 'bodyweight', 'bodyweight_reps', 'BeReYBf', array['Stand and set your feet about shoulder width and your knees soft.', 'Hold a pull-up bar with palms facing down, hands just beyond shoulder width.', 'Begin from a controlled hang with the shoulders active rather than slack.', 'Pull your elbows down and bring your upper chest toward the bar without kicking your legs.', 'Avoid swinging the legs to clear the bar.', 'Lower to long arms without dropping suddenly from the top.']::text[]),
('Incline Press on Exercise Ball (Dumbbell)', 'chest', array['shoulders', 'triceps']::text[], 'dumbbell', 'weight_reps', 'bfiHMpI', array['Take a seat on an exercise ball with a dumbbell in each hand, palms facing forward.', 'With control walk your feet forward, rolling your body down the ball until your head, neck, and upper back are supported on the ball.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Keep the ball steady and use the feet to manage your balance.', 'Lower the weight to its starting height under control before pressing again.']::text[]),
('Incline Single-Arm Press on Exercise Ball (Dumbbell)', 'chest', array['shoulders', 'triceps']::text[], 'dumbbell', 'weight_reps', 'Bg5JKSH', array['Take a seat on an exercise ball with a dumbbell in one hand, feet planted.', 'With control walk your feet forward, rolling the ball until your head, neck, and upper back are supported on the ball.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Keep both shoulders level and resist turning toward the working arm.', 'Lower the weight to its starting height under control before pressing again; switch sides when the set calls for it.']::text[]),
('Reverse T-Bar Row (Machine)', 'back', array['biceps', 'forearms']::text[], 'machine', 'weight_reps', 'BgljGjd', array['Set the seat height and footplate position on the leverage machine.', 'Take a seat on the machine with your chest against the pad and your feet flat on the footplate.', 'Set the torso and allow the arms to reach forward without rounding excessively.', 'Draw your elbows back and bring the handle or weight toward your torso.', 'Bring the elbows back without jerking the torso.', 'Reach the arms forward again without letting the torso lurch.']::text[]),
('Standing Single-Arm Curl (Over Incline Bench) (Dumbbell)', 'biceps', array['forearms']::text[], 'dumbbell', 'weight_reps', 'BIb1tGo', array['Stand and set your feet about shoulder width, holding a dumbbell in one hand with your palm facing forward.', 'Set your other hand on an incline bench for support.', 'Set the shoulders and upper arms before bending the elbows.', 'Bend your elbows to bring the weight toward your shoulders without swinging your torso.', 'Keep both shoulders level and resist turning toward the working arm.', 'Lower until the elbows are nearly straight, keeping the upper arms still; switch sides when the set calls for it.']::text[]),
('Bent Over Row (Dumbbell)', 'back', array['biceps', 'forearms']::text[], 'dumbbell', 'weight_reps', 'BJ0Hz5L', array['Stand and set your feet about shoulder width, knees soft, and hold a dumbbell in each hand with your palms facing your body.', 'Bend forward at the hips, with your spine steady and your core engaged.', 'Set the torso and allow the arms to reach forward without rounding excessively.', 'Draw your elbows back and bring the handle or weight toward your torso.', 'Bring the elbows back without jerking the torso.', 'Reach the arms forward again without letting the torso lurch.']::text[]),
('Standing Hand Squeeze (Weighted)', 'forearms', array['biceps', 'triceps']::text[], 'bodyweight', 'bodyweight_reps', 'bjqbauy', array['Stand and set your feet about shoulder width and hold a weight in each hand.', 'Reach your arms straight in front of you, palms facing each other.', 'Keep the elbows relaxed so the small muscles of the hand or forearm take the load.', 'Move through the wrists or fingers while the forearms stay supported and still.', 'Use a small, smooth range without swinging the elbows.', 'Ease back to the start without letting the load fall from your hands.']::text[]),
('Bodyweight Standing Calf Raise', 'calves', '{}'::text[], 'bodyweight', 'bodyweight_reps', 'bJYHBIN', array['Stand and set your feet about shoulder width, toes pointing forward.', 'Set your hands on a wall or stable surface for balance.', 'Let the ankles move freely while the rest of the body stays quiet.', 'Rise through the balls of your feet, lifting the heels as high as you can without rocking.', 'Pause at the top without rolling the ankles outward.', 'Lower the heels at a measured pace before rising again.']::text[]),
('Over Bench Neutral Wrist Curl (Dumbbell)', 'biceps', array['forearms']::text[], 'dumbbell', 'weight_reps', 'BKa8dmT', array['Plant both feet while seated on a bench; hold a dumbbell in each hand, palms facing up.', 'Support the forearms on the bench while leaving the wrists free beyond its edge.', 'Keep the elbows relaxed so the small muscles of the hand or forearm take the load.', 'Move through the wrists or fingers while the forearms stay supported and still.', 'Use a small, smooth range without swinging the elbows.', 'Ease back to the start without letting the load fall from your hands.']::text[]),
('Single-Arm Towel Row', 'back', array['biceps', 'forearms']::text[], 'bodyweight', 'bodyweight_reps', 'bKWbrTA', array['Stand and set your feet about shoulder width, knees soft, and hold a towel with one hand.', 'Bend forward at the waist, with your spine steady and your core engaged.', 'Set the torso and allow the arms to reach forward without rounding excessively.', 'Draw your elbows back and bring the handle or weight toward your torso.', 'Keep both shoulders level and resist turning toward the working arm.', 'Reach the arms forward again without letting the torso lurch; switch sides when the set calls for it.']::text[]),
('Straddle Planche', 'core', array['shoulders', 'triceps', 'chest']::text[], 'bodyweight', 'bodyweight_reps', 'BL3GHeY', array['Begin in a push-up position with your hands about shoulder width and your feet spread wide apart.', 'Brace your trunk and With control shift your weight forward, bringing your shoulders over your hands.', 'Brace the abdomen and find a position you can maintain without holding your breath.', 'Brace your midsection and hold the position while breathing normally.', 'Keep breathing steadily as you maintain the same body line.', 'Keep the shape for the planned time, then come out of it with control.']::text[]),
('Two-Arm Military Press (Kettlebell)', 'shoulders', array['triceps', 'back']::text[], 'kettlebell', 'weight_reps', 'blBXysN', array['Stand and set your feet about shoulder width, holding a kettlebell in each hand at shoulder level with your palms facing forward.', 'Brace your trunk and press the kettlebells overhead, straighten your arms.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Keep the wrists stacked and use a shoulder path that feels natural.', 'Lower the weight to its starting height under control before pressing again.']::text[]),
('Reverse Wrist Curl (Dumbbell)', 'forearms', array['biceps']::text[], 'dumbbell', 'weight_reps', 'BLCvwr2', array['Take a seat on a bench or chair with your feet planted.', 'Take a dumbbell in each hand with palms facing down.', 'Keep the elbows relaxed so the small muscles of the hand or forearm take the load.', 'Move through the wrists or fingers while the forearms stay supported and still.', 'Use a small, smooth range without swinging the elbows.', 'Ease back to the start without letting the load fall from your hands.']::text[]),
('London Bridge', 'back', array['shoulders', 'biceps', 'forearms']::text[], 'cable', 'weight_reps', 'bLyQokI', array['Connect the rope to a high anchor point.', 'Face the away from the anchor point from a stable stance with feet about shoulder width.', 'Set the torso and allow the arms to reach forward without rounding excessively.', 'Draw your elbows back and bring the handle or weight toward your torso.', 'Bring the elbows back without jerking the torso.', 'Reach the arms forward again without letting the torso lurch.']::text[]),
('Lying External Shoulder Rotation (Dumbbell)', 'shoulders', array['triceps']::text[], 'dumbbell', 'weight_reps', 'bmBf7LN', array['Settle onto your side on a flat bench with your upper arm against your side and your elbow bent 90 degrees.', 'Take a dumbbell in your hand with your palm facing down.', 'Set the pelvis and make the turn through the rib cage.', 'Turn through the torso while the hips and lower body stay as steady as the setup allows.', 'Keep the turn smooth instead of throwing the arms across the body.', 'Return through center before turning to the other side.']::text[]),
('Tuck Crunch', 'core', '{}'::text[], 'bodyweight', 'bodyweight_reps', 'BMMolZ3', array['Settle onto your back with your knees bent and feet planted.', 'Set your hands behind your head with your elbows pointing outwards.', 'Set the pelvis and keep the neck relaxed before curling upward.', 'Curl your rib cage toward your pelvis, letting the abdominals move the torso.', 'Leave a little space between the chin and chest; keep the movement in the torso.', 'Lower the shoulders or torso with control before the next curl.']::text[]),
('Sumo Pull Through (Dumbbell)', 'glutes', array['hamstrings', 'quads', 'core']::text[], 'dumbbell', 'weight_reps', 'BmrwWzo', array['Stand and set your feet wider than about shoulder width, toes pointed outwards.', 'Take a dumbbell with both hands ahead of your body, arms extended.', 'Unlock the knees and brace the abdomen before moving the hips back.', 'Push the hips back while keeping the load close and the spine steady.', 'Keep the weight close to the legs and stop when the back would begin to round.', 'Drive the hips forward to stand tall without leaning back at the top.']::text[]),
('Gorilla Chin', 'core', array['forearms', 'biceps']::text[], 'bodyweight', 'bodyweight_reps', 'bmwlYvD', array['Stand and set your feet about shoulder width and your knees soft.', 'Hold a pull-up bar with palms facing down, just beyond shoulder width.', 'Begin from a controlled hang with the shoulders active rather than slack.', 'Pull your elbows down and bring your upper chest toward the bar without kicking your legs.', 'Avoid swinging the legs to clear the bar.', 'Lower to long arms without dropping suddenly from the top.']::text[]),
('Sit-Up', 'core', '{}'::text[], 'bodyweight', 'bodyweight_reps', 'Bn6TXyO', array['Settle onto your back with your knees bent and feet planted.', 'Set your hands behind your head with your elbows pointing outwards.', 'Set the pelvis and keep the neck relaxed before curling upward.', 'Curl your rib cage toward your pelvis, letting the abdominals move the torso.', 'Leave a little space between the chin and chest; keep the movement in the torso.', 'Lower the shoulders or torso with control before the next curl.']::text[]),
('Pin Presses (Barbell)', 'triceps', array['shoulders']::text[], 'barbell', 'weight_reps', 'bndCa3Q', array['Prepare a barbell on a power rack at chest height.', 'Face the barbell and position yourself underneath it, from a stable stance with feet about shoulder width.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Keep the wrists stacked and use a shoulder path that feels natural.', 'Lower the weight to its starting height under control before pressing again.']::text[]),
('Pronate-Grip Triceps Extension (Dumbbell)', 'triceps', array['forearms']::text[], 'dumbbell', 'weight_reps', 'bpJL2Qs', array['Take a seat on a bench or chair with your back straight and feet planted.', 'Take a dumbbell with both hands, palms facing down, and extend your arms straight up overhead.', 'Set the upper arms in place before extending the elbows.', 'Keep the upper arms steady and extend through the elbows to move the weight.', 'Keep the upper arms steady while the forearms travel.', 'Bend the elbows slowly to return to the start of the next rep.']::text[]),
('Single-Arm Chest Fly on Exercise Ball (Dumbbell)', 'chest', array['shoulders', 'triceps']::text[], 'dumbbell', 'weight_reps', 'Bpkf41o', array['Take a seat on an exercise ball with a dumbbell in one hand and your feet planted.', 'Step your feet forward, rolling the ball until your upper back is supported on the ball and your head, neck, and shoulders are off the ball.', 'Keep a soft elbow bend and set the shoulders before moving the arms.', 'With a soft bend in the elbows, sweep your arms together in a wide arc.', 'Keep both shoulders level and resist turning toward the working arm.', 'Open the arms back along the same arc without dropping the load; switch sides when the set calls for it.']::text[]),
('Cuban Press (Dumbbell)', 'shoulders', array['triceps', 'back']::text[], 'dumbbell', 'weight_reps', 'BqgCRif', array['Stand and set your feet about shoulder width, holding a dumbbell in each hand at shoulder height with your palms facing down.', 'With your core engaged and your back straight, press the dumbbells straight up overhead until your arms are straight.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Keep the wrists stacked and use a shoulder path that feels natural.', 'Lower the weight to its starting height under control before pressing again.']::text[]),
('Single-Arm Pullover on Exercise Ball (Dumbbell)', 'chest', array['triceps', 'back']::text[], 'dumbbell', 'weight_reps', 'bQHPBU3', array['Take a seat on an exercise ball with your feet planted and your knees bent at a 90-degree angle.', 'Take a dumbbell with one hand and extend your arm straight up above your chest.', 'Set the ribs down and keep a small elbow bend before lowering the weight.', 'Lower the weight in an arc behind your head until you feel a comfortable shoulder stretch.', 'Keep both shoulders level and resist turning toward the working arm.', 'Pull the weight back over the chest along the same arc, without lifting the ribs; switch sides when the set calls for it.']::text[]),
('Single-Arm Kickback (Dumbbell)', 'triceps', array['shoulders']::text[], 'dumbbell', 'weight_reps', 'bQy2Eni', array['Stand and set your feet about shoulder width and hold a dumbbell in your right hand.', 'Bend your knees slightly and hinge forward at the hips, with your spine steady.', 'Set the upper arms in place before extending the elbows.', 'Hold the upper arm beside your torso and straighten the elbow behind you.', 'Keep both shoulders level and resist turning toward the working arm.', 'Bend the elbows slowly to return to the start of the next rep; switch sides when the set calls for it.']::text[]),
('Bodyweight Squatting Row (With Towel)', 'back', array['biceps', 'shoulders']::text[], 'bodyweight', 'bodyweight_reps', 'BReCuOn', array['Stand and set your feet about shoulder width, holding a towel in front of you with your palms facing down.', 'Bend your knees and lower your body into a squat position, with your spine steady and your chest up.', 'Brace the abdomen and spread pressure across the whole foot.', 'Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.', 'Drive upward with the chest and hips rising together; keep the knees from collapsing inward.', 'Stand fully, reset your footing and breathing, then begin the next descent.']::text[]),
('Seated Dip (Machine)', 'triceps', array['chest', 'shoulders']::text[], 'machine', 'weight_reps', 'BRImeP8', array['Set the seat height so that your feet are flat on the ground and your knees are at a 90-degree angle.', 'Hold the handles of the leverage machine with your palms facing down and your arms straight.', 'Set the shoulders down and keep the elbows pointed mostly behind you.', 'Bend the elbows to lower between the supports; stop at a comfortable shoulder depth.', 'Choose a depth that lets the shoulders stay comfortable.', 'Press through the hands to rise, then reset the shoulders before another rep.']::text[]),
('Decline Shrug (Dumbbell)', 'traps', array['shoulders', 'back']::text[], 'dumbbell', 'weight_reps', 'bRlbdjK', array['Prepare a decline bench at a 45-degree angle.', 'Position yourself face down on the bench with your chest and stomach resting on it.', 'Let the arms hang long and keep the head neutral.', 'Lift your shoulders toward your ears without bending the elbows or rolling the shoulders.', 'Lift and lower vertically without circling the shoulders.', 'Bring the weight or body back to its starting position without rushing.']::text[]),
('Low Bar Squat (Barbell)', 'glutes', array['quads', 'hamstrings', 'calves']::text[], 'barbell', 'weight_reps', 'bTpEUcm', array['Stand and set your feet about shoulder width and the barbell resting on your upper back.', 'With your chest up and core engaged, With control lower your body by bending your knees and pushing your hips back.', 'Brace the abdomen and spread pressure across the whole foot.', 'Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.', 'Drive upward with the chest and hips rising together; keep the knees from collapsing inward.', 'Stand fully, reset your footing and breathing, then begin the next descent.']::text[]),
('Alternate Biceps Curl (Dumbbell)', 'biceps', array['forearms']::text[], 'dumbbell', 'weight_reps', 'BU15nH4', array['Stand tall with a dumbbell in each hand, palms facing forward and arms straight.', 'With your upper arms stationary, exhale and curl the weights while contracting your biceps.', 'Set the shoulders and upper arms before bending the elbows.', 'Bend your elbows to bring the weight toward your shoulders without swinging your torso.', 'Finish one side''s motion before the other side takes over.', 'Lower until the elbows are nearly straight, keeping the upper arms still; switch sides when the set calls for it.']::text[]),
('Butterfly Yoga Pose', 'quads', array['hamstrings']::text[], 'bodyweight', 'bodyweight_reps', 'bWlZvXh', array['Take a seat on the floor with your legs extended in front of you.', 'Bend your knees and bring the soles of your feet together, letting your knees to fall out to the sides.', 'Settle into the starting position and take an easy breath before moving deeper.', 'Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.', 'Stay in a mild stretch rather than pulling farther with momentum.', 'Hold the position with steady breathing, then release gently; repeat on the other side if needed.']::text[]),
('Lying (Side) Quads Stretch', 'quads', array['hamstrings']::text[], 'bodyweight', 'duration', 'BWnJR72', array['Settle onto your side with your legs straight.', 'Before moving, bend your top leg and grab your ankle or foot with your hand.', 'Settle into the starting position and take an easy breath before moving deeper.', 'Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.', 'Stay in a mild stretch rather than pulling farther with momentum.', 'Hold the position with steady breathing, then release gently; repeat on the other side if needed.']::text[]),
('Single-Arm Reverse Wrist Curl (Dumbbell)', 'forearms', '{}'::text[], 'dumbbell', 'weight_reps', 'BwSNDGt', array['Take a seat on a bench or chair with your feet planted.', 'Take a dumbbell in one hand with palms facing down, palm facing down.', 'Keep the elbows relaxed so the small muscles of the hand or forearm take the load.', 'Move through the wrists or fingers while the forearms stay supported and still.', 'Keep both shoulders level and resist turning toward the working arm.', 'Ease back to the start without letting the load fall from your hands; switch sides when the set calls for it.']::text[]),
('Single-Arm Reverse Preacher Curl (Dumbbell)', 'biceps', array['forearms']::text[], 'dumbbell', 'weight_reps', 'bWxq4op', array['Take a seat on a preacher bench with your chest against the pad and your arm extended over the edge of the bench, holding a dumbbell with palms facing up.', 'Lower the dumbbell With control until your arm is straight.', 'Set the working upper arm against the preacher pad and leave the elbow free to bend.', 'Curl the weight while your upper arms stay in contact with the pad.', 'Keep both shoulders level and resist turning toward the working arm.', 'Lower until the elbows are nearly straight, keeping the upper arms still; switch sides when the set calls for it.']::text[]),
('Incline Hammer Curl (Dumbbell)', 'biceps', array['forearms']::text[], 'dumbbell', 'weight_reps', 'ByX0WxV', array['Take a seat on an incline bench with a dumbbell in each hand, palms facing your torso and arms straight.', 'Keep your back against the bench and your feet planted.', 'Set the shoulders and upper arms before bending the elbows.', 'Curl with palms facing each other and elbows near your sides; avoid rocking back.', 'Keep the palms facing each other and the wrists straight.', 'Lower until the elbows are nearly straight, keeping the upper arms still.']::text[]),
('Triceps Dips (Weighted)', 'triceps', array['chest', 'shoulders']::text[], 'bodyweight', 'bodyweight_reps', 'bZq4bwK', array['Take a seat on the edge of a bench or chair with your hands gripping the edge next to your hips.', 'Move your butt off the front of the bench with your legs extended in front of you.', 'Set the shoulders down and keep the elbows pointed mostly behind you.', 'Bend the elbows to lower between the supports; stop at a comfortable shoulder depth.', 'Choose a depth that lets the shoulders stay comfortable.', 'Press through the hands to rise, then reset the shoulders before another rep.']::text[]),
('Single-Arm Twisting Chest Press (Band)', 'chest', array['shoulders', 'triceps']::text[], 'band', 'weight_reps', 'c16nYGA', array['Connect the band to a sturdy anchor point at chest height.', 'Stand and set your side facing the anchor point and grab the band with one hand.', 'Brace the torso and align the wrists with the forearms.', 'Press the weights up while turning the palms inward; reverse the turn as you lower.', 'Keep both shoulders level and resist turning toward the working arm.', 'Lower the weight to its starting height under control before pressing again; switch sides when the set calls for it.']::text[]),
('Single-Leg Squat', 'glutes', array['quads', 'hamstrings', 'calves']::text[], 'bodyweight', 'bodyweight_reps', 'C31LMnP', array['Stand and set your feet about shoulder width.', 'Reach one leg forward, keeping it off the ground.', 'Brace the abdomen and spread pressure across the whole foot.', 'Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.', 'Keep the pelvis level as the supporting leg does the work.', 'Stand fully, reset your footing and breathing, then begin the next descent; switch sides when the set calls for it.']::text[]),
('Roller Side Lat Stretch', 'back', array['shoulders', 'triceps']::text[], 'other', 'duration', 'c3Pfhti', array['Stand and set your feet about shoulder width and hold the roller with both hands ahead of your body.', 'Bend your knees slightly and hinge forward at the hips, with your spine steady.', 'Settle into the starting position and take an easy breath before moving deeper.', 'Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.', 'Stay in a mild stretch rather than pulling farther with momentum.', 'Hold the position with steady breathing, then release gently; repeat on the other side if needed.']::text[]),
('Rear Drive (Cable)', 'triceps', array['shoulders', 'back']::text[], 'cable', 'weight_reps', 'c3QQLPi', array['Connect a handle to a low pulley cable machine and stand turned away from the machine.', 'Hold the handle with palms facing down and extend your arms straight out in front of you.', 'Set the upper arms in place before extending the elbows.', 'Keep the upper arms steady and extend through the elbows to move the weight.', 'Keep the upper arms steady while the forearms travel.', 'Bend the elbows slowly to return to the start of the next rep.']::text[]),
('Standing Single Leg Curl', 'hamstrings', array['glutes']::text[], 'bodyweight', 'bodyweight_reps', 'C5jncD2', array['Stand and set your feet about hip width and your hands on your hips.', 'Transfer your weight onto your left leg and lift your right foot off the ground, bending your knee.', 'Line the knees up with the machine or bench edge before starting the curl.', 'Bend your knees to draw the pad toward you without lifting your hips from the support.', 'Keep the hips still while the knees bend.', 'Ease back to the start before repeating.']::text[]),
('Close-Grip Bench Press (Smith Machine)', 'triceps', array['chest', 'shoulders']::text[], 'machine', 'weight_reps', 'C8Crfa4', array['Fit the seat to your body, then settle into the machine.', 'Hold the barbell with a close grip, slightly narrower than about shoulder width.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Keep the wrists stacked and use a shoulder path that feels natural.', 'Lower the weight to its starting height under control before pressing again.']::text[]),
('Side-Lying Hip Adduction', 'quads', array['glutes', 'hamstrings']::text[], 'bodyweight', 'bodyweight_reps', 'c8f5cSY', array['Settle onto your side with your legs straight and stacked on top of each other.', 'Set your bottom arm under your head for support.', 'Square the pelvis before moving the working leg.', 'Draw the working leg inward against resistance without leaning sideways.', 'Move only as far as the pelvis can remain steady.', 'Bring the weight or body back to its starting position without rushing.']::text[]),
('Rope Elevated Seated Row (Cable)', 'back', array['biceps', 'forearms']::text[], 'cable', 'weight_reps', 'c8oybX6', array['Take a seat on the elevated seat facing the cable machine.', 'Take a rope end in each hand with the palms facing each other.', 'Set the torso and allow the arms to reach forward without rounding excessively.', 'Draw your elbows back and bring the handle or weight toward your torso.', 'Bring the elbows back without jerking the torso.', 'Reach the arms forward again without letting the torso lurch.']::text[]),
('Donkey Calf Raise (Machine)', 'calves', array['hamstrings', 'glutes']::text[], 'machine', 'weight_reps', 'C9LuR4A', array['Set the leverage machine to the appropriate height for your body.', 'Set yourself facing the machine, with your toes on the foot platform and your heels hanging off the edge.', 'Let the ankles move freely while the rest of the body stays quiet.', 'Rise through the balls of your feet, lifting the heels as high as you can without rocking.', 'Pause at the top without rolling the ankles outward.', 'Lower the heels at a measured pace before rising again.']::text[]),
('Raise (Dumbbell)', 'shoulders', array['traps', 'back']::text[], 'dumbbell', 'weight_reps', 'c9MnDRp', array['Stand and set your feet about shoulder width and hold a dumbbell in each hand, palms facing your body.', 'Keep your spine in a comfortable neutral position and Brace your trunk.', 'Start with a manageable load and a small bend in the elbows.', 'Lift the weights away from your torso to about shoulder height, keeping the elbows softly bent.', 'Stop near shoulder height rather than shrugging to lift higher.', 'Lower the arms slowly to your sides without swinging the weight.']::text[]),
('Alternating Row (Kettlebell)', 'back', array['biceps', 'forearms']::text[], 'kettlebell', 'weight_reps', 'Ca76jUE', array['Stand and set your feet about shoulder width, knees soft, and hold a kettlebell in each hand with your palms facing your body.', 'Bend forward at the hips, with your spine steady and your core engaged.', 'Set the torso and allow the arms to reach forward without rounding excessively.', 'Draw your elbows back and bring the handle or weight toward your torso.', 'Finish one side''s motion before the other side takes over.', 'Reach the arms forward again without letting the torso lurch; switch sides when the set calls for it.']::text[]),
('Bent Arm Pullover (Barbell)', 'back', array['triceps', 'chest']::text[], 'barbell', 'weight_reps', 'cA9FuWG', array['Settle onto a bench with your head at one end and your feet on the floor.', 'Take a barbell with a shoulder-width grip and extend your arms straight above your chest.', 'Set the ribs down and keep a small elbow bend before lowering the weight.', 'Lower the weight in an arc behind your head until you feel a comfortable shoulder stretch.', 'Keep the ribs down as the arms travel overhead.', 'Pull the weight back over the chest along the same arc, without lifting the ribs.']::text[]),
('Upright Row (Cable)', 'shoulders', array['traps', 'biceps']::text[], 'cable', 'weight_reps', 'cALKspW', array['Stand and set your feet about shoulder width, knees soft, and hold the cable attachment with palms facing down.', 'Keep your spine in a comfortable neutral position and your core engaged throughout the exercise.', 'Set the torso and allow the arms to reach forward without rounding excessively.', 'Draw your elbows back and bring the handle or weight toward your torso.', 'Bring the elbows back without jerking the torso.', 'Reach the arms forward again without letting the torso lurch.']::text[]),
('Kickbacks on Exercise Ball (Dumbbell)', 'triceps', array['shoulders', 'back']::text[], 'dumbbell', 'weight_reps', 'cAvTaSg', array['Take a seat on an exercise ball with your feet planted and your back straight.', 'Take a dumbbell in each hand with your palms facing inwards and your arms bent at a 90-degree angle.', 'Set the upper arms in place before extending the elbows.', 'Hold the upper arm beside your torso and straighten the elbow behind you.', 'Keep the ball steady and use the feet to manage your balance.', 'Bend the elbows slowly to return to the start of the next rep.']::text[]),
('Incline Push Up Depth Jump', 'chest', array['triceps', 'shoulders', 'core']::text[], 'bodyweight', 'bodyweight_reps', 'CB8WET1', array['Choose an elevated surface, such as a bench or step, and place your hands about shoulder width on the edge.', 'Move your feet back, keeping your body in a straight line from head to heels.', 'Brace the abdomen and glutes so the shoulders, hips and ankles move together.', 'Bend your elbows to lower your chest while keeping your body in one line.', 'Keep the head in line with the spine as the elbows bend.', 'Press back to straight arms, keeping the body line intact.']::text[]),
('Rear Pull-Up', 'back', array['biceps', 'forearms']::text[], 'bodyweight', 'bodyweight_reps', 'CbFSYC1', array['Take hold of the pull-up bar with palms facing down, just beyond shoulder width.', 'Suspend yourself from the bar with your arms straight and your body straight.', 'Begin from a controlled hang with the shoulders active rather than slack.', 'Pull up with control, keeping the head neutral and the elbows moving down beside the torso.', 'Avoid swinging the legs to clear the bar.', 'Lower to long arms without dropping suddenly from the top.']::text[]),
('Gripless Shrug (Machine)', 'traps', array['shoulders', 'forearms']::text[], 'machine', 'weight_reps', 'cbuFJrn', array['Fit the seat to your body, then settle into the machine.', 'Hold the handles or bars with palms facing down, keeping your arms straight.', 'Let the arms hang long and keep the head neutral.', 'Lift your shoulders toward your ears without bending the elbows or rolling the shoulders.', 'Lift and lower vertically without circling the shoulders.', 'Ease back to the start before repeating.']::text[]),
('Short Stride Run', 'cardio', array['quads', 'hamstrings', 'calves']::text[], 'bodyweight', 'duration', 'CcWEoWV', array['Choose an open space or a treadmill to perform the exercise.', 'Stand tall and set your feet about hip width.', 'Start at a pace that lets the feet and arms move in sync.', 'Move at a repeatable pace, keeping the motion smooth and your breathing steady.', 'Keep the pattern repeatable as speed increases.', 'Keep the rhythm for the planned interval, slowing if your form starts to slip.']::text[]),
('Alternate Biceps Curl (With Arm Blaster) (Dumbbell)', 'biceps', array['forearms']::text[], 'dumbbell', 'weight_reps', 'CfKsRbG', array['Stand tall with your feet about shoulder width and hold a dumbbell in each hand, palms facing forward.', 'Set the arm blaster on your upper arms, ensuring a secure fit.', 'Set the shoulders and upper arms before bending the elbows.', 'Bend your elbows to bring the weight toward your shoulders without swinging your torso.', 'Finish one side''s motion before the other side takes over.', 'Lower until the elbows are nearly straight, keeping the upper arms still; switch sides when the set calls for it.']::text[]),
('French Press on Exercise Ball (EZ Bar)', 'triceps', array['shoulders']::text[], 'barbell', 'weight_reps', 'CFN9P8G', array['Take a seat on an exercise ball and hold an EZ barbell with palms facing down.', 'Reach your arms straight up, keeping your elbows close to your head.', 'Set the upper arms in place before extending the elbows.', 'Bend the elbows to lower the bar behind your head while the upper arms stay mostly still.', 'Keep the ball steady and use the feet to manage your balance.', 'Straighten the elbows to bring the bar overhead, then begin the next controlled rep.']::text[]),
('Military Press (Machine)', 'shoulders', array['triceps', 'chest']::text[], 'machine', 'weight_reps', 'CggQhII', array['Fit the seat to your body, then settle into the machine.', 'Hold the handles with palms facing down and position your hands just beyond shoulder width.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Keep the wrists stacked and use a shoulder path that feels natural.', 'Lower the weight to its starting height under control before pressing again.']::text[]),
('Back Pec Stretch', 'back', array['shoulders', 'chest']::text[], 'bodyweight', 'duration', 'chfnQnM', array['Stand tall and set your feet about shoulder width.', 'Reach your arms straight out in front of you, parallel to the ground.', 'Settle into the starting position and take an easy breath before moving deeper.', 'Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.', 'Stay in a mild stretch rather than pulling farther with momentum.', 'Hold the position with steady breathing, then release gently; repeat on the other side if needed.']::text[]),
('Bottoms-Up', 'core', '{}'::text[], 'bodyweight', 'bodyweight_reps', 'CI6baTY', array['Settle onto your back with your legs extended and your arms by your sides.', 'Bend your knees and bring them toward your chest, keeping your feet off the ground.', 'Set the pelvis and keep the neck relaxed before curling upward.', 'Curl your rib cage toward your pelvis, letting the abdominals move the torso.', 'Leave a little space between the chin and chest; keep the movement in the torso.', 'Lower the shoulders or torso with control before the next curl.']::text[]),
('Roller Seated Single Leg Shoulder Flexor Depressor Retractor', 'chest', array['shoulders', 'triceps']::text[], 'other', 'bodyweight_reps', 'CjETvlw', array['Take a seat on a flat surface with your legs extended in front of you.', 'Take hold of the roller with both hands, palms facing down, and place it on your thighs.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Keep the wrists stacked and use a shoulder path that feels natural.', 'Lower the weight to its starting height under control before pressing again.']::text[]),
('Oblique Crunch', 'core', '{}'::text[], 'bodyweight', 'bodyweight_reps', 'cJgSTmh', array['Settle onto your back with your knees bent and feet planted.', 'Set your hands behind your head or cross them over your chest.', 'Set the pelvis and keep the neck relaxed before curling upward.', 'Curl your rib cage toward your pelvis, letting the abdominals move the torso.', 'Leave a little space between the chin and chest; keep the movement in the torso.', 'Lower the shoulders or torso with control before the next curl.']::text[]),
('Standing Bent Over Single-Arm Triceps Extension (Dumbbell)', 'triceps', array['shoulders', 'back']::text[], 'dumbbell', 'weight_reps', 'CJwa0vD', array['Stand and set your feet about shoulder width and hold a dumbbell in one hand.', 'Bend forward at the waist, with your spine steady and parallel to the ground.', 'Set the upper arms in place before extending the elbows.', 'Keep the upper arms steady and extend through the elbows to move the weight.', 'Keep both shoulders level and resist turning toward the working arm.', 'Bend the elbows slowly to return to the start of the next rep; switch sides when the set calls for it.']::text[]),
('Clock Push-Up', 'chest', array['triceps', 'shoulders', 'core']::text[], 'bodyweight', 'bodyweight_reps', 'CMAxnsG', array['Begin in a high plank position with your hands directly under your shoulders and your body in a straight line.', 'Lower your body toward the ground by bending your elbows, keeping them close to your sides.', 'Brace the abdomen and glutes so the shoulders, hips and ankles move together.', 'Bend your elbows to lower your chest while keeping your body in one line.', 'Keep the head in line with the spine as the elbows bend.', 'Press back to straight arms, keeping the body line intact.']::text[]),
('Wide-Grip Rear Pulldown Behind Neck (Cable)', 'back', array['biceps', 'shoulders']::text[], 'cable', 'weight_reps', 'CmEr4pM', array['Set the cable machine so that the pulldown bar is at a height above your head.', 'Sit on the seat and grab the pulldown bar with a wide overhand grip.', 'Sit tall and set the shoulders before drawing the handle down.', 'Draw the bar toward the upper back behind your head only as far as the shoulders allow comfortably.', 'Pull with the elbows rather than leaning far back to move the handle.', 'Let the handle rise steadily until the arms are long, then reset the shoulders.']::text[]),
('Front Plank with Twist', 'core', array['shoulders']::text[], 'bodyweight', 'duration', 'CosupLu', array['Begin in a high plank position with your hands directly under your shoulders and your body in a straight line from head to toe.', 'Brace your trunk and glutes to maintain a stable position.', 'Brace the abdomen and find a position you can maintain without holding your breath.', 'Brace your midsection and hold the position while breathing normally.', 'Keep breathing steadily as you maintain the same body line.', 'Keep the shape for the planned time, then come out of it with control.']::text[]),
('Rocky Pull-Up Pulldown', 'back', array['biceps', 'forearms']::text[], 'bodyweight', 'bodyweight_reps', 'cQ19bBP', array['Take your place in front of a pull-up bar with your feet about shoulder width.', 'Reach up to hold the bar with palms facing down, just beyond shoulder width.', 'Begin from a controlled hang with the shoulders active rather than slack.', 'Pull your elbows down and bring your upper chest toward the bar without kicking your legs.', 'Avoid swinging the legs to clear the bar.', 'Lower to long arms without dropping suddenly from the top.']::text[]),
('Decline Triceps Extension (EZ Bar)', 'triceps', array['shoulders']::text[], 'barbell', 'weight_reps', 'CQHoDm0', array['Settle onto a decline bench with your head lower than your feet and your feet secured.', 'Take hold of the ez barbell with palms facing down, hands about shoulder width.', 'Set the upper arms in place before extending the elbows.', 'Keep the upper arms steady and extend through the elbows to move the weight.', 'Keep the upper arms steady while the forearms travel.', 'Bend the elbows slowly to return to the start of the next rep.']::text[]),
('Hip Raise (Smith Machine)', 'core', array['glutes', 'hamstrings']::text[], 'machine', 'weight_reps', 'CqhoytW', array['Set yourself on the smith machine with your back against the pad and your feet about shoulder width.', 'Set your hands on the barbell, just beyond shoulder width.', 'Plant the feet and keep the ribs from flaring as the hips prepare to rise.', 'Press through the feet and lift your hips until your torso and thighs line up.', 'Stop when the hips line up with the torso; do not arch higher through the lower back.', 'Lower the hips steadily and keep the feet planted for the next lift.']::text[]),
('Lateral Pulldown (With Rope Attachment) (Cable)', 'back', array['biceps', 'forearms']::text[], 'cable', 'weight_reps', 'CuaWCmC', array['Connect a rope attachment to the cable machine at a high position.', 'Face the machine from a stable stance with feet about shoulder width.', 'Sit tall and set the shoulders before drawing the handle down.', 'Pull the handle down by driving your elbows toward your ribs; keep your torso steady.', 'Pull with the elbows rather than leaning far back to move the handle.', 'Let the handle rise steadily until the arms are long, then reset the shoulders.']::text[]),
('Standing Pelvic Tilt', 'back', array['core']::text[], 'bodyweight', 'bodyweight_reps', 'cuKYxhu', array['Stand and set your feet about shoulder width and your knees soft.', 'Set your arms at your sides, or set your hands at your waist.', 'Relax the shoulders and find a comfortable neutral starting position.', 'Gently roll the pelvis to flatten and release the lower back through a small range.', 'Use a small range and avoid forcing the lower back into the floor.', 'Release the tilt gently and repeat without forcing the range.']::text[]),
('Kneeling Crunch (Cable)', 'core', '{}'::text[], 'cable', 'weight_reps', 'CUmLRTA', array['Connect a rope handle to a high pulley and kneel down turned away from the machine.', 'Take hold of the rope handle with both hands and place it behind your head, keeping your elbows out to the sides.', 'Set the pelvis and keep the neck relaxed before curling upward.', 'Curl your rib cage toward your pelvis, letting the abdominals move the torso.', 'Leave a little space between the chin and chest; keep the movement in the torso.', 'Lower the shoulders or torso with control before the next curl.']::text[]),
('Standing Pulldown (With Rope) (Cable)', 'biceps', array['forearms', 'shoulders']::text[], 'cable', 'weight_reps', 'CvPn9WV', array['Connect a rope to the cable machine at the highest setting.', 'Face the machine from a stable stance with feet about shoulder width.', 'Sit tall and set the shoulders before drawing the handle down.', 'Pull the handle down by driving your elbows toward your ribs; keep your torso steady.', 'Pull with the elbows rather than leaning far back to move the handle.', 'Let the handle rise steadily until the arms are long, then reset the shoulders.']::text[]),
('Prone Incline Hammer Curl (Dumbbell)', 'biceps', array['forearms']::text[], 'dumbbell', 'weight_reps', 'cWemPG8', array['Set the bench to a 45-degree incline.', 'Position yourself face down on the bench with a dumbbell in each hand, palms facing each other.', 'Set the shoulders and upper arms before bending the elbows.', 'Curl with palms facing each other and elbows near your sides; avoid rocking back.', 'Keep the palms facing each other and the wrists straight.', 'Lower until the elbows are nearly straight, keeping the upper arms still.']::text[]),
('L-Pull-Up', 'back', array['biceps', 'forearms']::text[], 'bodyweight', 'bodyweight_reps', 'd1GgzTU', array['Take hold of the pull-up bar with palms facing down, just beyond shoulder width.', 'Hang with your arms straight and your body straight.', 'Begin from a controlled hang with the shoulders active rather than slack.', 'Pull your elbows down and bring your upper chest toward the bar without kicking your legs.', 'Avoid swinging the legs to clear the bar.', 'Lower to long arms without dropping suddenly from the top.']::text[]),
('Over Bench Wrist Curl (Dumbbell)', 'forearms', array['biceps']::text[], 'dumbbell', 'weight_reps', 'D1xYJAU', array['Take a seat on a bench with your forearms resting on the bench and your palms facing up, holding a dumbbell in each hand.', 'Let your wrists to hang over the edge of the bench.', 'Keep the elbows relaxed so the small muscles of the hand or forearm take the load.', 'Move through the wrists or fingers while the forearms stay supported and still.', 'Use a small, smooth range without swinging the elbows.', 'Ease back to the start without letting the load fall from your hands.']::text[]),
('Step-Up (Band)', 'glutes', array['quads', 'hamstrings', 'calves']::text[], 'band', 'weight_reps', 'd5bTEPV', array['Set a band around your thighs, just above your knees.', 'Face a step or platform with your feet about hip width.', 'Put the lead foot fully on the platform before shifting your weight onto it.', 'Step onto the platform and drive through the lead foot to stand tall on it.', 'Control the band on the way back instead of letting it snap you into position.', 'Push through the lead foot to return to the start, then change legs as planned.']::text[]),
('Overhand Triceps Dip (Machine)', 'triceps', array['chest', 'shoulders']::text[], 'machine', 'weight_reps', 'D5yqP2p', array['Set the machine to the appropriate height and secure your body in position.', 'Hold the handles with palms facing down and position your body so that your arms are straight.', 'Set the shoulders down and keep the elbows pointed mostly behind you.', 'Bend the elbows to lower between the supports; stop at a comfortable shoulder depth.', 'Choose a depth that lets the shoulders stay comfortable.', 'Press through the hands to rise, then reset the shoulders before another rep.']::text[]),
('Exercise Ball Hug', 'back', array['shoulders', 'chest']::text[], 'bodyweight', 'bodyweight_reps', 'd7z1Y7V', array['Take a seat on the stability ball with your feet planted and your back straight.', 'Take hold of the stability ball with both hands, hugging it close to your chest.', 'Settle into the starting position and take an easy breath before moving deeper.', 'Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.', 'Keep the ball steady and use the feet to manage your balance.', 'Hold the position with steady breathing, then release gently; repeat on the other side if needed.']::text[]),
('Seated Good Morning (Barbell)', 'glutes', array['hamstrings', 'back']::text[], 'barbell', 'weight_reps', 'd960PgE', array['Plant both feet while seated on a bench; a barbell resting on your upper back.', 'Keep your spine in a comfortable neutral position and your chest up.', 'Unlock the knees and brace the abdomen before moving the hips back.', 'Push the hips back while keeping the load close and the spine steady.', 'Keep the weight close to the legs and stop when the back would begin to round.', 'Drive the hips forward to stand tall without leaning back at the top.']::text[]),
('Pelvic Tilt Into Bridge', 'glutes', array['hamstrings', 'core']::text[], 'bodyweight', 'bodyweight_reps', 'D9qe7CM', array['Settle onto your back with your knees bent and feet planted.', 'Set your arms by your sides with your palms facing down.', 'Plant the feet and keep the ribs from flaring as the hips prepare to rise.', 'Tuck the pelvis gently, then push through the feet to raise the hips into a bridge.', 'Stop when the hips line up with the torso; do not arch higher through the lower back.', 'Lower the hips steadily and keep the feet planted for the next lift.']::text[]),
('Russian Twists (On Stability Ball) (Cable)', 'core', array['back']::text[], 'cable', 'weight_reps', 'd9Xaxq6', array['Take a seat on a stability ball with your feet planted and your knees bent at a 90-degree angle.', 'Take hold of the cable handle with both hands and extend your arms straight out in front of you.', 'Set the pelvis and make the turn through the rib cage.', 'Turn through the torso while the hips and lower body stay as steady as the setup allows.', 'Keep the ball steady and use the feet to manage your balance.', 'Return through center before turning to the other side.']::text[]),
('Close-Grip Bench Press (EZ Bar)', 'triceps', array['chest', 'shoulders']::text[], 'barbell', 'weight_reps', 'da4cXST', array['Settle onto a bench with your feet planted and your back pressed against the bench.', 'Hold the ez barbell with a close grip, hands about shoulder width, palms facing forward.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Keep the wrists stacked and use a shoulder path that feels natural.', 'Lower the weight to its starting height under control before pressing again.']::text[]),
('Single Leg Deadlift with Stepbox Support (Dumbbell)', 'glutes', array['hamstrings', 'back']::text[], 'dumbbell', 'weight_reps', 'daBmy1Y', array['Stand and set your feet about hip width, holding a dumbbell in your right hand.', 'Set your left foot on a stepbox or elevated surface behind you.', 'Unlock the knees and brace the abdomen before moving the hips back.', 'Push the hips back while keeping the load close and the spine steady.', 'Keep the weight close to the legs and stop when the back would begin to round.', 'Drive the hips forward to stand tall without leaning back at the top.']::text[]),
('Incline Bench Row (Cable)', 'back', array['biceps', 'shoulders']::text[], 'cable', 'weight_reps', 'dAJscVq', array['Prepare an incline bench at a 45-degree angle and attach a cable handle to the low pulley.', 'Take a seat on the bench facing the cable machine with your feet planted and your knees soft.', 'Set the torso and allow the arms to reach forward without rounding excessively.', 'Draw your elbows back and bring the handle or weight toward your torso.', 'Bring the elbows back without jerking the torso.', 'Reach the arms forward again without letting the torso lurch.']::text[]),
('Single-Arm Bent-Over Cable Lateral Raise', 'chest', array['shoulders', 'traps']::text[], 'cable', 'weight_reps', 'dB07vDu', array['Stand and set your feet about shoulder width, facing a cable machine.', 'Hold the handle with one hand and step back to create tension on the cable.', 'Start with a manageable load and a small bend in the elbows.', 'Raise the arms out to the sides to about shoulder height without leaning or shrugging.', 'Keep both shoulders level and resist turning toward the working arm.', 'Lower the arms slowly to your sides without swinging the weight; switch sides when the set calls for it.']::text[]),
('Front Squat (Kettlebell)', 'glutes', array['quads', 'hamstrings', 'calves']::text[], 'kettlebell', 'weight_reps', 'DB0n8AG', array['Stand and set your feet about shoulder width, toes slightly turned out.', 'Take hold of the kettlebell with both hands ahead of your chest, close to your body.', 'Brace the abdomen and spread pressure across the whole foot.', 'Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.', 'Drive upward with the chest and hips rising together; keep the knees from collapsing inward.', 'Stand fully, reset your footing and breathing, then begin the next descent.']::text[]),
('Concentration Extension (On Knee) (Cable)', 'triceps', array['forearms']::text[], 'cable', 'weight_reps', 'Db7eEgw', array['Take a seat on a bench or chair with your knees bent and feet planted.', 'Take hold of the cable handle with your right hand and place your elbow on the inside of your right knee.', 'Set the upper arms in place before extending the elbows.', 'Keep the upper arms steady and extend through the elbows to move the weight.', 'Keep the upper arms steady while the forearms travel.', 'Bend the elbows slowly to return to the start of the next rep.']::text[]),
('Medicine Ball Chest Push From 3 Point Stance', 'chest', array['shoulders', 'triceps']::text[], 'other', 'weight_reps', 'dCJnuVq', array['Begin in a 3 point stance with one hand on the medicine ball and the other hand on the ground.', 'Reach your legs and position your body in a straight line.', 'Set a firm stance and leave enough clear space for the ball to travel.', 'Drive the ball away forcefully, using the arms and trunk together; catch or retrieve it before resetting.', 'Follow through with the whole body while keeping control of the landing or catch.', 'Bring the weight or body back to its starting position without rushing.']::text[]),
('Standing Bradford Press (Barbell)', 'shoulders', array['triceps', 'back']::text[], 'barbell', 'weight_reps', 'dCPESfR', array['Stand and set your feet about shoulder width and hold the barbell ahead of your shoulders with palms facing down.', 'Press the barbell overhead, straighten your arms.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Keep the wrists stacked and use a shoulder path that feels natural.', 'Lower the weight to its starting height under control before pressing again.']::text[]),
('Seated Glute Stretch', 'glutes', array['hamstrings']::text[], 'bodyweight', 'duration', 'DeDThfG', array['Take a seat on the ground with your legs extended in front of you.', 'Before moving, bend your right knee and cross your right ankle over your left thigh.', 'Settle into the starting position and take an easy breath before moving deeper.', 'Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.', 'Stay in a mild stretch rather than pulling farther with momentum.', 'Hold the position with steady breathing, then release gently; repeat on the other side if needed.']::text[]),
('Posterior Tibialis Stretch', 'calves', array['hamstrings', 'quads']::text[], 'cable', 'duration', 'DEEqoI2', array['Take a seat on the ground with your legs extended in front of you.', 'Thread the rope around the ball of your foot and hold the ends of the rope with your hands.', 'Settle into the starting position and take an easy breath before moving deeper.', 'Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.', 'Stay in a mild stretch rather than pulling farther with momentum.', 'Hold the position with steady breathing, then release gently; repeat on the other side if needed.']::text[]),
('World Greatest Stretch', 'hamstrings', array['glutes', 'quads', 'calves']::text[], 'bodyweight', 'duration', 'DFGXwZr', array['Begin in a lunge position with your right foot forward and your left foot back.', 'Set your hands on the ground on either side of your right foot.', 'Settle into the starting position and take an easy breath before moving deeper.', 'Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.', 'Stay in a mild stretch rather than pulling farther with momentum.', 'Hold the position with steady breathing, then release gently; repeat on the other side if needed.']::text[]),
('Seated Twist (Barbell)', 'core', array['back']::text[], 'barbell', 'weight_reps', 'dFSNDOA', array['Take a seat on a flat bench with your feet planted and your knees bent.', 'Take a barbell with both hands ahead of your chest, keeping your elbows soft.', 'Set the pelvis and make the turn through the rib cage.', 'Turn through the torso while the hips and lower body stay as steady as the setup allows.', 'Keep the turn smooth instead of throwing the arms across the body.', 'Return through center before turning to the other side.']::text[]),
('Snatch Pull', 'quads', array['hamstrings', 'glutes', 'calves']::text[], 'barbell', 'weight_reps', 'dG5Smob', array['Stand and set your feet about shoulder width and the barbell on the ground in front of you.', 'Bend your knees and hinge at the hips to lower into a squat position, gripping the barbell with palms facing down.', 'Brace before the pull and keep the load close to the body.', 'Drive through the legs and hips, then guide the weight to its receiving position.', 'Receive the load with the torso braced and feet stable.', 'Stand tall to finish, then lower the weight under control before the next rep.']::text[]),
('Shrug (Barbell)', 'traps', array['shoulders']::text[], 'barbell', 'weight_reps', 'dG7tG5y', array['Stand and set your feet about shoulder width and hold a barbell in front of you with palms facing down.', 'Keep your arms long and your spine steady throughout the exercise.', 'Let the arms hang long and keep the head neutral.', 'Lift your shoulders toward your ears without bending the elbows or rolling the shoulders.', 'Lift and lower vertically without circling the shoulders.', 'Ease back to the start before repeating.']::text[]),
('Decline Close-Grip Face Press (EZ Bar)', 'triceps', array['chest', 'shoulders']::text[], 'barbell', 'weight_reps', 'DgZQ11d', array['Settle onto a decline bench with your head lower than your feet.', 'Hold the ez barbell with a close grip, palms facing each other.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Keep the wrists stacked and use a shoulder path that feels natural.', 'Lower the weight to its starting height under control before pressing again.']::text[]),
('Full Squat (Back Pov) (Barbell)', 'glutes', array['quads', 'hamstrings', 'calves', 'core']::text[], 'barbell', 'weight_reps', 'DhMl549', array['Stand and set your feet about shoulder width, toes slightly turned out.', 'Rest the bar across the upper back and take a secure grip.', 'Brace the abdomen and spread pressure across the whole foot.', 'Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.', 'Drive upward with the chest and hips rising together; keep the knees from collapsing inward.', 'Stand fully, reset your footing and breathing, then begin the next descent.']::text[]),
('Single Leg Calf Raise (On a Dumbbell)', 'calves', '{}'::text[], 'dumbbell', 'weight_reps', 'DICPHtq', array['Stand and set your feet about hip width and hold a dumbbell in one hand.', 'Before moving, lift one foot off the ground and balance on the other foot.', 'Let the ankles move freely while the rest of the body stays quiet.', 'Rise through the balls of your feet, lifting the heels as high as you can without rocking.', 'Pause at the top without rolling the ankles outward.', 'Lower the heels at a measured pace before rising again.']::text[]),
('Sphinx', 'back', array['glutes', 'hamstrings']::text[], 'bodyweight', 'bodyweight_reps', 'DIVyqrU', array['Position yourself face down on the ground with your forearms flat on the floor, elbows directly under your shoulders.', 'Brace your trunk and lift your chest off the ground, keeping your forearms and toes on the floor.', 'Settle into the starting position and take an easy breath before moving deeper.', 'Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.', 'Stay in a mild stretch rather than pulling farther with momentum.', 'Hold the position with steady breathing, then release gently; repeat on the other side if needed.']::text[]),
('Burpee', 'cardio', array['quads', 'hamstrings', 'calves', 'shoulders', 'chest']::text[], 'bodyweight', 'duration', 'dK9394r', array['Begin in a standing position with your feet about shoulder width.', 'Before moving, lower your body into a squat position by bending your knees and placing your hands on the floor in front of you.', 'Start at a pace that lets the feet and arms move in sync.', 'Move at a repeatable pace, keeping the motion smooth and your breathing steady.', 'Keep the pattern repeatable as speed increases.', 'Keep the rhythm for the planned interval, slowing if your form starts to slip.']::text[]),
('Single-Arm Twisting Seated Row (Band)', 'back', array['biceps', 'shoulders']::text[], 'band', 'weight_reps', 'DKBwJrL', array['Take a seat on a bench or chair with your feet planted and your back straight.', 'Take hold of the band with one hand and extend your arm fully in front of you.', 'Set the torso and allow the arms to reach forward without rounding excessively.', 'Draw your elbows back and bring the handle or weight toward your torso.', 'Keep both shoulders level and resist turning toward the working arm.', 'Reach the arms forward again without letting the torso lurch; switch sides when the set calls for it.']::text[]),
('Incline Row (Barbell)', 'back', array['biceps', 'forearms']::text[], 'barbell', 'weight_reps', 'dmgMp3n', array['Angle the bench to roughly 45 degrees.', 'Position yourself face down on the bench with your chest against the pad and your feet planted.', 'Set the torso and allow the arms to reach forward without rounding excessively.', 'Draw your elbows back and bring the handle or weight toward your torso.', 'Bring the elbows back without jerking the torso.', 'Reach the arms forward again without letting the torso lurch.']::text[]),
('Sissy Squat', 'quads', array['calves', 'glutes']::text[], 'bodyweight', 'bodyweight_reps', 'DoEYq4s', array['Stand and set your feet about shoulder width and your toes pointing slightly outward.', 'Use a stable object for balance if needed.', 'Brace the abdomen and spread pressure across the whole foot.', 'Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.', 'Drive upward with the chest and hips rising together; keep the knees from collapsing inward.', 'Stand fully, reset your footing and breathing, then begin the next descent.']::text[]),
('Reverse-Grip Decline Bench Press (Barbell)', 'chest', array['triceps', 'shoulders']::text[], 'barbell', 'weight_reps', 'DotAgEF', array['Secure the feet on a decline bench, keeping the head below the hips.', 'Hold the barbell with a reverse grip, just beyond shoulder width.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Keep the palms in the chosen grip without bending the wrists back.', 'Lower the weight to its starting height under control before pressing again.']::text[]),
('Standing Calf Raise (Dumbbell)', 'calves', '{}'::text[], 'dumbbell', 'weight_reps', 'dPmaUaU', array['Stand and set your feet about shoulder width, holding a dumbbell in each hand.', 'Before moving, raise your heels off the ground as high as possible, using your calves.', 'Let the ankles move freely while the rest of the body stays quiet.', 'Rise through the balls of your feet, lifting the heels as high as you can without rocking.', 'Pause at the top without rolling the ankles outward.', 'Lower the heels at a measured pace before rising again.']::text[]),
('Close-Grip Pulldown (Band)', 'back', array['biceps', 'forearms']::text[], 'band', 'weight_reps', 'DptumMx', array['Connect the band to a high anchor point, such as a pull-up bar or sturdy beam.', 'Face the anchor point and grab the band with palms facing up, hands about shoulder width.', 'Sit tall and set the shoulders before drawing the handle down.', 'Pull the handle down by driving your elbows toward your ribs; keep your torso steady.', 'Control the band on the way back instead of letting it snap you into position.', 'Let the handle rise steadily until the arms are long, then reset the shoulders.']::text[]),
('Seated Overhead Curl (Cable)', 'biceps', array['forearms', 'shoulders']::text[], 'cable', 'weight_reps', 'DpWMFP5', array['Take a seat on a bench facing the cable machine with your feet planted.', 'Hold the cable attachment with palms facing up, and your hands about shoulder width.', 'Set the shoulders and upper arms before bending the elbows.', 'Bend your elbows to bring the weight toward your shoulders without swinging your torso.', 'Keep the torso quiet and let the elbow bend lift the weight.', 'Lower until the elbows are nearly straight, keeping the upper arms still.']::text[]),
('Three Bench Dip', 'triceps', array['chest', 'shoulders']::text[], 'bodyweight', 'bodyweight_reps', 'DQ0cqkT', array['Take a seat on a bench with your hands gripping the edge, fingers pointing forward.', 'Move your butt off the bench, supporting your weight with your hands.', 'Set the shoulders down and keep the elbows pointed mostly behind you.', 'Bend the elbows to lower between the supports; stop at a comfortable shoulder depth.', 'Choose a depth that lets the shoulders stay comfortable.', 'Press through the hands to rise, then reset the shoulders before another rep.']::text[]),
('Incline Fly (Cable)', 'chest', array['shoulders', 'triceps']::text[], 'cable', 'weight_reps', 'drfGhTV', array['Set the cable machine to a low position and attach the handles.', 'Take a seat on an incline bench with your back against the pad and feet planted.', 'Keep a soft elbow bend and set the shoulders before moving the arms.', 'With a soft bend in the elbows, sweep your arms together in a wide arc.', 'Keep the elbow angle nearly unchanged through the arc.', 'Open the arms back along the same arc without dropping the load.']::text[]),
('Lateral Raise (Machine)', 'shoulders', array['traps', 'back']::text[], 'machine', 'weight_reps', 'dRTfGZT', array['Fit the seat to your body, then settle into the machine.', 'Hold the handles with palms facing down and keep your arms straight.', 'Start with a manageable load and a small bend in the elbows.', 'Raise the arms out to the sides to about shoulder height without leaning or shrugging.', 'Stop near shoulder height rather than shrugging to lift higher.', 'Lower the arms slowly to your sides without swinging the weight.']::text[]),
('Seated Close-Grip Concentration Curl (EZ Bar)', 'biceps', array['forearms']::text[], 'barbell', 'weight_reps', 'Dsfz0Id', array['Plant both feet while seated on a bench; hold an EZ barbell with palms facing up.', 'Set your elbow on the inside of your thigh, just above the knee.', 'Set the shoulders and upper arms before bending the elbows.', 'Bend your elbows to bring the weight toward your shoulders without swinging your torso.', 'Keep the torso quiet and let the elbow bend lift the weight.', 'Lower until the elbows are nearly straight, keeping the upper arms still.']::text[]),
('Straight Arm Pulldown (With Rope) (Cable)', 'back', array['biceps', 'forearms']::text[], 'cable', 'weight_reps', 'DT14T9T', array['Connect a rope to the cable machine at the highest setting.', 'Face the machine from a stable stance with feet about shoulder width.', 'Sit tall and set the shoulders before drawing the handle down.', 'Pull the handle down by driving your elbows toward your ribs; keep your torso steady.', 'Pull with the elbows rather than leaning far back to move the handle.', 'Let the handle rise steadily until the arms are long, then reset the shoulders.']::text[]),
('Knee Touch Crunch', 'core', '{}'::text[], 'bodyweight', 'bodyweight_reps', 'dTg95eZ', array['Settle onto your back with your knees bent and feet planted.', 'Set your hands behind your head with your elbows pointing outwards.', 'Set the pelvis and keep the neck relaxed before curling upward.', 'Curl your rib cage toward your pelvis, letting the abdominals move the torso.', 'Leave a little space between the chin and chest; keep the movement in the torso.', 'Lower the shoulders or torso with control before the next curl.']::text[]),
('Standing Single-Arm Reverse Curl (Dumbbell)', 'biceps', array['forearms']::text[], 'dumbbell', 'weight_reps', 'DU5Kkj2', array['Stand tall with your feet about shoulder width and hold a dumbbell in one hand with palms facing down.', 'Keep your arm straight and close to your body, with your palm facing down.', 'Set the shoulders and upper arms before bending the elbows.', 'Curl the weight with your palms facing down, keeping the elbows close and torso still.', 'Keep both shoulders level and resist turning toward the working arm.', 'Lower until the elbows are nearly straight, keeping the upper arms still; switch sides when the set calls for it.']::text[]),
('Reverse-Grip Incline Bench Press (Barbell)', 'chest', array['triceps', 'shoulders']::text[], 'barbell', 'weight_reps', 'DU7I633', array['Angle the bench to roughly 45 degrees.', 'Get onto the bench with your feet planted.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Keep the palms in the chosen grip without bending the wrists back.', 'Lower the weight to its starting height under control before pressing again.']::text[]),
('Chin-Up', 'back', array['biceps', 'forearms']::text[], 'bodyweight', 'bodyweight_reps', 'dVeWXf2', array['Suspend yourself from a pull-up bar with your palms facing toward you and your hands about shoulder width.', 'Brace your trunk and pull your body up toward the bar, leading with your chest.', 'Begin from a controlled hang with the shoulders active rather than slack.', 'Pull your elbows down and bring your upper chest toward the bar without kicking your legs.', 'Avoid swinging the legs to clear the bar.', 'Lower to long arms without dropping suddenly from the top.']::text[]),
('Decline Bench Press (Dumbbell)', 'chest', array['triceps', 'shoulders']::text[], 'dumbbell', 'weight_reps', 'DwhEmmE', array['Get onto a decline bench with your feet secured and your head lower than your hips.', 'Take a dumbbell in each hand and extend your arms straight up above your chest, palms facing forward.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Keep the wrists stacked and use a shoulder path that feels natural.', 'Lower the weight to its starting height under control before pressing again.']::text[]),
('Single-Leg Calf Press on Leg Press (Machine)', 'calves', array['hamstrings', 'glutes']::text[], 'machine', 'weight_reps', 'Dx2RIva', array['Set the seat of the leg press machine so that your knees are soft when your feet are on the sled.', 'Take a seat on the machine with your back against the backrest and your feet on the sled, about shoulder width.', 'Let the ankles move freely while the rest of the body stays quiet.', 'Rise through the balls of your feet, lifting the heels as high as you can without rocking.', 'Keep the pelvis level as the supporting leg does the work.', 'Lower the heels at a measured pace before rising again; switch sides when the set calls for it.']::text[]),
('Drag Curl (Cable)', 'biceps', array['forearms']::text[], 'cable', 'weight_reps', 'dXz8zjF', array['Face the cable machine from a stable stance with feet about shoulder width.', 'Hold the cable attachment with palms facing up, and arms straight.', 'Set the shoulders and upper arms before bending the elbows.', 'Bend your elbows to bring the weight toward your shoulders without swinging your torso.', 'Keep the torso quiet and let the elbow bend lift the weight.', 'Lower until the elbows are nearly straight, keeping the upper arms still.']::text[]),
('Standing Overhead Triceps Extension (Barbell)', 'triceps', array['shoulders']::text[], 'barbell', 'weight_reps', 'dZl9Q27', array['Stand and set your feet about shoulder width and hold a barbell with palms facing down.', 'Raise the barbell overhead, straighten your arms.', 'Set the upper arms in place before extending the elbows.', 'Keep the upper arms pointed upward and extend at the elbows without flaring the ribs.', 'Keep the upper arms steady while the forearms travel.', 'Bend the elbows slowly to return to the start of the next rep.']::text[]),
('Sumo Squat (Smith Machine)', 'glutes', array['quads', 'hamstrings', 'calves']::text[], 'machine', 'weight_reps', 'dzz6BiV', array['Prepare the smith machine with the barbell at hip height.', 'Stand and set your feet wider than about shoulder width, toes pointing outwards.', 'Brace the abdomen and spread pressure across the whole foot.', 'Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.', 'Drive upward with the chest and hips rising together; keep the knees from collapsing inward.', 'Stand fully, reset your footing and breathing, then begin the next descent.']::text[]),
('Single-Arm Reverse Fly (With Support) (Dumbbell)', 'shoulders', array['traps', 'back']::text[], 'dumbbell', 'weight_reps', 'e25F58f', array['Plant both feet while seated on a bench; your back straight.', 'Take a dumbbell in one hand with your palm facing inwards.', 'Keep a soft elbow bend and set the shoulders before moving the arms.', 'Open your arms out and back with a slight elbow bend, drawing the shoulder blades together.', 'Keep both shoulders level and resist turning toward the working arm.', 'Open the arms back along the same arc without dropping the load; switch sides when the set calls for it.']::text[]),
('Front Raise (Weighted)', 'shoulders', array['biceps', 'forearms']::text[], 'bodyweight', 'bodyweight_reps', 'e4aFmFY', array['Stand and set your feet about shoulder width, holding a dumbbell in each hand with your palms facing your thighs.', 'With your arms straight, exhale and lift the dumbbells in front of you until they are at shoulder level.', 'Start with a manageable load and a small bend in the elbows.', 'Lift the arms forward to about shoulder height, keeping the ribs down and torso still.', 'Stop near shoulder height rather than shrugging to lift higher.', 'Lower the arms slowly to your sides without swinging the weight.']::text[]),
('Reverse-Grip Biceps Curl (Dumbbell)', 'biceps', array['forearms']::text[], 'dumbbell', 'weight_reps', 'e4ojVhP', array['Stand tall with a dumbbell in each hand, palms facing down and arms straight.', 'With your upper arms stationary, exhale and curl the weights while contracting your biceps.', 'Set the shoulders and upper arms before bending the elbows.', 'Curl the weight with your palms facing down, keeping the elbows close and torso still.', 'Keep the palms in the chosen grip without bending the wrists back.', 'Lower until the elbows are nearly straight, keeping the upper arms still.']::text[]),
('Self Assisted Inverse Leg Curl', 'hamstrings', array['glutes', 'calves']::text[], 'bodyweight', 'bodyweight_reps', 'E4PwJqI', array['Position yourself face down on a leg curl machine with your legs extended and your ankles hooked under the padded lever.', 'Set your hands on the side handles of the machine for support.', 'Line the knees up with the machine or bench edge before starting the curl.', 'Bend your knees to draw the pad toward you without lifting your hips from the support.', 'Keep the hips still while the knees bend.', 'Ease back to the start before repeating.']::text[]),
('High Knee Against Wall', 'cardio', array['quads', 'hamstrings', 'glutes', 'calves']::text[], 'bodyweight', 'duration', 'ealLwvX', array['Face a wall with your feet about hip width.', 'Set your hands on the wall for support.', 'Start at a pace that lets the feet and arms move in sync.', 'Move at a repeatable pace, keeping the motion smooth and your breathing steady.', 'Keep the pattern repeatable as speed increases.', 'Keep the rhythm for the planned interval, slowing if your form starts to slip.']::text[]),
('Reverse Fly (Dumbbell)', 'shoulders', array['traps', 'back']::text[], 'dumbbell', 'weight_reps', 'EAs3xL9', array['Stand and set your feet about shoulder width and hold a dumbbell in each hand.', 'Bend your knees slightly and hinge forward at the hips, with your spine steady.', 'Keep a soft elbow bend and set the shoulders before moving the arms.', 'Open your arms out and back with a slight elbow bend, drawing the shoulder blades together.', 'Keep the elbow angle nearly unchanged through the arc.', 'Open the arms back along the same arc without dropping the load.']::text[]),
