('Side-Lying Adductor Stretch (Assisted)', 'quads', array['hamstrings', 'glutes']::text[], 'bodyweight', 'duration', 'hC6oYY5', array['Settle onto your side with your legs straight and stacked on top of each other.', 'Before moving, bend your bottom leg slightly for stability.', 'Settle into the starting position and take an easy breath before moving deeper.', 'Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.', 'Stay in a mild stretch rather than pulling farther with momentum.', 'Hold the position with steady breathing, then release gently; repeat on the other side if needed.']::text[]),
('Power Point Plank', 'core', array['shoulders', 'triceps', 'glutes']::text[], 'bodyweight', 'duration', 'hCjGsRQ', array['Begin in a high plank position with your hands directly under your shoulders and your body in a straight line from head to toe.', 'Brace your trunk and squeeze your glutes to maintain a stable position.', 'Brace the abdomen and find a position you can maintain without holding your breath.', 'Brace your midsection and hold the position while breathing normally.', 'Keep breathing steadily as you maintain the same body line.', 'Keep the shape for the planned time, then come out of it with control.']::text[]),
('Cross Body Hammer Curl (Dumbbell)', 'biceps', array['forearms']::text[], 'dumbbell', 'weight_reps', 'HDYiZcY', array['Stand tall with a dumbbell in each hand, palms facing your body.', 'Hold your elbows near your torso and your upper arms stationary.', 'Set the shoulders and upper arms before bending the elbows.', 'Curl each weight across the torso toward the opposite shoulder, keeping the palm facing inward.', 'Keep the palms facing each other and the wrists straight.', 'Lower until the elbows are nearly straight, keeping the upper arms still.']::text[]),
