('Straddle Maltese', 'core', array['shoulders', 'chest']::text[], 'bodyweight', 'bodyweight_reps', 'HfqciZF', array['Begin by hanging from a pair of rings with your arms straight and your body in a straight line.', 'Move your legs wide apart, forming a straddle position.', 'Brace the abdomen and find a position you can maintain without holding your breath.', 'Brace your midsection and hold the position while breathing normally.', 'Keep breathing steadily as you maintain the same body line.', 'Keep the shape for the planned time, then come out of it with control.']::text[]),
('Seated Leg Raise', 'core', '{}'::text[], 'bodyweight', 'bodyweight_reps', 'Hgs6Nl1', array['Take a seat on a flat bench with your back straight and your feet planted.', 'Set your hands on the sides of the bench for support.', 'Brace the abdomen and keep the shoulders anchored to the support.', 'Lift your legs by bracing your trunk and moving at the hips rather than swinging.', 'Slow the legs before they pull the lower back out of position.', 'Lower the legs slowly without swinging or losing your trunk position.']::text[]),
('Single-Arm Fly on Exercise Ball (Cable)', 'chest', array['shoulders', 'triceps']::text[], 'cable', 'weight_reps', 'hHy8tQG', array['Take a seat on an exercise ball with your feet planted and your back straight.', 'Take a cable handle in one hand and extend your arm out to the side, parallel to the ground.', 'Keep a soft elbow bend and set the shoulders before moving the arms.', 'With a soft bend in the elbows, sweep your arms together in a wide arc.', 'Keep both shoulders level and resist turning toward the working arm.', 'Open the arms back along the same arc without dropping the load; switch sides when the set calls for it.']::text[]),
('Seated Wide Angle Pose Sequence', 'hamstrings', array['quads', 'calves']::text[], 'bodyweight', 'bodyweight_reps', 'HIgYKAB', array['Take a seat on the ground with your legs extended in a wide angle.', 'Pull your toes toward you and engage your quadriceps.', 'Settle into the starting position and take an easy breath before moving deeper.', 'Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.', 'Stay in a mild stretch rather than pulling farther with momentum.', 'Hold the position with steady breathing, then release gently; repeat on the other side if needed.']::text[]),
('Decline Wide-Grip Pullover (Barbell)', 'back', array['triceps', 'chest']::text[], 'barbell', 'weight_reps', 'Hj4FOCd', array['Settle onto a decline bench with your head lower than your hips and your feet secured.', 'Take a barbell with a wide grip and extend your arms straight above your chest.', 'Set the ribs down and keep a small elbow bend before lowering the weight.', 'Lower the weight in an arc behind your head until you feel a comfortable shoulder stretch.', 'Keep the ribs down as the arms travel overhead.', 'Pull the weight back over the chest along the same arc, without lifting the ribs.']::text[]),
('Lying Close-Grip Triceps Extension (Barbell)', 'triceps', array['shoulders']::text[], 'barbell', 'weight_reps', 'HJ63mSO', array['Settle onto a bench with your feet planted and your head at the end of the bench.', 'Hold the barbell with a close grip, hands about shoulder width, palms facing up.', 'Set the upper arms in place before extending the elbows.', 'Keep the upper arms steady and extend through the elbows to move the weight.', 'Keep the upper arms steady while the forearms travel.', 'Bend the elbows slowly to return to the start of the next rep.']::text[]),
('Single-Arm Chin-Up', 'back', array['biceps', 'forearms']::text[], 'bodyweight', 'bodyweight_reps', 'HjdqmZa', array['Face the pull-up bar from a stable stance with feet about shoulder width.', 'Reach up to hold the bar with palms facing up, with one hand gripping the bar and the other hand holding your wrist for support.', 'Begin from a controlled hang with the shoulders active rather than slack.', 'Pull your elbows down and bring your upper chest toward the bar without kicking your legs.', 'Keep both shoulders level and resist turning toward the working arm.', 'Lower to long arms without dropping suddenly from the top; switch sides when the set calls for it.']::text[]),
('Decline Wide-Grip Press (Barbell)', 'chest', array['triceps', 'shoulders']::text[], 'barbell', 'weight_reps', 'hl8DUh8', array['Secure the feet on a decline bench, keeping the head below the hips.', 'Hold the barbell with a wide grip, just beyond shoulder width.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Keep the wrists stacked and use a shoulder path that feels natural.', 'Lower the weight to its starting height under control before pressing again.']::text[]),
('Decline Bent Arm Pullover (Barbell)', 'back', array['triceps', 'chest']::text[], 'barbell', 'weight_reps', 'hMEptv0', array['Get onto a decline bench with your head lower than your hips and your feet secured.', 'Take a barbell with a pronated grip (palms turned away from you) and extend your arms straight above your chest.', 'Set the ribs down and keep a small elbow bend before lowering the weight.', 'Lower the weight in an arc behind your head until you feel a comfortable shoulder stretch.', 'Keep the ribs down as the arms travel overhead.', 'Pull the weight back over the chest along the same arc, without lifting the ribs.']::text[]),
('Pull-Up (Weighted)', 'back', array['biceps', 'forearms']::text[], 'bodyweight', 'bodyweight_reps', 'HMzLjXx', array['Take hold of the pull-up bar with palms facing down, just beyond shoulder width.', 'Suspend yourself from the bar with your arms straight and your body straight.', 'Begin from a controlled hang with the shoulders active rather than slack.', 'Pull your elbows down and bring your upper chest toward the bar without kicking your legs.', 'Avoid swinging the legs to clear the bar.', 'Lower to long arms without dropping suddenly from the top.']::text[]),
('Jm Bench Press (EZ Bar)', 'triceps', array['chest', 'shoulders']::text[], 'barbell', 'weight_reps', 'hnOYgH3', array['Settle onto a bench with your feet planted and your back pressed against the bench.', 'Hold the ez barbell with palms facing down, just beyond shoulder width.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Keep the wrists stacked and use a shoulder path that feels natural.', 'Lower the weight to its starting height under control before pressing again.']::text[]),
('Left Hook (Boxing)', 'shoulders', array['biceps', 'triceps', 'forearms']::text[], 'bodyweight', 'bodyweight_reps', 'hoXt6wv', array['Stand and set your feet about shoulder width and your knees soft.', 'Keep the left hand up to protect your face and your right hand by your chin.', 'Start at a pace that lets the feet and arms move in sync.', 'Pivot through the hips and feet as the left arm travels across at chest height.', 'Keep the pattern repeatable as speed increases.', 'Keep the rhythm for the planned interval, slowing if your form starts to slip.']::text[]),
('Hammer Curl (With Rope) (Cable)', 'biceps', array['forearms']::text[], 'cable', 'weight_reps', 'HPlPoQA', array['Stand upright with your feet about shoulder width and a slight bend in your knees.', 'Take hold of the cable rope attachment with palms facing up, palms facing each other, and your arms straight.', 'Set the shoulders and upper arms before bending the elbows.', 'Curl with palms facing each other and elbows near your sides; avoid rocking back.', 'Keep the palms facing each other and the wrists straight.', 'Lower until the elbows are nearly straight, keeping the upper arms still.']::text[]),
('Standing Preacher Curl (Dumbbell)', 'biceps', array['forearms']::text[], 'dumbbell', 'weight_reps', 'hq2hyDH', array['Stand upright with your feet about shoulder width and hold a dumbbell in each hand, palms facing forward.', 'Rest the back of your upper arms against the preacher bench or an incline bench, with your elbows soft.', 'Set the working upper arm against the preacher pad and leave the elbow free to bend.', 'Curl the weight while your upper arms stay in contact with the pad.', 'Keep the torso quiet and let the elbow bend lift the weight.', 'Lower until the elbows are nearly straight, keeping the upper arms still.']::text[]),
('Seated Lateral Raise (Dumbbell)', 'shoulders', array['traps', 'triceps']::text[], 'dumbbell', 'weight_reps', 'hrrS0Ed', array['Plant both feet while seated on a bench; a dumbbell in each hand, resting on your thighs.', 'Keep your spine in a comfortable neutral position and core engaged.', 'Start with a manageable load and a small bend in the elbows.', 'Raise the arms out to the sides to about shoulder height without leaning or shrugging.', 'Stop near shoulder height rather than shrugging to lift higher.', 'Lower the arms slowly to your sides without swinging the weight.']::text[]),
('Straight-Leg Deadlift (Barbell)', 'hamstrings', array['glutes', 'back']::text[], 'barbell', 'weight_reps', 'hrVQWvE', array['Stand and set your feet about shoulder width and your toes pointing forward.', 'Take hold of the barbell with palms facing down, hands just beyond shoulder width.', 'Unlock the knees and brace the abdomen before moving the hips back.', 'Send your hips back with a soft knee bend, lowering the load close to your legs until the hamstrings stretch.', 'Keep the weight close to the legs and stop when the back would begin to round.', 'Drive the hips forward to stand tall without leaning back at the top.']::text[]),
('Sprint Lunge (Smith Machine)', 'glutes', array['quads', 'hamstrings', 'calves']::text[], 'machine', 'weight_reps', 'HsjbB1z', array['Prepare the smith machine with the barbell at hip height.', 'Face the away from the machine from a stable stance with feet about shoulder width.', 'Set your stance wide enough to balance before bending either knee.', 'Step into the movement and bend both knees, keeping your front foot planted.', 'Keep the front foot planted and avoid collapsing inward at the knee.', 'Push through the lead foot to return to the start, then change legs as planned.']::text[]),
('Squat (Dumbbell)', 'glutes', array['quads', 'hamstrings', 'calves']::text[], 'dumbbell', 'weight_reps', 'HsvHqgf', array['Stand and set your feet about shoulder width, holding a dumbbell in each hand at your sides.', 'With your chest up and core engaged, lower your body down by bending at the knees and hips, as if sitting back into a chair.', 'Brace the abdomen and spread pressure across the whole foot.', 'Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.', 'Drive upward with the chest and hips rising together; keep the knees from collapsing inward.', 'Stand fully, reset your footing and breathing, then begin the next descent.']::text[]),
('Standing Behind Head Military Press (Smith Machine)', 'shoulders', array['triceps', 'back']::text[], 'machine', 'weight_reps', 'ht8xDrP', array['Set the seat height of the smith machine so that the bar is at shoulder level.', 'Stand and set your feet about shoulder width and your knees soft.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Keep the wrists stacked and use a shoulder path that feels natural.', 'Lower the weight to its starting height under control before pressing again.']::text[]),
('Star Jump', 'cardio', array['quads', 'hamstrings', 'calves']::text[], 'bodyweight', 'duration', 'HtfCpfi', array['Stand and set your feet about shoulder width and your arms by your sides.', 'Before moving, bend your knees slightly and jump up explosively.', 'Bend the hips and knees slightly to load the jump.', 'Load the legs with a small bend, then drive through the floor and land softly.', 'Land with bent hips and knees and let the feet absorb the impact.', 'Absorb the landing through the hips and knees before repeating.']::text[]),
('Seated Shoulder Press (Band)', 'shoulders', array['triceps', 'back']::text[], 'band', 'weight_reps', 'hTLtkXL', array['Take a seat on a chair or bench with your back straight and feet planted.', 'Take hold of the resistance band with both hands, palms facing forward, and bring it up to shoulder level.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Control the band on the way back instead of letting it snap you into position.', 'Lower the weight to its starting height under control before pressing again.']::text[]),
('Side Split Squat (Barbell)', 'quads', array['glutes', 'hamstrings', 'calves']::text[], 'barbell', 'weight_reps', 'HUEqZ1y', array['Stand and set your feet wider than about shoulder width, toes pointing slightly outwards.', 'Take a barbell across your upper back, resting it on your shoulders.', 'Brace the abdomen and spread pressure across the whole foot.', 'Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.', 'Drive upward with the chest and hips rising together; keep the knees from collapsing inward.', 'Stand fully, reset your footing and breathing, then begin the next descent.']::text[]),
('Forward Raise (Cable)', 'shoulders', array['triceps', 'forearms']::text[], 'cable', 'weight_reps', 'hvHhCv8', array['Stand and set your feet about shoulder width and your knees soft.', 'Take hold of the cable handle with palms facing down, and your arms straight in front of you.', 'Start with a manageable load and a small bend in the elbows.', 'Lift the arms forward to about shoulder height, keeping the ribs down and torso still.', 'Stop near shoulder height rather than shrugging to lift higher.', 'Lower the arms slowly to your sides without swinging the weight.']::text[]),
('Low Seated Row (Cable)', 'back', array['biceps', 'forearms']::text[], 'cable', 'weight_reps', 'hvV79Si', array['Take a seat on the machine with your feet flat on the footrests and your knees soft.', 'Hold the handles with palms facing down.', 'Set the torso and allow the arms to reach forward without rounding excessively.', 'Draw your elbows back and bring the handle or weight toward your torso.', 'Bring the elbows back without jerking the torso.', 'Reach the arms forward again without letting the torso lurch.']::text[]),
('Battling Ropes', 'shoulders', array['forearms', 'core']::text[], 'cable', 'weight_reps', 'hVzPY5j', array['Stand and set your feet about shoulder width and knees soft.', 'Keep one end of the rope in each hand, with your palms facing each other.', 'Start at a pace that lets the feet and arms move in sync.', 'Move at a repeatable pace, keeping the motion smooth and your breathing steady.', 'Keep the pattern repeatable as speed increases.', 'Keep the rhythm for the planned interval, slowing if your form starts to slip.']::text[]),
('Preacher Curl Over Exercise Ball (Dumbbell)', 'biceps', array['forearms']::text[], 'dumbbell', 'weight_reps', 'hwygydB', array['Take a seat on an exercise ball with your feet planted and your back straight.', 'Take a dumbbell in one hand with palms facing up, resting your elbow on the exercise ball.', 'Set the working upper arm against the preacher pad and leave the elbow free to bend.', 'Curl the weight while your upper arms stay in contact with the pad.', 'Keep the ball steady and use the feet to manage your balance.', 'Lower until the elbows are nearly straight, keeping the upper arms still.']::text[]),
('Incline Triceps Extension (Cable)', 'triceps', array['shoulders']::text[], 'cable', 'weight_reps', 'Hx1WC8I', array['Set the cable machine to a low pulley position.', 'Connect a straight bar to the cable.', 'Set the upper arms in place before extending the elbows.', 'Keep the upper arms steady and extend through the elbows to move the weight.', 'Keep the upper arms steady while the forearms travel.', 'Bend the elbows slowly to return to the start of the next rep.']::text[]),
('45° Side Bend', 'core', '{}'::text[], 'bodyweight', 'bodyweight_reps', 'Hy9D21L', array['Stand and set your feet about shoulder width and your arms extended straight down by your sides.', 'With your back straight and your core engaged, With control bend your torso to one side, lowering your hand toward your knee.', 'Stand or sit tall with the pelvis facing forward.', 'Bend sideways through the waist without twisting or letting the hips shift.', 'Let the side of the trunk work; do not twist or shift the hips.', 'Bring the weight or body back to its starting position without rushing.']::text[]),
('Incline Fly on Exercise Ball (Dumbbell)', 'chest', array['shoulders']::text[], 'dumbbell', 'weight_reps', 'HYe1ZqR', array['Angle the bench to roughly 45 degrees.', 'Take a seat on an exercise ball and roll forward until your upper back is resting on the incline bench.', 'Keep a soft elbow bend and set the shoulders before moving the arms.', 'With a soft bend in the elbows, sweep your arms together in a wide arc.', 'Keep the ball steady and use the feet to manage your balance.', 'Open the arms back along the same arc without dropping the load.']::text[]),
('Suspended Abdominal Fallout', 'core', '{}'::text[], 'bodyweight', 'bodyweight_reps', 'HZgQPxh', array['Connect a suspension trainer to a high anchor point and adjust the straps to waist height.', 'Face away from the anchor point and hold the handles with your arms extended in front of you.', 'Tighten the abdomen and keep the pelvis tucked before the arms reach away.', 'Reach the arms away while keeping your ribs and pelvis aligned; stop before the lower back sags.', 'Stop reaching when the lower back starts to sag.', 'Pull back to the start through your shoulders and abdominals, keeping the same body line.']::text[]),
('Standing Reverse-Grip Single-Arm Overhead Triceps Extension (Cable)', 'triceps', array['shoulders']::text[], 'cable', 'weight_reps', 'i11JWU7', array['Face the away from the cable machine from a stable stance with feet about shoulder width.', 'Take hold of the cable handle with palms facing up and extend your arm overhead, keeping your elbow close to your head.', 'Set the upper arms in place before extending the elbows.', 'Keep the upper arms pointed upward and extend at the elbows without flaring the ribs.', 'Keep both shoulders level and resist turning toward the working arm.', 'Bend the elbows slowly to return to the start of the next rep; switch sides when the set calls for it.']::text[]),
('Svend Press (Weighted)', 'chest', array['shoulders', 'triceps']::text[], 'bodyweight', 'bodyweight_reps', 'I1OBLnn', array['Stand and set your feet about shoulder width and hold a weight plate ahead of your chest with both hands.', 'Keep your elbows soft and your palms facing each other.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Keep the wrists stacked and use a shoulder path that feels natural.', 'Lower the weight to its starting height under control before pressing again.']::text[]),
('Side Bent (Barbell)', 'core', array['back']::text[], 'barbell', 'weight_reps', 'i4JkUaL', array['Stand and set your feet about shoulder width and hold a barbell with both hands, palms facing down.', 'Keep your spine in a comfortable neutral position and core engaged throughout the exercise.', 'Stand or sit tall with the pelvis facing forward.', 'Bend sideways through the waist without twisting or letting the hips shift.', 'Let the side of the trunk work; do not twist or shift the hips.', 'Bring the weight or body back to its starting position without rushing.']::text[]),
('Double Push Press (Kettlebell)', 'shoulders', array['triceps', 'core']::text[], 'kettlebell', 'weight_reps', 'I4KkPdl', array['Begin by standing with your feet about shoulder width, holding a kettlebell in each hand at shoulder height.', 'Bend your knees slightly and Brace your trunk.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Keep the wrists stacked and use a shoulder path that feels natural.', 'Lower the weight to its starting height under control before pressing again.']::text[]),
('Alternating Hang Clean (Kettlebell)', 'forearms', array['shoulders', 'traps', 'core']::text[], 'kettlebell', 'duration', 'I4tibZG', array['Stand and set your feet about shoulder width, holding a kettlebell in each hand with palms facing down.', 'Bend your knees slightly and hinge forward at the hips, with your spine steady and chest up.', 'Brace before the pull and keep the load close to the body.', 'Drive through the legs and hips, then guide the weight to its receiving position.', 'Finish one side''s motion before the other side takes over.', 'Stand tall to finish, then lower the weight under control before the next rep; switch sides when the set calls for it.']::text[]),
('Decline Push-Up', 'chest', array['triceps', 'shoulders']::text[], 'bodyweight', 'bodyweight_reps', 'i5cEhka', array['Set your hands on the ground just beyond shoulder width, with your feet elevated on a stable surface.', 'Hold your body in a straight line from head to toe, engaging your core muscles.', 'Brace the abdomen and glutes so the shoulders, hips and ankles move together.', 'Bend your elbows to lower your chest while keeping your body in one line.', 'Keep the head in line with the spine as the elbows bend.', 'Press back to straight arms, keeping the body line intact.']::text[]),
('Pullover (Barbell)', 'back', array['chest', 'triceps']::text[], 'barbell', 'weight_reps', 'i6LWjok', array['Settle onto a bench with your head at one end and your feet on the floor.', 'Take a barbell with a shoulder-width grip and extend your arms straight above your chest.', 'Set the ribs down and keep a small elbow bend before lowering the weight.', 'Lower the weight in an arc behind your head until you feel a comfortable shoulder stretch.', 'Keep the ribs down as the arms travel overhead.', 'Pull the weight back over the chest along the same arc, without lifting the ribs.']::text[]),
('Straight Arm Pullover (Dumbbell)', 'chest', array['back', 'triceps']::text[], 'dumbbell', 'weight_reps', 'i8BdLTK', array['Settle onto a bench with your head at one end and your feet planted firmly on the ground.', 'Take a dumbbell with both hands and extend your arms straight above your chest.', 'Set the ribs down and keep a small elbow bend before lowering the weight.', 'Lower the weight in an arc behind your head until you feel a comfortable shoulder stretch.', 'Keep the ribs down as the arms travel overhead.', 'Pull the weight back over the chest along the same arc, without lifting the ribs.']::text[]),
('Half Knee Bends', 'cardio', array['quads', 'hamstrings', 'glutes']::text[], 'bodyweight', 'duration', 'ia6kIIl', array['Stand and set your feet about shoulder width.', 'Before moving, bend your knees and lower your body down as if you were sitting back into a chair.', 'Brace the abdomen and spread pressure across the whole foot.', 'Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.', 'Drive upward with the chest and hips rising together; keep the knees from collapsing inward.', 'Stand fully, reset your footing and breathing, then begin the next descent.']::text[]),
('Seated Single-Leg Calf Raise (Dumbbell)', 'calves', array['hamstrings', 'glutes']::text[], 'dumbbell', 'weight_reps', 'Ia7tumC', array['Take a seat on a bench or chair with your feet planted and a dumbbell resting on your right thigh.', 'Reach your left leg straight out in front of you, keeping your foot flexed.', 'Let the ankles move freely while the rest of the body stays quiet.', 'Rise through the balls of your feet, lifting the heels as high as you can without rocking.', 'Keep the pelvis level as the supporting leg does the work.', 'Lower the heels at a measured pace before rising again; switch sides when the set calls for it.']::text[]),
('Seated Triceps Extension (EZ Bar)', 'triceps', array['shoulders']::text[], 'barbell', 'weight_reps', 'iaapw0g', array['Take a seat on a bench with your back straight and feet planted.', 'Take hold of the ez barbell with palms facing down, hands about shoulder width.', 'Set the upper arms in place before extending the elbows.', 'Keep the upper arms steady and extend through the elbows to move the weight.', 'Keep the upper arms steady while the forearms travel.', 'Bend the elbows slowly to return to the start of the next rep.']::text[]),
('Suspended Push-Up', 'chest', array['triceps', 'shoulders', 'core']::text[], 'bodyweight', 'bodyweight_reps', 'IaGQCrC', array['Choose a suspension trainer and adjust it to an appropriate height.', 'Face away from the anchor point and hold the handles with palms facing down.', 'Brace the abdomen and glutes so the shoulders, hips and ankles move together.', 'Bend your elbows to lower your chest while keeping your body in one line.', 'Keep the head in line with the spine as the elbows bend.', 'Press back to straight arms, keeping the body line intact.']::text[]),
('Quick Feet', 'quads', array['calves', 'hamstrings']::text[], 'bodyweight', 'bodyweight_reps', 'IBj3nsn', array['Stand and set your feet about shoulder width and your arms by your sides.', 'Start by rapidly moving your feet up and down, as if you were running in place.', 'Start at a pace that lets the feet and arms move in sync.', 'Move at a repeatable pace, keeping the motion smooth and your breathing steady.', 'Keep the pattern repeatable as speed increases.', 'Keep the rhythm for the planned interval, slowing if your form starts to slip.']::text[]),
('Chest and Front of Shoulder Stretch', 'chest', array['shoulders']::text[], 'bodyweight', 'duration', 'iDGtjyi', array['Stand tall and set your feet about shoulder width.', 'Reach your arms straight out in front of you at shoulder height.', 'Settle into the starting position and take an easy breath before moving deeper.', 'Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.', 'Stay in a mild stretch rather than pulling farther with momentum.', 'Hold the position with steady breathing, then release gently; repeat on the other side if needed.']::text[]),
('Seated Calf Press (Machine)', 'calves', array['hamstrings']::text[], 'machine', 'weight_reps', 'Ie9UGty', array['Set the seat of the machine so that your shoulders are aligned with the lever pad.', 'Set your toes on the lower portion of the platform and position your knees under the lever pad.', 'Let the ankles move freely while the rest of the body stays quiet.', 'Rise through the balls of your feet, lifting the heels as high as you can without rocking.', 'Pause at the top without rolling the ankles outward.', 'Lower the heels at a measured pace before rising again.']::text[]),
('Seated Squat Calf Raise on Leg Press Machine (Machine)', 'calves', array['quads', 'hamstrings', 'glutes']::text[], 'machine', 'weight_reps', 'IeDEXTe', array['Move the leg-press seat until the knees remain soft at the start.', 'Take a seat on the machine with your back against the backrest and your feet flat on the footplate, about shoulder width.', 'Brace the abdomen and spread pressure across the whole foot.', 'Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.', 'Drive upward with the chest and hips rising together; keep the knees from collapsing inward.', 'Stand fully, reset your footing and breathing, then begin the next descent.']::text[]),
('Drag Curl (Barbell)', 'biceps', array['forearms']::text[], 'barbell', 'weight_reps', 'IENzBdA', array['Stand and set your feet about shoulder width and hold a barbell with palms facing up.', 'Keep the barbell hanging at arm''s length ahead of your thighs.', 'Set the shoulders and upper arms before bending the elbows.', 'Bend your elbows to bring the weight toward your shoulders without swinging your torso.', 'Keep the torso quiet and let the elbow bend lift the weight.', 'Lower until the elbows are nearly straight, keeping the upper arms still.']::text[]),
('Front Chest Squat (Barbell)', 'glutes', array['quads', 'hamstrings', 'calves', 'core']::text[], 'barbell', 'weight_reps', 'IeTIEqg', array['Begin by standing with your feet about shoulder width, toes slightly turned out.', 'Take hold of the barbell ahead of your chest with your hands about shoulder width, elbows pointing forward.', 'Brace the abdomen and spread pressure across the whole foot.', 'Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.', 'Drive upward with the chest and hips rising together; keep the knees from collapsing inward.', 'Stand fully, reset your footing and breathing, then begin the next descent.']::text[]),
('Seated Hammer Curl (Dumbbell)', 'biceps', array['forearms']::text[], 'dumbbell', 'weight_reps', 'IGtBdNT', array['Take a seat on a bench with a dumbbell in each hand, palms facing your torso and arms extended straight down.', 'With your upper arms stationary, exhale and curl the weights while contracting your biceps.', 'Set the shoulders and upper arms before bending the elbows.', 'Curl with palms facing each other and elbows near your sides; avoid rocking back.', 'Keep the palms facing each other and the wrists straight.', 'Lower until the elbows are nearly straight, keeping the upper arms still.']::text[]),
('Lying Pullover on Exercise Ball (Dumbbell)', 'chest', array['triceps', 'shoulders', 'back']::text[], 'dumbbell', 'weight_reps', 'iK59oEA', array['Take a seat on an exercise ball and roll forward until your upper back is resting on the ball.', 'Take a dumbbell with both hands and extend your arms straight up over your chest.', 'Set the ribs down and keep a small elbow bend before lowering the weight.', 'Lower the weight in an arc behind your head until you feel a comfortable shoulder stretch.', 'Keep the ball steady and use the feet to manage your balance.', 'Pull the weight back over the chest along the same arc, without lifting the ribs.']::text[]),
('Gironda Sternum Chin-Up', 'back', array['biceps', 'shoulders']::text[], 'bodyweight', 'bodyweight_reps', 'IL0JUxR', array['Face the high bar from a stable stance with feet about shoulder width.', 'Reach up to hold the bar with palms facing down, just beyond shoulder width.', 'Begin from a controlled hang with the shoulders active rather than slack.', 'Lean back as you pull, aiming the sternum toward the bar and drawing your elbows behind you.', 'Avoid swinging the legs to clear the bar.', 'Lower to long arms without dropping suddenly from the top.']::text[]),
('Squat Jerk', 'quads', array['glutes', 'hamstrings', 'calves', 'core']::text[], 'barbell', 'weight_reps', 'IMRsOCn', array['Start with the barbell resting on your shoulders, with your feet about shoulder width.', 'Before moving, lower your body into a squat position, keeping your chest up and your knees tracking over your toes.', 'Brace before the pull and keep the load close to the body.', 'Drive through the legs and hips, then guide the weight to its receiving position.', 'Receive the load with the torso braced and feet stable.', 'Stand tall to finish, then lower the weight under control before the next rep.']::text[]),
('Dead Bug', 'core', array['back']::text[], 'bodyweight', 'bodyweight_reps', 'iny3m5y', array['Settle onto your back with your arms extended toward the ceiling.', 'Before moving, bend your knees and lift your legs off the ground, creating a 90-degree angle at your hips and knees.', 'Brace the trunk lightly before moving a limb.', 'Move the working arm or leg while keeping the trunk steady and the breathing even.', 'Keep the pelvis from rocking as the arm or leg moves.', 'Reset your posture before changing sides or beginning the next rep.']::text[]),
('Lying on Floor Rear Delt Raise (Dumbbell)', 'shoulders', array['traps', 'back']::text[], 'dumbbell', 'weight_reps', 'Ion0XWz', array['Position yourself face down on the floor with a dumbbell in each hand, palms facing each other.', 'Reach your arms straight out in front of you, keeping a slight bend in your elbows.', 'Start with a manageable load and a small bend in the elbows.', 'Lift the arms out and back with soft elbows, letting the rear shoulders do the work.', 'Stop near shoulder height rather than shrugging to lift higher.', 'Lower the arms slowly to your sides without swinging the weight.']::text[]),
('Overhead Curl on Exercise Ball (Cable)', 'biceps', array['forearms', 'shoulders']::text[], 'cable', 'weight_reps', 'ioTf098', array['Take a seat on an exercise ball and hold the cable handle with palms facing up.', 'Reach your arms fully overhead, keeping your elbows close to your ears.', 'Set the shoulders and upper arms before bending the elbows.', 'Bend your elbows to bring the weight toward your shoulders without swinging your torso.', 'Keep the ball steady and use the feet to manage your balance.', 'Lower until the elbows are nearly straight, keeping the upper arms still.']::text[]),
('Box Jump Down with Single-Leg Stabilization', 'calves', array['quads', 'hamstrings', 'glutes']::text[], 'bodyweight', 'bodyweight_reps', 'iPm26QU', array['Take your place in front of a box or platform with your feet about shoulder width.', 'Before moving, bend your knees and jump onto the box, landing softly with one foot on the box and the other foot hanging off the edge.', 'Bend the hips and knees slightly to load the jump.', 'Load the legs with a small bend, then drive through the floor and land softly.', 'Keep the pelvis level as the supporting leg does the work.', 'Absorb the landing through the hips and knees before repeating; switch sides when the set calls for it.']::text[]),
('Side Bend (Dumbbell)', 'core', '{}'::text[], 'dumbbell', 'weight_reps', 'IpONWYv', array['Stand tall with your feet about shoulder width and hold a dumbbell in one hand, letting it hang down by your side.', 'With your back straight and your core engaged, With control bend sideways at the waist toward the opposite side of the dumbbell, lowering the weight as far as you comfortably can.', 'Stand or sit tall with the pelvis facing forward.', 'Bend sideways through the waist without twisting or letting the hips shift.', 'Let the side of the trunk work; do not twist or shift the hips.', 'Bring the weight or body back to its starting position without rushing.']::text[]),
('Upright Row (Back Pov) (Dumbbell)', 'shoulders', array['traps', 'biceps']::text[], 'dumbbell', 'weight_reps', 'Iptlv6x', array['Stand and set your feet about shoulder width, holding a dumbbell in each hand with palms facing down.', 'Let the dumbbells hang ahead of your thighs, with your arms straight and your palms facing your body.', 'Set the torso and allow the arms to reach forward without rounding excessively.', 'Draw your elbows back and bring the handle or weight toward your torso.', 'Bring the elbows back without jerking the torso.', 'Reach the arms forward again without letting the torso lurch.']::text[]),
('Seated Calf Raise (Barbell)', 'calves', array['hamstrings']::text[], 'barbell', 'weight_reps', 'ipvgBnC', array['Plant both feet while seated on a bench; a barbell resting on your thighs.', 'Set the balls of your feet on a raised platform, such as a block or step.', 'Let the ankles move freely while the rest of the body stays quiet.', 'Rise through the balls of your feet, lifting the heels as high as you can without rocking.', 'Pause at the top without rolling the ankles outward.', 'Lower the heels at a measured pace before rising again.']::text[]),
('Half Sit-Up', 'core', '{}'::text[], 'bodyweight', 'bodyweight_reps', 'iQ241UP', array['Settle onto your back with your knees bent and feet planted.', 'Set your hands behind your head with your elbows pointing outwards.', 'Set the pelvis and keep the neck relaxed before curling upward.', 'Curl your rib cage toward your pelvis, letting the abdominals move the torso.', 'Leave a little space between the chin and chest; keep the movement in the torso.', 'Lower the shoulders or torso with control before the next curl.']::text[]),
('Forward Lunge', 'glutes', array['quads', 'hamstrings', 'calves']::text[], 'bodyweight', 'bodyweight_reps', 'iqH55N8', array['Stand and set your feet about hip width and hands on your hips.', 'Step wide forward with your right foot, lowering your body into a lunge position.', 'Set your stance wide enough to balance before bending either knee.', 'Step into the movement and bend both knees, keeping your front foot planted.', 'Keep the front foot planted and avoid collapsing inward at the knee.', 'Push through the lead foot to return to the start, then change legs as planned.']::text[]),
('Roller Back Stretch', 'back', array['hamstrings', 'glutes']::text[], 'other', 'duration', 'isofgzg', array['Begin by sitting on the ground with your legs extended in front of you.', 'Set the roller perpendicular to your body, just below your glutes.', 'Settle into the starting position and take an easy breath before moving deeper.', 'Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.', 'Stay in a mild stretch rather than pulling farther with momentum.', 'Hold the position with steady breathing, then release gently; repeat on the other side if needed.']::text[]),
('Over Bench Single-Arm Neutral Wrist Curl (Dumbbell)', 'biceps', array['forearms']::text[], 'dumbbell', 'weight_reps', 'IvV6C9M', array['Take a seat on a bench with a dumbbell in one hand and your arm extended over the bench, palm facing up.', 'Keep your upper arm stationary and curl the dumbbell toward your shoulder, keeping your wrist in a neutral position.', 'Keep the elbows relaxed so the small muscles of the hand or forearm take the load.', 'Move through the wrists or fingers while the forearms stay supported and still.', 'Keep both shoulders level and resist turning toward the working arm.', 'Ease back to the start without letting the load fall from your hands; switch sides when the set calls for it.']::text[]),
('Reverse Preacher Curl (Cable)', 'biceps', array['forearms']::text[], 'cable', 'weight_reps', 'IwX5NqK', array['Set the cable machine so that the preacher curl pad is at chest height.', 'Take a seat on the preacher curl bench and place your upper arms on the pad, with your palms facing down and your elbows straight.', 'Set the working upper arm against the preacher pad and leave the elbow free to bend.', 'Curl the weight while your upper arms stay in contact with the pad.', 'Keep the torso quiet and let the elbow bend lift the weight.', 'Lower until the elbows are nearly straight, keeping the upper arms still.']::text[]),
('Judo Flip (Cable)', 'core', array['shoulders']::text[], 'cable', 'weight_reps', 'IxsFgRT', array['Face the cable machine from a stable stance with feet about shoulder width.', 'Take hold of the cable handle with both hands at chest level, palms facing down.', 'Set the pelvis and make the turn through the rib cage.', 'Turn through the torso while the hips and lower body stay as steady as the setup allows.', 'Keep the turn smooth instead of throwing the arms across the body.', 'Return through center before turning to the other side.']::text[]),
('Full Squat (Barbell)', 'glutes', array['quads', 'hamstrings', 'calves', 'core']::text[], 'barbell', 'weight_reps', 'iYzB0Cz', array['Stand and set your feet about shoulder width, toes slightly turned out.', 'Rest the bar across the upper back and take a secure grip.', 'Brace the abdomen and spread pressure across the whole foot.', 'Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.', 'Drive upward with the chest and hips rising together; keep the knees from collapsing inward.', 'Stand fully, reset your footing and breathing, then begin the next descent.']::text[]),
('Alternate Side Press (Dumbbell)', 'shoulders', array['triceps', 'core']::text[], 'dumbbell', 'weight_reps', 'izMnLqz', array['Stand and set your feet about shoulder width, holding a dumbbell in each hand at shoulder height.', 'Before moving, press one dumbbell overhead while keeping the other dumbbell at shoulder height.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Finish one side''s motion before the other side takes over.', 'Lower the weight to its starting height under control before pressing again; switch sides when the set calls for it.']::text[]),
('Walking Lunge', 'glutes', array['quads', 'hamstrings', 'calves']::text[], 'bodyweight', 'bodyweight_reps', 'IZVHb27', array['Stand and set your feet about shoulder width.', 'Step forward with your right leg, lowering your body into a lunge position.', 'Set your stance wide enough to balance before bending either knee.', 'Step into the movement and bend both knees, keeping your front foot planted.', 'Keep the front foot planted and avoid collapsing inward at the knee.', 'Push through the lead foot to return to the start, then change legs as planned.']::text[]),
('Triceps Dip (Kneeling) (Assisted)', 'triceps', array['chest', 'shoulders']::text[], 'machine', 'weight_reps', 'J60bN17', array['Set the machine to your desired weight and height.', 'Get down on the pad facing the machine, with your hands gripping the handles.', 'Set the shoulders down and keep the elbows pointed mostly behind you.', 'Bend the elbows to lower between the supports; stop at a comfortable shoulder depth.', 'Choose a depth that lets the shoulders stay comfortable.', 'Press through the hands to rise, then reset the shoulders before another rep.']::text[]),
('Extended Range Single-Arm Press on Floor (Kettlebell)', 'chest', array['triceps', 'shoulders']::text[], 'kettlebell', 'weight_reps', 'j6uIfep', array['Begin by lying on your back on the floor with your knees bent and feet planted.', 'Take a kettlebell in one hand, with your palm facing toward your feet.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Keep both shoulders level and resist turning toward the working arm.', 'Lower the weight to its starting height under control before pressing again; switch sides when the set calls for it.']::text[]),
('Exercise Ball on the Wall Calf Raise (Tennis Ball Between Knees)', 'calves', array['quads', 'hamstrings']::text[], 'dumbbell', 'weight_reps', 'j74M6Zn', array['Stand and set your back against a wall and place an exercise ball between your lower back and the wall.', 'Set your feet about shoulder width and slightly in front of you.', 'Let the ankles move freely while the rest of the body stays quiet.', 'Rise through the balls of your feet, lifting the heels as high as you can without rocking.', 'Keep the ball steady and use the feet to manage your balance.', 'Lower the heels at a measured pace before rising again.']::text[]),
('Alternating Seated Biceps Curl on Exercise Ball (Dumbbell)', 'biceps', array['forearms']::text[], 'dumbbell', 'weight_reps', 'J74XlNf', array['Take a seat on an exercise ball with your feet planted and your back straight.', 'Take a dumbbell in each hand with your palms facing forward and your arms straight.', 'Set the shoulders and upper arms before bending the elbows.', 'Bend your elbows to bring the weight toward your shoulders without swinging your torso.', 'Finish one side''s motion before the other side takes over.', 'Lower until the elbows are nearly straight, keeping the upper arms still; switch sides when the set calls for it.']::text[]),
('Upper Chest Crossovers (Cable)', 'chest', array['shoulders', 'triceps']::text[], 'cable', 'weight_reps', 'j7XMAyn', array['Connect the handles to the cables at chest height.', 'Take your place in the center of the cable machine with one foot slightly in front of the other.', 'Keep a soft elbow bend and set the shoulders before moving the arms.', 'Bring the handles across the front of your chest in a broad arc, keeping a slight elbow bend.', 'Keep the elbow angle nearly unchanged through the arc.', 'Open the arms back along the same arc without dropping the load.']::text[]),
('Walking on Stepmill', 'cardio', array['quads', 'hamstrings', 'glutes', 'calves']::text[], 'machine', 'duration', 'j9Q5crt', array['Set the stepmill machine to a comfortable level.', 'Get onto the machine and place your hands on the handrails for support.', 'Stand tall with the load secure and the shoulders level.', 'Walk at a controlled pace, keeping your shoulders level and your steps even.', 'Keep steps even and avoid leaning away from the load.', 'Stop before posture breaks down, set the load down safely, and reset for the next walk.']::text[]),
('Walking High Knees Lunge', 'cardio', array['quads', 'hamstrings', 'glutes', 'calves']::text[], 'bodyweight', 'duration', 'J9zIWig', array['Stand and set your feet about hip width.', 'Lift your right knee up toward your chest as high as you can while balancing on your left leg.', 'Set your stance wide enough to balance before bending either knee.', 'Step into the movement and bend both knees, keeping your front foot planted.', 'Keep the front foot planted and avoid collapsing inward at the knee.', 'Push through the lead foot to return to the start, then change legs as planned.']::text[]),
('Spine Stretch', 'back', array['hamstrings', 'glutes']::text[], 'bodyweight', 'duration', 'JbC2iaV', array['Take a seat on the ground with your legs extended in front of you.', 'Set your hands on the ground behind you, fingers pointing toward your body.', 'Settle into the starting position and take an easy breath before moving deeper.', 'Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.', 'Stay in a mild stretch rather than pulling farther with momentum.', 'Hold the position with steady breathing, then release gently; repeat on the other side if needed.']::text[]),
('Single-Arm Slam (With Medicine Ball)', 'core', array['shoulders', 'back']::text[], 'other', 'weight_reps', 'jCrtE9b', array['Stand and set your feet about shoulder width, holding the medicine ball with one hand ahead of your waist.', 'Bend your knees slightly and Brace your trunk.', 'Set a firm stance and leave enough clear space for the ball to travel.', 'Drive the ball away forcefully, using the arms and trunk together; catch or retrieve it before resetting.', 'Keep both shoulders level and resist turning toward the working arm.', 'Return along the same path at a controlled pace; switch sides when the set calls for it.']::text[]),
('Inverted Row with Straps', 'back', array['biceps', 'forearms']::text[], 'bodyweight', 'bodyweight_reps', 'jdiExfW', array['Prepare a suspension trainer or straps at chest height.', 'Face the anchor point and grab the handles with palms facing down.', 'Set the torso and allow the arms to reach forward without rounding excessively.', 'Draw your elbows back and bring the handle or weight toward your torso.', 'Bring the elbows back without jerking the torso.', 'Reach the arms forward again without letting the torso lurch.']::text[]),
('Incline Single-Arm Hammer Press on Exercise Ball (Dumbbell)', 'triceps', array['shoulders', 'chest']::text[], 'dumbbell', 'weight_reps', 'jDnrkar', array['Take a seat on an exercise ball with a dumbbell in one hand.', 'Step your feet forward and roll your body down until your head, neck, and upper back are supported on the ball.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Keep both shoulders level and resist turning toward the working arm.', 'Lower the weight to its starting height under control before pressing again; switch sides when the set calls for it.']::text[]),
('Side-Lying Floor Stretch', 'back', array['core', 'glutes']::text[], 'bodyweight', 'duration', 'jDOKRM5', array['Settle onto your side with your legs straight and your bottom arm extended straight overhead.', 'Bend your top knee and place your foot on the ground ahead of your bottom leg.', 'Settle into the starting position and take an easy breath before moving deeper.', 'Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.', 'Stay in a mild stretch rather than pulling farther with momentum.', 'Hold the position with steady breathing, then release gently; repeat on the other side if needed.']::text[]),
('Medicine Ball Chest Push Single Response', 'chest', array['triceps', 'shoulders']::text[], 'other', 'weight_reps', 'jeHtrlO', array['Stand and set your feet about shoulder width, holding the medicine ball at chest level.', 'Reach your arms forward, pushing the medicine ball away from your chest.', 'Set a firm stance and leave enough clear space for the ball to travel.', 'Drive the ball away forcefully, using the arms and trunk together; catch or retrieve it before resetting.', 'Follow through with the whole body while keeping control of the landing or catch.', 'Bring the weight or body back to its starting position without rushing.']::text[]),
('Standing Archer', 'back', array['shoulders', 'biceps', 'forearms']::text[], 'bodyweight', 'bodyweight_reps', 'JF8AkMX', array['Stand and set your feet about shoulder width and your knees soft.', 'Reach your arms straight out in front of you at shoulder height, parallel to the ground.', 'Set the pelvis and make the turn through the rib cage.', 'Turn through the torso while the hips and lower body stay as steady as the setup allows.', 'Keep the turn smooth instead of throwing the arms across the body.', 'Return through center before turning to the other side.']::text[]),
('Squat (Smith Machine)', 'glutes', array['quads', 'hamstrings', 'calves']::text[], 'machine', 'weight_reps', 'jFtipLl', array['Prepare the smith machine with the barbell at an appropriate height for your squat.', 'Stand and set your feet about shoulder width, toes slightly turned out.', 'Brace the abdomen and spread pressure across the whole foot.', 'Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.', 'Drive upward with the chest and hips rising together; keep the knees from collapsing inward.', 'Stand fully, reset your footing and breathing, then begin the next descent.']::text[]),
('Incline T-Raise (Dumbbell)', 'shoulders', array['traps', 'back']::text[], 'dumbbell', 'weight_reps', 'jgbvVJ0', array['Angle an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand, palms facing inwards.', 'Tip forward and let your arms hang straight down, perpendicular to the floor.', 'Start with a manageable load and a small bend in the elbows.', 'Open the arms sideways into a T shape, keeping the torso steady on the bench.', 'Stop near shoulder height rather than shrugging to lift higher.', 'Lower the arms slowly to your sides without swinging the weight.']::text[]),
('Narrow Row (Smith Machine)', 'back', array['biceps', 'shoulders']::text[], 'machine', 'weight_reps', 'JGKowMS', array['Fit the seat to your body, then settle into the machine.', 'Hold the handles with palms facing down, slightly narrower than about shoulder width.', 'Set the torso and allow the arms to reach forward without rounding excessively.', 'Draw your elbows back and bring the handle or weight toward your torso.', 'Bring the elbows back without jerking the torso.', 'Reach the arms forward again without letting the torso lurch.']::text[]),
('Incline Chest Press (Machine)', 'chest', array['shoulders', 'triceps']::text[], 'machine', 'weight_reps', 'jHAnWmT', array['Set the seat and backrest of the leverage machine to a comfortable position.', 'Take a seat on the machine with your back against the backrest and your feet planted.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Keep the wrists stacked and use a shoulder path that feels natural.', 'Lower the weight to its starting height under control before pressing again.']::text[]),
('Seated Bench Extension (Dumbbell)', 'triceps', array['shoulders']::text[], 'dumbbell', 'weight_reps', 'JhYSVwT', array['Take a seat on a bench with your back straight and feet planted.', 'Take a dumbbell with both hands and extend your arms straight up above your head.', 'Set the upper arms in place before extending the elbows.', 'Keep the upper arms steady and extend through the elbows to move the weight.', 'Keep the upper arms steady while the forearms travel.', 'Bend the elbows slowly to return to the start of the next rep.']::text[]),
('Preacher Curl (Dumbbell)', 'biceps', array['forearms']::text[], 'dumbbell', 'weight_reps', 'jivWf8n', array['Take a seat on a preacher curl bench with your upper arms resting on the pad and your chest against it.', 'Take a dumbbell in each hand with your palms facing up and your arms straight.', 'Set the working upper arm against the preacher pad and leave the elbow free to bend.', 'Curl the weight while your upper arms stay in contact with the pad.', 'Keep the torso quiet and let the elbow bend lift the weight.', 'Lower until the elbows are nearly straight, keeping the upper arms still.']::text[]),
('Standing Military Press (Smith Machine)', 'shoulders', array['triceps', 'back']::text[], 'machine', 'weight_reps', 'jjUPrze', array['Stand and set your feet about shoulder width and your knees soft.', 'Hold the barbell with palms facing down, just beyond shoulder width.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Keep the wrists stacked and use a shoulder path that feels natural.', 'Lower the weight to its starting height under control before pressing again.']::text[]),
('Single-Arm Seated Hammer Curl (Dumbbell)', 'biceps', array['forearms']::text[], 'dumbbell', 'weight_reps', 'jK2hZ6n', array['Take a seat on a bench with your back straight and feet planted.', 'Take a dumbbell in one hand with a neutral grip (palms facing each other).', 'Set the shoulders and upper arms before bending the elbows.', 'Curl with palms facing each other and elbows near your sides; avoid rocking back.', 'Keep both shoulders level and resist turning toward the working arm.', 'Lower until the elbows are nearly straight, keeping the upper arms still; switch sides when the set calls for it.']::text[]),
('Two-Leg Calf Raise - (Band Under Both Legs) (Band)', 'calves', '{}'::text[], 'band', 'weight_reps', 'jl6uxZV', array['Stand and set your feet about shoulder width and place a resistance band under both feet.', 'Take hold of the ends of the band with your hands for stability.', 'Let the ankles move freely while the rest of the body stays quiet.', 'Rise through the balls of your feet, lifting the heels as high as you can without rocking.', 'Control the band on the way back instead of letting it snap you into position.', 'Lower the heels at a measured pace before rising again.']::text[]),
('Wide Hand Push Up', 'chest', array['triceps', 'shoulders']::text[], 'bodyweight', 'bodyweight_reps', 'JmMVpR3', array['Begin in a high plank position with your hands wider than about shoulder width.', 'Hold your body in a straight line from head to toe.', 'Brace the abdomen and glutes so the shoulders, hips and ankles move together.', 'Bend your elbows to lower your chest while keeping your body in one line.', 'Keep the head in line with the spine as the elbows bend.', 'Press back to straight arms, keeping the body line intact.']::text[]),
('Outside Leg Kick Push-Up', 'glutes', array['quads', 'hamstrings', 'calves']::text[], 'bodyweight', 'bodyweight_reps', 'jNU1gFQ', array['Begin in a push-up position with your hands just beyond shoulder width and your feet together.', 'Lower your body toward the ground by bending your elbows, with your spine steady and core engaged.', 'Brace the abdomen and glutes so the shoulders, hips and ankles move together.', 'Bend your elbows to lower your chest while keeping your body in one line.', 'Keep the head in line with the spine as the elbows bend.', 'Press back to straight arms, keeping the body line intact.']::text[]),
('Standing Twist Row (V-Bar) (Cable)', 'back', array['biceps', 'shoulders']::text[], 'cable', 'weight_reps', 'JOZhu2h', array['Connect a v-bar attachment to a cable machine at chest height.', 'Face the cable machine from a stable stance with feet about shoulder width.', 'Set the torso and allow the arms to reach forward without rounding excessively.', 'Draw your elbows back and bring the handle or weight toward your torso.', 'Bring the elbows back without jerking the torso.', 'Reach the arms forward again without letting the torso lurch.']::text[]),
('Standing Crunch (Cable)', 'core', '{}'::text[], 'cable', 'weight_reps', 'jpgqxiS', array['Connect a cable handle to a high pulley and stand turned away from the machine.', 'Take hold of the handle with both hands and place it behind your head, keeping your elbows bent.', 'Set the pelvis and keep the neck relaxed before curling upward.', 'Curl your rib cage toward your pelvis, letting the abdominals move the torso.', 'Leave a little space between the chin and chest; keep the movement in the torso.', 'Lower the shoulders or torso with control before the next curl.']::text[]),
('Deadlift (Trap Bar)', 'glutes', array['hamstrings', 'quads', 'back']::text[], 'barbell', 'weight_reps', 'jQGwmxN', array['Stand and set your feet about shoulder width and the trap bar on the ground in front of you.', 'Bend at the hips and knees to lower yourself down and grip the handles of the trap bar with palms facing down.', 'Unlock the knees and brace the abdomen before moving the hips back.', 'Push the hips back while keeping the load close and the spine steady.', 'Keep the weight close to the legs and stop when the back would begin to round.', 'Drive the hips forward to stand tall without leaning back at the top.']::text[]),
('Stiff Leg Good Morning (Barbell)', 'glutes', array['hamstrings', 'back']::text[], 'barbell', 'weight_reps', 'JrOHAZc', array['Stand and set your feet about shoulder width and your knees soft.', 'Take hold of the barbell across your upper back, resting it on your traps.', 'Unlock the knees and brace the abdomen before moving the hips back.', 'Push the hips back while keeping the load close and the spine steady.', 'Keep the weight close to the legs and stop when the back would begin to round.', 'Drive the hips forward to stand tall without leaning back at the top.']::text[]),
('Single-Arm Bent Over Row (Barbell)', 'back', array['biceps', 'forearms']::text[], 'barbell', 'weight_reps', 'Jsgsc27', array['Stand and set your feet about shoulder width, knees soft, and hold a barbell with one hand using an overhand grip.', 'Bend forward at the hips, with your spine steady and your head in a neutral position.', 'Set the torso and allow the arms to reach forward without rounding excessively.', 'Draw your elbows back and bring the handle or weight toward your torso.', 'Keep both shoulders level and resist turning toward the working arm.', 'Reach the arms forward again without letting the torso lurch; switch sides when the set calls for it.']::text[]),
('Wide Bench Press (Barbell)', 'chest', array['shoulders', 'triceps']::text[], 'barbell', 'weight_reps', 'JsKq9so', array['Settle onto a bench with your feet planted and your back pressed against the bench.', 'Hold the barbell with a wide grip, just beyond shoulder width.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Keep the wrists stacked and use a shoulder path that feels natural.', 'Lower the weight to its starting height under control before pressing again.']::text[]),
('Muscle Up (Weighted)', 'back', array['biceps', 'triceps', 'shoulders', 'chest']::text[], 'bodyweight', 'bodyweight_reps', 'JsOV1SU', array['Begin by hanging from a pull-up bar with your palms turned away from you and your hands just beyond shoulder width.', 'Brace your trunk and pull your body up toward the bar, leading with your chest.', 'Begin from a controlled hang with the shoulders active rather than slack.', 'Pull your elbows down and bring your upper chest toward the bar without kicking your legs.', 'Avoid swinging the legs to clear the bar.', 'Lower to long arms without dropping suddenly from the top.']::text[]),
('Seated Curls (EZ Bar)', 'biceps', array['forearms']::text[], 'barbell', 'weight_reps', 'jtFKbt5', array['Plant both feet while seated on a bench; your back straight.', 'Take hold of the ez barbell with palms facing up, and your hands about shoulder width.', 'Set the shoulders and upper arms before bending the elbows.', 'Bend your elbows to bring the weight toward your shoulders without swinging your torso.', 'Keep the torso quiet and let the elbow bend lift the weight.', 'Lower until the elbows are nearly straight, keeping the upper arms still.']::text[]),
('Side Hip (On Parallel Bars)', 'core', '{}'::text[], 'bodyweight', 'bodyweight_reps', 'jTkSc6o', array['Stand between two parallel bars with your feet about shoulder width.', 'Set your hands on the bars and lift your body off the ground, supporting your weight on your arms.', 'Brace the abdomen and keep the shoulders anchored to the support.', 'Lift your legs by bracing your trunk and moving at the hips rather than swinging.', 'Slow the legs before they pull the lower back out of position.', 'Lower the legs slowly without swinging or losing your trunk position.']::text[]),
('Elbow-To-Knee', 'core', '{}'::text[], 'bodyweight', 'bodyweight_reps', 'jvp6DiD', array['Begin by lying flat on your back with your knees bent and feet planted.', 'Set your hands behind your head with your elbows pointing outwards.', 'Set the pelvis and keep the neck relaxed before curling upward.', 'Curl your rib cage toward your pelvis, letting the abdominals move the torso.', 'Leave a little space between the chin and chest; keep the movement in the torso.', 'Lower the shoulders or torso with control before the next curl.']::text[]),
('Single-Arm Prone Curl (Dumbbell)', 'biceps', array['forearms']::text[], 'dumbbell', 'weight_reps', 'JWjujiY', array['Position yourself face down on a flat bench with a dumbbell in one hand, palm facing down.', 'Extend your arm fully, letting it hang straight down toward the floor.', 'Set the shoulders and upper arms before bending the elbows.', 'Bend your elbows to bring the weight toward your shoulders without swinging your torso.', 'Keep both shoulders level and resist turning toward the working arm.', 'Lower until the elbows are nearly straight, keeping the upper arms still; switch sides when the set calls for it.']::text[]),
('Kneeling Single-Arm Pulldown (Band)', 'back', array['biceps']::text[], 'band', 'weight_reps', 'JxrY9mC', array['Connect the band to a sturdy anchor point above your head.', 'Kneel and hold the band with one hand, palm facing down.', 'Sit tall and set the shoulders before drawing the handle down.', 'Pull the handle down by driving your elbows toward your ribs; keep your torso steady.', 'Keep both shoulders level and resist turning toward the working arm.', 'Let the handle rise steadily until the arms are long, then reset the shoulders; switch sides when the set calls for it.']::text[]),
('Incline Shrug (Dumbbell)', 'traps', array['shoulders']::text[], 'dumbbell', 'weight_reps', 'JymLInS', array['Angle an incline bench to a 45-degree angle and sit on it with a dumbbell in each hand.', 'Set your feet planted and let your arms hang straight down with your palms facing your body.', 'Let the arms hang long and keep the head neutral.', 'Lift your shoulders toward your ears without bending the elbows or rolling the shoulders.', 'Lift and lower vertically without circling the shoulders.', 'Ease back to the start before repeating.']::text[]),
('Seated Bent Arm Lateral Raise (Dumbbell)', 'shoulders', array['traps', 'back']::text[], 'dumbbell', 'weight_reps', 'JzQbv7J', array['Take a seat on a bench with your back straight and feet planted.', 'Take a dumbbell in each hand with your palms facing your body and your arms bent at a 90-degree angle.', 'Start with a manageable load and a small bend in the elbows.', 'Raise the arms out to the sides to about shoulder height without leaning or shrugging.', 'Stop near shoulder height rather than shrugging to lift higher.', 'Lower the arms slowly to your sides without swinging the weight.']::text[]),
('Squat (Weighted)', 'glutes', array['quads', 'hamstrings', 'calves']::text[], 'bodyweight', 'bodyweight_reps', 'JZuApnB', array['Stand and set your feet about shoulder width, toes pointing slightly outward.', 'Take a weight ahead of your chest or on your shoulders.', 'Brace the abdomen and spread pressure across the whole foot.', 'Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.', 'Drive upward with the chest and hips rising together; keep the knees from collapsing inward.', 'Stand fully, reset your footing and breathing, then begin the next descent.']::text[]),
('Triceps Dip on High Parallel Bars (Weighted)', 'triceps', array['chest', 'shoulders']::text[], 'bodyweight', 'bodyweight_reps', 'K1vlode', array['Set yourself between two parallel bars with your hands gripping the bars and your arms straight.', 'Before moving, bend your elbows and lower your body until your upper arms are parallel to the ground.', 'Set the shoulders down and keep the elbows pointed mostly behind you.', 'Bend the elbows to lower between the supports; stop at a comfortable shoulder depth.', 'Choose a depth that lets the shoulders stay comfortable.', 'Press through the hands to rise, then reset the shoulders before another rep.']::text[]),
('Lying Single-Arm Press (Dumbbell)', 'chest', array['triceps', 'shoulders']::text[], 'dumbbell', 'weight_reps', 'K3dIO25', array['Settle onto a bench with your back supported and feet planted.', 'Take a dumbbell in one hand with your palm facing toward your feet.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Keep both shoulders level and resist turning toward the working arm.', 'Lower the weight to its starting height under control before pressing again; switch sides when the set calls for it.']::text[]),
('Single-Arm Concentration Curl (On Stability Ball) (Dumbbell)', 'biceps', array['forearms']::text[], 'dumbbell', 'weight_reps', 'k5IpyHg', array['Take a seat on a stability ball with your feet planted and your knees bent at a 90-degree angle.', 'Take a dumbbell in one hand with your palm facing up and your arm extended down toward the floor.', 'Set the shoulders and upper arms before bending the elbows.', 'Bend your elbows to bring the weight toward your shoulders without swinging your torso.', 'Keep both shoulders level and resist turning toward the working arm.', 'Lower until the elbows are nearly straight, keeping the upper arms still; switch sides when the set calls for it.']::text[]),
('Reclining Big Toe Pose with Rope', 'hamstrings', array['calves', 'glutes']::text[], 'cable', 'weight_reps', 'K5xgdvI', array['Settle onto your back with your legs extended and your arms by your sides.', 'Thread the rope around the ball of your right foot and hold the ends of the rope with your hands.', 'Settle into the starting position and take an easy breath before moving deeper.', 'Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.', 'Stay in a mild stretch rather than pulling farther with momentum.', 'Hold the position with steady breathing, then release gently; repeat on the other side if needed.']::text[]),
('Lunge with Twist', 'core', array['quads', 'glutes', 'hamstrings']::text[], 'bodyweight', 'bodyweight_reps', 'K9VL0Jq', array['Begin by standing with your feet about shoulder width.', 'Step forward with your right foot, lowering your body into a lunge position.', 'Set your stance wide enough to balance before bending either knee.', 'Step into the movement and bend both knees, keeping your front foot planted.', 'Keep the front foot planted and avoid collapsing inward at the knee.', 'Push through the lead foot to return to the start, then change legs as planned.']::text[]),
('Advanced Windmill (Kettlebell)', 'core', array['shoulders']::text[], 'kettlebell', 'weight_reps', 'Kal9cQQ', array['Stand and set your feet wider than about shoulder width, toes pointing slightly outward.', 'Take a kettlebell in your right hand, with your arm extended overhead and your palm facing forward.', 'Set the pelvis and make the turn through the rib cage.', 'Turn through the torso while the hips and lower body stay as steady as the setup allows.', 'Keep the turn smooth instead of throwing the arms across the body.', 'Return through center before turning to the other side.']::text[]),
('Decline Seated Wide-Grip Row (Cable)', 'back', array['biceps', 'forearms']::text[], 'cable', 'weight_reps', 'kesXOpB', array['Take a seat on the decline bench facing the cable machine with your feet securely placed on the footrests.', 'Hold the cable attachment with a wide overhand grip, palms facing down.', 'Set the torso and allow the arms to reach forward without rounding excessively.', 'Draw your elbows back and bring the handle or weight toward your torso.', 'Bring the elbows back without jerking the torso.', 'Reach the arms forward again without letting the torso lurch.']::text[]),
('Sumo Deadlift (Barbell)', 'glutes', array['hamstrings', 'quads', 'back']::text[], 'barbell', 'weight_reps', 'KgI0tqW', array['Stand and set your feet wider than about shoulder width, toes pointing outwards.', 'Set a barbell on the ground in front of you, centered between your feet.', 'Unlock the knees and brace the abdomen before moving the hips back.', 'Push the hips back while keeping the load close and the spine steady.', 'Keep the weight close to the legs and stop when the back would begin to round.', 'Drive the hips forward to stand tall without leaning back at the top.']::text[]),
('Decline Single-Arm Press (Cable)', 'chest', array['triceps', 'shoulders']::text[], 'cable', 'weight_reps', 'KHGNa16', array['Set the cable machine to a decline position.', 'Face away from the machine and grab the handle with one hand.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Keep both shoulders level and resist turning toward the working arm.', 'Lower the weight to its starting height under control before pressing again; switch sides when the set calls for it.']::text[]),
('Push-Up to Side Plank', 'core', array['shoulders', 'chest', 'triceps']::text[], 'bodyweight', 'duration', 'KhHJ338', array['Begin in a push-up position with your hands about shoulder width and your body in a straight line.', 'Lower your body toward the ground by bending your elbows, keeping your core engaged.', 'Brace the abdomen and find a position you can maintain without holding your breath.', 'Brace your midsection and hold the position while breathing normally.', 'Keep breathing steadily as you maintain the same body line.', 'Keep the shape for the planned time, then come out of it with control.']::text[]),
('Bench Press (Band)', 'chest', array['triceps', 'shoulders']::text[], 'band', 'weight_reps', 'khlHMqs', array['Settle onto a bench with your feet planted and your back pressed against the bench.', 'Hold the band handles with palms facing down, just beyond shoulder width.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Control the band on the way back instead of letting it snap you into position.', 'Lower the weight to its starting height under control before pressing again.']::text[]),
('Alternate Shoulder Press (Cable)', 'shoulders', array['triceps', 'back']::text[], 'cable', 'weight_reps', 'KHPZL0b', array['Stand and set your feet about shoulder width and Hold the handles of the cable machine with palms facing down.', 'Set your hands at shoulder height, with your palms facing forward.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Finish one side''s motion before the other side takes over.', 'Lower the weight to its starting height under control before pressing again; switch sides when the set calls for it.']::text[]),
('Bent Press (Kettlebell)', 'core', array['shoulders', 'triceps']::text[], 'kettlebell', 'weight_reps', 'kjE55n5', array['Stand and set your feet about shoulder width, holding a kettlebell in your right hand.', 'Before moving, bend your knees slightly and press the kettlebell overhead with your right arm, keeping your elbow locked.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Keep the wrists stacked and use a shoulder path that feels natural.', 'Lower the weight to its starting height under control before pressing again.']::text[]),
('Crunch (Hands Overhead)', 'core', '{}'::text[], 'bodyweight', 'bodyweight_reps', 'kjJ3VoQ', array['Settle onto your back with your knees bent and feet planted.', 'Reach your arms straight above your head.', 'Set the pelvis and keep the neck relaxed before curling upward.', 'Curl your rib cage toward your pelvis, letting the abdominals move the torso.', 'Leave a little space between the chin and chest; keep the movement in the torso.', 'Lower the shoulders or torso with control before the next curl.']::text[]),
('Exercise Ball Single-Leg Prone Lower Body Rotation', 'glutes', array['hamstrings', 'quads', 'core']::text[], 'bodyweight', 'bodyweight_reps', 'kKYTkjJ', array['Position yourself face down on the stability ball with your hips resting on the ball and your legs extended straight behind you.', 'Set your hands on the ground in front of you for support.', 'Set the pelvis and make the turn through the rib cage.', 'Turn through the torso while the hips and lower body stay as steady as the setup allows.', 'Keep the pelvis level as the supporting leg does the work.', 'Return through center before turning to the other side; switch sides when the set calls for it.']::text[]),
('Single-Arm Standing Low Row (Band)', 'back', array['biceps', 'shoulders']::text[], 'band', 'weight_reps', 'km0sQC0', array['Connect the band to a stable anchor point at waist height.', 'Face the anchor point from a stable stance with feet about shoulder width.', 'Set the torso and allow the arms to reach forward without rounding excessively.', 'Draw your elbows back and bring the handle or weight toward your torso.', 'Keep both shoulders level and resist turning toward the working arm.', 'Reach the arms forward again without letting the torso lurch; switch sides when the set calls for it.']::text[]),
('Wheel Run', 'cardio', array['quads', 'hamstrings', 'calves']::text[], 'bodyweight', 'duration', 'km2Ljzj', array['Begin in a plank position with your hands on the wheel and your body straight.', 'Brace your trunk and start rolling the wheel forward by extending your arms.', 'Start at a pace that lets the feet and arms move in sync.', 'Move at a repeatable pace, keeping the motion smooth and your breathing steady.', 'Keep the pattern repeatable as speed increases.', 'Keep the rhythm for the planned interval, slowing if your form starts to slip.']::text[]),
('Concentration Curl (Band)', 'biceps', array['forearms']::text[], 'band', 'weight_reps', 'kmVVAfu', array['Take a seat on a bench or chair with your legs spread apart and your feet planted.', 'Keep one end of the band in your hand and step on the other end with your foot on the same side.', 'Set the shoulders and upper arms before bending the elbows.', 'Bend your elbows to bring the weight toward your shoulders without swinging your torso.', 'Control the band on the way back instead of letting it snap you into position.', 'Lower until the elbows are nearly straight, keeping the upper arms still.']::text[]),
('Seated Triceps Extension (Dumbbell)', 'triceps', array['shoulders']::text[], 'dumbbell', 'weight_reps', 'kont8Ut', array['Take a seat on a bench with your back straight and feet planted.', 'Take a dumbbell with both hands and extend your arms straight up overhead.', 'Set the upper arms in place before extending the elbows.', 'Keep the upper arms steady and extend through the elbows to move the weight.', 'Keep the upper arms steady while the forearms travel.', 'Bend the elbows slowly to return to the start of the next rep.']::text[]),
('Waiter Biceps Curl (Dumbbell)', 'biceps', array['forearms', 'shoulders']::text[], 'dumbbell', 'weight_reps', 'KOpzGBL', array['Stand tall with a dumbbell in each hand, palms facing forward.', 'Keep the upper arms close to your body and your elbows tucked in.', 'Set the shoulders and upper arms before bending the elbows.', 'Bend your elbows to bring the weight toward your shoulders without swinging your torso.', 'Keep the torso quiet and let the elbow bend lift the weight.', 'Lower until the elbows are nearly straight, keeping the upper arms still.']::text[]),
('Standing Hip Extension (Cable)', 'glutes', array['hamstrings', 'quads']::text[], 'cable', 'weight_reps', 'Kpajagk', array['Connect a cable to a low pulley and stand turned away from the machine.', 'Set the cable around your ankle and stand with your feet about shoulder width.', 'Plant the feet and keep the ribs from flaring as the hips prepare to rise.', 'Press through the feet and lift your hips until your torso and thighs line up.', 'Stop when the hips line up with the torso; do not arch higher through the lower back.', 'Lower the hips steadily and keep the feet planted for the next lift.']::text[]),
('Exercise Ball Dip', 'triceps', array['chest', 'shoulders']::text[], 'bodyweight', 'bodyweight_reps', 'kprile3', array['Take a seat on the stability ball with your feet planted and your knees bent at a 90-degree angle.', 'Set your hands on the ball beside your hips, fingers pointing forward.', 'Set the shoulders down and keep the elbows pointed mostly behind you.', 'Bend the elbows to lower between the supports; stop at a comfortable shoulder depth.', 'Keep the ball steady and use the feet to manage your balance.', 'Press through the hands to rise, then reset the shoulders before another rep.']::text[]),
('Reverse-Grip Row (Dumbbell)', 'back', array['biceps', 'forearms']::text[], 'dumbbell', 'weight_reps', 'KQfySvS', array['Stand and set your feet about shoulder width and knees soft.', 'Take a dumbbell in each hand with palms facing down, palms facing your body.', 'Set the torso and allow the arms to reach forward without rounding excessively.', 'Draw your elbows back and bring the handle or weight toward your torso.', 'Keep the palms in the chosen grip without bending the wrists back.', 'Reach the arms forward again without letting the torso lurch.']::text[]),
('Reverse Hyperextension (Machine)', 'glutes', array['hamstrings', 'back']::text[], 'machine', 'weight_reps', 'Krmb3cB', array['Set the leverage machine to fit your body and secure your feet in the foot pads.', 'Position yourself face down on the machine with your upper body hanging off the edge and your hips resting on the pad.', 'Secure the hips and feet on the support before lifting.', 'Raise your torso or legs until they line up with your body, without arching sharply at the lower back.', 'Finish in a straight body line, before the lower back overarches.', 'Ease back to the start before repeating.']::text[]),
('Seated Overhead Press (Barbell)', 'shoulders', array['triceps', 'back']::text[], 'barbell', 'weight_reps', 'kTbSH9h', array['Take a seat on a bench with your back straight and feet planted.', 'Take hold of the barbell with palms facing down, just beyond shoulder width.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Keep the wrists stacked and use a shoulder path that feels natural.', 'Lower the weight to its starting height under control before pressing again.']::text[]),
('Plyo Push-Up (Kettlebell)', 'chest', array['triceps', 'shoulders', 'core']::text[], 'kettlebell', 'weight_reps', 'ktf3nvW', array['Begin in a high plank position with your hands on the kettlebells, about shoulder width.', 'Lower your chest toward the ground, keeping your elbows close to your body.', 'Brace the abdomen and glutes so the shoulders, hips and ankles move together.', 'Bend your elbows to lower your chest while keeping your body in one line.', 'Keep the head in line with the spine as the elbows bend.', 'Press back to straight arms, keeping the body line intact.']::text[]),
('Standing Wheel Rollout', 'core', array['back', 'shoulders']::text[], 'bodyweight', 'bodyweight_reps', 'KtRomty', array['Begin by standing tall with your feet about shoulder width and the wheel roller in front of you.', 'Bend at your waist and With control roll the wheel forward, with your spine steady and your core engaged.', 'Tighten the abdomen and keep the pelvis tucked before the arms reach away.', 'Reach the arms away while keeping your ribs and pelvis aligned; stop before the lower back sags.', 'Stop reaching when the lower back starts to sag.', 'Pull back to the start through your shoulders and abdominals, keeping the same body line.']::text[]),
('Straight-Leg Deadlift (Band)', 'back', array['hamstrings', 'glutes']::text[], 'band', 'weight_reps', 'KUaoUV8', array['Stand and set your feet about shoulder width and place the band around your feet.', 'Take hold of the band with both hands, palms facing your body, and keep your arms straight.', 'Unlock the knees and brace the abdomen before moving the hips back.', 'Send your hips back with a soft knee bend, lowering the load close to your legs until the hamstrings stretch.', 'Control the band on the way back instead of letting it snap you into position.', 'Drive the hips forward to stand tall without leaning back at the top.']::text[]),
('Lying Supine Curl (Dumbbell)', 'biceps', array['forearms']::text[], 'dumbbell', 'weight_reps', 'KUaZst7', array['Settle onto a bench with a dumbbell in each hand, palms facing up and arms straight.', 'With your upper arms stationary, exhale and curl the weights while contracting your biceps.', 'Set the shoulders and upper arms before bending the elbows.', 'Bend your elbows to bring the weight toward your shoulders without swinging your torso.', 'Keep the torso quiet and let the elbow bend lift the weight.', 'Lower until the elbows are nearly straight, keeping the upper arms still.']::text[]),
('Stiff Leg Deadlift (Band)', 'glutes', array['hamstrings', 'back']::text[], 'band', 'weight_reps', 'kuMiR2T', array['Stand and set your feet about shoulder width and place the band around your ankles.', 'Take hold of the band with both hands ahead of your thighs, palms facing your body.', 'Unlock the knees and brace the abdomen before moving the hips back.', 'Push the hips back while keeping the load close and the spine steady.', 'Control the band on the way back instead of letting it snap you into position.', 'Drive the hips forward to stand tall without leaning back at the top.']::text[]),
('Single-Arm Kettlebell Overhead Press', 'shoulders', array['triceps', 'forearms']::text[], 'kettlebell', 'weight_reps', 'kuXhl0o', array['Stand and set your feet about shoulder width, holding a kettlebell in one hand.', 'Bend your knees slightly and hinge forward at the hips, with your spine steady.', 'Brace the torso and align the wrists with the forearms.', 'Bring the kettlebell to the rack position, then press it overhead with the wrist stacked above the shoulder.', 'Keep both shoulders level and resist turning toward the working arm.', 'Lower the weight to its starting height under control before pressing again; switch sides when the set calls for it.']::text[]),
('Kneeling Triceps Extension (Cable)', 'triceps', array['shoulders']::text[], 'cable', 'weight_reps', 'KWdF2JI', array['Connect a rope handle to a high pulley and kneel down facing the cable machine.', 'Hold the rope with a neutral grip (palms facing each other) and bring your hands to the sides of your head.', 'Set the upper arms in place before extending the elbows.', 'Keep the upper arms steady and extend through the elbows to move the weight.', 'Keep the upper arms steady while the forearms travel.', 'Bend the elbows slowly to return to the start of the next rep.']::text[]),
('Lying Single-Arm Rear Lateral Raise (Dumbbell)', 'shoulders', array['traps', 'back']::text[], 'dumbbell', 'weight_reps', 'KwFGiEP', array['Position yourself face down on a flat bench with a dumbbell in one hand, hanging toward the floor.', 'Keep the arm straight and lift the dumbbell out to the side, away from your body.', 'Start with a manageable load and a small bend in the elbows.', 'Raise the arms out to the sides to about shoulder height without leaning or shrugging.', 'Keep both shoulders level and resist turning toward the working arm.', 'Lower the arms slowly to your sides without swinging the weight; switch sides when the set calls for it.']::text[]),
('Bent-Over Row with V-Bar (Machine)', 'back', array['biceps', 'forearms']::text[], 'machine', 'weight_reps', 'KWyEjtI', array['Fit the seat to your body, then settle into the machine.', 'Hold the v-bar with palms facing down, with your spine steady and your knees soft.', 'Set the torso and allow the arms to reach forward without rounding excessively.', 'Draw your elbows back and bring the handle or weight toward your torso.', 'Bring the elbows back without jerking the torso.', 'Reach the arms forward again without letting the torso lurch.']::text[]),
('Zottman Curl (Dumbbell)', 'biceps', array['forearms']::text[], 'dumbbell', 'weight_reps', 'kXaIn5A', array['Stand tall with a dumbbell in each hand, palms facing your body.', 'Hold your elbows near your torso and rotate your palms to face forward.', 'Set the shoulders and upper arms before bending the elbows.', 'Curl palms-up, turn the palms down at the top, and lower with that overhand grip.', 'Keep the torso quiet and let the elbow bend lift the weight.', 'Lower until the elbows are nearly straight, keeping the upper arms still.']::text[]),
('Step-Up (Barbell)', 'glutes', array['quads', 'hamstrings', 'calves']::text[], 'barbell', 'weight_reps', 'Kxquu2E', array['Take your place in front of a bench or step with a barbell resting on your upper back.', 'Set one foot on the bench or step, ensuring your entire foot is in contact with the surface.', 'Put the lead foot fully on the platform before shifting your weight onto it.', 'Step onto the platform and drive through the lead foot to stand tall on it.', 'Keep the front foot planted and avoid collapsing inward at the knee.', 'Push through the lead foot to return to the start, then change legs as planned.']::text[]),
('Seated Inner Biceps Curl (Dumbbell)', 'biceps', array['forearms']::text[], 'dumbbell', 'weight_reps', 'KXyoEtA', array['Plant both feet while seated on a bench; hold a dumbbell in each hand, palms facing up.', 'Set your upper arms on your thighs, letting the dumbbells to hang down.', 'Set the shoulders and upper arms before bending the elbows.', 'Bend your elbows to bring the weight toward your shoulders without swinging your torso.', 'Keep the torso quiet and let the elbow bend lift the weight.', 'Lower until the elbows are nearly straight, keeping the upper arms still.']::text[]),
('Reverse-Grip Lateral Pulldown (Machine)', 'back', array['biceps', 'shoulders']::text[], 'machine', 'weight_reps', 'ky8FLU8', array['Fit the seat to your body, then settle into the machine.', 'Hold the handles with palms facing down, just beyond shoulder width.', 'Sit tall and set the shoulders before drawing the handle down.', 'Pull the handle down by driving your elbows toward your ribs; keep your torso steady.', 'Keep the palms in the chosen grip without bending the wrists back.', 'Let the handle rise steadily until the arms are long, then reset the shoulders.']::text[]),
('Standing Wide Military Press (Barbell)', 'shoulders', array['triceps', 'back']::text[], 'barbell', 'weight_reps', 'Kyd9Rz5', array['Stand and set your feet about shoulder width and hold the barbell with palms facing down, slightly wider than shoulder-width.', 'Before moving, lift the barbell to shoulder height, keeping your elbows slightly in front of the bar.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Keep the wrists stacked and use a shoulder path that feels natural.', 'Lower the weight to its starting height under control before pressing again.']::text[]),
('Incline Triceps Extension (EZ Bar)', 'triceps', array['shoulders']::text[], 'barbell', 'weight_reps', 'KyLtiLT', array['Angle the bench to roughly 45 degrees.', 'Take a seat on the bench with your back against the pad and hold the ez barbell with palms facing down.', 'Set the upper arms in place before extending the elbows.', 'Keep the upper arms steady and extend through the elbows to move the weight.', 'Keep the upper arms steady while the forearms travel.', 'Bend the elbows slowly to return to the start of the next rep.']::text[]),
('Standing Crunch (Band)', 'core', '{}'::text[], 'band', 'weight_reps', 'Kzg30R7', array['Connect the band to a sturdy anchor point at waist height.', 'Face the away from the anchor point from a stable stance with feet about shoulder width.', 'Set the pelvis and keep the neck relaxed before curling upward.', 'Curl your rib cage toward your pelvis, letting the abdominals move the torso.', 'Control the band on the way back instead of letting it snap you into position.', 'Lower the shoulders or torso with control before the next curl.']::text[]),
('Flexion Leg Sit Up (Straight Arm)', 'core', array['quads']::text[], 'bodyweight', 'bodyweight_reps', 'KZn52RC', array['Settle onto your back with your legs extended and arms straight above your head.', 'Engaging your abs, lift your upper body off the ground while simultaneously lifting your legs toward your chest.', 'Set the pelvis and keep the neck relaxed before curling upward.', 'Curl your rib cage toward your pelvis, letting the abdominals move the torso.', 'Leave a little space between the chin and chest; keep the movement in the torso.', 'Lower the shoulders or torso with control before the next curl.']::text[]),
('Push-Up Close-Grip Off Dumbbell', 'triceps', array['chest', 'shoulders']::text[], 'dumbbell', 'weight_reps', 'KZXAtKQ', array['Begin in a push-up position with your hands placed close together, directly under your shoulders.', 'Take a dumbbell in each hand, resting them on the ground.', 'Brace the abdomen and glutes so the shoulders, hips and ankles move together.', 'Bend your elbows to lower your chest while keeping your body in one line.', 'Keep the head in line with the spine as the elbows bend.', 'Press back to straight arms, keeping the body line intact.']::text[]),
('Lying Extension (Across Face) (Dumbbell)', 'triceps', array['shoulders']::text[], 'dumbbell', 'weight_reps', 'L2V5Nan', array['Settle onto a bench with your feet planted and your head at the end of the bench.', 'Take a dumbbell with both hands and extend your arms straight up above your chest, palms facing each other.', 'Set the upper arms in place before extending the elbows.', 'Keep the upper arms steady and extend through the elbows to move the weight.', 'Keep the upper arms steady while the forearms travel.', 'Bend the elbows slowly to return to the start of the next rep.']::text[]),
('Figure 8 (Kettlebell)', 'core', array['shoulders', 'forearms']::text[], 'kettlebell', 'weight_reps', 'L4ay0PW', array['Stand and set your feet about shoulder width, holding a kettlebell in one hand.', 'Bend your knees slightly and hinge forward at the hips, with your spine steady.', 'Set the pelvis and make the turn through the rib cage.', 'Turn through the torso while the hips and lower body stay as steady as the setup allows.', 'Keep the turn smooth instead of throwing the arms across the body.', 'Return through center before turning to the other side.']::text[]),
('Seated Twist (Band)', 'core', '{}'::text[], 'band', 'weight_reps', 'L68dTQj', array['Take a seat on the ground with your legs extended in front of you and your back straight.', 'Loop the band around your waist and hold the ends with both hands.', 'Set the pelvis and make the turn through the rib cage.', 'Turn through the torso while the hips and lower body stay as steady as the setup allows.', 'Control the band on the way back instead of letting it snap you into position.', 'Return through center before turning to the other side.']::text[]),
('Standing Front Raise Above Head (Dumbbell)', 'shoulders', array['traps', 'biceps']::text[], 'dumbbell', 'weight_reps', 'laVRfDf', array['Stand and set your feet about shoulder width, holding a dumbbell in each hand with palms facing down.', 'Maintain straight arms and lift the dumbbells in front of you, raising them above your head.', 'Start with a manageable load and a small bend in the elbows.', 'Lift the arms forward to about shoulder height, keeping the ribs down and torso still.', 'Stop near shoulder height rather than shrugging to lift higher.', 'Lower the arms slowly to your sides without swinging the weight.']::text[]),
('Exercise Ball Prsingle-Leg Raise', 'back', array['core', 'glutes']::text[], 'bodyweight', 'bodyweight_reps', 'lCKm4Rs', array['Position yourself face down on a mat with your legs extended and your toes resting on top of the stability ball.', 'Set your hands on the ground, about shoulder width, and Brace your trunk muscles.', 'Brace the abdomen and keep the shoulders anchored to the support.', 'Lift your legs by bracing your trunk and moving at the hips rather than swinging.', 'Keep the pelvis level as the supporting leg does the work.', 'Lower the legs slowly without swinging or losing your trunk position; switch sides when the set calls for it.']::text[]),
('Incline Inner Biceps Curl (Dumbbell)', 'biceps', array['forearms']::text[], 'dumbbell', 'weight_reps', 'LCtQPn8', array['Take a seat on an incline bench with a dumbbell in each hand, palms facing each other.', 'Set your upper arms on the bench, letting your elbows to hang down and your palms to face forward.', 'Set the shoulders and upper arms before bending the elbows.', 'Bend your elbows to bring the weight toward your shoulders without swinging your torso.', 'Keep the torso quiet and let the elbow bend lift the weight.', 'Lower until the elbows are nearly straight, keeping the upper arms still.']::text[]),
('Standing Alternate Hammer Curl and Press (Dumbbell)', 'biceps', array['forearms', 'shoulders']::text[], 'dumbbell', 'weight_reps', 'LeaZOIz', array['Stand tall with a dumbbell in each hand, palms facing your body.', 'Hold your elbows near your torso and your back straight.', 'Set the shoulders and upper arms before bending the elbows.', 'Curl with palms facing each other and elbows near your sides; avoid rocking back.', 'Finish one side''s motion before the other side takes over.', 'Lower until the elbows are nearly straight, keeping the upper arms still; switch sides when the set calls for it.']::text[]),
('Push-Up (Wall)', 'chest', array['triceps', 'shoulders']::text[], 'bodyweight', 'bodyweight_reps', 'LEH9jxP', array['Face a wall, about arm''s length away.', 'Set your hands on the wall at shoulder height, just beyond shoulder width.', 'Brace the abdomen and glutes so the shoulders, hips and ankles move together.', 'Bend your elbows to lower your chest while keeping your body in one line.', 'Keep the head in line with the spine as the elbows bend.', 'Press back to straight arms, keeping the body line intact.']::text[]),
('Front Squat (Clean Grip) (Smith Machine)', 'glutes', array['quads', 'hamstrings', 'calves', 'core']::text[], 'machine', 'weight_reps', 'lFhb2Rw', array['Prepare the smith machine with the barbell at shoulder height.', 'Face the barbell from a stable stance with feet about shoulder width.', 'Brace before the pull and keep the load close to the body.', 'Drive through the legs and hips, then guide the weight to its receiving position.', 'Receive the load with the torso braced and feet stable.', 'Stand tall to finish, then lower the weight under control before the next rep.']::text[]),
('Straight Back Stiff Leg Deadlift (Band)', 'glutes', array['hamstrings', 'back']::text[], 'band', 'weight_reps', 'lHeUULr', array['Stand and set your feet about shoulder width and place the band around your upper legs.', 'Take hold of the band with both hands ahead of your thighs, palms facing your body.', 'Unlock the knees and brace the abdomen before moving the hips back.', 'Push the hips back while keeping the load close and the spine steady.', 'Control the band on the way back instead of letting it snap you into position.', 'Drive the hips forward to stand tall without leaning back at the top.']::text[]),
('Hang Clean (Kettlebell)', 'hamstrings', array['glutes', 'quads', 'calves']::text[], 'kettlebell', 'duration', 'LHWF7us', array['Stand and set your feet about shoulder width, holding a kettlebell ahead of your thighs.', 'Bend your knees slightly and hinge forward at the hips, with your spine steady.', 'Brace before the pull and keep the load close to the body.', 'Drive through the legs and hips, then guide the weight to its receiving position.', 'Receive the load with the torso braced and feet stable.', 'Stand tall to finish, then lower the weight under control before the next rep.']::text[]),
('Pullover Hip Extension on Exercise Ball (Dumbbell)', 'chest', array['triceps', 'shoulders', 'core']::text[], 'dumbbell', 'weight_reps', 'lI7easp', array['Take a seat on an exercise ball with your feet planted and the dumbbell resting on your thighs.', 'With control walk your feet forward, rolling the exercise ball down your back until your head, neck, and upper back are supported on the ball.', 'Set the ribs down and keep a small elbow bend before lowering the weight.', 'Lower the weight in an arc behind your head until you feel a comfortable shoulder stretch.', 'Keep the ball steady and use the feet to manage your balance.', 'Pull the weight back over the chest along the same arc, without lifting the ribs.']::text[]),
('Single-Arm Prone Hammer Curl (Dumbbell)', 'biceps', array['forearms']::text[], 'dumbbell', 'weight_reps', 'LIGZSTA', array['Position yourself face down on a flat bench with a dumbbell in one hand, palm facing your body and arm straight.', 'Keep your upper arm stationary and curl the dumbbell toward your shoulder, contracting your biceps.', 'Set the shoulders and upper arms before bending the elbows.', 'Curl with palms facing each other and elbows near your sides; avoid rocking back.', 'Keep both shoulders level and resist turning toward the working arm.', 'Lower until the elbows are nearly straight, keeping the upper arms still; switch sides when the set calls for it.']::text[]),
('Jump Squat', 'glutes', array['quads', 'hamstrings', 'calves']::text[], 'bodyweight', 'bodyweight_reps', 'LIlE5Tn', array['Stand and set your feet about shoulder width.', 'Before moving, lower your body into a squat position by bending your knees and pushing your hips back.', 'Brace the abdomen and spread pressure across the whole foot.', 'Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.', 'Drive upward with the chest and hips rising together; keep the knees from collapsing inward.', 'Stand fully, reset your footing and breathing, then begin the next descent.']::text[]),
('Lying Fly (Cable)', 'chest', array['shoulders', 'triceps']::text[], 'cable', 'weight_reps', 'lJJ7Yq8', array['Connect the handles to the cables and Lie back on the bench with your feet planted.', 'Take hold of the handles with your palms facing each other and your arms extended straight above your chest.', 'Keep a soft elbow bend and set the shoulders before moving the arms.', 'With a soft bend in the elbows, sweep your arms together in a wide arc.', 'Keep the elbow angle nearly unchanged through the arc.', 'Open the arms back along the same arc without dropping the load.']::text[]),
('Elbow Dips', 'triceps', array['chest', 'shoulders']::text[], 'bodyweight', 'bodyweight_reps', 'LkoAWAE', array['Take a seat on the edge of a bench or chair with your hands gripping the edge next to your hips.', 'Move your hips forward off the bench and straighten your legs, keeping your heels on the ground.', 'Set the shoulders down and keep the elbows pointed mostly behind you.', 'Bend the elbows to lower between the supports; stop at a comfortable shoulder depth.', 'Choose a depth that lets the shoulders stay comfortable.', 'Press through the hands to rise, then reset the shoulders before another rep.']::text[]),
('Incline Single-Arm Hammer Press (Dumbbell)', 'triceps', array['shoulders', 'chest']::text[], 'dumbbell', 'weight_reps', 'LL1UiTX', array['Take a seat on an incline bench with a dumbbell in one hand, resting on your thigh.', 'Recline on the bench and use your thigh to help raise the dumbbell to shoulder height.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Keep both shoulders level and resist turning toward the working arm.', 'Lower the weight to its starting height under control before pressing again; switch sides when the set calls for it.']::text[]),
('Incline Single-Arm Fly on Exercise Ball (Dumbbell)', 'chest', array['shoulders']::text[], 'dumbbell', 'weight_reps', 'LLNh6q5', array['Take a seat on an exercise ball with a dumbbell in one hand.', 'Step your feet forward and roll your body down until your head, neck, and upper back are supported on the ball.', 'Keep a soft elbow bend and set the shoulders before moving the arms.', 'With a soft bend in the elbows, sweep your arms together in a wide arc.', 'Keep both shoulders level and resist turning toward the working arm.', 'Open the arms back along the same arc without dropping the load; switch sides when the set calls for it.']::text[]),
('Donkey Calf Raise (Weighted)', 'calves', array['hamstrings', 'glutes']::text[], 'bodyweight', 'bodyweight_reps', 'LmaFNZS', array['Step onto a raised platform with your toes on the edge and your heels hanging off.', 'Use a stable object for support.', 'Let the ankles move freely while the rest of the body stays quiet.', 'Rise through the balls of your feet, lifting the heels as high as you can without rocking.', 'Pause at the top without rolling the ankles outward.', 'Lower the heels at a measured pace before rising again.']::text[]),
('Decline Close-Grip to Skull Press (Barbell)', 'triceps', array['chest', 'shoulders']::text[], 'barbell', 'weight_reps', 'LMGXZn8', array['Settle onto a decline bench with your head lower than your feet and hold a barbell with a close grip.', 'Lower the barbell toward your forehead by bending your elbows, With the upper arms still.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Keep the wrists stacked and use a shoulder path that feels natural.', 'Lower the weight to its starting height under control before pressing again.']::text[]),
('Rear Delt Raise (Barbell)', 'shoulders', array['traps', 'back']::text[], 'barbell', 'weight_reps', 'Ln9iTbU', array['Stand and set your feet about shoulder width and hold a barbell with palms facing down.', 'Bend your knees slightly and hinge forward at the hips, with your spine steady.', 'Start with a manageable load and a small bend in the elbows.', 'Lift the arms out and back with soft elbows, letting the rear shoulders do the work.', 'Stop near shoulder height rather than shrugging to lift higher.', 'Lower the arms slowly to your sides without swinging the weight.']::text[]),
('Single Leg Platform Slide', 'hamstrings', array['glutes', 'quads']::text[], 'bodyweight', 'bodyweight_reps', 'LNE3wfo', array['Begin by standing with one foot on a platform or slide board.', 'Before moving, bend your knee slightly and slide the foot on the platform backward, extending your leg.', 'Set your stance wide enough to balance before bending either knee.', 'Step into the movement and bend both knees, keeping your front foot planted.', 'Keep the front foot planted and avoid collapsing inward at the knee.', 'Push through the lead foot to return to the start, then change legs as planned.']::text[]),
('Chest Dip on Straight Bar', 'chest', array['triceps', 'shoulders']::text[], 'bodyweight', 'bodyweight_reps', 'LQFOrMn', array['Take hold of the parallel bars with your palms facing down and your arms straight.', 'Before moving, bend your knees and cross your ankles.', 'Set the shoulders down and keep the elbows pointed mostly behind you.', 'Bend the elbows to lower between the supports; stop at a comfortable shoulder depth.', 'Choose a depth that lets the shoulders stay comfortable.', 'Press through the hands to rise, then reset the shoulders before another rep.']::text[]),
('Wrist Curl (Cable)', 'forearms', array['biceps']::text[], 'cable', 'weight_reps', 'LrV4s90', array['Connect a straight bar to a low pulley cable machine.', 'Face the machine from a stable stance with feet about shoulder width.', 'Keep the elbows relaxed so the small muscles of the hand or forearm take the load.', 'Move through the wrists or fingers while the forearms stay supported and still.', 'Use a small, smooth range without swinging the elbows.', 'Ease back to the start without letting the load fall from your hands.']::text[]),
('Reverse Calf Raises (Smith Machine)', 'calves', array['hamstrings']::text[], 'machine', 'weight_reps', 'Lsqrgh4', array['Set the smith machine bar to a height just below your shoulders.', 'Face the bar with your feet about hip width and toes pointing forward.', 'Let the ankles move freely while the rest of the body stays quiet.', 'Rise through the balls of your feet, lifting the heels as high as you can without rocking.', 'Pause at the top without rolling the ankles outward.', 'Lower the heels at a measured pace before rising again.']::text[]),
('Zercher Squat (Barbell)', 'glutes', array['quads', 'hamstrings', 'calves', 'core']::text[], 'barbell', 'weight_reps', 'LSTChY9', array['Stand and set your feet about shoulder width and toes slightly turned out.', 'Take hold of the barbell in the crooks of your elbows, with your hands gripping the bar for stability.', 'Brace the abdomen and spread pressure across the whole foot.', 'Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.', 'Drive upward with the chest and hips rising together; keep the knees from collapsing inward.', 'Stand fully, reset your footing and breathing, then begin the next descent.']::text[]),
('Reverse Wrist Curl (Barbell)', 'forearms', array['biceps']::text[], 'barbell', 'weight_reps', 'LsZkfU6', array['Plant both feet while seated on a bench; hold a barbell with palms facing down.', 'Set your forearms on your thighs, letting your wrists hang off the edge.', 'Keep the elbows relaxed so the small muscles of the hand or forearm take the load.', 'Move through the wrists or fingers while the forearms stay supported and still.', 'Use a small, smooth range without swinging the elbows.', 'Ease back to the start without letting the load fall from your hands.']::text[]),
('Fly on Exercise Ball (Dumbbell)', 'chest', array['shoulders', 'triceps']::text[], 'dumbbell', 'weight_reps', 'Lt3iWnf', array['Take a seat on an exercise ball and hold a dumbbell in each hand.', 'Step your feet forward and roll your body down until your head, neck, and upper back are supported by the ball.', 'Keep a soft elbow bend and set the shoulders before moving the arms.', 'With a soft bend in the elbows, sweep your arms together in a wide arc.', 'Keep the ball steady and use the feet to manage your balance.', 'Open the arms back along the same arc without dropping the load.']::text[]),
('Lean Planche', 'core', array['shoulders', 'chest', 'triceps']::text[], 'bodyweight', 'bodyweight_reps', 'LYJodFS', array['Begin in a push-up position with your hands about shoulder width and your body straight.', 'Brace your trunk and With control shift your weight forward, bringing your shoulders past your hands.', 'Brace the abdomen and find a position you can maintain without holding your breath.', 'Brace your midsection and hold the position while breathing normally.', 'Keep breathing steadily as you maintain the same body line.', 'Keep the shape for the planned time, then come out of it with control.']::text[]),
('Seated Reverse-Grip Concentration Curl (Dumbbell)', 'biceps', array['forearms']::text[], 'dumbbell', 'weight_reps', 'lyKCLmK', array['Sit with both feet grounded and hold one dumbbell with the palm facing down.', 'Set your elbow on the inside of your thigh, just above the knee.', 'Set the shoulders and upper arms before bending the elbows.', 'Curl the dumbbell with the palm facing down while the upper arm stays braced against the inner thigh.', 'Keep the palms in the chosen grip without bending the wrists back.', 'Lower until the elbows are nearly straight, keeping the upper arms still.']::text[]),
('All Fours Squad Stretch', 'quads', array['hamstrings', 'glutes']::text[], 'bodyweight', 'duration', 'LzX8YEz', array['Get onto hands and knees with your hands directly under your shoulders and your knees directly under your hips.', 'Reach one leg straight back, keeping your knee bent and your foot flexed.', 'Settle into the starting position and take an easy breath before moving deeper.', 'Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.', 'Stay in a mild stretch rather than pulling farther with momentum.', 'Hold the position with steady breathing, then release gently; repeat on the other side if needed.']::text[]),
('Calf Stretch with Hands Against Wall', 'calves', array['hamstrings']::text[], 'bodyweight', 'duration', 'm0tCHqc', array['Face a wall with your feet about hip width.', 'Set your hands against the wall at shoulder height.', 'Settle into the starting position and take an easy breath before moving deeper.', 'Ease the heel down and shift until the calf stretches; keep the foot pointed ahead.', 'Stay in a mild stretch rather than pulling farther with momentum.', 'Hold the position with steady breathing, then release gently; repeat on the other side if needed.']::text[]),
('Lying Supination (Dumbbell)', 'forearms', array['biceps', 'shoulders']::text[], 'dumbbell', 'weight_reps', 'M2Pm3zj', array['Settle onto a bench with your feet planted.', 'Take a dumbbell in each hand with your palms facing up and your arms straight.', 'Keep the elbows relaxed so the small muscles of the hand or forearm take the load.', 'Move through the wrists or fingers while the forearms stay supported and still.', 'Use a small, smooth range without swinging the elbows.', 'Ease back to the start without letting the load fall from your hands.']::text[]),
('Standing Curl (Weighted)', 'biceps', array['forearms']::text[], 'bodyweight', 'bodyweight_reps', 'M5Y7GPg', array['Stand and set your feet about shoulder width and hold a dumbbell in each hand, palms facing forward.', 'Hold your elbows near your torso and Breathe out and curl the weights up to shoulder level.', 'Set the shoulders and upper arms before bending the elbows.', 'Bend your elbows to bring the weight toward your shoulders without swinging your torso.', 'Keep the torso quiet and let the elbow bend lift the weight.', 'Lower until the elbows are nearly straight, keeping the upper arms still.']::text[]),
('Double Snatch (Kettlebell)', 'shoulders', array['traps', 'forearms', 'core']::text[], 'kettlebell', 'weight_reps', 'M74kdvm', array['Stand and set your feet about shoulder width, holding a kettlebell in each hand at arm''s length ahead of your thighs.', 'Before moving, bend your knees slightly and hinge forward at the hips, keeping your back flat and chest up.', 'Brace before the pull and keep the load close to the body.', 'Drive through the legs and hips, then guide the weight to its receiving position.', 'Receive the load with the torso braced and feet stable.', 'Stand tall to finish, then lower the weight under control before the next rep.']::text[]),
('Close-Grip Preacher Curl (EZ Bar)', 'biceps', array['forearms']::text[], 'barbell', 'weight_reps', 'M8IolhQ', array['Take a seat on a preacher curl bench and place your upper arms on the pad, gripping the ez barbell with palms facing up.', 'Set your triceps on the pad and straighten your arms, with your spine steady.', 'Set the working upper arm against the preacher pad and leave the elbow free to bend.', 'Curl the weight while your upper arms stay in contact with the pad.', 'Keep the torso quiet and let the elbow bend lift the weight.', 'Lower until the elbows are nearly straight, keeping the upper arms still.']::text[]),
('Assisted Pull-Up (Machine)', 'back', array['biceps', 'forearms']::text[], 'machine', 'weight_reps', 'MaMuGH6', array['Set the leverage machine to your desired resistance level.', 'Step onto the foot platform and grip the handles with palms facing down, just beyond shoulder width.', 'Begin from a controlled hang with the shoulders active rather than slack.', 'Pull your elbows down and bring your upper chest toward the bar without kicking your legs.', 'Avoid swinging the legs to clear the bar.', 'Lower to long arms without dropping suddenly from the top.']::text[]),
('Jackknife Sit-Up', 'core', '{}'::text[], 'bodyweight', 'bodyweight_reps', 'mbkgB44', array['Settle onto your back with your legs extended and your arms overhead.', 'Brace your trunk and lift your legs and upper body simultaneously, reaching your hands toward your toes.', 'Set the pelvis and keep the neck relaxed before curling upward.', 'Curl your rib cage toward your pelvis, letting the abdominals move the torso.', 'Leave a little space between the chin and chest; keep the movement in the torso.', 'Lower the shoulders or torso with control before the next curl.']::text[]),
('Muscle Up (On Bar) (Weighted)', 'back', array['biceps', 'triceps', 'shoulders', 'forearms']::text[], 'bodyweight', 'bodyweight_reps', 'MCkqdKE', array['Begin by hanging from a pull-up bar with your palms turned away from you and your hands just beyond shoulder width.', 'Brace your trunk and pull your shoulder blades down and back.', 'Begin from a controlled hang with the shoulders active rather than slack.', 'Pull your elbows down and bring your upper chest toward the bar without kicking your legs.', 'Avoid swinging the legs to clear the bar.', 'Lower to long arms without dropping suddenly from the top.']::text[]),
('Crunch (On Stability Ball)', 'core', '{}'::text[], 'bodyweight', 'bodyweight_reps', 'MCUhf1F', array['Take a seat on the stability ball with your feet planted and your knees bent at a 90-degree angle.', 'Recline on the ball until your lower back is supported and your upper body is parallel to the floor.', 'Set the pelvis and keep the neck relaxed before curling upward.', 'Curl your rib cage toward your pelvis, letting the abdominals move the torso.', 'Keep the ball steady and use the feet to manage your balance.', 'Lower the shoulders or torso with control before the next curl.']::text[]),
('Bench Pull-Ups', 'back', array['biceps', 'forearms']::text[], 'bodyweight', 'bodyweight_reps', 'mExgrF9', array['Set yourself under a bar or a sturdy horizontal surface that is at chest height.', 'Take hold of the bar or surface with palms facing down, just beyond shoulder width.', 'Begin from a controlled hang with the shoulders active rather than slack.', 'Pull your elbows down and bring your upper chest toward the bar without kicking your legs.', 'Avoid swinging the legs to clear the bar.', 'Lower to long arms without dropping suddenly from the top.']::text[]),
