('Bicycle Crunch (Band)', 'core', '{}'::text[], 'band', 'weight_reps', 'tZkGYZ9', array['Settle onto your back with your hands behind your head and your knees bent.', 'Lift your feet off the ground and bring your right knee toward your chest while simultaneously twisting your torso to bring your left elbow toward your right knee.', 'Set the pelvis and keep the neck relaxed before curling upward.', 'Bring one elbow toward the opposite knee as the other leg extends; switch sides in a steady rhythm.', 'Control the band on the way back instead of letting it snap you into position.', 'Lower the shoulders or torso with control before the next curl.']::text[]),
('Double Jerk (Kettlebell)', 'shoulders', array['triceps', 'core']::text[], 'kettlebell', 'weight_reps', 'tznL2Ad', array['Stand and set your feet about shoulder width, holding a kettlebell in each hand at shoulder height.', 'Bend your knees slightly and Brace your trunk.', 'Brace before the pull and keep the load close to the body.', 'Drive through the legs and hips, then guide the weight to its receiving position.', 'Receive the load with the torso braced and feet stable.', 'Stand tall to finish, then lower the weight under control before the next rep.']::text[]),
('Low Glute Bridge on Floor', 'glutes', array['hamstrings', 'core']::text[], 'bodyweight', 'bodyweight_reps', 'u0cNiij', array['Settle onto your back with your knees bent and feet planted.', 'Set your arms by your sides, palms facing down.', 'Plant the feet and keep the ribs from flaring as the hips prepare to rise.', 'Press through the feet and lift your hips until your torso and thighs line up.', 'Stop when the hips line up with the torso; do not arch higher through the lower back.', 'Lower the hips steadily and keep the feet planted for the next lift.']::text[]),
('Upright Shoulder External Rotation (Dumbbell)', 'shoulders', array['traps']::text[], 'dumbbell', 'weight_reps', 'u1iHcoD', array['Stand and set your feet about shoulder width and hold a dumbbell in each hand with your palms facing your body.', 'Raise your arms out to the sides until they are parallel to the ground, keeping your elbows soft.', 'Set the pelvis and make the turn through the rib cage.', 'Turn through the torso while the hips and lower body stay as steady as the setup allows.', 'Keep the turn smooth instead of throwing the arms across the body.', 'Return through center before turning to the other side.']::text[]),
('Bench Hip Extension', 'glutes', array['hamstrings']::text[], 'bodyweight', 'bodyweight_reps', 'u27Kcdz', array['Take a seat on a bench with your back against the bench and your feet planted.', 'Set your hands on the bench for support.', 'Plant the feet and keep the ribs from flaring as the hips prepare to rise.', 'Press through the feet and lift your hips until your torso and thighs line up.', 'Stop when the hips line up with the torso; do not arch higher through the lower back.', 'Lower the hips steadily and keep the feet planted for the next lift.']::text[]),
('Front Raise (Cable)', 'shoulders', array['triceps', 'forearms']::text[], 'cable', 'weight_reps', 'u2X71Np', array['Stand and set your feet about shoulder width and Hold the cable handle with palms facing down.', 'Keep your spine in a comfortable neutral position and your core engaged.', 'Start with a manageable load and a small bend in the elbows.', 'Lift the arms forward to about shoulder height, keeping the ribs down and torso still.', 'Stop near shoulder height rather than shrugging to lift higher.', 'Lower the arms slowly to your sides without swinging the weight.']::text[]),
('Rope Lying on Floor Triceps Extension (Cable)', 'triceps', array['shoulders']::text[], 'cable', 'weight_reps', 'U3ffHlY', array['Fit the rope handle to the cable''s lowest setting.', 'Settle onto the floor facing up, with your head toward the cable machine.', 'Set the upper arms in place before extending the elbows.', 'Keep the upper arms steady and extend through the elbows to move the weight.', 'Keep the upper arms steady while the forearms travel.', 'Bend the elbows slowly to return to the start of the next rep.']::text[]),
('Two-Arm Row (Kettlebell)', 'back', array['biceps', 'forearms']::text[], 'kettlebell', 'weight_reps', 'u3UuCZu', array['Stand and set your feet about shoulder width, knees soft, and hold a kettlebell in each hand with your palms facing your body.', 'Bend forward at the hips, with your spine steady and your core engaged.', 'Set the torso and allow the arms to reach forward without rounding excessively.', 'Draw your elbows back and bring the handle or weight toward your torso.', 'Bring the elbows back without jerking the torso.', 'Reach the arms forward again without letting the torso lurch.']::text[]),
('Twisting Overhead Press (Band)', 'shoulders', array['triceps', 'back']::text[], 'band', 'weight_reps', 'u4bAmKp', array['Stand and set your feet about shoulder width and place the band under your feet.', 'Take hold of the band handles at shoulder height with your palms facing forward.', 'Brace the torso and align the wrists with the forearms.', 'Press the weights up while turning the palms inward; reverse the turn as you lower.', 'Control the band on the way back instead of letting it snap you into position.', 'Lower the weight to its starting height under control before pressing again.']::text[]),
('Donkey Calf Raise', 'calves', array['hamstrings', 'glutes']::text[], 'bodyweight', 'bodyweight_reps', 'u5ESqzH', array['Stand and set your toes on an elevated surface, such as a step or block.', 'Set your hands on a stable support, such as a wall or railing, for balance.', 'Let the ankles move freely while the rest of the body stays quiet.', 'Rise through the balls of your feet, lifting the heels as high as you can without rocking.', 'Pause at the top without rolling the ankles outward.', 'Lower the heels at a measured pace before rising again.']::text[]),
('Single-Arm Pulldown (Cable)', 'back', array['biceps', 'forearms']::text[], 'cable', 'weight_reps', 'U5INZY6', array['Connect a single handle to a high pulley cable machine.', 'Face the machine from a stable stance with feet about shoulder width.', 'Sit tall and set the shoulders before drawing the handle down.', 'Pull the handle down by driving your elbows toward your ribs; keep your torso steady.', 'Keep both shoulders level and resist turning toward the working arm.', 'Let the handle rise steadily until the arms are long, then reset the shoulders; switch sides when the set calls for it.']::text[]),
('Body-Up', 'triceps', array['chest', 'shoulders']::text[], 'bodyweight', 'bodyweight_reps', 'U6G2gk9', array['Begin by placing your hands on a raised surface, such as a bench or parallel bars, with your palms facing down and fingers pointing forward.', 'Reach your legs out in front of you, keeping your heels on the ground and your body straight.', 'Set the shoulders down and keep the elbows pointed mostly behind you.', 'Bend the elbows to lower between the supports; stop at a comfortable shoulder depth.', 'Choose a depth that lets the shoulders stay comfortable.', 'Press through the hands to rise, then reset the shoulders before another rep.']::text[]),
('Incline Two-Arm Extension (Dumbbell)', 'triceps', array['shoulders']::text[], 'dumbbell', 'weight_reps', 'U7D9Fx3', array['Take a seat on an incline bench with a dumbbell in each hand, resting on your thighs.', 'With control lie back on the bench, keeping the dumbbells close to your chest.', 'Set the upper arms in place before extending the elbows.', 'Keep the upper arms steady and extend through the elbows to move the weight.', 'Keep the upper arms steady while the forearms travel.', 'Bend the elbows slowly to return to the start of the next rep.']::text[]),
('Seesaw Press (Kettlebell)', 'shoulders', array['triceps', 'core']::text[], 'kettlebell', 'weight_reps', 'UDm6cGl', array['Stand and set your feet about shoulder width, holding a kettlebell in each hand at shoulder height.', 'Before moving, press one kettlebell overhead while keeping the other kettlebell at shoulder height.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Keep the wrists stacked and use a shoulder path that feels natural.', 'Lower the weight to its starting height under control before pressing again.']::text[]),
('Seated Twist (Cable)', 'core', '{}'::text[], 'cable', 'weight_reps', 'UEjSrKI', array['Take a seat on a cable machine with your feet planted and your knees soft.', 'Take hold of the cable handle with both hands and extend your arms straight in front of you.', 'Set the pelvis and make the turn through the rib cage.', 'Turn through the torso while the hips and lower body stay as steady as the setup allows.', 'Keep the turn smooth instead of throwing the arms across the body.', 'Return through center before turning to the other side.']::text[]),
('Close-Grip Push-Up (Band)', 'triceps', array['chest', 'shoulders']::text[], 'band', 'weight_reps', 'ufaxB52', array['Set a band around your upper arms, just above the elbows.', 'Get into a push-up position with your hands directly under your shoulders and your body in a straight line from head to heels.', 'Brace the abdomen and glutes so the shoulders, hips and ankles move together.', 'Bend your elbows to lower your chest while keeping your body in one line.', 'Control the band on the way back instead of letting it snap you into position.', 'Press back to straight arms, keeping the body line intact.']::text[]),
('Deadlift (Smith Machine)', 'glutes', array['hamstrings', 'quads', 'back']::text[], 'machine', 'weight_reps', 'UfePqpx', array['Prepare the smith machine with the bar at hip height.', 'Stand and set your feet about shoulder width, toes pointing slightly outward.', 'Unlock the knees and brace the abdomen before moving the hips back.', 'Push the hips back while keeping the load close and the spine steady.', 'Keep the weight close to the legs and stop when the back would begin to round.', 'Drive the hips forward to stand tall without leaning back at the top.']::text[]),
('Rope Crossover Seated Row (Cable)', 'back', array['biceps', 'forearms']::text[], 'cable', 'weight_reps', 'UFGF6gk', array['Take a seat on the rowing machine with your feet flat on the footrests and your knees soft.', 'Hold the cable ropes with palms facing down, palms facing each other.', 'Keep a soft elbow bend and set the shoulders before moving the arms.', 'Bring the handles across the front of your chest in a broad arc, keeping a slight elbow bend.', 'Keep the elbow angle nearly unchanged through the arc.', 'Open the arms back along the same arc without dropping the load.']::text[]),
('Kneeling Jump Squat', 'glutes', array['quads', 'hamstrings', 'calves']::text[], 'barbell', 'weight_reps', 'UgDm3oy', array['Begin by kneeling on the ground with your feet about hip width and your toes pointing forward.', 'Take a barbell across your upper back, resting it on your shoulders.', 'Brace the abdomen and spread pressure across the whole foot.', 'Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.', 'Drive upward with the chest and hips rising together; keep the knees from collapsing inward.', 'Stand fully, reset your footing and breathing, then begin the next descent.']::text[]),
('Lying Windshield Wipers', 'core', '{}'::text[], 'bodyweight', 'bodyweight_reps', 'UGhRD1A', array['Settle onto your back with your legs extended and your arms by your sides.', 'Set your hands under your glutes for support.', 'Brace the abdomen and keep the shoulders anchored to the support.', 'Lift both legs, then lower them together toward one side without letting the shoulders roll off the floor.', 'Slow the legs before they pull the lower back out of position.', 'Bring the legs back through center, then lower them toward the other side with the same control.']::text[]),
('Swing (Kettlebell)', 'glutes', array['hamstrings', 'core']::text[], 'kettlebell', 'weight_reps', 'UHJlbu3', array['Stand and set your feet about shoulder width, toes pointed slightly outward.', 'Take hold of the kettlebell with both hands ahead of your body, arms extended.', 'Set the shoulders and let the weight move back between the legs as the hips hinge.', 'Hinge back, then drive the hips forward to send the weight up; let the arms guide it.', 'Let the hips, not the shoulders, provide the power.', 'Let the weight fall naturally and hinge again for the next swing.']::text[]),
('Reverse Bench Press (Dumbbell)', 'chest', array['triceps', 'shoulders']::text[], 'dumbbell', 'weight_reps', 'UIbGx6H', array['Settle onto a bench with your feet planted and your knees bent.', 'Take a dumbbell in each hand with palms facing down, palms facing toward your feet.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Keep the wrists stacked and use a shoulder path that feels natural.', 'Lower the weight to its starting height under control before pressing again.']::text[]),
('Standing Neutral-Grip Press (Dumbbell)', 'shoulders', array['triceps', 'chest']::text[], 'dumbbell', 'weight_reps', 'UilDHSs', array['Stand and set your feet about shoulder width, holding a dumbbell in each hand at shoulder level with your palms facing inwards.', 'With your core engaged and your back straight, press the dumbbells upwards until your arms are straight overhead.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Keep the palms facing each other and the wrists straight.', 'Lower the weight to its starting height under control before pressing again.']::text[]),
('Seated Neutral Wrist Curl (Dumbbell)', 'biceps', array['forearms']::text[], 'dumbbell', 'weight_reps', 'uJmK7Z1', array['Plant both feet while seated on a bench; hold a dumbbell in each hand, palms facing each other.', 'Set your forearms on your thighs, letting the dumbbells to hang down.', 'Keep the elbows relaxed so the small muscles of the hand or forearm take the load.', 'Move through the wrists or fingers while the forearms stay supported and still.', 'Use a small, smooth range without swinging the elbows.', 'Ease back to the start without letting the load fall from your hands.']::text[]),
('Standing Up Straight Crossovers (Cable)', 'chest', array['shoulders', 'triceps']::text[], 'cable', 'weight_reps', 'UKWTJWR', array['Take your place in the middle of a cable machine with your feet about shoulder width.', 'Take hold of the handles of the cables with your palms facing down and your arms extended straight out to the sides.', 'Keep a soft elbow bend and set the shoulders before moving the arms.', 'Bring the handles across the front of your chest in a broad arc, keeping a slight elbow bend.', 'Keep the elbow angle nearly unchanged through the arc.', 'Open the arms back along the same arc without dropping the load.']::text[]),
('Single-Leg Squat (Barbell)', 'quads', array['glutes', 'hamstrings', 'calves']::text[], 'barbell', 'weight_reps', 'uKyN64F', array['Stand and set your feet about shoulder width and hold a barbell across your upper back.', 'Before moving, lift one foot off the ground and extend it forward, keeping it parallel to the ground.', 'Brace the abdomen and spread pressure across the whole foot.', 'Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.', 'Keep the pelvis level as the supporting leg does the work.', 'Stand fully, reset your footing and breathing, then begin the next descent; switch sides when the set calls for it.']::text[]),
('Leg Extension (Band)', 'quads', array['hamstrings']::text[], 'band', 'weight_reps', 'Ul5OFSV', array['Connect the resistance band to a sturdy anchor point and secure it around your ankle.', 'Face the anchor point from a stable stance with feet about shoulder width.', 'Set the pad just above the ankles and keep the thighs against the seat.', 'Straighten your knees to lift the pad, keeping your hips against the seat.', 'Control the band on the way back instead of letting it snap you into position.', 'Return along the same path at a controlled pace.']::text[]),
('Ankle Circles', 'calves', '{}'::text[], 'bodyweight', 'bodyweight_reps', 'uL9CsKm', array['Take a seat on the ground with your legs extended in front of you.', 'Before moving, lift one leg off the ground and rotate your ankle in a circular motion.', 'Relax the limb above the joint you are circling.', 'Circle the joint slowly in one direction, then reverse the circle without forcing the range.', 'Keep the rest of the limb still while the joint traces each circle.', 'Switch to the other side after completing both directions.']::text[]),
('Prone Incline Curl (Barbell)', 'biceps', array['forearms']::text[], 'barbell', 'weight_reps', 'Um8xUAc', array['Angle the bench to roughly 45 degrees.', 'Position yourself face down on the bench with your chest and stomach resting against it.', 'Set the shoulders and upper arms before bending the elbows.', 'Bend your elbows to bring the weight toward your shoulders without swinging your torso.', 'Keep the torso quiet and let the elbow bend lift the weight.', 'Lower until the elbows are nearly straight, keeping the upper arms still.']::text[]),
('Standing Kickback (Dumbbell)', 'triceps', array['shoulders']::text[], 'dumbbell', 'weight_reps', 'UmpPAAe', array['Stand and set your feet about shoulder width and hold a dumbbell in each hand.', 'Bend your knees slightly and hinge forward at the hips, with your spine steady.', 'Set the upper arms in place before extending the elbows.', 'Hold the upper arm beside your torso and straighten the elbow behind you.', 'Keep the upper arms steady while the forearms travel.', 'Bend the elbows slowly to return to the start of the next rep.']::text[]),
('Single-Arm Overhead Biceps Curl (Band)', 'biceps', array['forearms', 'shoulders']::text[], 'band', 'weight_reps', 'UNAB8ak', array['Stand and set your feet about shoulder width and place one end of the band under your foot.', 'Take hold of the other end of the band with your arm straight overhead, palm facing forward.', 'Set the shoulders and upper arms before bending the elbows.', 'Bend your elbows to bring the weight toward your shoulders without swinging your torso.', 'Keep both shoulders level and resist turning toward the working arm.', 'Lower until the elbows are nearly straight, keeping the upper arms still; switch sides when the set calls for it.']::text[]),
('Side Bend (Cable)', 'core', '{}'::text[], 'cable', 'weight_reps', 'UOphC6N', array['Stand and set your feet about shoulder width and Hold the cable handle with one hand.', 'Keep your spine in a comfortable neutral position and your core engaged.', 'Stand or sit tall with the pelvis facing forward.', 'Bend sideways through the waist without twisting or letting the hips shift.', 'Let the side of the trunk work; do not twist or shift the hips.', 'Bring the weight or body back to its starting position without rushing.']::text[]),
('Triceps Stretch', 'triceps', array['shoulders']::text[], 'bodyweight', 'duration', 'uOV3Itw', array['Either stand or sit upright with your back straight.', 'Reach one arm overhead, bending it at the elbow.', 'Settle into the starting position and take an easy breath before moving deeper.', 'Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.', 'Stay in a mild stretch rather than pulling farther with momentum.', 'Hold the position with steady breathing, then release gently; repeat on the other side if needed.']::text[]),
('Rear Decline Bridge', 'glutes', array['hamstrings', 'back']::text[], 'bodyweight', 'bodyweight_reps', 'UpAlold', array['Settle onto your back with your feet planted and your knees bent.', 'Set your arms by your sides with your palms facing down.', 'Plant the feet and keep the ribs from flaring as the hips prepare to rise.', 'Press through the feet and lift your hips until your torso and thighs line up.', 'Stop when the hips line up with the torso; do not arch higher through the lower back.', 'Lower the hips steadily and keep the feet planted for the next lift.']::text[]),
('L-Sit on Floor', 'core', '{}'::text[], 'bodyweight', 'bodyweight_reps', 'UpWmA5E', array['Take a seat on the floor with your legs extended in front of you.', 'Set your hands on the floor beside your hips, fingers pointing forward.', 'Brace the abdomen and find a position you can maintain without holding your breath.', 'Brace your midsection and hold the position while breathing normally.', 'Keep breathing steadily as you maintain the same body line.', 'Keep the shape for the planned time, then come out of it with control.']::text[]),
('Pull-In (On Stability Ball)', 'core', '{}'::text[], 'bodyweight', 'bodyweight_reps', 'UQr48Oi', array['Begin by sitting on the stability ball with your feet planted and your knees bent at a 90-degree angle.', 'Set your hands on the sides of the stability ball for support.', 'Set the pelvis and keep the neck relaxed before curling upward.', 'Curl your rib cage toward your pelvis, letting the abdominals move the torso.', 'Keep the ball steady and use the feet to manage your balance.', 'Lower the shoulders or torso with control before the next curl.']::text[]),
('Biceps Curl with Stork Stance (Dumbbell)', 'biceps', array['forearms']::text[], 'dumbbell', 'weight_reps', 'uSkDMYl', array['Stand and set your feet about shoulder width and hold a dumbbell in each hand, palms facing forward.', 'Reach one leg behind you, balancing on the toes of that foot.', 'Set the shoulders and upper arms before bending the elbows.', 'Bend your elbows to bring the weight toward your shoulders without swinging your torso.', 'Keep the torso quiet and let the elbow bend lift the weight.', 'Lower until the elbows are nearly straight, keeping the upper arms still.']::text[]),
('Scapular Pull-Up', 'traps', array['biceps', 'back', 'shoulders']::text[], 'bodyweight', 'bodyweight_reps', 'uTBt1HV', array['Begin by hanging from a pull-up bar with your palms turned away from you and your arms straight.', 'Draw back your shoulder blades by pulling them down and back.', 'Begin from a controlled hang with the shoulders active rather than slack.', 'Pull your elbows down and bring your upper chest toward the bar without kicking your legs.', 'Avoid swinging the legs to clear the bar.', 'Lower to long arms without dropping suddenly from the top.']::text[]),
('Side Wrist Pull Stretch', 'forearms', '{}'::text[], 'bodyweight', 'duration', 'UtmIqcI', array['Stand and set your feet about shoulder width and your arms extended in front of you.', 'Reach your right arm out to the side, parallel to the ground, with your palm facing down.', 'Settle into the starting position and take an easy breath before moving deeper.', 'Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.', 'Stay in a mild stretch rather than pulling farther with momentum.', 'Hold the position with steady breathing, then release gently; repeat on the other side if needed.']::text[]),
('Bodyweight Standing Row (With Towel)', 'back', array['biceps', 'shoulders']::text[], 'bodyweight', 'bodyweight_reps', 'uTv34oq', array['Stand and set your feet about shoulder width and hold a towel in front of you with both hands.', 'Bend your knees slightly and hinge forward at the hips, with your spine steady.', 'Set the torso and allow the arms to reach forward without rounding excessively.', 'Draw your elbows back and bring the handle or weight toward your torso.', 'Bring the elbows back without jerking the torso.', 'Reach the arms forward again without letting the torso lurch.']::text[]),
('Otis Up', 'core', array['back']::text[], 'bodyweight', 'bodyweight_reps', 'UVL20oz', array['Settle onto your back with your knees bent and feet planted.', 'Set your hands behind your head with your elbows pointing outwards.', 'Set the pelvis and keep the neck relaxed before curling upward.', 'Curl your rib cage toward your pelvis, letting the abdominals move the torso.', 'Leave a little space between the chin and chest; keep the movement in the torso.', 'Lower the shoulders or torso with control before the next curl.']::text[]),
('Flutter Kicks', 'glutes', array['core']::text[], 'bodyweight', 'bodyweight_reps', 'UVo2Qs2', array['Settle onto your back with your legs extended and your hands by your sides.', 'Brace your trunk and lift your legs off the ground about 6 inches.', 'Brace the trunk lightly before moving a limb.', 'Move the working arm or leg while keeping the trunk steady and the breathing even.', 'Keep the pelvis from rocking as the arm or leg moves.', 'Reset your posture before changing sides or beginning the next rep.']::text[]),
('Arm Slingers Hanging Bent Knee Legs', 'core', array['shoulders', 'back']::text[], 'bodyweight', 'bodyweight_reps', 'uWpxD4v', array['Suspend yourself from a pull-up bar with your arms straight and your knees bent at a 90-degree angle.', 'Brace your trunk and lift your knees toward your chest, bringing them as close to your elbows as possible.', 'Brace the abdomen and keep the shoulders anchored to the support.', 'Lift your legs by bracing your trunk and moving at the hips rather than swinging.', 'Slow the legs before they pull the lower back out of position.', 'Lower the legs slowly without swinging or losing your trunk position.']::text[]),
('Lying Triceps Extension (Cable)', 'triceps', array['shoulders']::text[], 'cable', 'weight_reps', 'uxJcFUU', array['Connect a rope handle to a low pulley cable machine.', 'Get onto a flat bench facing up, with your head toward the cable machine.', 'Set the upper arms in place before extending the elbows.', 'Keep the upper arms steady and extend through the elbows to move the weight.', 'Keep the upper arms steady while the forearms travel.', 'Bend the elbows slowly to return to the start of the next rep.']::text[]),
('Lying Two-Single-Leg Curl (Machine)', 'hamstrings', array['glutes']::text[], 'machine', 'weight_reps', 'UXpKJoq', array['Set the machine to fit your body and sit on it with your back against the backrest.', 'Set your legs on the lever pad, just above your ankles.', 'Line the knees up with the machine or bench edge before starting the curl.', 'Bend your knees to draw the pad toward you without lifting your hips from the support.', 'Keep the pelvis level as the supporting leg does the work.', 'Ease back to the start before repeating; switch sides when the set calls for it.']::text[]),
('Lunge (Dumbbell)', 'glutes', array['quads', 'hamstrings', 'calves']::text[], 'dumbbell', 'weight_reps', 'Uywa4S5', array['Stand and set your feet about shoulder width, holding a dumbbell in each hand.', 'Step forward with your right foot, lowering your body into a lunge position.', 'Set your stance wide enough to balance before bending either knee.', 'Step into the movement and bend both knees, keeping your front foot planted.', 'Keep the front foot planted and avoid collapsing inward at the knee.', 'Push through the lead foot to return to the start, then change legs as planned.']::text[]),
('Rear Lateral Raise (Support Head) (Dumbbell)', 'shoulders', array['traps', 'back']::text[], 'dumbbell', 'weight_reps', 'UzkLrem', array['Stand and set your feet about shoulder width and hold a dumbbell in each hand.', 'Bend your knees slightly and hinge forward at the hips, with your spine steady.', 'Start with a manageable load and a small bend in the elbows.', 'Raise the arms out to the sides to about shoulder height without leaning or shrugging.', 'Stop near shoulder height rather than shrugging to lift higher.', 'Lower the arms slowly to your sides without swinging the weight.']::text[]),
('Forward Jump', 'quads', array['calves', 'hamstrings', 'glutes']::text[], 'bodyweight', 'bodyweight_reps', 'uZKq7lo', array['Stand and set your feet about shoulder width.', 'Before moving, bend your knees and lower your body into a squat position.', 'Bend the hips and knees slightly to load the jump.', 'Load the legs with a small bend, then drive through the floor and land softly.', 'Land with bent hips and knees and let the feet absorb the impact.', 'Absorb the landing through the hips and knees before repeating.']::text[]),
('Alternate Leg Press (Machine)', 'quads', array['hamstrings', 'glutes']::text[], 'machine', 'weight_reps', 'V07qpXy', array['Set the seat and foot platform of the leverage machine to your desired position.', 'Take a seat on the machine with your back against the backrest and your feet on the foot platform.', 'Set your feet firmly on the plate and keep the hips against the seat.', 'Bend the knees to bring the platform toward you, then press it away through the feet.', 'Finish one side''s motion before the other side takes over.', 'Bring the weight or body back to its starting position without rushing; switch sides when the set calls for it.']::text[]),
('Rear Lateral Raise (Dumbbell)', 'shoulders', array['traps', 'back']::text[], 'dumbbell', 'weight_reps', 'v1qBec9', array['Stand and set your feet about shoulder width and hold a dumbbell in each hand, palms facing your body.', 'Bend your knees slightly and hinge forward at the hips, with your spine steady and core engaged.', 'Start with a manageable load and a small bend in the elbows.', 'Raise the arms out to the sides to about shoulder height without leaning or shrugging.', 'Stop near shoulder height rather than shrugging to lift higher.', 'Lower the arms slowly to your sides without swinging the weight.']::text[]),
('Single-Arm Dumbbell Bent-Over Row', 'back', array['biceps', 'forearms']::text[], 'dumbbell', 'weight_reps', 'v2DfH14', array['Stand and set your feet about shoulder width, knees soft, and hold a dumbbell in one hand with a neutral grip.', 'Bend forward at the hips, with your spine steady and your core engaged.', 'Set the torso and allow the arms to reach forward without rounding excessively.', 'Draw your elbows back and bring the handle or weight toward your torso.', 'Keep both shoulders level and resist turning toward the working arm.', 'Reach the arms forward again without letting the torso lurch; switch sides when the set calls for it.']::text[]),
('Close-Grip Push-Up (On Knees)', 'triceps', array['chest', 'shoulders']::text[], 'bodyweight', 'bodyweight_reps', 'v3vLFW0', array['Begin by getting on your hands and knees, with your hands about shoulder width and your knees about hip width.', 'Lower your upper body toward the ground by bending your elbows, keeping them close to your sides.', 'Brace the abdomen and glutes so the shoulders, hips and ankles move together.', 'Bend your elbows to lower your chest while keeping your body in one line.', 'Keep the head in line with the spine as the elbows bend.', 'Press back to straight arms, keeping the body line intact.']::text[]),
('Close-Grip Curl (EZ Bar)', 'biceps', array['forearms']::text[], 'barbell', 'weight_reps', 'V4ryaZa', array['Stand tall with your feet about shoulder width and hold the ez barbell with palms facing up, hands about shoulder width.', 'Hold your elbows near your torso and your upper arms stationary throughout the movement.', 'Set the shoulders and upper arms before bending the elbows.', 'Bend your elbows to bring the weight toward your shoulders without swinging your torso.', 'Keep the torso quiet and let the elbow bend lift the weight.', 'Lower until the elbows are nearly straight, keeping the upper arms still.']::text[]),
('Kick Out Sit', 'hamstrings', array['quads', 'glutes']::text[], 'bodyweight', 'bodyweight_reps', 'v7p5bYl', array['Take a seat on the edge of a bench or chair with your feet planted and your knees bent at a 90-degree angle.', 'Recline slightly and place your hands on the edge of the bench or chair for support.', 'Brace the abdomen and keep the shoulders anchored to the support.', 'Lift your legs by bracing your trunk and moving at the hips rather than swinging.', 'Slow the legs before they pull the lower back out of position.', 'Lower the legs slowly without swinging or losing your trunk position.']::text[]),
('Press on Exercise Ball (Cable)', 'chest', array['shoulders', 'triceps']::text[], 'cable', 'weight_reps', 'vAwm6rK', array['Take a seat on an exercise ball with your feet planted and your knees at a 90-degree angle.', 'Take hold of the cable handles at chest height with your palms facing down and your elbows bent.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Keep the ball steady and use the feet to manage your balance.', 'Lower the weight to its starting height under control before pressing again.']::text[]),
('Reverse-Grip Preacher Curl (EZ Bar)', 'biceps', array['forearms']::text[], 'barbell', 'weight_reps', 'vBNyir7', array['Take a seat on a preacher bench with your chest against the pad and your feet planted.', 'Hold the ez barbell with palms facing up, hands about shoulder width.', 'Set the working upper arm against the preacher pad and leave the elbow free to bend.', 'Curl the weight while your upper arms stay in contact with the pad.', 'Keep the palms in the chosen grip without bending the wrists back.', 'Lower until the elbows are nearly straight, keeping the upper arms still.']::text[]),
('Single-Arm Reverse Spider Curl (Dumbbell)', 'biceps', array['forearms']::text[], 'dumbbell', 'weight_reps', 'VdLZ3nB', array['Stand tall with a dumbbell in one hand, palm facing down and arm straight.', 'With your upper arm stationary, curl the dumbbell toward your shoulder by flexing your elbow.', 'Set the shoulders and upper arms before bending the elbows.', 'Curl the weight with your palms facing down, keeping the elbows close and torso still.', 'Keep both shoulders level and resist turning toward the working arm.', 'Lower until the elbows are nearly straight, keeping the upper arms still; switch sides when the set calls for it.']::text[]),
('Hanging Leg Hip Raise', 'core', array['back']::text[], 'bodyweight', 'bodyweight_reps', 'VEcJRo2', array['Suspend yourself from a pull-up bar with your arms straight and your palms turned away from you.', 'Brace your trunk and lift your legs up by flexing your hips and knees until your thighs are parallel to the ground.', 'Plant the feet and keep the ribs from flaring as the hips prepare to rise.', 'Press through the feet and lift your hips until your torso and thighs line up.', 'Stop when the hips line up with the torso; do not arch higher through the lower back.', 'Lower the hips steadily and keep the feet planted for the next lift.']::text[]),
('Floor Seated Wide-Grip Row (Cable)', 'back', array['biceps', 'forearms']::text[], 'cable', 'weight_reps', 'veXwo0D', array['Take a seat on the floor with your legs extended and your back straight.', 'Connect a cable handle to a low pulley and position the cable machine behind you.', 'Set the torso and allow the arms to reach forward without rounding excessively.', 'Draw your elbows back and bring the handle or weight toward your torso.', 'Bring the elbows back without jerking the torso.', 'Reach the arms forward again without letting the torso lurch.']::text[]),
('Incline Bench Press (Cable)', 'chest', array['shoulders', 'triceps']::text[], 'cable', 'weight_reps', 'Vh0GsK4', array['Set the bench to a 45-degree incline.', 'Connect the cable handles to the high pulleys.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Keep the wrists stacked and use a shoulder path that feels natural.', 'Lower the weight to its starting height under control before pressing again.']::text[]),
('Standing Back Wrist Curl (Cable)', 'forearms', array['biceps']::text[], 'cable', 'weight_reps', 'VhX2JdE', array['Face the cable machine from a stable stance with feet about shoulder width.', 'Take hold of the cable handle with palms facing down.', 'Keep the elbows relaxed so the small muscles of the hand or forearm take the load.', 'Move through the wrists or fingers while the forearms stay supported and still.', 'Use a small, smooth range without swinging the elbows.', 'Ease back to the start without letting the load fall from your hands.']::text[]),
('Around Pullover (Dumbbell)', 'chest', array['triceps', 'back']::text[], 'dumbbell', 'weight_reps', 'vi8EhoE', array['Settle onto a bench with your head at one end and your feet firmly on the ground.', 'Take a dumbbell with both hands and extend your arms straight above your chest.', 'Set the ribs down and keep a small elbow bend before lowering the weight.', 'Lower the weight in an arc behind your head until you feel a comfortable shoulder stretch.', 'Keep the ribs down as the arms travel overhead.', 'Pull the weight back over the chest along the same arc, without lifting the ribs.']::text[]),
('Lying Hip Internal Rotation (Band)', 'glutes', array['hamstrings', 'quads']::text[], 'band', 'weight_reps', 'vIICElP', array['Settle onto your back with your legs straight and a resistance band looped around your feet.', 'Bend your knees and bring them toward your chest, keeping your feet together.', 'Set the pelvis and make the turn through the rib cage.', 'Turn through the torso while the hips and lower body stay as steady as the setup allows.', 'Control the band on the way back instead of letting it snap you into position.', 'Return through center before turning to the other side.']::text[]),
('Reverse-Grip Pushdown (Cable)', 'triceps', array['forearms']::text[], 'cable', 'weight_reps', 'VjYliFZ', array['Connect a straight bar to a high pulley cable machine.', 'Face the machine from a stable stance with feet about shoulder width.', 'Stand far enough from the stack for the cable to stay taut.', 'Keep your elbows near your ribs and straighten your arms against the cable.', 'Keep the palms in the chosen grip without bending the wrists back.', 'Ease back to the start before repeating.']::text[]),
('Standing Inner Biceps Curl (Dumbbell)', 'biceps', array['forearms']::text[], 'dumbbell', 'weight_reps', 'vKilzz3', array['Stand tall with a dumbbell in each hand, palms facing your torso.', 'Hold your elbows near your torso and rotate the palms of your hands until they are facing forward.', 'Set the shoulders and upper arms before bending the elbows.', 'Bend your elbows to bring the weight toward your shoulders without swinging your torso.', 'Keep the torso quiet and let the elbow bend lift the weight.', 'Lower until the elbows are nearly straight, keeping the upper arms still.']::text[]),
('Round Arm (Weighted)', 'shoulders', array['triceps', 'back']::text[], 'bodyweight', 'bodyweight_reps', 'VLYXo8S', array['Stand and set your feet about shoulder width and hold a dumbbell in each hand.', 'Bend your knees slightly and hinge forward at the hips, with your spine steady.', 'Start with a manageable load and a small bend in the elbows.', 'Lift the weights away from your torso to about shoulder height, keeping the elbows softly bent.', 'Stop near shoulder height rather than shrugging to lift higher.', 'Lower the arms slowly to your sides without swinging the weight.']::text[]),
('Reverse Hyper Extension (On Stability Ball)', 'glutes', array['hamstrings', 'back']::text[], 'bodyweight', 'bodyweight_reps', 'vM5YS2g', array['Position yourself face down on a stability ball with your hips resting on the ball and your legs extended straight behind you.', 'Set your hands on the ground in front of you for stability.', 'Secure the hips and feet on the support before lifting.', 'Raise your torso or legs until they line up with your body, without arching sharply at the lower back.', 'Keep the ball steady and use the feet to manage your balance.', 'Ease back to the start before repeating.']::text[]),
('W-Press (Dumbbell)', 'shoulders', array['triceps', 'chest']::text[], 'dumbbell', 'weight_reps', 'vmwLyCg', array['Take a seat on a bench with a dumbbell in each hand, palms facing forward.', 'Before moving, raise the dumbbells to shoulder height, elbows bent and palms facing forward.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Keep the wrists stacked and use a shoulder path that feels natural.', 'Lower the weight to its starting height under control before pressing again.']::text[]),
('Close-Grip Chin-Up', 'back', array['biceps', 'forearms']::text[], 'bodyweight', 'bodyweight_reps', 'VnfUNW7', array['Take hold of the pull-up bar with your palms facing toward you and your hands about shoulder width.', 'Suspend yourself from the bar with your arms straight and your feet off the ground.', 'Begin from a controlled hang with the shoulders active rather than slack.', 'Pull your elbows down and bring your upper chest toward the bar without kicking your legs.', 'Avoid swinging the legs to clear the bar.', 'Lower to long arms without dropping suddenly from the top.']::text[]),
('Rope Incline Triceps Extension (Cable)', 'triceps', array['shoulders']::text[], 'cable', 'weight_reps', 'vNPJbDA', array['Connect a rope to a high pulley and adjust the incline bench to a comfortable angle.', 'Face the away from the pulley from a stable stance with feet about shoulder width.', 'Set the upper arms in place before extending the elbows.', 'Keep the upper arms steady and extend through the elbows to move the weight.', 'Keep the upper arms steady while the forearms travel.', 'Bend the elbows slowly to return to the start of the next rep.']::text[]),
('Side Plank Hip Abduction', 'glutes', array['core']::text[], 'bodyweight', 'duration', 'VO2qeJg', array['Begin by lying on your side with your legs extended and stacked on top of each other.', 'Support yourself up on your forearm, keeping your elbow directly below your shoulder.', 'Brace the abdomen and find a position you can maintain without holding your breath.', 'Hold the side plank line and raise the top leg without letting the hips roll back.', 'Keep breathing steadily as you maintain the same body line.', 'Lower the leg without dropping the hips, then repeat before changing sides.']::text[]),
('Seated Single-Arm Alternate Row (Cable)', 'back', array['biceps', 'forearms']::text[], 'cable', 'weight_reps', 'vpp9Ku2', array['Take a seat on a bench facing a cable machine with your feet planted and knees soft.', 'Hold the handle with one hand and keep your arm straight in front of you.', 'Set the torso and allow the arms to reach forward without rounding excessively.', 'Draw your elbows back and bring the handle or weight toward your torso.', 'Keep both shoulders level and resist turning toward the working arm.', 'Reach the arms forward again without letting the torso lurch; switch sides when the set calls for it.']::text[]),
('Inverted Row Bent Knees', 'back', array['biceps', 'forearms']::text[], 'bodyweight', 'bodyweight_reps', 'VPPtusI', array['Prepare a bar at waist height and lie underneath it.', 'Take hold of the bar with palms facing down, just beyond shoulder width.', 'Set the torso and allow the arms to reach forward without rounding excessively.', 'Draw your elbows back and bring the handle or weight toward your torso.', 'Bring the elbows back without jerking the torso.', 'Reach the arms forward again without letting the torso lurch.']::text[]),
('Ski Ergometer', 'triceps', array['shoulders', 'forearms']::text[], 'machine', 'weight_reps', 'vpQaQkH', array['Set the seat height and footrests to a comfortable position.', 'Hold the handles with palms facing down.', 'Start at a pace that lets the feet and arms move in sync.', 'Move at a repeatable pace, keeping the motion smooth and your breathing steady.', 'Keep the pattern repeatable as speed increases.', 'Keep the rhythm for the planned interval, slowing if your form starts to slip.']::text[]),
('Deep Push Up', 'chest', array['triceps', 'shoulders']::text[], 'dumbbell', 'weight_reps', 'vptOQ4N', array['Begin in a high plank position with your hands just beyond shoulder width and your body in a straight line.', 'Lower your chest toward the ground by bending your elbows, keeping them close to your body.', 'Brace the abdomen and glutes so the shoulders, hips and ankles move together.', 'Bend your elbows to lower your chest while keeping your body in one line.', 'Keep the head in line with the spine as the elbows bend.', 'Press back to straight arms, keeping the body line intact.']::text[]),
('Seated Single-Arm Kickback (Dumbbell)', 'triceps', array['shoulders']::text[], 'dumbbell', 'weight_reps', 'VQ3sNCn', array['Plant both feet while seated on a bench; hold a dumbbell in one hand.', 'Bend your torso forward at the waist, with your spine steady and parallel to the ground.', 'Set the upper arms in place before extending the elbows.', 'Hold the upper arm beside your torso and straighten the elbow behind you.', 'Keep both shoulders level and resist turning toward the working arm.', 'Bend the elbows slowly to return to the start of the next rep; switch sides when the set calls for it.']::text[]),
('Full Zercher Squat (Barbell)', 'glutes', array['quads', 'hamstrings', 'calves', 'core']::text[], 'barbell', 'weight_reps', 'vR1vold', array['Stand and set your feet about shoulder width and toes slightly turned out.', 'Take hold of the barbell in the crooks of your elbows, with your hands gripping the barbell for stability.', 'Brace the abdomen and spread pressure across the whole foot.', 'Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.', 'Drive upward with the chest and hips rising together; keep the knees from collapsing inward.', 'Stand fully, reset your footing and breathing, then begin the next descent.']::text[]),
('Parallel Close-Grip Pull-Up (Assisted)', 'back', array['biceps', 'forearms']::text[], 'machine', 'weight_reps', 'vrhHa6D', array['Set the machine to your desired weight and height.', 'Set your hands on the parallel bars with a close grip, palms facing each other.', 'Begin from a controlled hang with the shoulders active rather than slack.', 'Pull your elbows down and bring your upper chest toward the bar without kicking your legs.', 'Avoid swinging the legs to clear the bar.', 'Lower to long arms without dropping suddenly from the top.']::text[]),
('Standing Concentration Curl (Barbell)', 'biceps', array['forearms']::text[], 'barbell', 'weight_reps', 'vsMcDi9', array['Stand and set your feet about shoulder width and hold a barbell in one hand, palm facing up.', 'Set your opposite hand on your thigh for support.', 'Set the shoulders and upper arms before bending the elbows.', 'Bend your elbows to bring the weight toward your shoulders without swinging your torso.', 'Keep the torso quiet and let the elbow bend lift the weight.', 'Lower until the elbows are nearly straight, keeping the upper arms still.']::text[]),
('Close-Grip Push-Up', 'triceps', array['chest', 'shoulders']::text[], 'bodyweight', 'bodyweight_reps', 'VsopqcV', array['Begin in a high plank position with your hands placed close together, directly under your shoulders.', 'Brace your trunk and lower your body toward the ground, keeping your elbows close to your sides.', 'Brace the abdomen and glutes so the shoulders, hips and ankles move together.', 'Bend your elbows to lower your chest while keeping your body in one line.', 'Keep the head in line with the spine as the elbows bend.', 'Press back to straight arms, keeping the body line intact.']::text[]),
('Decline Chest Press (Machine)', 'chest', array['triceps', 'shoulders']::text[], 'machine', 'weight_reps', 'vsVoPHt', array['Set the seat height and backrest of the leverage machine to a comfortable position.', 'Take a seat on the machine with your back against the backrest and your feet planted.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Keep the wrists stacked and use a shoulder path that feels natural.', 'Lower the weight to its starting height under control before pressing again.']::text[]),
('Pull Through (Band)', 'glutes', array['hamstrings', 'back']::text[], 'band', 'weight_reps', 'VtTbiP3', array['Connect a resistance band to a sturdy anchor point at ground level.', 'Face the away from the anchor point from a stable stance with feet about shoulder width.', 'Unlock the knees and brace the abdomen before moving the hips back.', 'Push the hips back while keeping the load close and the spine steady.', 'Control the band on the way back instead of letting it snap you into position.', 'Drive the hips forward to stand tall without leaning back at the top.']::text[]),
('Single-Arm Floor Press (Barbell)', 'triceps', array['chest', 'shoulders']::text[], 'barbell', 'weight_reps', 'vtusOWT', array['Settle onto your back on the floor with your knees bent and feet planted.', 'Take hold of the barbell with one hand, palm facing up, and extend your arm straight up over your chest.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Keep both shoulders level and resist turning toward the working arm.', 'Lower the weight to its starting height under control before pressing again; switch sides when the set calls for it.']::text[]),
('Triceps Dip (Bench Leg)', 'triceps', array['chest', 'shoulders']::text[], 'bodyweight', 'bodyweight_reps', 'VuoerH0', array['Take a seat on the edge of a bench with your hands gripping the edge, fingers pointing forward.', 'Step your feet forward, sliding your butt off the bench, and straighten your arms.', 'Set the shoulders down and keep the elbows pointed mostly behind you.', 'Bend the elbows to lower between the supports; stop at a comfortable shoulder depth.', 'Choose a depth that lets the shoulders stay comfortable.', 'Press through the hands to rise, then reset the shoulders before another rep.']::text[]),
('Wrist Curl (Band)', 'forearms', array['biceps', 'triceps']::text[], 'band', 'weight_reps', 'vUTfFHw', array['Take a seat on a bench or chair with your feet planted.', 'Take hold of the band with both hands, palms facing up, and rest your forearms on your thighs.', 'Keep the elbows relaxed so the small muscles of the hand or forearm take the load.', 'Move through the wrists or fingers while the forearms stay supported and still.', 'Control the band on the way back instead of letting it snap you into position.', 'Ease back to the start without letting the load fall from your hands.']::text[]),
('Two-Arm Triceps Kickback (Cable)', 'triceps', array['shoulders']::text[], 'cable', 'weight_reps', 'vvNjDJS', array['Stand and set your feet about shoulder width and knees soft.', 'Take hold of the cable handle in each hand with your palms facing inwards and your arms bent at a 90-degree angle.', 'Set the upper arms in place before extending the elbows.', 'Hold the upper arm beside your torso and straighten the elbow behind you.', 'Keep the upper arms steady while the forearms travel.', 'Bend the elbows slowly to return to the start of the next rep.']::text[]),
('Glute-Ham Raise', 'hamstrings', array['glutes', 'back']::text[], 'bodyweight', 'bodyweight_reps', 'Vvwjz6N', array['Set the glute-ham raise machine to fit your body.', 'Set yourself face down on the machine with your ankles secured.', 'Line the knees up with the machine or bench edge before starting the curl.', 'Bend your knees to draw the pad toward you without lifting your hips from the support.', 'Keep the hips still while the knees bend.', 'Return along the same path at a controlled pace.']::text[]),
('Seated Single-Leg Calf Raise - Palm Up (Dumbbell)', 'calves', array['hamstrings', 'glutes']::text[], 'dumbbell', 'weight_reps', 'VW88JNd', array['Take a seat on a bench or chair with your back straight and your feet planted.', 'Take a dumbbell in one hand and place it on top of your thigh, palm facing up.', 'Let the ankles move freely while the rest of the body stays quiet.', 'Rise through the balls of your feet, lifting the heels as high as you can without rocking.', 'Keep the pelvis level as the supporting leg does the work.', 'Lower the heels at a measured pace before rising again; switch sides when the set calls for it.']::text[]),
('Lying Leg Raise with Throw Down (Assisted)', 'core', array['quads']::text[], 'bodyweight', 'bodyweight_reps', 'VX5YKR5', array['Settle onto your back with your legs extended and your arms by your sides.', 'Set your hands under your glutes for support.', 'Brace the abdomen and keep the shoulders anchored to the support.', 'Lift your legs by bracing your trunk and moving at the hips rather than swinging.', 'Slow the legs before they pull the lower back out of position.', 'Lower the legs slowly without swinging or losing your trunk position.']::text[]),
('Incline Rear Lateral Raise (Dumbbell)', 'shoulders', array['traps', 'back']::text[], 'dumbbell', 'weight_reps', 'vYk8lqw', array['Angle the bench to roughly 45 degrees.', 'Take a seat on the bench with your chest against the backrest and hold a dumbbell in each hand.', 'Start with a manageable load and a small bend in the elbows.', 'Raise the arms out to the sides to about shoulder height without leaning or shrugging.', 'Stop near shoulder height rather than shrugging to lift higher.', 'Lower the arms slowly to your sides without swinging the weight.']::text[]),
('Single-Arm Hammer Press on Exercise Ball (Dumbbell)', 'triceps', array['shoulders', 'chest']::text[], 'dumbbell', 'weight_reps', 'VYmYxK5', array['Take a seat on an exercise ball with your feet planted and your back straight.', 'Take a dumbbell in one hand with your palm facing inwards and your elbow bent at a 90-degree angle.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Keep both shoulders level and resist turning toward the working arm.', 'Lower the weight to its starting height under control before pressing again; switch sides when the set calls for it.']::text[]),
('Single-Arm Clean and Jerk (Kettlebell)', 'shoulders', array['triceps', 'core']::text[], 'kettlebell', 'weight_reps', 'vzAxBtt', array['Stand and set your feet about shoulder width, holding a kettlebell in one hand with palms facing down.', 'Before moving, bend your knees slightly and hinge at the hips, lowering the kettlebell between your legs.', 'Brace before the pull and keep the load close to the body.', 'Drive through the legs and hips, then guide the weight to its receiving position.', 'Keep both shoulders level and resist turning toward the working arm.', 'Stand tall to finish, then lower the weight under control before the next rep; switch sides when the set calls for it.']::text[]),
('Squat Row (Band)', 'glutes', array['hamstrings', 'quads', 'back']::text[], 'band', 'weight_reps', 'w1NOByi', array['Connect the band to a sturdy anchor point at waist height.', 'Face the anchor point from a stable stance with feet about shoulder width.', 'Brace the abdomen and spread pressure across the whole foot.', 'Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.', 'Control the band on the way back instead of letting it snap you into position.', 'Stand fully, reset your footing and breathing, then begin the next descent.']::text[]),
('Chest Stretch with Exercise Ball', 'chest', array['shoulders', 'triceps']::text[], 'bodyweight', 'duration', 'W1p7BND', array['Take a seat on the stability ball with your feet planted and your back straight.', 'Take hold of the exercise ball with both hands and extend your arms straight out in front of you.', 'Settle into the starting position and take an easy breath before moving deeper.', 'Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.', 'Keep the ball steady and use the feet to manage your balance.', 'Hold the position with steady breathing, then release gently; repeat on the other side if needed.']::text[]),
('Alternating Narrow Grip Seated Row (Machine)', 'back', array['biceps', 'forearms']::text[], 'machine', 'weight_reps', 'w2oRpuH', array['Set the seat height and footplate position to ensure proper alignment.', 'Take a seat on the machine with your back straight and feet flat on the footplate.', 'Set the torso and allow the arms to reach forward without rounding excessively.', 'Draw your elbows back and bring the handle or weight toward your torso.', 'Finish one side''s motion before the other side takes over.', 'Reach the arms forward again without letting the torso lurch; switch sides when the set calls for it.']::text[]),
('Single-Arm Decline Chest Fly (Cable)', 'chest', array['shoulders', 'triceps']::text[], 'cable', 'weight_reps', 'w4dLzSx', array['Connect a D-handle to a low pulley cable machine and set the bench to a decline angle.', 'Get onto the bench with your head toward the machine and grab the handle with your right hand.', 'Keep a soft elbow bend and set the shoulders before moving the arms.', 'With a soft bend in the elbows, sweep your arms together in a wide arc.', 'Keep both shoulders level and resist turning toward the working arm.', 'Open the arms back along the same arc without dropping the load; switch sides when the set calls for it.']::text[]),
('Kickback (Dumbbell)', 'triceps', array['shoulders']::text[], 'dumbbell', 'weight_reps', 'W6PxUkg', array['Stand and set your feet about shoulder width and hold a dumbbell in each hand.', 'Bend your knees slightly and hinge forward at the hips, with your spine steady.', 'Set the upper arms in place before extending the elbows.', 'Hold the upper arm beside your torso and straighten the elbow behind you.', 'Keep the upper arms steady while the forearms travel.', 'Bend the elbows slowly to return to the start of the next rep.']::text[]),
('Single-Arm French Press on Exercise Ball (Dumbbell)', 'triceps', array['shoulders']::text[], 'dumbbell', 'weight_reps', 'W7yh3Yo', array['Take a seat on an exercise ball with your feet planted and your back straight.', 'Take a dumbbell in one hand with your palm facing up and your elbow bent at a 90-degree angle.', 'Set the upper arms in place before extending the elbows.', 'Bend the elbows to lower the bar behind your head while the upper arms stay mostly still.', 'Keep both shoulders level and resist turning toward the working arm.', 'Straighten the elbows to bring the bar overhead, then begin the next controlled rep; switch sides when the set calls for it.']::text[]),
('Push-Up Medicine Ball', 'chest', array['triceps', 'shoulders', 'core']::text[], 'other', 'weight_reps', 'W8KAlkI', array['Begin in a high plank position with your hands on the medicine ball, about shoulder width.', 'Brace your trunk and lower your body toward the ground by bending your elbows, with your spine steady.', 'Brace the abdomen and glutes so the shoulders, hips and ankles move together.', 'Bend your elbows to lower your chest while keeping your body in one line.', 'Keep the head in line with the spine as the elbows bend.', 'Press back to straight arms, keeping the body line intact.']::text[]),
('Bench Squat (Barbell)', 'quads', array['glutes', 'hamstrings', 'calves']::text[], 'barbell', 'weight_reps', 'W9pFVv1', array['Prepare a barbell on a squat rack at chest height.', 'Face the away from the rack, from a stable stance with feet about shoulder width.', 'Brace the abdomen and spread pressure across the whole foot.', 'Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.', 'Drive upward with the chest and hips rising together; keep the knees from collapsing inward.', 'Stand fully, reset your footing and breathing, then begin the next descent.']::text[]),
('Elbow Lift - Reverse Push-Up', 'back', array['triceps', 'shoulders']::text[], 'bodyweight', 'bodyweight_reps', 'wbUYILZ', array['Begin by lying face down on the ground with your legs extended and your hands placed directly under your shoulders.', 'Brace your trunk and press through your palms to lift your upper body off the ground, keeping your elbows close to your sides.', 'Brace the abdomen and glutes so the shoulders, hips and ankles move together.', 'Bend your elbows to lower your chest while keeping your body in one line.', 'Keep the head in line with the spine as the elbows bend.', 'Press back to straight arms, keeping the body line intact.']::text[]),
('Side-To-Side Toe Touch', 'core', '{}'::text[], 'bodyweight', 'bodyweight_reps', 'WCAvOfC', array['Stand and set your feet about shoulder width and your arms extended to the sides.', 'Bend at the waist to the right, reaching your right hand toward your right foot while keeping your left hand extended to the side.', 'Soften the knees and let the hips start the fold.', 'Fold forward from the hips and let your hands travel toward your feet without forcing the reach.', 'Keep the movement controlled throughout the range.', 'Return along the same path at a controlled pace.']::text[]),
