('Bodyweight Drop Jump Squat', 'glutes', array['quads', 'hamstrings', 'calves']::text[], 'bodyweight', 'bodyweight_reps', 'wfotm7S', array['Stand and set your feet about shoulder width.', 'Before moving, lower your body into a squat position by bending your knees and pushing your hips back.', 'Brace the abdomen and spread pressure across the whole foot.', 'Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.', 'Drive upward with the chest and hips rising together; keep the knees from collapsing inward.', 'Stand fully, reset your footing and breathing, then begin the next descent.']::text[]),
('Seated Biceps Curl (On Stability Ball) (Dumbbell)', 'biceps', array['forearms']::text[], 'dumbbell', 'weight_reps', 'WgJnBH5', array['Take a seat on a stability ball with your feet planted and your back straight.', 'Take a dumbbell in each hand with your palms facing forward and your arms straight.', 'Set the shoulders and upper arms before bending the elbows.', 'Bend your elbows to bring the weight toward your shoulders without swinging your torso.', 'Keep the ball steady and use the feet to manage your balance.', 'Lower until the elbows are nearly straight, keeping the upper arms still.']::text[]),
('Lying Leg Raise Flat Bench', 'core', '{}'::text[], 'bodyweight', 'bodyweight_reps', 'WhuFnR7', array['Settle onto a flat bench with your back pressed against it.', 'Set your hands under your glutes for support.', 'Brace the abdomen and keep the shoulders anchored to the support.', 'Lift your legs by bracing your trunk and moving at the hips rather than swinging.', 'Slow the legs before they pull the lower back out of position.', 'Lower the legs slowly without swinging or losing your trunk position.']::text[]),
('Wide-Grip Decline Bench Press (Smith Machine)', 'chest', array['triceps', 'shoulders']::text[], 'machine', 'weight_reps', 'wi2H9QX', array['Set the decline bench to the desired angle.', 'Get onto the bench with your feet secured under the foot pads.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Keep the wrists stacked and use a shoulder path that feels natural.', 'Lower the weight to its starting height under control before pressing again.']::text[]),
('Clap Push Up', 'chest', array['triceps', 'shoulders']::text[], 'bodyweight', 'bodyweight_reps', 'wigSg76', array['Begin in a high plank position with your hands just beyond shoulder width.', 'Lower your body toward the ground by bending your elbows, keeping your core engaged.', 'Brace the abdomen and glutes so the shoulders, hips and ankles move together.', 'Bend your elbows to lower your chest while keeping your body in one line.', 'Keep the head in line with the spine as the elbows bend.', 'Press back to straight arms, keeping the body line intact.']::text[]),
('Incline Hammer Press on Exercise Ball (Dumbbell)', 'triceps', array['chest', 'shoulders']::text[], 'dumbbell', 'weight_reps', 'wkgnGfb', array['Take a seat on an exercise ball with a dumbbell in each hand, palms facing each other.', 'Step your feet forward and roll your body down the ball until your head, neck, and upper back are supported on the ball.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Keep the ball steady and use the feet to manage your balance.', 'Lower the weight to its starting height under control before pressing again.']::text[]),
('Lunge Pass Through (Kettlebell)', 'glutes', array['quads', 'hamstrings', 'calves']::text[], 'kettlebell', 'weight_reps', 'WKMQzCD', array['Stand and set your feet about shoulder width, holding a kettlebell ahead of your chest with both hands.', 'Step forward with your right foot, lowering your body into a lunge position.', 'Set your stance wide enough to balance before bending either knee.', 'Step into the movement and bend both knees, keeping your front foot planted.', 'Keep the front foot planted and avoid collapsing inward at the knee.', 'Push through the lead foot to return to the start, then change legs as planned.']::text[]),
('Side Bridge Hip Abduction', 'glutes', array['core']::text[], 'bodyweight', 'bodyweight_reps', 'WL4EmxJ', array['Settle onto your side with your legs extended and stacked on top of each other.', 'Support yourself up on your forearm, keeping your elbow directly below your shoulder.', 'Brace the abdomen and find a position you can maintain without holding your breath.', 'Hold the side plank line and raise the top leg without letting the hips roll back.', 'Keep breathing steadily as you maintain the same body line.', 'Lower the leg without dropping the hips, then repeat before changing sides.']::text[]),
('Exercise Ball Back Extension with Knees Off Ground', 'back', array['glutes', 'hamstrings']::text[], 'bodyweight', 'bodyweight_reps', 'WME869U', array['Set the stability ball on the ground and Position yourself face down on top of it, with your hips resting on the ball and your feet against a wall for stability.', 'Set your hands behind your head or crossed over your chest.', 'Secure the hips and feet on the support before lifting.', 'Raise your torso or legs until they line up with your body, without arching sharply at the lower back.', 'Keep the ball steady and use the feet to manage your balance.', 'Bring the weight or body back to its starting position without rushing.']::text[]),
('Press Sit-Up (Barbell)', 'core', array['shoulders', 'chest']::text[], 'barbell', 'weight_reps', 'wnEscH8', array['Settle onto your back on a mat with your knees bent and feet planted.', 'Take hold of the barbell with palms facing down, resting it on your chest.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Keep the wrists stacked and use a shoulder path that feels natural.', 'Lower the weight to its starting height under control before pressing again.']::text[]),
('Triceps Kickback with Stork Stance (Dumbbell)', 'triceps', array['shoulders']::text[], 'dumbbell', 'weight_reps', 'wOLmCXc', array['Stand and set your feet about shoulder width and hold a dumbbell in your right hand.', 'Bend your knees slightly and hinge forward at the hips, with your spine steady.', 'Set the upper arms in place before extending the elbows.', 'Hold the upper arm beside your torso and straighten the elbow behind you.', 'Keep the upper arms steady while the forearms travel.', 'Bend the elbows slowly to return to the start of the next rep.']::text[]),
('Side Push-Up', 'triceps', array['shoulders', 'chest', 'core']::text[], 'bodyweight', 'bodyweight_reps', 'wpbD28t', array['Begin by lying on your side with your legs extended and stacked on top of each other.', 'Set your bottom hand on the ground directly under your shoulder, fingers pointing forward.', 'Brace the abdomen and glutes so the shoulders, hips and ankles move together.', 'Bend your elbows to lower your chest while keeping your body in one line.', 'Keep the head in line with the spine as the elbows bend.', 'Press back to straight arms, keeping the body line intact.']::text[]),
('Single-Arm Straight Back High Row (Kneeling) (Cable)', 'back', array['biceps', 'shoulders']::text[], 'cable', 'weight_reps', 'WrYPP2g', array['Connect a handle to a cable machine at waist height.', 'Kneel facing the cable machine and grab the handle with one hand.', 'Set the torso and allow the arms to reach forward without rounding excessively.', 'Draw your elbows back and bring the handle or weight toward your torso.', 'Keep both shoulders level and resist turning toward the working arm.', 'Reach the arms forward again without letting the torso lurch; switch sides when the set calls for it.']::text[]),
('Bent-Over Hip Extension (Band)', 'glutes', array['hamstrings', 'back']::text[], 'band', 'weight_reps', 'wSScovH', array['Secure the band low on a solid anchor.', 'Face the away from the anchor point from a stable stance with feet about shoulder width.', 'Plant the feet and keep the ribs from flaring as the hips prepare to rise.', 'Press through the feet and lift your hips until your torso and thighs line up.', 'Control the band on the way back instead of letting it snap you into position.', 'Lower the hips steadily and keep the feet planted for the next lift.']::text[]),
('Palm Rotational Bent Over Row (Dumbbell)', 'back', array['biceps', 'forearms']::text[], 'dumbbell', 'weight_reps', 'wt6rwjk', array['Stand and set your feet about shoulder width, holding a dumbbell in each hand with palms facing down.', 'Bend forward at the hips, with your spine steady and your knees soft.', 'Set the torso and allow the arms to reach forward without rounding excessively.', 'Draw your elbows back and bring the handle or weight toward your torso.', 'Bring the elbows back without jerking the torso.', 'Reach the arms forward again without letting the torso lurch.']::text[]),
('Triceps Extension (Barbell)', 'triceps', array['shoulders']::text[], 'barbell', 'weight_reps', 'wu5LXwz', array['Begin by standing with your feet about shoulder width and holding the barbell with palms facing down.', 'Raise the barbell above your head, straighten your arms.', 'Set the upper arms in place before extending the elbows.', 'Keep the upper arms steady and extend through the elbows to move the weight.', 'Keep the upper arms steady while the forearms travel.', 'Bend the elbows slowly to return to the start of the next rep.']::text[]),
('Russian Twist (Legs Up) (Weighted)', 'core', '{}'::text[], 'bodyweight', 'bodyweight_reps', 'WU9BLIs', array['Take a seat on the ground with your knees bent and feet lifted off the ground, keeping your legs together.', 'Take hold of the weight with both hands ahead of your chest, keeping your elbows soft.', 'Set the pelvis and make the turn through the rib cage.', 'Turn through the torso while the hips and lower body stay as steady as the setup allows.', 'Keep the turn smooth instead of throwing the arms across the body.', 'Return through center before turning to the other side.']::text[]),
('Exercise Ball Back Extension with Rotation', 'back', array['glutes', 'hamstrings']::text[], 'bodyweight', 'bodyweight_reps', 'WVD66ff', array['Begin by lying face down on the stability ball with your hips resting on the ball and your feet firmly planted on the ground.', 'Set your hands behind your head or cross them over your chest.', 'Secure the hips and feet on the support before lifting.', 'Raise your torso or legs until they line up with your body, without arching sharply at the lower back.', 'Keep the ball steady and use the feet to manage your balance.', 'Ease back to the start before repeating.']::text[]),
('Single Leg Split Squat (Smith Machine)', 'quads', array['glutes', 'hamstrings']::text[], 'machine', 'weight_reps', 'wWFspEi', array['Take your place in front of the smith machine with your feet about shoulder width.', 'Set one foot behind you on a bench or step, with your toes pointing forward.', 'Brace the abdomen and spread pressure across the whole foot.', 'Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.', 'Drive upward with the chest and hips rising together; keep the knees from collapsing inward.', 'Stand fully, reset your footing and breathing, then begin the next descent.']::text[]),
('Push and Pull Bodyweight', 'chest', array['triceps', 'shoulders']::text[], 'bodyweight', 'bodyweight_reps', 'wXvUZC8', array['Begin in a push-up position with your hands just beyond shoulder width and your body in a straight line.', 'Lower your chest toward the ground by bending your elbows, keeping your body straight.', 'Brace the abdomen and glutes so the shoulders, hips and ankles move together.', 'Bend your elbows to lower your chest while keeping your body in one line.', 'Keep the head in line with the spine as the elbows bend.', 'Press back to straight arms, keeping the body line intact.']::text[]),
('Lying Single-Arm Pronated Triceps Extension (Dumbbell)', 'triceps', array['shoulders']::text[], 'dumbbell', 'weight_reps', 'wyaqzOS', array['Settle onto a bench with your back and head supported, and your feet planted.', 'Take a dumbbell in one hand with your palm facing down, and extend your arm straight up above your shoulder.', 'Set the upper arms in place before extending the elbows.', 'Keep the upper arms steady and extend through the elbows to move the weight.', 'Keep both shoulders level and resist turning toward the working arm.', 'Bend the elbows slowly to return to the start of the next rep; switch sides when the set calls for it.']::text[]),
('Seated Bent Over Alternate Kickback (Dumbbell)', 'triceps', array['shoulders', 'back']::text[], 'dumbbell', 'weight_reps', 'x0lwvfq', array['Take a seat on a bench with a dumbbell in each hand, palms facing inwards.', 'Bend forward at the waist, with your spine steady and parallel to the ground.', 'Set the upper arms in place before extending the elbows.', 'Hold the upper arm beside your torso and straighten the elbow behind you.', 'Finish one side''s motion before the other side takes over.', 'Bend the elbows slowly to return to the start of the next rep; switch sides when the set calls for it.']::text[]),
('Neck Side Stretch', 'traps', '{}'::text[], 'bodyweight', 'duration', 'x2chWLO', array['Either stand or sit up straight with your shoulders relaxed.', 'Tilt your head to one side, bringing your ear toward your shoulder.', 'Settle into the starting position and take an easy breath before moving deeper.', 'Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.', 'Stay in a mild stretch rather than pulling farther with momentum.', 'Hold the position with steady breathing, then release gently; repeat on the other side if needed.']::text[]),
('Bent Over Row (Machine)', 'back', array['biceps', 'forearms']::text[], 'barbell', 'weight_reps', 'X3cqyXz', array['Stand and set your feet about shoulder width and knees soft.', 'Take hold of the barbell with palms facing down, hands just beyond shoulder width.', 'Set the torso and allow the arms to reach forward without rounding excessively.', 'Draw your elbows back and bring the handle or weight toward your torso.', 'Bring the elbows back without jerking the torso.', 'Reach the arms forward again without letting the torso lurch.']::text[]),
('Side Plank with Rear Fly (Dumbbell)', 'back', array['shoulders', 'core']::text[], 'dumbbell', 'duration', 'X6ytgYZ', array['Begin by lying on your side with your legs extended and stacked on top of each other.', 'Set your forearm on the ground directly below your shoulder, keeping your elbow bent at a 90-degree angle.', 'Brace the abdomen and find a position you can maintain without holding your breath.', 'Brace your midsection and hold the position while breathing normally.', 'Keep breathing steadily as you maintain the same body line.', 'Keep the shape for the planned time, then come out of it with control.']::text[]),
('Circles Knee Stretch', 'calves', array['hamstrings', 'quads']::text[], 'bodyweight', 'duration', 'X7jbxra', array['Stand and set your feet about shoulder width and your hands on your hips.', 'Before moving, bend your knees slightly and lift your heels off the ground, balancing on the balls of your feet.', 'Settle into the starting position and take an easy breath before moving deeper.', 'Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.', 'Stay in a mild stretch rather than pulling farther with momentum.', 'Hold the position with steady breathing, then release gently; repeat on the other side if needed.']::text[]),
('Seated Rear Lateral Raise (Cable)', 'shoulders', array['traps', 'back']::text[], 'cable', 'weight_reps', 'x825CZm', array['Take a seat on a bench facing the cable machine with your feet planted.', 'Hold the cable handles with palms facing down and extend your arms straight in front of you.', 'Start with a manageable load and a small bend in the elbows.', 'Raise the arms out to the sides to about shoulder height without leaning or shrugging.', 'Stop near shoulder height rather than shrugging to lift higher.', 'Lower the arms slowly to your sides without swinging the weight.']::text[]),
('Incline Reverse-Grip Push-Up', 'chest', array['triceps', 'shoulders']::text[], 'bodyweight', 'bodyweight_reps', 'XaaRnRn', array['Set your hands on the edge of a bench or elevated surface, just beyond shoulder width.', 'Reach your legs behind you, resting on the balls of your feet, creating a straight line from your head to your heels.', 'Brace the abdomen and glutes so the shoulders, hips and ankles move together.', 'Bend your elbows to lower your chest while keeping your body in one line.', 'Keep the palms in the chosen grip without bending the wrists back.', 'Press back to straight arms, keeping the body line intact.']::text[]),
('Forward Lunge Triceps Extension (Dumbbell)', 'triceps', array['shoulders', 'core']::text[], 'dumbbell', 'weight_reps', 'XalXcvM', array['Stand and set your feet about shoulder width, holding a dumbbell in each hand.', 'Step forward with your right foot, lowering your body into a lunge position.', 'Set your stance wide enough to balance before bending either knee.', 'Step into the movement and bend both knees, keeping your front foot planted.', 'Keep the front foot planted and avoid collapsing inward at the knee.', 'Push through the lead foot to return to the start, then change legs as planned.']::text[]),
('Balance Board', 'quads', array['calves', 'hamstrings', 'glutes']::text[], 'bodyweight', 'bodyweight_reps', 'xAySMB0', array['Set the balance board on a flat surface.', 'Get onto the balance board with one foot, ensuring it is centered.', 'Brace the abdomen and find a position you can maintain without holding your breath.', 'Brace your midsection and hold the position while breathing normally.', 'Keep breathing steadily as you maintain the same body line.', 'Keep the shape for the planned time, then come out of it with control.']::text[]),
('Bodyweight Standing Single-Arm Row', 'back', array['biceps', 'forearms']::text[], 'bodyweight', 'bodyweight_reps', 'xbkPfaw', array['Stand and set your feet about shoulder width, knees soft, and hold a dumbbell in one hand.', 'Bend forward at the hips, with your spine steady and your core engaged.', 'Set the torso and allow the arms to reach forward without rounding excessively.', 'Draw your elbows back and bring the handle or weight toward your torso.', 'Keep both shoulders level and resist turning toward the working arm.', 'Reach the arms forward again without letting the torso lurch; switch sides when the set calls for it.']::text[]),
('Underhand Pulldown (Cable)', 'back', array['biceps', 'forearms']::text[], 'cable', 'weight_reps', 'xBYcQHj', array['Set the cable machine so that the pulldown bar is at a height above your head.', 'Sit down on the seat and grab the pulldown bar with palms facing up, hands just beyond shoulder width.', 'Sit tall and set the shoulders before drawing the handle down.', 'Pull the handle down by driving your elbows toward your ribs; keep your torso steady.', 'Pull with the elbows rather than leaning far back to move the handle.', 'Let the handle rise steadily until the arms are long, then reset the shoulders.']::text[]),
('Standing Behind Neck Press', 'shoulders', array['triceps', 'back']::text[], 'barbell', 'weight_reps', 'xDh0lJr', array['Stand and set your feet about shoulder width and hold the barbell behind your neck with palms facing down.', 'Keep your spine in a comfortable neutral position and core engaged.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Keep the wrists stacked and use a shoulder path that feels natural.', 'Lower the weight to its starting height under control before pressing again.']::text[]),
('Forward Angled Calf Raise (Machine)', 'calves', array['hamstrings', 'glutes']::text[], 'machine', 'weight_reps', 'XDOiFns', array['Set the sled machine to a comfortable weight and position yourself on the machine with your toes on the platform and your heels hanging off.', 'Set your hands on the handles or the sides of the machine for support.', 'Let the ankles move freely while the rest of the body stays quiet.', 'Rise through the balls of your feet, lifting the heels as high as you can without rocking.', 'Pause at the top without rolling the ankles outward.', 'Lower the heels at a measured pace before rising again.']::text[]),
('Roller Body Saw', 'core', array['shoulders', 'triceps']::text[], 'other', 'bodyweight_reps', 'XeMvLgE', array['Begin in a plank position with your forearms on the roller and your body in a straight line.', 'Brace your trunk and With control roll the roller forward, extending your body as far as you can while maintaining control.', 'Tighten the abdomen and keep the pelvis tucked before the arms reach away.', 'Reach the arms away while keeping your ribs and pelvis aligned; stop before the lower back sags.', 'Stop reaching when the lower back starts to sag.', 'Pull back to the start through your shoulders and abdominals, keeping the same body line.']::text[]),
('Seated Biceps Curl (Band)', 'biceps', array['forearms']::text[], 'band', 'weight_reps', 'XFc3vpY', array['Take a seat on a chair or bench with your back straight and feet planted.', 'Take hold of the resistance band with palms facing up, and arms extended down by your sides.', 'Set the shoulders and upper arms before bending the elbows.', 'Bend your elbows to bring the weight toward your shoulders without swinging your torso.', 'Control the band on the way back instead of letting it snap you into position.', 'Lower until the elbows are nearly straight, keeping the upper arms still.']::text[]),
('Crab Twist Toe Touch', 'core', '{}'::text[], 'bodyweight', 'bodyweight_reps', 'xgsGFVM', array['Begin by sitting on the ground with your knees bent and feet planted.', 'Set your hands behind you, fingers pointing toward your feet, and lift your hips off the ground.', 'Soften the knees and let the hips start the fold.', 'Fold forward from the hips and let your hands travel toward your feet without forcing the reach.', 'Keep the movement controlled throughout the range.', 'Hold briefly at a comfortable depth, then rise by extending the hips.']::text[]),
('Chest Dip (On Dip-Pull-Up Cage)', 'chest', array['triceps', 'shoulders']::text[], 'bodyweight', 'bodyweight_reps', 'XgWyAiA', array['Set the dip bars to a height that allows you to comfortably grip them.', 'Stand between the bars and place your hands on each bar, just beyond shoulder width.', 'Begin from a controlled hang with the shoulders active rather than slack.', 'Pull your elbows down and bring your upper chest toward the bar without kicking your legs.', 'Avoid swinging the legs to clear the bar.', 'Lower to long arms without dropping suddenly from the top.']::text[]),
('Peroneals Stretch', 'calves', '{}'::text[], 'cable', 'duration', 'XhfS1DZ', array['Take a seat on the ground with your legs extended in front of you.', 'Thread the rope around the ball of your foot and hold the ends of the rope with your hands.', 'Settle into the starting position and take an easy breath before moving deeper.', 'Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.', 'Stay in a mild stretch rather than pulling farther with momentum.', 'Hold the position with steady breathing, then release gently; repeat on the other side if needed.']::text[]),
('Single-Arm Snatch (Barbell)', 'shoulders', array['traps', 'forearms', 'core']::text[], 'barbell', 'weight_reps', 'xHKN2s8', array['Stand and set your feet about shoulder width, toes pointing slightly outwards.', 'Take hold of the barbell with palms facing down, hands just beyond shoulder width.', 'Brace before the pull and keep the load close to the body.', 'Drive through the legs and hips, then guide the weight to its receiving position.', 'Keep both shoulders level and resist turning toward the working arm.', 'Stand tall to finish, then lower the weight under control before the next rep; switch sides when the set calls for it.']::text[]),
('Incline Shoulder Raise (Barbell)', 'chest', array['shoulders', 'traps']::text[], 'barbell', 'weight_reps', 'xi0yckC', array['Angle the bench to roughly 45 degrees.', 'Take a seat on the bench with your back against the pad and feet planted.', 'Start with a manageable load and a small bend in the elbows.', 'Lift the weights away from your torso to about shoulder height, keeping the elbows softly bent.', 'Stop near shoulder height rather than shrugging to lift higher.', 'Lower the arms slowly to your sides without swinging the weight.']::text[]),
('Seated Biceps Curl (Dumbbell)', 'biceps', array['forearms']::text[], 'dumbbell', 'weight_reps', 'xiA6lRr', array['Plant both feet while seated on a bench; hold a dumbbell in each hand, palms facing up.', 'Keep your spine in a comfortable neutral position and your elbows close to your torso.', 'Set the shoulders and upper arms before bending the elbows.', 'Bend your elbows to bring the weight toward your shoulders without swinging your torso.', 'Keep the torso quiet and let the elbow bend lift the weight.', 'Lower until the elbows are nearly straight, keeping the upper arms still.']::text[]),
('Rear Deltoid Stretch', 'shoulders', array['traps', 'back']::text[], 'bodyweight', 'duration', 'xifhB5W', array['Stand tall and set your feet about shoulder width.', 'Reach your right arm across your chest, placing your left hand on your right elbow.', 'Settle into the starting position and take an easy breath before moving deeper.', 'Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.', 'Stay in a mild stretch rather than pulling farther with momentum.', 'Hold the position with steady breathing, then release gently; repeat on the other side if needed.']::text[]),
('Standing Calves', 'calves', array['hamstrings', 'glutes']::text[], 'bodyweight', 'bodyweight_reps', 'XIHEoCG', array['Stand and set your feet about shoulder width, toes pointing forward.', 'Before moving, raise your heels off the ground as high as possible, standing on your toes.', 'Let the ankles move freely while the rest of the body stays quiet.', 'Rise through the balls of your feet, lifting the heels as high as you can without rocking.', 'Pause at the top without rolling the ankles outward.', 'Lower the heels at a measured pace before rising again.']::text[]),
('Seated Reverse Fly (Parallel Grip) (Machine)', 'shoulders', array['traps', 'back']::text[], 'machine', 'weight_reps', 'xiHiJcA', array['Fit the seat to your body, then settle into the machine.', 'Hold the handles with a parallel grip, palms facing each other, and keep your arms soft.', 'Keep a soft elbow bend and set the shoulders before moving the arms.', 'Open your arms out and back with a slight elbow bend, drawing the shoulder blades together.', 'Keep the elbow angle nearly unchanged through the arc.', 'Open the arms back along the same arc without dropping the load.']::text[]),
('Middle Fly (Cable)', 'chest', array['shoulders', 'triceps']::text[], 'cable', 'weight_reps', 'xLYSdtg', array['Connect cables to both sides of a cable machine at chest height.', 'Take your place in the center of the machine with one foot slightly in front of the other.', 'Keep a soft elbow bend and set the shoulders before moving the arms.', 'With a soft bend in the elbows, sweep your arms together in a wide arc.', 'Keep the elbow angle nearly unchanged through the arc.', 'Open the arms back along the same arc without dropping the load.']::text[]),
('Good Morning (Barbell)', 'hamstrings', array['back']::text[], 'barbell', 'weight_reps', 'XlZ4lAC', array['Begin by standing with your feet about shoulder width and the barbell resting on your upper back.', 'With your back straight and your core engaged, hinge forward at the hips, pushing your buttocks back as if you were trying to touch the wall behind you with your glutes.', 'Unlock the knees and brace the abdomen before moving the hips back.', 'Push the hips back while keeping the load close and the spine steady.', 'Keep the weight close to the legs and stop when the back would begin to round.', 'Drive the hips forward to stand tall without leaning back at the top.']::text[]),
('Lateral to Front Raise (Dumbbell)', 'shoulders', array['traps', 'biceps']::text[], 'dumbbell', 'weight_reps', 'xMjBKwn', array['Stand and set your feet about shoulder width, holding a dumbbell in each hand with your palms facing your body.', 'Keep your spine in a comfortable neutral position and Brace your trunk.', 'Start with a manageable load and a small bend in the elbows.', 'Lift the arms forward to about shoulder height, keeping the ribs down and torso still.', 'Stop near shoulder height rather than shrugging to lift higher.', 'Lower the arms slowly to your sides without swinging the weight.']::text[]),
('Overhead Crunch (On Stability Ball) (Weighted)', 'core', array['back']::text[], 'bodyweight', 'weight_reps', 'xmM75XG', array['Take a seat on a stability ball with your feet planted and your knees bent at a 90-degree angle.', 'Take a weight plate or dumbbell with both hands and extend your arms overhead.', 'Set the pelvis and keep the neck relaxed before curling upward.', 'Curl your rib cage toward your pelvis, letting the abdominals move the torso.', 'Keep the ball steady and use the feet to manage your balance.', 'Lower the shoulders or torso with control before the next curl.']::text[]),
('Standing Ab Rollout (Barbell)', 'core', array['shoulders', 'back']::text[], 'barbell', 'weight_reps', 'xnInPfE', array['Stand upright with your feet about shoulder width and hold the barbell with both hands ahead of your thighs.', 'Brace your trunk and With control roll the barbell down toward the ground, with your spine steady and your arms extended.', 'Tighten the abdomen and keep the pelvis tucked before the arms reach away.', 'Reach the arms away while keeping your ribs and pelvis aligned; stop before the lower back sags.', 'Stop reaching when the lower back starts to sag.', 'Pull back to the start through your shoulders and abdominals, keeping the same body line.']::text[]),
('Reverse Curl (Barbell)', 'biceps', array['forearms']::text[], 'barbell', 'weight_reps', 'xNrS20v', array['Stand tall with your feet about shoulder width and hold a barbell with palms facing down.', 'Let the elbows do the moving while the upper arms stay put and Breathe out and curl the barbell upward, contracting your biceps.', 'Set the shoulders and upper arms before bending the elbows.', 'Curl the weight with your palms facing down, keeping the elbows close and torso still.', 'Keep the torso quiet and let the elbow bend lift the weight.', 'Lower until the elbows are nearly straight, keeping the upper arms still.']::text[]),
('Exercise Ball on the Wall Calf Raise', 'calves', array['hamstrings', 'quads']::text[], 'dumbbell', 'weight_reps', 'xo6sENf', array['Stand and set your back against a wall and place an exercise ball between your lower back and the wall.', 'Set your feet about shoulder width, with your toes pointing forward.', 'Let the ankles move freely while the rest of the body stays quiet.', 'Rise through the balls of your feet, lifting the heels as high as you can without rocking.', 'Keep the ball steady and use the feet to manage your balance.', 'Lower the heels at a measured pace before rising again.']::text[]),
('Handstand', 'triceps', array['shoulders', 'core']::text[], 'bodyweight', 'bodyweight_reps', 'XooAdhl', array['Choose an open space with enough room to perform a handstand.', 'Set your hands on the ground about shoulder width, fingers pointing forward.', 'Brace the abdomen and find a position you can maintain without holding your breath.', 'Brace your midsection and hold the position while breathing normally.', 'Keep breathing steadily as you maintain the same body line.', 'Keep the shape for the planned time, then come out of it with control.']::text[]),
('Pike-To-Cobra Push-Up', 'glutes', array['core', 'shoulders', 'triceps']::text[], 'bodyweight', 'bodyweight_reps', 'XPUDTt7', array['Begin in a push-up position with your hands just beyond shoulder width and your feet together.', 'Brace your trunk and lift your hips up toward the ceiling, forming an inverted V shape with your body.', 'Brace the abdomen and glutes so the shoulders, hips and ankles move together.', 'Bend your elbows to lower your chest while keeping your body in one line.', 'Keep the head in line with the spine as the elbows bend.', 'Press back to straight arms, keeping the body line intact.']::text[]),
('Seated Good Morning (Machine)', 'glutes', array['hamstrings', 'back']::text[], 'machine', 'weight_reps', 'XsCcxCC', array['Set the seat height so that your hips are slightly higher than your knees.', 'Take a seat on the machine with your back against the pad and your feet flat on the footrests.', 'Unlock the knees and brace the abdomen before moving the hips back.', 'Push the hips back while keeping the load close and the spine steady.', 'Keep the weight close to the legs and stop when the back would begin to round.', 'Drive the hips forward to stand tall without leaning back at the top.']::text[]),
('Cycle Cross Trainer', 'cardio', array['quads', 'hamstrings', 'glutes']::text[], 'machine', 'duration', 'XSCHmiI', array['Fit the seat to your body, then settle into the machine.', 'Set your feet on the pedals and grip the handlebars.', 'Start at a pace that lets the feet and arms move in sync.', 'Move at a repeatable pace, keeping the motion smooth and your breathing steady.', 'Keep the pattern repeatable as speed increases.', 'Keep the rhythm for the planned interval, slowing if your form starts to slip.']::text[]),
('Standing Hamstring and Calf Stretch with Strap', 'hamstrings', array['calves']::text[], 'cable', 'duration', 'xTjr103', array['Stand upright with your feet about shoulder width.', 'Take hold of the strap with both hands and place it around the ball of your foot.', 'Settle into the starting position and take an easy breath before moving deeper.', 'Ease the heel down and shift until the calf stretches; keep the foot pointed ahead.', 'Stay in a mild stretch rather than pulling farther with momentum.', 'Hold the position with steady breathing, then release gently; repeat on the other side if needed.']::text[]),
('Lying Rear Delt Row (Dumbbell)', 'back', array['shoulders', 'biceps']::text[], 'dumbbell', 'weight_reps', 'XUUD0Fs', array['Position yourself face down on a flat bench with a dumbbell in each hand, palms facing inwards.', 'Extend your arms straight down toward the floor, keeping a slight bend in your elbows.', 'Set the torso and allow the arms to reach forward without rounding excessively.', 'Draw your elbows back and bring the handle or weight toward your torso.', 'Bring the elbows back without jerking the torso.', 'Reach the arms forward again without letting the torso lurch.']::text[]),
('Lying Supine Biceps Curl (Dumbbell)', 'biceps', array['forearms']::text[], 'dumbbell', 'weight_reps', 'XVzF3iZ', array['Settle onto a bench with your back and head supported, and your feet planted.', 'Take a dumbbell in each hand with your palms facing up and your arms straight.', 'Set the shoulders and upper arms before bending the elbows.', 'Bend your elbows to bring the weight toward your shoulders without swinging your torso.', 'Keep the torso quiet and let the elbow bend lift the weight.', 'Lower until the elbows are nearly straight, keeping the upper arms still.']::text[]),
('Decline Fly (Dumbbell)', 'chest', array['shoulders']::text[], 'dumbbell', 'weight_reps', 'xXm4nYq', array['Secure the feet on a decline bench, keeping the head below the hips.', 'Take a dumbbell in each hand with your palms facing each other and your arms extended above your chest.', 'Keep a soft elbow bend and set the shoulders before moving the arms.', 'With a soft bend in the elbows, sweep your arms together in a wide arc.', 'Keep the elbow angle nearly unchanged through the arc.', 'Open the arms back along the same arc without dropping the load.']::text[]),
('Toe Raise (Smith Machine)', 'calves', '{}'::text[], 'machine', 'weight_reps', 'Y4QlY8z', array['Set the smith machine bar to a height that allows you to comfortably stand with your feet planted.', 'Set yourself under the bar with your shoulders directly below it and your feet about shoulder width.', 'Let the ankles move freely while the rest of the body stays quiet.', 'Rise through the balls of your feet, lifting the heels as high as you can without rocking.', 'Pause at the top without rolling the ankles outward.', 'Lower the heels at a measured pace before rising again.']::text[]),
('Run (Equipment)', 'cardio', array['quads', 'hamstrings', 'calves']::text[], 'bodyweight', 'duration', 'y5p0H8a', array['Begin by standing upright with your feet about hip width.', 'Brace your trunk and keep your upper body relaxed.', 'Start at a pace that lets the feet and arms move in sync.', 'Move at a repeatable pace, keeping the motion smooth and your breathing steady.', 'Keep the pattern repeatable as speed increases.', 'Keep the rhythm for the planned interval, slowing if your form starts to slip.']::text[]),
('Zottman Preacher Curl (Dumbbell)', 'biceps', array['forearms']::text[], 'dumbbell', 'weight_reps', 'y5U5B9Y', array['Take a seat on a preacher bench with a dumbbell in each hand, palms facing up and elbows resting on the pad.', 'Curl the dumbbells up toward your shoulders, With the upper arms still and your palms facing up.', 'Set the working upper arm against the preacher pad and leave the elbow free to bend.', 'Curl palms-up, turn the palms down at the top, and lower with that overhand grip.', 'Keep the torso quiet and let the elbow bend lift the weight.', 'Lower until the elbows are nearly straight, keeping the upper arms still.']::text[]),
('Reverse-Grip Curl (EZ Bar)', 'biceps', array['forearms']::text[], 'barbell', 'weight_reps', 'Y5X65IB', array['Stand tall with your feet about shoulder width and hold the ez barbell with palms facing up.', 'Hold your elbows near your torso and your upper arms stationary throughout the exercise.', 'Set the shoulders and upper arms before bending the elbows.', 'Curl the weight with your palms facing down, keeping the elbows close and torso still.', 'Keep the palms in the chosen grip without bending the wrists back.', 'Lower until the elbows are nearly straight, keeping the upper arms still.']::text[]),
('Bench Front Squat (Barbell)', 'quads', array['hamstrings', 'glutes', 'calves']::text[], 'barbell', 'weight_reps', 'Y7YcmIJ', array['Begin by standing with your feet about shoulder width and the barbell resting on your upper chest, just below your collarbone.', 'Take hold of the barbell with palms facing down, keeping your elbows up and your upper arms parallel to the ground.', 'Brace the abdomen and spread pressure across the whole foot.', 'Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.', 'Drive upward with the chest and hips rising together; keep the knees from collapsing inward.', 'Stand fully, reset your footing and breathing, then begin the next descent.']::text[]),
('Single Leg Split Squat (Band)', 'quads', array['glutes', 'hamstrings']::text[], 'band', 'weight_reps', 'y8bYM8w', array['Stand and set your feet about hip width and place a resistance band around your ankles.', 'Step wide forward with your right foot and a smaller step back with your left foot.', 'Brace the abdomen and spread pressure across the whole foot.', 'Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.', 'Control the band on the way back instead of letting it snap you into position.', 'Stand fully, reset your footing and breathing, then begin the next descent.']::text[]),
('Seated Side Crunch (Wall)', 'core', '{}'::text[], 'bodyweight', 'bodyweight_reps', 'Y9hNPcN', array['Take a seat on the floor with your back against a wall and your legs extended in front of you.', 'Bend your knees and place your feet planted, about hip width.', 'Set the pelvis and keep the neck relaxed before curling upward.', 'Curl your rib cage toward your pelvis, letting the abdominals move the torso.', 'Leave a little space between the chin and chest; keep the movement in the torso.', 'Lower the shoulders or torso with control before the next curl.']::text[]),
('Rope Climb', 'back', array['forearms', 'biceps', 'shoulders']::text[], 'cable', 'weight_reps', 'yaAxcQr', array['Face the rope from a stable stance with feet about shoulder width.', 'Take hold of the rope with both hands, palms facing toward you.', 'Begin from a controlled hang with the shoulders active rather than slack.', 'Pull your elbows down and bring your upper chest toward the bar without kicking your legs.', 'Avoid swinging the legs to clear the bar.', 'Lower to long arms without dropping suddenly from the top.']::text[]),
('Reverse-Grip Pull-Up', 'back', array['biceps', 'forearms']::text[], 'bodyweight', 'bodyweight_reps', 'YAk5dIw', array['Take hold of the pull-up bar with palms facing up, hands about shoulder width.', 'Suspend yourself from the bar with your arms straight and your body straight.', 'Begin from a controlled hang with the shoulders active rather than slack.', 'Pull your elbows down and bring your upper chest toward the bar without kicking your legs.', 'Keep the palms in the chosen grip without bending the wrists back.', 'Lower to long arms without dropping suddenly from the top.']::text[]),
('Machine Decline Close-Grip Bench Press (Smith Machine)', 'triceps', array['chest', 'shoulders']::text[], 'machine', 'weight_reps', 'yB9SvIF', array['Set the bench on the smith machine to a decline position.', 'Get onto the bench with your feet firmly planted on the ground.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Keep the wrists stacked and use a shoulder path that feels natural.', 'Lower the weight to its starting height under control before pressing again.']::text[]),
('Single-Arm Military Press to the Side (Kettlebell)', 'shoulders', array['triceps', 'core']::text[], 'kettlebell', 'weight_reps', 'yCvYdi7', array['Stand and set your feet about shoulder width, holding a kettlebell in one hand at shoulder height.', 'Brace your trunk and Keep your spine in a comfortable neutral position.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Keep both shoulders level and resist turning toward the working arm.', 'Lower the weight to its starting height under control before pressing again; switch sides when the set calls for it.']::text[]),
('Single-Arm Lateral Raise with Support (Dumbbell)', 'shoulders', array['traps']::text[], 'dumbbell', 'weight_reps', 'Yg7MJAT', array['Stand and set your feet about shoulder width and hold a dumbbell in one hand, with your palm facing your body.', 'Set your other hand on a stable surface, such as a bench or wall, for support.', 'Start with a manageable load and a small bend in the elbows.', 'Raise the arms out to the sides to about shoulder height without leaning or shrugging.', 'Keep both shoulders level and resist turning toward the working arm.', 'Lower the arms slowly to your sides without swinging the weight; switch sides when the set calls for it.']::text[]),
('Muscle Up', 'back', array['biceps', 'triceps', 'shoulders', 'chest']::text[], 'bodyweight', 'bodyweight_reps', 'yJUHKTn', array['Begin by hanging from a pull-up bar with your palms turned away from you and your arms straight.', 'Brace your trunk and pull your body up toward the bar, leading with your chest.', 'Begin from a controlled hang with the shoulders active rather than slack.', 'Pull your elbows down and bring your upper chest toward the bar without kicking your legs.', 'Avoid swinging the legs to clear the bar.', 'Lower to long arms without dropping suddenly from the top.']::text[]),
('Calf Press on Leg Press (Machine)', 'calves', array['hamstrings', 'quads']::text[], 'machine', 'weight_reps', 'ykHcWme', array['Set the seat of the leg press machine so that your knees are soft when your feet are on the sled.', 'Set your feet about shoulder width on the sled, with your toes pointing forward.', 'Let the ankles move freely while the rest of the body stays quiet.', 'Rise through the balls of your feet, lifting the heels as high as you can without rocking.', 'Pause at the top without rolling the ankles outward.', 'Lower the heels at a measured pace before rising again.']::text[]),
('Standing Calf Raise (Cable)', 'calves', array['hamstrings', 'glutes']::text[], 'cable', 'weight_reps', 'yl2IYyy', array['Face the cable machine from a stable stance with feet about shoulder width.', 'Use the cable machine handles or attach a cable ankle strap to your ankles.', 'Let the ankles move freely while the rest of the body stays quiet.', 'Rise through the balls of your feet, lifting the heels as high as you can without rocking.', 'Pause at the top without rolling the ankles outward.', 'Lower the heels at a measured pace before rising again.']::text[]),
('Lying Glutes Stretch (Assisted)', 'glutes', array['hamstrings']::text[], 'bodyweight', 'duration', 'yn0LjwL', array['Settle onto your back with your legs extended.', 'Before moving, bend your right knee and place your right ankle on your left thigh, just above the knee.', 'Settle into the starting position and take an easy breath before moving deeper.', 'Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.', 'Stay in a mild stretch rather than pulling farther with momentum.', 'Hold the position with steady breathing, then release gently; repeat on the other side if needed.']::text[]),
('45° Leg Press (Back Pov) (Machine)', 'glutes', array['quads', 'hamstrings', 'calves']::text[], 'machine', 'weight_reps', 'yn2lLSI', array['Set the seat of the sled machine so that your knees are at a 45-degree angle.', 'Take a seat on the sled machine with your back against the backrest and your feet about shoulder width on the footplate.', 'Set your feet firmly on the plate and keep the hips against the seat.', 'Bend the knees to bring the platform toward you, then press it away through the feet.', 'Stop the descent before the hips lift from the seat.', 'Ease back to the start before repeating.']::text[]),
('Seated Shoulder Internal Rotation (Cable)', 'shoulders', array['triceps']::text[], 'cable', 'weight_reps', 'YPoVrBi', array['Take a seat on a bench or chair facing the cable machine with your feet planted.', 'Take hold of the cable handle with your arm extended straight out in front of you, parallel to the ground.', 'Set the pelvis and make the turn through the rib cage.', 'Turn through the torso while the hips and lower body stay as steady as the setup allows.', 'Keep the turn smooth instead of throwing the arms across the body.', 'Return through center before turning to the other side.']::text[]),
('Hands Reversed Clasped Circular Toe Touch', 'glutes', array['hamstrings', 'quads', 'calves']::text[], 'bodyweight', 'bodyweight_reps', 'yq3GAJX', array['Stand and set your feet about shoulder width and your arms extended to the sides.', 'Bend forward at the waist, with your spine steady and your knees soft.', 'Settle into the starting position and take an easy breath before moving deeper.', 'Fold forward from the hips and let your hands travel toward your feet without forcing the reach.', 'Stay in a mild stretch rather than pulling farther with momentum.', 'Hold briefly at a comfortable depth, then rise by extending the hips.']::text[]),
('Standing Twist (Barbell)', 'core', array['back']::text[], 'barbell', 'weight_reps', 'yQe5HpE', array['Stand and set your feet about shoulder width and hold a barbell ahead of your chest with both hands, palms facing down.', 'Brace your trunk and Keep your spine in a comfortable neutral position throughout the exercise.', 'Set the pelvis and make the turn through the rib cage.', 'Turn through the torso while the hips and lower body stay as steady as the setup allows.', 'Keep the turn smooth instead of throwing the arms across the body.', 'Return through center before turning to the other side.']::text[]),
('Reverse Close-Grip Bench Press (Barbell)', 'triceps', array['chest', 'shoulders']::text[], 'barbell', 'weight_reps', 'YqJw82s', array['Settle onto a bench with your feet planted and your back pressed against the bench.', 'Hold the barbell with a reverse grip, hands about shoulder width.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Keep the wrists stacked and use a shoulder path that feels natural.', 'Lower the weight to its starting height under control before pressing again.']::text[]),
('Full Maltese', 'core', array['shoulders', 'chest']::text[], 'bodyweight', 'bodyweight_reps', 'YRaCa5Y', array['Begin by standing with your feet about shoulder width and your arms extended straight out to the sides.', 'With control lean forward, keeping your arms straight, until your upper body is parallel to the ground.', 'Brace the abdomen and find a position you can maintain without holding your breath.', 'Brace your midsection and hold the position while breathing normally.', 'Keep breathing steadily as you maintain the same body line.', 'Keep the shape for the planned time, then come out of it with control.']::text[]),
('Reverse-Grip Skullcrusher (Barbell)', 'triceps', array['forearms']::text[], 'barbell', 'weight_reps', 'yRLPCLu', array['Settle onto a bench with your feet planted and your head at the end of the bench.', 'Take hold of the barbell with a reverse grip, palms facing toward your face, and your hands about shoulder width.', 'Set the upper arms in place before extending the elbows.', 'Keep the upper arms steady and extend through the elbows to move the weight.', 'Keep the palms in the chosen grip without bending the wrists back.', 'Bend the elbows slowly to return to the start of the next rep.']::text[]),
('Shoulder Tap', 'core', array['shoulders', 'triceps']::text[], 'bodyweight', 'bodyweight_reps', 'yRpV5TC', array['Begin in a high plank position with your hands directly under your shoulders and your body in a straight line.', 'Brace your trunk and lift your right hand off the ground, reaching across to tap your left shoulder.', 'Brace the trunk lightly before moving a limb.', 'Move the working arm or leg while keeping the trunk steady and the breathing even.', 'Keep the pelvis from rocking as the arm or leg moves.', 'Reset your posture before changing sides or beginning the next rep.']::text[]),
('Exercise Ball Seated Hamstring Stretch', 'hamstrings', array['glutes', 'back']::text[], 'bodyweight', 'duration', 'yRYyfdA', array['Take a seat on the stability ball with your feet planted and your knees bent at a 90-degree angle.', 'With control roll the ball forward, walking your feet out until your upper back is resting on the ball and your legs are extended straight in front of you.', 'Settle into the starting position and take an easy breath before moving deeper.', 'Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.', 'Keep the ball steady and use the feet to manage your balance.', 'Hold the position with steady breathing, then release gently; repeat on the other side if needed.']::text[]),
('Seated Front Raise (Dumbbell)', 'shoulders', array['traps', 'biceps']::text[], 'dumbbell', 'weight_reps', 'Ys97II0', array['Plant both feet while seated on a bench; a dumbbell in each hand, resting on your thighs.', 'Keep your spine in a comfortable neutral position and core engaged.', 'Start with a manageable load and a small bend in the elbows.', 'Lift the arms forward to about shoulder height, keeping the ribs down and torso still.', 'Stop near shoulder height rather than shrugging to lift higher.', 'Lower the arms slowly to your sides without swinging the weight.']::text[]),
('Single-Arm Seated Neutral Wrist Curl (Dumbbell)', 'forearms', array['biceps']::text[], 'dumbbell', 'weight_reps', 'YtaCTYl', array['Plant both feet while seated on a bench; hold a dumbbell in one hand, palm facing up.', 'Set your forearm on your thigh, letting your wrist to hang off the edge.', 'Keep the elbows relaxed so the small muscles of the hand or forearm take the load.', 'Move through the wrists or fingers while the forearms stay supported and still.', 'Keep both shoulders level and resist turning toward the working arm.', 'Ease back to the start without letting the load fall from your hands; switch sides when the set calls for it.']::text[]),
('Shoulder Grip Pull-Up', 'back', array['biceps', 'forearms']::text[], 'bodyweight', 'bodyweight_reps', 'YtgD7Xq', array['Take hold of the pull-up bar with a shoulder-width grip, palms turned away from you.', 'Hang freely with your arms straight.', 'Begin from a controlled hang with the shoulders active rather than slack.', 'Pull your elbows down and bring your upper chest toward the bar without kicking your legs.', 'Avoid swinging the legs to clear the bar.', 'Lower to long arms without dropping suddenly from the top.']::text[]),
('Single-Arm Curl (Cable)', 'biceps', array['forearms']::text[], 'cable', 'weight_reps', 'YTur5nR', array['Face the cable machine from a stable stance with feet about shoulder width.', 'Hold the cable handle with palms facing up, palm facing up.', 'Set the shoulders and upper arms before bending the elbows.', 'Bend your elbows to bring the weight toward your shoulders without swinging your torso.', 'Keep both shoulders level and resist turning toward the working arm.', 'Lower until the elbows are nearly straight, keeping the upper arms still; switch sides when the set calls for it.']::text[]),
('Exercise Ball Lower Back Stretch (Pyramid)', 'back', array['glutes', 'hamstrings']::text[], 'bodyweight', 'duration', 'yU7w7CA', array['Take a seat on the stability ball with your feet planted and your knees bent at a 90-degree angle.', 'With control walk your feet forward, rolling the ball down your back until your lower back is resting on the ball.', 'Settle into the starting position and take an easy breath before moving deeper.', 'Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.', 'Keep the ball steady and use the feet to manage your balance.', 'Hold the position with steady breathing, then release gently; repeat on the other side if needed.']::text[]),
('Rear Delt Row (Stirrups) (Cable)', 'shoulders', array['traps', 'back', 'biceps']::text[], 'cable', 'weight_reps', 'yUdIGNs', array['Connect a stirrup handle to a low cable pulley and stand facing the machine.', 'Hold the handle with your left hand and take a step back with your right foot, positioning your body at a slight angle.', 'Set the torso and allow the arms to reach forward without rounding excessively.', 'Draw your elbows back and bring the handle or weight toward your torso.', 'Bring the elbows back without jerking the torso.', 'Reach the arms forward again without letting the torso lurch.']::text[]),
('Prone Lying Quads Stretch (Assisted)', 'quads', array['hamstrings', 'glutes']::text[], 'bodyweight', 'duration', 'YUYAMEj', array['Position yourself face down on the ground with your legs extended.', 'Before moving, bend your left knee and reach back with your left hand to grab your left foot or ankle.', 'Settle into the starting position and take an easy breath before moving deeper.', 'Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.', 'Stay in a mild stretch rather than pulling farther with momentum.', 'Hold the position with steady breathing, then release gently; repeat on the other side if needed.']::text[]),
('Standing Inner Curl (Cable)', 'biceps', array['forearms']::text[], 'cable', 'weight_reps', 'YwnI4ja', array['Face the cable machine from a stable stance with feet about shoulder width.', 'Hold the cable handle with palms facing up.', 'Set the shoulders and upper arms before bending the elbows.', 'Bend your elbows to bring the weight toward your shoulders without swinging your torso.', 'Keep the torso quiet and let the elbow bend lift the weight.', 'Lower until the elbows are nearly straight, keeping the upper arms still.']::text[]),
('Thruster (Kettlebell)', 'shoulders', array['quads', 'glutes', 'core']::text[], 'kettlebell', 'weight_reps', 'yWxMvB5', array['Begin by standing with your feet about shoulder width, holding a kettlebell ahead of your chest with both hands, palms facing each other.', 'Before moving, lower into a squat position by bending your knees and pushing your hips back, keeping your chest up and your back straight.', 'Rack the weight securely and brace before dropping into the squat.', 'Stand from the squat and use that leg drive to press the weight overhead.', 'Let the leg drive start the press while keeping the ribs from flaring.', 'Ease back to the start before repeating.']::text[]),
('Full Planche', 'core', array['shoulders', 'chest', 'triceps']::text[], 'bodyweight', 'bodyweight_reps', 'YZ4961r', array['Begin in a push-up position with your hands about shoulder width and your fingers pointing forward.', 'Brace your trunk and With control shift your weight forward, lifting your feet off the ground.', 'Brace the abdomen and find a position you can maintain without holding your breath.', 'Brace your midsection and hold the position while breathing normally.', 'Keep breathing steadily as you maintain the same body line.', 'Keep the shape for the planned time, then come out of it with control.']::text[]),
('Alternate Biceps Curl (Barbell)', 'biceps', array['forearms']::text[], 'barbell', 'weight_reps', 'Yza7XrQ', array['Stand tall with your feet about shoulder width and hold a barbell in each hand, palms facing forward.', 'Let the elbows do the moving while the upper arms stay put and Breathe out and curl the weights while contracting your biceps.', 'Set the shoulders and upper arms before bending the elbows.', 'Bend your elbows to bring the weight toward your shoulders without swinging your torso.', 'Finish one side''s motion before the other side takes over.', 'Lower until the elbows are nearly straight, keeping the upper arms still; switch sides when the set calls for it.']::text[]),
('Palms Down Wrist Curl Over a Bench (Barbell)', 'forearms', array['biceps']::text[], 'barbell', 'weight_reps', 'yzYH9pI', array['Plant both feet while seated on a bench; your forearms resting on your thighs, palms facing down.', 'Take a barbell with palms facing down, hands about shoulder width.', 'Keep the elbows relaxed so the small muscles of the hand or forearm take the load.', 'Move through the wrists or fingers while the forearms stay supported and still.', 'Use a small, smooth range without swinging the elbows.', 'Ease back to the start without letting the load fall from your hands.']::text[]),
('Overhead Triceps Stretch', 'triceps', array['shoulders']::text[], 'bodyweight', 'duration', 'Z5YStHW', array['Either stand or sit upright with your feet about shoulder width.', 'Extend one arm overhead, bending at the elbow so that your hand reaches toward the opposite shoulder blade.', 'Settle into the starting position and take an easy breath before moving deeper.', 'Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.', 'Stay in a mild stretch rather than pulling farther with momentum.', 'Hold the position with steady breathing, then release gently; repeat on the other side if needed.']::text[]),
('Twisting Bench Press (Dumbbell)', 'triceps', array['chest', 'shoulders']::text[], 'dumbbell', 'weight_reps', 'z6TAHoT', array['Settle onto a bench with your feet planted and your back pressed against the bench.', 'Hold a dumbbell in each hand at chest level with the palms facing forward.', 'Brace the torso and align the wrists with the forearms.', 'Press the weights up while turning the palms inward; reverse the turn as you lower.', 'Keep the wrists stacked and use a shoulder path that feels natural.', 'Lower the weight to its starting height under control before pressing again.']::text[]),
('Goblet Squat (Kettlebell)', 'glutes', array['quads', 'hamstrings', 'calves']::text[], 'kettlebell', 'weight_reps', 'ZA8b5hc', array['Stand and set your feet about shoulder width, holding a kettlebell close to your chest with both hands.', 'With your chest up and core engaged, lower your body down into a squat position by bending at the knees and hips.', 'Brace the abdomen and spread pressure across the whole foot.', 'Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.', 'Drive upward with the chest and hips rising together; keep the knees from collapsing inward.', 'Stand fully, reset your footing and breathing, then begin the next descent.']::text[]),
('Rack Pull (Barbell)', 'glutes', array['hamstrings', 'back']::text[], 'barbell', 'weight_reps', 'za9Ni4z', array['Prepare a barbell on a rack at knee height.', 'Stand and set your feet about shoulder width, toes pointing slightly outwards.', 'Unlock the knees and brace the abdomen before moving the hips back.', 'Push the hips back while keeping the load close and the spine steady.', 'Keep the weight close to the legs and stop when the back would begin to round.', 'Drive the hips forward to stand tall without leaning back at the top.']::text[]),
('Stalder Press', 'triceps', array['shoulders', 'core']::text[], 'bodyweight', 'bodyweight_reps', 'zd4P4B2', array['Begin by standing with your feet about shoulder width and your arms extended overhead.', 'Bend your knees slightly and Brace your trunk.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Keep the wrists stacked and use a shoulder path that feels natural.', 'Lower the weight to its starting height under control before pressing again.']::text[]),
('Single-Arm Reverse-Grip Press (Dumbbell)', 'chest', array['triceps', 'shoulders']::text[], 'dumbbell', 'weight_reps', 'Ze7MoIb', array['Take a seat on a flat bench with a dumbbell in one hand, palm facing toward your body.', 'Set your feet planted and Keep your spine in a comfortable neutral position.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Keep both shoulders level and resist turning toward the working arm.', 'Lower the weight to its starting height under control before pressing again; switch sides when the set calls for it.']::text[]),
('Seated Two-Arm Military Press (Kettlebell)', 'shoulders', array['triceps', 'back']::text[], 'kettlebell', 'weight_reps', 'ZEkjZDi', array['Take a seat on a bench with your back straight and feet planted.', 'Take a kettlebell in each hand at shoulder level with your palms facing forward.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Keep the wrists stacked and use a shoulder path that feels natural.', 'Lower the weight to its starting height under control before pressing again.']::text[]),
('Skater Hops', 'cardio', array['quads', 'hamstrings', 'glutes', 'calves']::text[], 'bodyweight', 'duration', 'zfNHMN9', array['Stand and set your feet about shoulder width.', 'Before moving, bend your knees slightly and jump to the right, landing on your right foot.', 'Bend the hips and knees slightly to load the jump.', 'Load the legs with a small bend, then drive through the floor and land softly.', 'Land with bent hips and knees and let the feet absorb the impact.', 'Absorb the landing through the hips and knees before repeating.']::text[]),
('Standing Rear Delt Row (With Rope) (Cable)', 'shoulders', array['traps', 'back', 'biceps']::text[], 'cable', 'weight_reps', 'ZfyAGhK', array['Face the cable machine from a stable stance with feet about shoulder width.', 'Take hold of the cable attachment with both hands, palms facing each other, and step back to create tension in the cable.', 'Set the torso and allow the arms to reach forward without rounding excessively.', 'Draw your elbows back and bring the handle or weight toward your torso.', 'Bring the elbows back without jerking the torso.', 'Reach the arms forward again without letting the torso lurch.']::text[]),
('Thibaudeau Kayak Row (Cable)', 'back', array['biceps', 'shoulders']::text[], 'cable', 'weight_reps', 'ZgwWBoC', array['Connect a cable handle to a low pulley and sit facing the machine with your feet planted.', 'Hold the handle with your right hand and extend your arm fully, keeping a slight bend in your elbow.', 'Set the torso and allow the arms to reach forward without rounding excessively.', 'Draw your elbows back and bring the handle or weight toward your torso.', 'Bring the elbows back without jerking the torso.', 'Reach the arms forward again without letting the torso lurch.']::text[]),
('Fixed Back Underhand Pulldown (Band)', 'back', array['biceps', 'shoulders']::text[], 'band', 'weight_reps', 'ZH68exZ', array['Connect the band to a sturdy anchor point above your head.', 'Face the anchor point from a stable stance with feet about shoulder width.', 'Sit tall and set the shoulders before drawing the handle down.', 'Pull the handle down by driving your elbows toward your ribs; keep your torso steady.', 'Control the band on the way back instead of letting it snap you into position.', 'Let the handle rise steadily until the arms are long, then reset the shoulders.']::text[]),
('Assisted Inverse Leg Curl (Cable)', 'hamstrings', array['glutes', 'calves']::text[], 'cable', 'weight_reps', 'zHEpuuc', array['Set the cable machine so that the ankle attachment is at the lowest setting.', 'Position yourself face down on the bench with your legs straight and the ankle attachment secured to your ankles.', 'Line the knees up with the machine or bench edge before starting the curl.', 'Bend your knees to draw the pad toward you without lifting your hips from the support.', 'Keep the hips still while the knees bend.', 'Return along the same path at a controlled pace.']::text[]),
('Assisted Wheel Rollout (Band)', 'core', array['back']::text[], 'band', 'weight_reps', 'zhF9lW4', array['Get down on the floor and hold the handles of the band with both hands, palms facing down.', 'Set the band on the ground in front of you and position your hands about shoulder width.', 'Tighten the abdomen and keep the pelvis tucked before the arms reach away.', 'Reach the arms away while keeping your ribs and pelvis aligned; stop before the lower back sags.', 'Control the band on the way back instead of letting it snap you into position.', 'Pull back to the start through your shoulders and abdominals, keeping the same body line.']::text[]),
('Machine Biceps Curl (Smith Machine)', 'biceps', array['forearms']::text[], 'machine', 'weight_reps', 'zILLZ98', array['Set the height of the smith machine bar to be at waist level.', 'Face the smith machine from a stable stance with feet about shoulder width.', 'Set the shoulders and upper arms before bending the elbows.', 'Bend your elbows to bring the weight toward your shoulders without swinging your torso.', 'Keep the torso quiet and let the elbow bend lift the weight.', 'Lower until the elbows are nearly straight, keeping the upper arms still.']::text[]),
('Reverse-Grip Incline Bench Single-Arm Row (Dumbbell)', 'back', array['biceps', 'shoulders']::text[], 'dumbbell', 'weight_reps', 'ZIViNh1', array['Angle the bench to roughly 45 degrees.', 'Set a dumbbell on the floor next to the bench.', 'Set the torso and allow the arms to reach forward without rounding excessively.', 'Draw your elbows back and bring the handle or weight toward your torso.', 'Keep both shoulders level and resist turning toward the working arm.', 'Reach the arms forward again without letting the torso lurch; switch sides when the set calls for it.']::text[]),
('Reverse-Grip Press (Smith Machine)', 'chest', array['triceps', 'shoulders']::text[], 'machine', 'weight_reps', 'zK8Fu1W', array['Set the height of the smith machine bar to chest level.', 'Face the bar from a stable stance with feet about shoulder width.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Keep the palms in the chosen grip without bending the wrists back.', 'Lower the weight to its starting height under control before pressing again.']::text[]),
('Hyperextension (On Bench)', 'back', array['glutes', 'hamstrings']::text[], 'bodyweight', 'bodyweight_reps', 'zkgRrbK', array['Set the hyperextension bench so that your hips are resting comfortably on the pad and your feet are secured.', 'Fold your arms over your chest or place your hands behind your head.', 'Secure the hips and feet on the support before lifting.', 'Raise your torso or legs until they line up with your body, without arching sharply at the lower back.', 'Finish in a straight body line, before the lower back overarches.', 'Ease back to the start before repeating.']::text[]),
('Vertical Leg Raise (On Parallel Bars)', 'core', '{}'::text[], 'bodyweight', 'bodyweight_reps', 'ZNgOYQU', array['Suspend yourself from the parallel bars with your arms straight and your body straight.', 'Brace your trunk and lift your legs up in front of you, keeping them straight.', 'Brace the abdomen and keep the shoulders anchored to the support.', 'Lift your legs by bracing your trunk and moving at the hips rather than swinging.', 'Slow the legs before they pull the lower back out of position.', 'Lower the legs slowly without swinging or losing your trunk position.']::text[]),
('Seated Crunch (Chest Pad) (Machine)', 'core', '{}'::text[], 'machine', 'weight_reps', 'ZnJHhMk', array['Set the seat height and chest pad position according to your comfort.', 'Take a seat on the machine with your back against the chest pad and your feet planted.', 'Set the pelvis and keep the neck relaxed before curling upward.', 'Curl your rib cage toward your pelvis, letting the abdominals move the torso.', 'Leave a little space between the chin and chest; keep the movement in the torso.', 'Lower the shoulders or torso with control before the next curl.']::text[]),
('Pullover to Press (Barbell)', 'back', array['triceps', 'chest', 'shoulders']::text[], 'barbell', 'weight_reps', 'znLogoF', array['Settle onto a bench with your head at one end and your feet on the ground.', 'Take hold of the barbell with a pronated grip (palms turned away from you) and extend your arms straight above your chest.', 'Set the ribs down and keep a small elbow bend before lowering the weight.', 'Lower the weight in an arc behind your head until you feel a comfortable shoulder stretch.', 'Keep the ribs down as the arms travel overhead.', 'Pull the weight back over the chest along the same arc, without lifting the ribs.']::text[]),
('Hug Knees to Chest', 'glutes', array['hamstrings', 'quads']::text[], 'bodyweight', 'bodyweight_reps', 'znP9SIh', array['Begin by standing with your feet about shoulder width.', 'Before moving, bend your knees and lower your body down into a squat position.', 'Settle into the starting position and take an easy breath before moving deeper.', 'Ease toward the stretch until you feel mild tension; keep breathing and avoid bouncing.', 'Stay in a mild stretch rather than pulling farther with momentum.', 'Hold the position with steady breathing, then release gently; repeat on the other side if needed.']::text[]),
('Wide-Grip Bench Press (Smith Machine)', 'chest', array['triceps', 'shoulders']::text[], 'machine', 'weight_reps', 'zoOvPcx', array['Set the bench to a comfortable position on the smith machine.', 'Get onto the bench with your feet planted.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Keep the wrists stacked and use a shoulder path that feels natural.', 'Lower the weight to its starting height under control before pressing again.']::text[]),
('Kneeling Push-Up', 'chest', array['triceps', 'shoulders']::text[], 'bodyweight', 'bodyweight_reps', 'ZOuKWir', array['Begin by kneeling on the ground with your hands about shoulder width, fingers pointing forward.', 'Reach your legs behind you, resting on the balls of your feet, so that your body forms a straight line from head to heels.', 'Brace the abdomen and glutes so the shoulders, hips and ankles move together.', 'Bend your elbows to lower your chest while keeping your body in one line.', 'Keep the head in line with the spine as the elbows bend.', 'Press back to straight arms, keeping the body line intact.']::text[]),
('Reverse-Grip Vertical Row (Machine)', 'back', array['biceps', 'forearms']::text[], 'machine', 'weight_reps', 'ZqNOWQ6', array['Set the seat height and footplate position to ensure proper alignment.', 'Take a seat on the machine with your chest against the pad and your feet flat on the footplate.', 'Set the torso and allow the arms to reach forward without rounding excessively.', 'Draw your elbows back and bring the handle or weight toward your torso.', 'Keep the palms in the chosen grip without bending the wrists back.', 'Reach the arms forward again without letting the torso lurch.']::text[]),
('Jm Bench Press (Barbell)', 'triceps', array['chest', 'shoulders']::text[], 'barbell', 'weight_reps', 'ZsiqXYa', array['Settle onto a bench with your feet planted and your back pressed against the bench.', 'Hold the barbell with palms facing down, just beyond shoulder width.', 'Brace the torso and align the wrists with the forearms.', 'Press the weight or handles away while keeping your trunk braced.', 'Keep the wrists stacked and use a shoulder path that feels natural.', 'Lower the weight to its starting height under control before pressing again.']::text[]),
('Self Assisted Inverse Leg Curl (On Floor)', 'hamstrings', array['glutes', 'calves']::text[], 'bodyweight', 'bodyweight_reps', 'ZSY3MsL', array['Settle onto your back with your legs extended and your arms by your sides.', 'Bend your knees and place your feet planted, about hip width.', 'Line the knees up with the machine or bench edge before starting the curl.', 'Bend your knees to draw the pad toward you without lifting your hips from the support.', 'Keep the hips still while the knees bend.', 'Ease back to the start before repeating.']::text[]),
('Hack Squat (Smith Machine)', 'glutes', array['quads', 'hamstrings', 'calves']::text[], 'machine', 'weight_reps', 'ZuPXtCK', array['Set the barbell on the smith machine to an appropriate height for your body.', 'Stand and set your feet about shoulder width, toes slightly pointed outwards.', 'Brace the abdomen and spread pressure across the whole foot.', 'Bend at the hips and knees to lower, keeping your feet grounded and knees tracking with the toes.', 'Drive upward with the chest and hips rising together; keep the knees from collapsing inward.', 'Stand fully, reset your footing and breathing, then begin the next descent.']::text[]),
('V-Sit on Floor', 'core', '{}'::text[], 'bodyweight', 'bodyweight_reps', 'ZuXu4Eq', array['Take a seat on the floor with your legs extended in front of you.', 'Recline slightly and lift your legs off the ground, keeping them straight.', 'Brace the abdomen and find a position you can maintain without holding your breath.', 'Brace your midsection and hold the position while breathing normally.', 'Keep breathing steadily as you maintain the same body line.', 'Keep the shape for the planned time, then come out of it with control.']::text[]),
('Alternating Biceps Curl with Leg Raised on Exercise Ball (Dumbbell)', 'biceps', array['forearms', 'shoulders']::text[], 'dumbbell', 'weight_reps', 'Zwiw7XR', array['Stand and set your feet about shoulder width and hold a dumbbell in each hand, palms facing forward.', 'Set an exercise ball behind you and position one foot on top of it, keeping your balance.', 'Set the shoulders and upper arms before bending the elbows.', 'Bend your elbows to bring the weight toward your shoulders without swinging your torso.', 'Finish one side''s motion before the other side takes over.', 'Lower until the elbows are nearly straight, keeping the upper arms still; switch sides when the set calls for it.']::text[]),
('Single-Arm Reverse Preacher Curl (Cable)', 'biceps', array['forearms']::text[], 'cable', 'weight_reps', 'ZXnjcOQ', array['Move the cable pulley to its lowest setting.', 'Face the cable machine from a stable stance with feet about shoulder width.', 'Set the working upper arm against the preacher pad and leave the elbow free to bend.', 'Curl the weight while your upper arms stay in contact with the pad.', 'Keep both shoulders level and resist turning toward the working arm.', 'Lower until the elbows are nearly straight, keeping the upper arms still; switch sides when the set calls for it.']::text[]),
('Elevator', 'back', array['shoulders', 'traps']::text[], 'bodyweight', 'bodyweight_reps', 'zYmNaoY', array['Stand and set your feet about shoulder width and your knees soft.', 'Set your hands on your hips or cross them ahead of your chest.', 'Unlock the knees and brace the abdomen before moving the hips back.', 'Push the hips back while keeping the load close and the spine steady.', 'Keep the weight close to the legs and stop when the back would begin to round.', 'Drive the hips forward to stand tall without leaning back at the top.']::text[]),
('Shrug (Machine)', 'traps', array['shoulders']::text[], 'machine', 'weight_reps', 'ZZKbeMw', array['Fit the seat to your body, then settle into the machine.', 'Hold the handles with palms facing down and keep your arms straight.', 'Let the arms hang long and keep the head neutral.', 'Lift your shoulders toward your ears without bending the elbows or rolling the shoulders.', 'Lift and lower vertically without circling the shoulders.', 'Ease back to the start before repeating.']::text[]),
('Lying Single-Arm Supinated Triceps Extension (Dumbbell)', 'triceps', array['forearms']::text[], 'dumbbell', 'weight_reps', 'zZlORz6', array['Settle onto a bench with your back and head supported, and your feet planted.', 'Take a dumbbell in one hand with palms facing up, and extend your arm straight up above your shoulder.', 'Set the upper arms in place before extending the elbows.', 'Keep the upper arms steady and extend through the elbows to move the weight.', 'Keep both shoulders level and resist turning toward the working arm.', 'Bend the elbows slowly to return to the start of the next rep; switch sides when the set calls for it.']::text[])
) as v (name, primary_muscle, secondary_muscles, equipment, kind, gif_id, instructions)
where not exists (
  select 1 from public.exercises x where x.created_by is null and (x.gif_id = v.gif_id or lower(x.name) = lower(v.name))
);

create index if not exists exercises_primary_muscle on public.exercises (primary_muscle);
